        const double DEG = Math.PI / 180.0;
        static readonly long J2000Ticks = new DateTime(2000, 1, 1, 12, 0, 0, DateTimeKind.Utc).Ticks;

        static double N360(double x)
        {
            x = x % 360.0;
            if (x < 0) x += 360.0;
            return x;
        }

        // Differenza TT - UT in secondi (valore approssimato, adeguato per gli anni 2015-2035)
        public static double DeltaT(int year)
        {
            if (year < 2015) return 67.6;
            if (year <= 2035) return 69.2;
            double t = year - 2000;
            return 62.92 + 0.32217 * t + 0.005589 * t * t;
        }

        public static double JulianDay(DateTime utc)
        {
            return 2451545.0 + (double)(utc.Ticks - J2000Ticks) / TimeSpan.TicksPerDay;
        }

        // Calcola azimut/elevazione topocentrici. Az da Nord verso Est.
        public static MoonPos Compute(DateTime utc, double latDeg, double lonDeg, double heightM, bool refraction)
        {
            double jdUT = JulianDay(utc);
            double jde = jdUT + DeltaT(utc.Year) / 86400.0;
            double T = (jde - 2451545.0) / 36525.0;
            double T2 = T * T, T3 = T2 * T, T4 = T3 * T;

            double Lp = N360(218.3164477 + 481267.88123421 * T - 0.0015786 * T2 + T3 / 538841.0 - T4 / 65194000.0);
            double D = N360(297.8501921 + 445267.1114034 * T - 0.0018819 * T2 + T3 / 545868.0 - T4 / 113065000.0);
            double M = N360(357.5291092 + 35999.0502909 * T - 0.0001536 * T2 + T3 / 24490000.0);
            double Mp = N360(134.9633964 + 477198.8675055 * T + 0.0087414 * T2 + T3 / 69699.0 - T4 / 14712000.0);
            double F = N360(93.2720950 + 483202.0175233 * T - 0.0036539 * T2 - T3 / 3526000.0 + T4 / 863310000.0);
            double A1 = N360(119.75 + 131.849 * T);
            double A2 = N360(53.09 + 479264.290 * T);
            double A3 = N360(313.45 + 481266.484 * T);
            double E = 1.0 - 0.002516 * T - 0.0000074 * T2;

            double sl = 0, sr = 0, sb = 0;
            for (int i = 0; i < TL.GetLength(0); i++)
            {
                double arg = (TL[i, 0] * D + TL[i, 1] * M + TL[i, 2] * Mp + TL[i, 3] * F) * DEG;
                int am = Math.Abs(TL[i, 1]);
                double e = am == 1 ? E : (am == 2 ? E * E : 1.0);
                sl += TL[i, 4] * e * Math.Sin(arg);
                sr += TL[i, 5] * e * Math.Cos(arg);
            }
            for (int i = 0; i < TB.GetLength(0); i++)
            {
                double arg = (TB[i, 0] * D + TB[i, 1] * M + TB[i, 2] * Mp + TB[i, 3] * F) * DEG;
                int am = Math.Abs(TB[i, 1]);
                double e = am == 1 ? E : (am == 2 ? E * E : 1.0);
                sb += TB[i, 4] * e * Math.Sin(arg);
            }
            sl += 3958 * Math.Sin(A1 * DEG) + 1962 * Math.Sin((Lp - F) * DEG) + 318 * Math.Sin(A2 * DEG);
            sb += -2235 * Math.Sin(Lp * DEG) + 382 * Math.Sin(A3 * DEG)
                  + 175 * Math.Sin((A1 - F) * DEG) + 175 * Math.Sin((A1 + F) * DEG)
                  + 127 * Math.Sin((Lp - Mp) * DEG) - 115 * Math.Sin((Lp + Mp) * DEG);

            double lambda = Lp + sl / 1e6;
            double beta = sb / 1e6;
            double dist = 385000.56 + sr / 1000.0;

            // Nutazione (precisione ~0.5") e obliquità
            double Om = (125.04452 - 1934.136261 * T) * DEG;
            double Ls = (280.4665 + 36000.7698 * T) * DEG;
            double Lm = (218.3165 + 481267.8813 * T) * DEG;
            double dpsi = (-17.20 * Math.Sin(Om) - 1.32 * Math.Sin(2 * Ls) - 0.23 * Math.Sin(2 * Lm) + 0.21 * Math.Sin(2 * Om)) / 3600.0;
            double deps = (9.20 * Math.Cos(Om) + 0.57 * Math.Cos(2 * Ls) + 0.10 * Math.Cos(2 * Lm) - 0.09 * Math.Cos(2 * Om)) / 3600.0;
            double eps = (23.4392911111 - (46.8150 * T + 0.00059 * T2 - 0.001813 * T3) / 3600.0 + deps) * DEG;

            double la = (lambda + dpsi) * DEG;
            double b = beta * DEG;
            double ra = Math.Atan2(Math.Sin(la) * Math.Cos(eps) - Math.Tan(b) * Math.Sin(eps), Math.Cos(la));
            double dec = Math.Asin(Math.Sin(b) * Math.Cos(eps) + Math.Cos(b) * Math.Sin(eps) * Math.Sin(la));

            // Tempo siderale apparente di Greenwich
            double Tu = (jdUT - 2451545.0) / 36525.0;
            double gmst = N360(280.46061837 + 360.98564736629 * (jdUT - 2451545.0) + 0.000387933 * Tu * Tu - Tu * Tu * Tu / 38710000.0);
            double gast = gmst + dpsi * Math.Cos(eps);

            // Correzione topocentrica (Meeus cap. 40)
            double phi = latDeg * DEG;
            double u = Math.Atan(0.99664719 * Math.Tan(phi));
            double rhoSin = 0.99664719 * Math.Sin(u) + heightM / 6378140.0 * Math.Sin(phi);
            double rhoCos = Math.Cos(u) + heightM / 6378140.0 * Math.Cos(phi);
            double sinPi = 6378.14 / dist;
            double H = (gast + lonDeg) * DEG - ra;
            double dra = Math.Atan2(-rhoCos * sinPi * Math.Sin(H), Math.Cos(dec) - rhoCos * sinPi * Math.Cos(H));
            double decT = Math.Atan2((Math.Sin(dec) - rhoSin * sinPi) * Math.Cos(dra), Math.Cos(dec) - rhoCos * sinPi * Math.Cos(H));
            double Ht = H - dra;

            double az = Math.Atan2(Math.Sin(Ht), Math.Cos(Ht) * Math.Sin(phi) - Math.Tan(decT) * Math.Cos(phi)) / DEG + 180.0;
            double el = Math.Asin(Math.Sin(phi) * Math.Sin(decT) + Math.Cos(phi) * Math.Cos(decT) * Math.Cos(Ht)) / DEG;
            double elGeo = el;

            // Distanza topocentrica
            double rc = rhoCos * 6378.14, rs = rhoSin * 6378.14;
            double distTopo = Math.Sqrt(dist * dist + rc * rc + rs * rs
                - 2.0 * dist * (rc * Math.Cos(dec) * Math.Cos(H) + rs * Math.Sin(dec)));

            // Longitudine eclittica (obliquità 23.443° come in WSJT-X)
            double raT = ra + dra;
            double eW = 23.443 * DEG;
            double lamT = N360(Math.Atan2(Math.Sin(raT) * Math.Cos(eW) + Math.Tan(decT) * Math.Sin(eW), Math.Cos(raT)) / DEG);

            if (refraction && el > -1.5)
            {
                // Saemundsson: da elevazione vera ad apparente (primi d'arco), atmosfera standard
                double r = 1.02 / Math.Tan((el + 10.3 / (el + 5.11)) * DEG);
                if (r > 0) el += r / 60.0;
            }

            MoonPos p;
            p.Az = N360(az);
            p.El = el;
            p.Ra = N360((ra + dra) / DEG);
            p.Dec = decT / DEG;
            p.DecGeo = dec / DEG;
            p.RaGeo = N360(ra / DEG);
            p.Gast = gast;
            double ha = N360(Ht / DEG);
            p.Ha = ha > 180 ? ha - 360 : ha;
            p.Dist = dist;
            p.ElGeo = elGeo;
            p.DistTopo = distTopo;
            p.Lambda = lamT;
            return p;
        }

        // ---- Grandezze EME, stesse formule di WSJT-X (lib/astro.f90) ----

        // Temperatura del cielo a 144 MHz lungo l'eclittica, passo 2° (fonte: WSJT-X)
        static readonly short[] NT144 = {
             234, 246, 257, 267, 275, 280, 283, 286, 291, 298,
             305, 313, 322, 331, 341, 351, 361, 369, 376, 381,
             383, 382, 379, 374, 370, 366, 363, 361, 363, 368,
             376, 388, 401, 415, 428, 440, 453, 467, 487, 512,
             544, 579, 607, 618, 609, 588, 563, 539, 512, 482,
             450, 422, 398, 379, 363, 349, 334, 319, 302, 282,
             262, 242, 226, 213, 205, 200, 198, 197, 196, 197,
             200, 202, 204, 205, 204, 203, 202, 201, 203, 206,
             212, 218, 223, 227, 231, 236, 240, 243, 247, 257,
             276, 301, 324, 339, 346, 344, 339, 331, 323, 316,
             312, 310, 312, 317, 327, 341, 358, 375, 392, 407,
             422, 437, 451, 466, 480, 494, 511, 530, 552, 579,
             612, 653, 702, 768, 863,1008,1232,1557,1966,2385,
            2719,2924,3018,3038,2986,2836,2570,2213,1823,1461,
            1163, 939, 783, 677, 602, 543, 494, 452, 419, 392,
             373, 360, 353, 350, 350, 350, 350, 350, 350, 348,
             344, 337, 329, 319, 307, 295, 284, 276, 272, 272,
             273, 274, 274, 271, 266, 260, 252, 245, 238, 231
        };

        public static double Tsky(double lambdaDeg, double freqMHz)
        {
            int k = (int)Math.Round(lambdaDeg / 2.0, MidpointRounding.AwayFromZero);
            if (k < 1 || k > 180) k = 180;
            double t144 = NT144[k - 1];
            return (t144 - 2.7) * Math.Pow(144.0 / freqMHz, 2.6) + 2.7;
        }

        // Degradazione rispetto alle condizioni ideali (Luna al perigeo, cielo freddo), dB <= 0 circa
        public static double Dgrd(double lambdaDeg, double distTopo, double freqMHz)
        {
            const double tr = 80.0; // preamplificatore buono, come in WSJT-X
            double tsky = Tsky(lambdaDeg, freqMHz);
            double tskymin = 13.0 * Math.Pow(408.0 / freqMHz, 2.6);
            double dbMoon = -40.0 * Math.Log10(distTopo / 356903.0);
            return -10.0 * Math.Log10((tsky + tr) / (tskymin + tr)) + dbMoon;
        }

        // Posizione del Sole (Meeus cap. 25, precisione ~0,01°): az/el topocentrici, RA/Dec apparenti
        public static void SunPos(DateTime utc, double latDeg, double lonDeg, out double az, out double el, out double raDeg, out double decDeg)
        {
            double jdUT = JulianDay(utc);
            double jde = jdUT + DeltaT(utc.Year) / 86400.0;
            double T = (jde - 2451545.0) / 36525.0;
            double L0 = 280.46646 + 36000.76983 * T + 0.0003032 * T * T;
            double M = (357.52911 + 35999.05029 * T - 0.0001537 * T * T) * DEG;
            double C = (1.914602 - 0.004817 * T - 0.000014 * T * T) * Math.Sin(M)
                     + (0.019993 - 0.000101 * T) * Math.Sin(2 * M) + 0.000289 * Math.Sin(3 * M);
            double Om = (125.04 - 1934.136 * T) * DEG;
            double lam = (L0 + C - 0.00569 - 0.00478 * Math.Sin(Om)) * DEG;
            double eps = (23.4392911111 - 46.8150 * T / 3600.0 + 0.00256 * Math.Cos(Om)) * DEG;
            double ra = Math.Atan2(Math.Cos(eps) * Math.Sin(lam), Math.Cos(lam));
            double dec = Math.Asin(Math.Sin(eps) * Math.Sin(lam));
            double Tu = (jdUT - 2451545.0) / 36525.0;
            double gmst = N360(280.46061837 + 360.98564736629 * (jdUT - 2451545.0) + 0.000387933 * Tu * Tu - Tu * Tu * Tu / 38710000.0);
            double phi = latDeg * DEG;
            double H = (gmst + lonDeg) * DEG - ra;
            az = N360(Math.Atan2(Math.Sin(H), Math.Cos(H) * Math.Sin(phi) - Math.Tan(dec) * Math.Cos(phi)) / DEG + 180.0);
            el = Math.Asin(Math.Sin(phi) * Math.Sin(dec) + Math.Cos(phi) * Math.Cos(dec) * Math.Cos(H)) / DEG;
            raDeg = N360(ra / DEG);
            decDeg = dec / DEG;
        }

        // Tempo siderale locale (gradi)
        public static double Lst(DateTime utc, double lonDeg)
        {
            double jdUT = JulianDay(utc);
            double Tu = (jdUT - 2451545.0) / 36525.0;
            return N360(280.46061837 + 360.98564736629 * (jdUT - 2451545.0) + 0.000387933 * Tu * Tu - Tu * Tu * Tu / 38710000.0 + lonDeg);
        }

        // Coordinate galattiche -> equatoriali J2000 (gradi)
        public static void GalToEq(double lDeg, double bDeg, out double raDeg, out double decDeg)
        {
            double aG = 192.85948 * DEG, dG = 27.12825 * DEG, lN = 122.93192 * DEG;
            double l = lDeg * DEG, b = bDeg * DEG;
            double sd = Math.Sin(dG) * Math.Sin(b) + Math.Cos(dG) * Math.Cos(b) * Math.Cos(lN - l);
            double ra = aG + Math.Atan2(Math.Cos(b) * Math.Sin(lN - l), Math.Cos(dG) * Math.Sin(b) - Math.Sin(dG) * Math.Cos(b) * Math.Cos(lN - l));
            raDeg = N360(ra / DEG);
            decDeg = Math.Asin(sd) / DEG;
        }

        // Eclittica (latitudine 0) -> equatoriali, obliquità 23,44°
        public static void EclToEq(double lamDeg, out double raDeg, out double decDeg)
        {
            double e = 23.44 * DEG, l = lamDeg * DEG;
            raDeg = N360(Math.Atan2(Math.Sin(l) * Math.Cos(e), Math.Cos(l)) / DEG);
            decDeg = Math.Asin(Math.Sin(e) * Math.Sin(l)) / DEG;
        }

        // Distanza angolare tra due punti del cielo (gradi)
        public static double Separation(double ra1, double dec1, double ra2, double dec2)
        {
            double c = Math.Sin(dec1 * DEG) * Math.Sin(dec2 * DEG)
                     + Math.Cos(dec1 * DEG) * Math.Cos(dec2 * DEG) * Math.Cos((ra1 - ra2) * DEG);
            if (c > 1) c = 1;
            if (c < -1) c = -1;
            return Math.Acos(c) / DEG;
        }

        // Perdita di tratta EME tra antenne isotropiche (equazione radar), dB.
        // Riflettività lunare 0,065, raggio lunare 1737,4 km, distanze topocentriche TX e RX in km.
        public static double PathLoss(double freqMHz, double dTxKm, double dRxKm)
        {
            double lambda = 299.792458 / freqMHz;
            double rm = 1737.4e3;
            double sigma = 0.065 * Math.PI * rm * rm;
            double d1 = dTxKm * 1e3, d2 = dRxKm * 1e3;
            return 10.0 * Math.Log10(Math.Pow(4.0 * Math.PI, 3) * d1 * d1 * d2 * d2 / (sigma * lambda * lambda));
        }

        // Angolo di polarizzazione locale (WSJT-X), gradi
        public static double PolAngle(double latDeg, double azDeg, double elDeg)
        {
            double la = latDeg * DEG, az = azDeg * DEG, el = elDeg * DEG;
            double xx = Math.Sin(la) * Math.Cos(el) - Math.Cos(la) * Math.Cos(az) * Math.Sin(el);
            double yy = Math.Cos(la) * Math.Sin(az);
            return Math.Atan2(yy, xx) / DEG;
        }

        // Offset di polarizzazione spaziale DX rispetto a me, tra -90 e +90 gradi
        public static double PolOffset(double polMe, double polDx)
        {
            double p = (polDx - polMe + 720.0) % 180.0;
            if (p > 90.0) p -= 180.0;
            return p;
        }

        // Perdita per polarizzazione lineare dovuta al solo offset spaziale (senza Faraday), dB
        public static double PolLoss(double offDeg)
        {
            double x = Math.Abs(Math.Cos(offDeg * DEG));
            if (x < 0.0316228) x = 0.0316228; // limite 30 dB
            return -20.0 * Math.Log10(x);
        }

        // Massima non reciprocità (MNR) tra i due sensi di trasmissione, dB (WSJT-X)
        public static double Mnr(double offDeg)
        {
            double x = Math.Abs(Math.Cos(2.0 * offDeg * DEG));
            if (x < 0.056234) x = 0.056234;
            return -20.0 * Math.Log10(x);
        }
    }

    public static class Locator
    {
        // Restituisce il centro del quadrato (da 4 a 14 caratteri; oltre gli 8 si ripetono le regole base 24 / base 10)
        public static bool TryParse(string s, out double lat, out double lon)
        {
            lat = 0; lon = 0;
            if (s == null) return false;
            s = s.Trim().ToUpperInvariant();
            if (s.Length < 4 || s.Length > 14 || s.Length % 2 != 0) return false;
            double lonW = 20.0, latH = 10.0;
            lon = -180.0; lat = -90.0;
            for (int pair = 0; pair < s.Length / 2; pair++)
            {
                char c1 = s[pair * 2], c2 = s[pair * 2 + 1];
                int v1, v2;
                if (pair == 0)
                {
                    if (c1 < 'A' || c1 > 'R' || c2 < 'A' || c2 > 'R') return false;
                    v1 = c1 - 'A'; v2 = c2 - 'A';
                }
                else if (pair % 2 == 1)
                {
                    if (c1 < '0' || c1 > '9' || c2 < '0' || c2 > '9') return false;
                    v1 = c1 - '0'; v2 = c2 - '0';
                    lonW /= 10.0; latH /= 10.0;
                }
                else
                {
                    if (c1 < 'A' || c1 > 'X' || c2 < 'A' || c2 > 'X') return false;
                    v1 = c1 - 'A'; v2 = c2 - 'A';
                    lonW /= 24.0; latH /= 24.0;
                }
                lon += v1 * lonW;
                lat += v2 * latH;
            }
            lon += lonW / 2.0;
            lat += latH / 2.0;
            return true;
        }

        // Locator di n caratteri (da 4 a 14, pari) del punto dato: stesse regole di TryParse
        public static string Da(double lat, double lon, int n)
        {
            if (n < 4) n = 4; if (n > 14) n = 14; if (n % 2 != 0) n--;
            lon = ((lon + 180.0) % 360.0 + 360.0) % 360.0;            // 0 … 360 da -180°
            lat = Math.Max(0.0, Math.Min(179.9999999, lat + 90.0));     // 0 … 180 da -90°
            double lonW = 20.0, latH = 10.0;
            StringBuilder sb = new StringBuilder();
            for (int pair = 0; pair < n / 2; pair++)
            {
                if (pair > 0) { double d = pair % 2 == 1 ? 10.0 : 24.0; lonW /= d; latH /= d; }
                int max = pair == 0 ? 18 : (pair % 2 == 1 ? 10 : 24);
                int v1 = Math.Min(max - 1, (int)Math.Floor(lon / lonW));
                int v2 = Math.Min(max - 1, (int)Math.Floor(lat / latH));
                lon -= v1 * lonW; lat -= v2 * latH;
                if (pair % 2 == 1) { sb.Append((char)('0' + v1)); sb.Append((char)('0' + v2)); }
                else { sb.Append((char)('A' + v1)); sb.Append((char)('A' + v2)); }
            }
            return sb.ToString();
        }

        // Lati della casella (m) per un locator di n caratteri alla latitudine data
        public static void Casella(int n, double lat, out double latoEstOvest, out double latoNordSud)
        {
            double lonW = 20.0, latH = 10.0;
            for (int pair = 1; pair < n / 2; pair++)
            {
                if (pair % 2 == 1) { lonW /= 10.0; latH /= 10.0; }
                else { lonW /= 24.0; latH /= 24.0; }
            }
            latoNordSud = latH * 111132.0;
            latoEstOvest = lonW * 111320.0 * Math.Cos(lat * Math.PI / 180.0);
        }

        // Errore massimo sulla posizione (m): metà della diagonale della casella, con la stazione nel centro
        public static double ErroreMetri(string s, double lat)
        {
            if (s == null) return double.NaN;
            int n = s.Trim().Length;
            if (n < 4 || n > 14 || n % 2 != 0) return double.NaN;
            double a, b;
            Casella(n, lat, out a, out b);
            return Math.Sqrt(a * a + b * b) / 2.0;
        }

        // Testo breve della precisione: "±18 m", "±4,4 km"
        public static string TestoErrore(double m, System.Globalization.CultureInfo c)
        {
            if (double.IsNaN(m)) return "";
            if (m >= 10000) return "±" + (m / 1000.0).ToString("0", c) + " km";
            if (m >= 1000) return "±" + (m / 1000.0).ToString("0.0", c) + " km";
            if (m >= 10) return "±" + m.ToString("0", c) + " m";
            if (m >= 1) return "±" + m.ToString("0.0", c) + " m";
            return "±" + (m * 100.0).ToString("0", c) + " cm";
        }
    }

