            "YAEC کے لیے تجویز کردہ فونٹس",
        };
    }

    static class Lang
    {
        public static readonly string[] Codici = { "en", "it", "de", "fr", "es", "pt", "zh", "ja", "hi", "ko", "id", "ru", "uk", "af", "bn", "ar", "tr",
            "nl", "et", "lv", "lt", "sv", "nb", "is", "he", "ur" };
        public static readonly string[] Nomi = { "English", "Italiano", "Deutsch", "Français", "Español", "Português", "中文 (简体)", "日本語", "हिन्दी", "한국어", "Bahasa Indonesia", "Русский", "Українська", "Afrikaans", "বাংলা", "العربية", "Türkçe",
            "Nederlands", "Eesti", "Latviešu", "Lietuvių", "Svenska", "Norsk (bokmål)", "Íslenska", "עברית", "اردو" };
        static readonly string[] Culture = { "en-GB", "it-IT", "de-DE", "fr-FR", "es-ES", "pt-PT", "zh-CN", "ja-JP", "hi-IN", "ko-KR", "id-ID", "ru-RU", "uk-UA", "af-ZA", "bn-BD", "ar-EG", "tr-TR",
            "nl-NL", "et-EE", "lv-LV", "lt-LT", "sv-SE", "nb-NO", "is-IS", "he-IL", "ur-PK" };
        public static int Idx;
        public static CultureInfo Cultura = new CultureInfo("en-GB");
        public static string FontUi = "Segoe UI";
        public static string FontAuto = "Segoe UI";   // carattere scelto automaticamente per la lingua
        static Dictionary<string, int> indice;

        public static void Imposta(string codice)
        {
            int i = Array.IndexOf(Codici, codice);
            Idx = i < 0 ? 0 : i;
            try { Cultura = new CultureInfo(Culture[Idx]); } catch { Cultura = CultureInfo.InvariantCulture; }
            FontUi = "Segoe UI";
            if (Idx == 6 && FontEsiste("Microsoft YaHei UI")) FontUi = "Microsoft YaHei UI";
            if (Idx == 7) FontUi = FontEsiste("Yu Gothic UI") ? "Yu Gothic UI" : (FontEsiste("Meiryo UI") ? "Meiryo UI" : "Segoe UI");
            if (Idx == 8 && FontEsiste("Nirmala UI")) FontUi = "Nirmala UI";
            if (Idx == 9 && FontEsiste("Malgun Gothic")) FontUi = "Malgun Gothic";
            if (Idx == 14) FontUi = FontEsiste("Nirmala UI") ? "Nirmala UI" : (FontEsiste("Vrinda") ? "Vrinda" : "Segoe UI");
            FontAuto = FontUi;
        }

        // Arabo, ebraico e urdu: testo da destra a sinistra
        public static bool Rtl { get { return Idx == 15 || Idx == 24 || Idx == 25; } }

        // Caratteri che contengono la scrittura delle lingue non latine (per gli altri si torna a quello automatico)
        static readonly string[][] CaratteriScrittura = {
            new string[] { "zh", "Microsoft YaHei UI", "Microsoft YaHei", "SimSun", "SimHei", "DengXian", "Microsoft JhengHei UI", "Microsoft JhengHei", "NSimSun" },
            new string[] { "ja", "Yu Gothic UI", "Yu Gothic", "Meiryo UI", "Meiryo", "MS Gothic", "MS UI Gothic", "MS PGothic", "Yu Mincho", "MS Mincho" },
            new string[] { "ko", "Malgun Gothic", "Gulim", "Dotum", "Batang", "Gungsuh" },
            new string[] { "hi", "Nirmala UI", "Mangal", "Aparajita", "Kokila", "Utsaah" },
            new string[] { "bn", "Nirmala UI", "Vrinda", "Shonar Bangla" },
            new string[] { "he", "Segoe UI", "Arial", "Tahoma", "Times New Roman", "Microsoft Sans Serif", "Courier New", "David", "Miriam", "Gisha", "Aharoni", "FrankRuehl" },
            new string[] { "ur", "Segoe UI", "Arial", "Tahoma", "Times New Roman", "Microsoft Sans Serif", "Courier New", "Urdu Typesetting", "Sakkal Majalla", "Traditional Arabic" },
            new string[] { "ar", "Segoe UI", "Arial", "Tahoma", "Times New Roman", "Microsoft Sans Serif", "Courier New", "Sakkal Majalla", "Traditional Arabic", "Simplified Arabic" },
            new string[] { "ru", "Segoe UI", "Arial", "Tahoma", "Calibri", "Cambria", "Times New Roman", "Verdana", "Consolas", "Courier New", "Georgia", "Trebuchet MS", "Microsoft Sans Serif", "Candara", "Constantia", "Corbel", "Bahnschrift" },
            new string[] { "uk", "Segoe UI", "Arial", "Tahoma", "Calibri", "Cambria", "Times New Roman", "Verdana", "Consolas", "Courier New", "Georgia", "Trebuchet MS", "Microsoft Sans Serif", "Candara", "Constantia", "Corbel", "Bahnschrift" }
        };

        // Caratteri proposti nell'elenco «Tipo di carattere» (i nomi con "|" sono alternative dello stesso carattere)
        static readonly string[] ConsigliatiWindows = { "Segoe UI", "Bahnschrift", "Calibri", "Arial", "Tahoma", "Verdana", "Trebuchet MS", "Corbel", "Candara", "Microsoft Sans Serif" };
        static readonly string[] ConsigliatiLinux = { "Noto Sans", "DejaVu Sans", "Liberation Sans", "Ubuntu", "Cantarell", "Open Sans", "Roboto", "Fira Sans", "Source Sans 3|Source Sans Pro", "FreeSans" };
        static readonly string[] ConsigliatiMac = { "Helvetica Neue", "Lucida Grande", "Avenir Next", "Helvetica", "Arial", "Verdana", "Geneva", "Tahoma", "Trebuchet MS", "Gill Sans" };

        public static string[] CaratteriConsigliati()
        {
            string cod = Codici[Idx];
            foreach (string[] r in CaratteriScrittura)
                if (r[0] == cod)
                {
                    List<string> l = new List<string>();
                    for (int i = 1; i < r.Length; i++) l.Add(r[i]);
                    // russo e ucraino: prima i caratteri consigliati del sistema che hanno il cirillico
                    if (cod == "ru" || cod == "uk")
                    {
                        string[] sis = Piattaforma.Windows ? ConsigliatiWindows : (Piattaforma.Mac ? ConsigliatiMac : ConsigliatiLinux);
                        List<string> o = new List<string>();
                        foreach (string n in sis) if (CarattereAdatto(n.Split('|')[0])) o.Add(n);
                        foreach (string n in l) if (!o.Contains(n)) o.Add(n);
                        return o.ToArray();
                    }
                    return l.ToArray();
                }
            return Piattaforma.Windows ? ConsigliatiWindows : (Piattaforma.Mac ? ConsigliatiMac : ConsigliatiLinux);
        }

        public static bool CarattereAdatto(string nome)
        {
            string cod = Codici[Idx];
            foreach (string[] r in CaratteriScrittura)
                if (r[0] == cod)
                {
                    if (Array.IndexOf(r, nome, 1) >= 1) return true;
                    // russo e ucraino: anche i consigliati di Linux e macOS che hanno il cirillico
                    if ((cod == "ru" || cod == "uk") && !Piattaforma.Windows && nome != "Gill Sans" && nome != "Avenir Next" && nome != "Cantarell")
                        foreach (string n in (Piattaforma.Mac ? ConsigliatiMac : ConsigliatiLinux))
                            if (Array.IndexOf(n.Split('|'), nome) >= 0) return true;
                    return false;
                }
            return true;
        }

        // Carattere scelto dall'utente per tutto il programma (vuoto = automatico secondo la lingua)
        public static void ImpostaCarattere(string nome)
        {
            if (!string.IsNullOrEmpty(nome) && FontEsiste(nome) && CarattereAdatto(nome)) FontUi = nome;
        }

        static bool FontEsiste(string nome)
        {
            try
            {
                using (System.Drawing.Text.InstalledFontCollection fc = new System.Drawing.Text.InstalledFontCollection())
                    foreach (FontFamily ff in fc.Families) if (ff.Name == nome) return true;
            }
            catch { }
            return false;
        }

        // Traduce un testo italiano nella lingua scelta (se manca la traduzione: inglese, poi italiano)
        public static string T(string it)
        {
            if (Idx == 1 || it == null) return it;
            if (indice == null)
            {
                indice = new Dictionary<string, int>();
                for (int k = 0; k < Testi.IT.Length; k++) if (!indice.ContainsKey(Testi.IT[k])) indice[Testi.IT[k]] = k;
            }
            int n;
            if (!indice.TryGetValue(it, out n)) return it;
            string[] col;
            switch (Idx)
            {
                case 0: col = Testi.EN; break;
                case 2: col = Testi.DE; break;
                case 3: col = Testi.FR; break;
                case 4: col = Testi.ES; break;
                case 5: col = Testi.PT; break;
                case 6: col = Testi.ZH; break;
                case 7: col = Testi.JA; break;
                case 8: col = Testi.HI; break;
                case 9: col = Testi.KO; break;
                case 11: col = Testi.RU; break;
                case 12: col = Testi.UK; break;
                case 13: col = Testi.AF; break;
                case 14: col = Testi.BN; break;
                case 15: col = Testi.AR; break;
                case 16: col = Testi.TR; break;
                case 17: col = Testi.NL; break;
                case 18: col = Testi.ET; break;
                case 19: col = Testi.LV; break;
                case 20: col = Testi.LT; break;
                case 21: col = Testi.SV; break;
                case 22: col = Testi.NB; break;
                case 23: col = Testi.IS; break;
                case 24: col = Testi.HE; break;
                case 25: col = Testi.UR; break;
                default: col = Testi.ID; break;
            }
            if (n < col.Length && !string.IsNullOrEmpty(col[n])) return col[n];
            if (n < Testi.EN.Length && !string.IsNullOrEmpty(Testi.EN[n])) return Testi.EN[n];
            return it;
        }
    }

    static class Tema
    {
        public static bool Scuro;
        public static int Schema;   // 0 chiaro, 1 notte (blu), 2 nero, 3 – 10 pastello (vedi Pastelli)
        // schemi pastello chiari: nome nelle impostazioni, nome da tradurre, tinta (colore pieno di riferimento)
        public static readonly string[] PastelloChiave = { "azzurro", "arancione", "acquamarina", "verde", "rosa", "lilla", "indaco", "marrone" };
        public static readonly string[] PastelloNome = { "Pastello azzurro", "Pastello arancione", "Pastello acquamarina", "Pastello verde", "Pastello rosa", "Pastello lilla", "Pastello indaco", "Pastello marrone" };
        static readonly Color[] PastelloTinta = {
            Color.FromArgb(70, 150, 230), Color.FromArgb(240, 140, 50), Color.FromArgb(40, 180, 170), Color.FromArgb(80, 170, 90),
            Color.FromArgb(230, 110, 160), Color.FromArgb(160, 120, 210), Color.FromArgb(80, 90, 190), Color.FromArgb(150, 105, 70) };
        public static string Chiave { get { return Schema == 2 ? "nero" : (Schema == 1 ? "scuro" : (Schema >= 3 ? "pastello-" + PastelloChiave[Schema - 3] : "chiaro")); } }
        public static int DaChiave(string k)
        {
            if (k == "nero") return 2;
            if (k == "scuro") return 1;
            if (k != null && k.StartsWith("pastello-")) { int i = Array.IndexOf(PastelloChiave, k.Substring(9)); if (i >= 0) return 3 + i; }
            return 0;
        }
        static Color Mix(Color tinta, float k) { return Color.FromArgb((int)(255 + (tinta.R - 255) * k), (int)(255 + (tinta.G - 255) * k), (int)(255 + (tinta.B - 255) * k)); }
        public static Color Back, Fore, Muted, Field, FieldFore, Section, Accent, OkFg, BadFg, WarnFg,
            OkBg, SoloBg, SottoFg, SnBg, MarginBg, Warn1, Warn2, ChartBg, ChartGrid, ChartText, Button,
            Carta, Linea, Limiti;   // riquadri disegnati, loro bordi, limiti dell'antenna

        static Tema() { Imposta(false); }

        public static void Imposta(bool scuro) { Imposta(scuro ? 1 : 0); }

        public static void Imposta(int schema)
        {
            Schema = Math.Max(0, Math.Min(2 + PastelloTinta.Length, schema));
            Scuro = Schema == 1 || Schema == 2;
            if (Schema == 2)
            {
                // nero: sfondo nero pieno, riquadri grigio molto scuro, colori di stato accesi
                Back = Color.FromArgb(0, 0, 0); Fore = Color.FromArgb(235, 235, 235); Muted = Color.FromArgb(140, 140, 140);
                Field = Color.FromArgb(18, 18, 18); FieldFore = Color.FromArgb(235, 235, 235); Section = Color.FromArgb(34, 34, 34);
                Accent = Color.FromArgb(80, 180, 255); OkFg = Color.FromArgb(60, 235, 130); BadFg = Color.FromArgb(255, 95, 85); WarnFg = Color.FromArgb(255, 170, 40);
                OkBg = Color.FromArgb(14, 60, 32); SoloBg = Color.FromArgb(70, 56, 10); SottoFg = Color.FromArgb(120, 120, 120);
                SnBg = Color.FromArgb(14, 30, 56); MarginBg = Color.FromArgb(46, 44, 20);
                Warn1 = Color.FromArgb(80, 26, 26); Warn2 = Color.FromArgb(70, 52, 14);
                ChartBg = Color.FromArgb(8, 8, 8); ChartGrid = Color.FromArgb(48, 48, 48); ChartText = Color.FromArgb(175, 175, 175);
                Button = Color.FromArgb(32, 32, 32);
                Carta = Color.FromArgb(18, 18, 18); Linea = Color.FromArgb(52, 52, 52); Limiti = Color.FromArgb(255, 209, 72);
                return;
            }
            if (Schema == 0 || Schema >= 3)   // chiaro e pastelli (i pastelli sono lo schema chiaro tinto)
            {
                Back = SystemColors.Control; Fore = SystemColors.ControlText; Muted = SystemColors.GrayText;
                Field = SystemColors.Window; FieldFore = SystemColors.WindowText; Section = Color.FromArgb(230, 232, 240);
                Accent = Color.DarkBlue; OkFg = Color.DarkGreen; BadFg = Color.Firebrick; WarnFg = Color.FromArgb(180, 100, 0);
                OkBg = Color.FromArgb(214, 245, 214); SoloBg = Color.FromArgb(255, 246, 200); SottoFg = Color.FromArgb(150, 150, 150);
                SnBg = Color.FromArgb(235, 245, 255); MarginBg = Color.FromArgb(245, 245, 225);
                Warn1 = Color.FromArgb(255, 225, 225); Warn2 = Color.FromArgb(255, 245, 220);
                ChartBg = Color.White; ChartGrid = Color.FromArgb(225, 228, 235); ChartText = Color.FromArgb(80, 90, 105);
                Button = SystemColors.Control;
                Carta = Color.White; Linea = Color.FromArgb(213, 220, 234); Limiti = Color.FromArgb(181, 131, 0);
                Accent = Color.FromArgb(31, 111, 209); OkFg = Color.FromArgb(19, 150, 80); WarnFg = Color.FromArgb(217, 123, 0);
                if (Schema >= 3)
                {
                    // pastello: lo schema chiaro con fondo, riquadri, campi e grafici tinti di un colore tenue
                    Color t = PastelloTinta[Schema - 3];
                    Back = Mix(t, 0.24f); Section = Mix(t, 0.34f); Field = Mix(t, 0.05f); Carta = Mix(t, 0.08f);
                    ChartBg = Mix(t, 0.06f); ChartGrid = Mix(t, 0.22f); Linea = Mix(t, 0.30f); Button = Mix(t, 0.18f);
                    SnBg = Mix(t, 0.12f); MarginBg = Mix(t, 0.14f);
                }
            }
            else
            {
                // tema notte: blu scuro, cifre luminose
                Back = Color.FromArgb(11, 18, 32); Fore = Color.FromArgb(219, 228, 245); Muted = Color.FromArgb(127, 141, 176);
                Field = Color.FromArgb(18, 27, 46); FieldFore = Color.FromArgb(219, 228, 245); Section = Color.FromArgb(26, 38, 64);
                Accent = Color.FromArgb(95, 168, 255); OkFg = Color.FromArgb(61, 220, 132); BadFg = Color.FromArgb(255, 110, 100); WarnFg = Color.FromArgb(255, 179, 64);
                OkBg = Color.FromArgb(20, 64, 44); SoloBg = Color.FromArgb(74, 62, 22); SottoFg = Color.FromArgb(118, 128, 150);
                SnBg = Color.FromArgb(22, 40, 70); MarginBg = Color.FromArgb(52, 50, 30);
                Warn1 = Color.FromArgb(86, 36, 40); Warn2 = Color.FromArgb(74, 58, 26);
                ChartBg = Color.FromArgb(14, 22, 40); ChartGrid = Color.FromArgb(40, 52, 80); ChartText = Color.FromArgb(160, 175, 200);
                Button = Color.FromArgb(28, 40, 66);
                Carta = Color.FromArgb(18, 27, 46); Linea = Color.FromArgb(36, 49, 79); Limiti = Color.FromArgb(255, 209, 102);
            }
        }
    }

