        TabControl tabs;
        ComboBox cmbBand, cmbBw;
        DateTimePicker dtpB;
        CheckBox chkPol;
        BudgetUi bMe, bDx;
        ListView lvB;
        Label lblBNote;
        // tutte le bande gestite (i parametri del budget sono memorizzati per ciascuna) e quelle scelte dall'utente
        static readonly int[] Bande = { 50, 70, 144, 222, 432 };   // dalla v27 solo fino a 432 MHz
        static readonly int[] BandePredefinite = { 50, 70, 144, 222, 432 };
        List<int> bandeAttive = new List<int>(BandePredefinite);
        bool ricostruzioneBande;
        static string NomeBanda(int f)
        {
            return f >= 47000 ? (f / 1000).ToString(inv) + " GHz (" + f.ToString(inv) + " MHz)" : f.ToString(inv) + " MHz";
        }
        int curBand = 144;
        Dictionary<int, BudgetParams> bpMe = new Dictionary<int, BudgetParams>();
        Dictionary<int, BudgetParams> bpDx = new Dictionary<int, BudgetParams>();
        bool loadingB;

        NumericUpDown NudB(decimal min, decimal max, decimal inc, int decimals)
        {
            NumericUpDown n = Nud(min, max, min, decimals, 75);
            n.Increment = inc;
            n.ValueChanged += (s, e) => { if (!loadingB) RecalcBudget(); };
            return n;
        }

        Label Section(string t)
        {
            Label l = L(t);
            l.Font = new Font(this.Font, FontStyle.Bold);
            return l;
        }

        // Riquadro di una stazione (a sinistra): antenna e guadagno; il resto dell'impianto è nello schema a destra
        NumericUpDown NudBU(decimal min, decimal max, decimal inc, int decimals, string unita, string formato)
        {
            NudUnita n = new NudUnita();
            n.Minimum = min; n.Maximum = max; n.DecimalPlaces = decimals;
            n.Value = min <= 0m && max >= 0m ? 0m : min;
            n.Increment = inc;
            n.TextAlign = HorizontalAlignment.Right;
            n.Width = S(84);
            n.Formato = formato;
            n.Unita = unita;
            n.SenzaFrecce = true;
            n.ValueChanged += (s, e) => { if (!loadingB) RecalcBudget(); };
            return n;
        }

        // Scheda di una stazione nel Budget EME (bozzetto 7): bianca, bordo superiore colorato, titolo con locator e Luna
        Control BuildBudgetStation(string title, Color colore, out BudgetUi b)
        {
            b = new BudgetUi();
            b.P = NudBU(1m, 100000m, 10m, 1, "W", "0.#");
            b.CavoTx = NudB(0m, 60m, 0.1m, 2);
            b.AccTx = NudB(0m, 60m, 0.1m, 2);
            b.PreLoss = NudB(0m, 60m, 0.1m, 2);
            b.PostLoss = NudB(0m, 60m, 0.1m, 2);
            foreach (NumericUpDown n in new NumericUpDown[] { b.CavoTx, b.AccTx, b.PreLoss, b.PostLoss }) n.Enabled = false;   // calcolati dallo schema
            b.GAnt = NudBU(-10m, 70m, 0.1m, 1, "dBi", null);
            b.NAnt = NudBU(1m, 256m, 1m, 0, "", null);
            b.PreGain = NudBU(0m, 60m, 0.5m, 1, "dB", null);
            b.TvGain = NudBU(-30m, 60m, 0.5m, 1, "dB", null);
            b.Mds = NudBU(-160m, -100m, 1m, 0, "dBm", null);
            b.Nf = NudBU(0m, 10m, 0.05m, 2, "dB", null);
            b.LenAnt = NudBU(0m, 500m, 0.5m, 1, "m", "0.#");
            b.Rele = NudBU(0m, 3m, 0.05m, 2, "dB", "0.0#");
            b.ConnTx = NudBU(0m, 60m, 1m, 0, "", "0");
            b.ConnRx = NudBU(0m, 60m, 1m, 0, "", "0");
            b.LenPa = NudBU(0m, 500m, 1m, 1, "m", "0.#");
            b.LenDis = NudBU(0m, 500m, 1m, 1, "m", "0.#");
            b.SnReq = NudBU(-40m, 20m, 0.5m, 1, "dB", "0.#");
            b.TvCavo = NudBU(0m, 30m, 0.1m, 1, "dB", null);
            b.TvNf = NudBU(0m, 20m, 0.1m, 1, "dB", null);
            b.Tant = NudBU(0m, 20000m, 5m, 0, "K", null);
            b.CavoAnt = ComboCavi(); b.CavoPa = ComboCavi(); b.CavoDis = ComboCavi();
            b.Modo = new Tendina(); ((Tendina)b.Modo).SuCarta = true;
            b.Modo.DropDownStyle = ComboBoxStyle.DropDownList;
            foreach (int i in BudgetParams.ModiOrdine)
                b.Modo.Items.Add(BudgetParams.ModiNome[i] + " · " + BudgetParams.ModiSn[i].ToString("0.#", ci) + " dB" + (BudgetParams.ModiDaVerificare[i] ? " (" + Lang.T("da verificare") + ")" : ""));
            b.Modo.Items.Add(Lang.T("personalizzato"));
            b.Modo.DropDownWidth = S(220);
            // transverter: modelli della tabella del manuale, oppure "personalizzato"
            b.TvMod = new Tendina(); ((Tendina)b.TvMod).SuCarta = true;
            b.TvMod.DropDownStyle = ComboBoxStyle.DropDownList;
            for (int i = 0; i < BudgetParams.TvNome.Length; i++)
                b.TvMod.Items.Add(BudgetParams.TvNome[i] + " · NF " + BudgetParams.TvNfMod[i].ToString("0.0", ci) + " dB · G " + BudgetParams.TvGMod[i].ToString("0", ci) + " dB");
            b.TvMod.Items.Add(Lang.T("personalizzato"));
            b.TvMod.SelectedIndex = b.TvMod.Items.Count - 1;
            b.TvMod.DropDownWidth = S(360);
            b.TvMod.Enabled = false;
            b.TvOn = new Spunta();
            b.TvOn.Text = Lang.T("TRANSVERTER");
            b.TvOn.AutoSize = true;
            b.TvOn.Font = new Font(Lang.FontUi, 9F * fontFactor, FontStyle.Bold);
            b.TvOn.Tag = "su-carta";
            BudgetUi bb = b;
            b.TvOn.CheckedChanged += (s, e) =>
            {
                bb.TvGain.Enabled = bb.TvOn.Checked; bb.TvNf.Enabled = bb.TvOn.Checked; bb.TvMod.Enabled = bb.TvOn.Checked;
                if (pnlImp != null) pnlImp.Invalidate();
                if (!loadingB) RecalcBudget();
            };
            bool tvImposta = false;
            b.TvMod.SelectedIndexChanged += (s, e) =>
            {
                int k = bb.TvMod.SelectedIndex;
                if (k >= 0 && k < BudgetParams.TvNome.Length && !loadingB)
                {
                    tvImposta = true;
                    bool lb = loadingB;
                    loadingB = true;
                    bb.TvGain.Value = (decimal)BudgetParams.TvGMod[k];
                    bb.TvNf.Value = (decimal)BudgetParams.TvNfMod[k];
                    loadingB = lb;
                    tvImposta = false;
                }
                if (!loadingB) RecalcBudget();
            };
            EventHandler tvMano = (s, e) =>
            {
                if (tvImposta || loadingB) return;
                int k = bb.TvMod.SelectedIndex;
                if (k >= 0 && k < BudgetParams.TvNome.Length && ((double)bb.TvGain.Value != BudgetParams.TvGMod[k] || (double)bb.TvNf.Value != BudgetParams.TvNfMod[k]))
                    bb.TvMod.SelectedIndex = bb.TvMod.Items.Count - 1;   // valori cambiati a mano: transverter personalizzato
            };
            b.TvGain.ValueChanged += tvMano;
            b.TvNf.ValueChanged += tvMano;
            foreach (ComboBox c in new ComboBox[] { b.CavoAnt, b.CavoPa, b.CavoDis })
                c.SelectedIndexChanged += (s, e) => { if (!loadingB) RecalcBudget(); };
            bool modoInterno = false;
            b.Modo.SelectedIndexChanged += (s, e) =>
            {
                int m = BudgetParams.ModoDaVoce(bb.Modo.SelectedIndex);
                if (m >= 0 && m < BudgetParams.ModiSn.Length && !modoInterno) bb.SnReq.Value = (decimal)BudgetParams.ModiSn[m];
                if (!loadingB) { MostraSchema(); RecalcBudget(); }
            };
            b.SnReq.ValueChanged += (s, e) =>
            {
                int m = BudgetParams.ModoDaVoce(bb.Modo.SelectedIndex);
                if (m >= 0 && m < BudgetParams.ModiSn.Length && (double)bb.SnReq.Value != BudgetParams.ModiSn[m])
                {
                    modoInterno = true;
                    bb.Modo.SelectedIndex = bb.Modo.Items.Count - 1;
                    modoInterno = false;
                }
            };

            tip.SetToolTip(b.P, Lang.T("Potenza di uscita dell'amplificatore in watt."));
            tip.SetToolTip(b.GAnt, Lang.T("Guadagno di una singola antenna in dBi (dBd + 2,15)."));
            tip.SetToolTip(b.NAnt, Lang.T("Numero di antenne in schiera: il guadagno totale è G + 10·log10(N) (accoppiamento ideale)."));
            tip.SetToolTip(b.Nf, Lang.T("Cifra di rumore del preamplificatore in dB: serve per stimare il rumore di sistema e l'S/N."));
            tip.SetToolTip(b.Mds, Lang.T("Segnale minimo rilevabile della radio (MDS), tra -100 e -140 dBm."));
            tip.SetToolTip(b.LenAnt, Lang.T("Lunghezza del cavo tra l'antenna e il relè coassiale: la sua perdita vale sia in trasmissione sia in ricezione (prima del preampli)."));
            tip.SetToolTip(b.Rele, Lang.T("Perdita di inserzione del relè coassiale TX/RX (tipica 0,3 dB): conta in trasmissione e, in ricezione, prima del preampli."));
            tip.SetToolTip(b.ConnTx, Lang.T("Connettori in TX") + "\u0001" + Lang.T("Numero stimato di connettori nella linea di trasmissione, tra il PA e l'antenna, compresi adattatori, relè e divisori. Consiglio di NJ9R: circa 1 dB ogni 8 – 10 connettori, cioè 0,11 dB ciascuno."));
            tip.SetToolTip(b.ConnRx, Lang.T("Connettori in RX") + "\u0001" + Lang.T("Numero stimato di connettori in ricezione prima del preamplificatore, tra l'antenna e l'ingresso del preampli (adattatori, relè, divisori): dopo il preampli la loro perdita pesa poco. Consiglio di NJ9R: 0,11 dB ciascuno."));
            tip.SetToolTip(b.LenPa, Lang.T("Lunghezza del cavo tra l'amplificatore (PA) e il relè coassiale."));
            tip.SetToolTip(b.LenDis, Lang.T("Lunghezza del cavo di discesa tra il preamplificatore in antenna e la stazione."));
            tip.SetToolTip(b.TvOn, Lang.T("Attiva il transverter quando la radio non lavora direttamente sulla banda scelta: entra nella catena di ricezione con il suo guadagno e la sua figura di rumore."));
            tip.SetToolTip(b.TvMod, Lang.T("Modello del transverter: il programma ne prende figura di rumore e guadagno dalla tabella del manuale «TEORIA E CONSIGLI SULL'EME» (§ 1.7.1). Con \"personalizzato\" li scrivi tu."));
            tip.SetToolTip(b.TvCavo, Lang.T("Perdita dei cavetti tra l'uscita RX del transverter e l'ingresso della radio (dB)."));
            tip.SetToolTip(b.TvNf, Lang.T("Cifra di rumore del transverter in ricezione (dB)."));
            tip.SetToolTip(b.TvGain, Lang.T("Guadagno di conversione del transverter in ricezione."));
            tip.SetToolTip(b.Modo, Lang.T("Modo usato e sua soglia tipica di decodifica (S/N in 2500 Hz, guida di WSJT-X), mostrata solo come riferimento: con Deep Search, media dei messaggi o decodifica AP si decodifica anche più in basso (vedi il manuale)."));
            tip.SetToolTip(b.SnReq, Lang.T("S/N richiesto dal modo in 2500 Hz: si può cambiare a mano (modo personalizzato)."));
            tip.SetToolTip(b.Tant, Lang.T("Temperatura d'antenna Ta in kelvin, come nelle tabelle di VE7BQH (Lionel Edwards) sulle prestazioni delle antenne: comprende lobi laterali, lobi posteriori, terreno e perdite interne, ed è calcolata con l'antenna inclinata a 30° di elevazione.\nCerca nelle tabelle VE7BQH la tua antenna (o una simile) e riporta qui il valore Ta della banda.\nNel calcolo: Tsys = Tant + (Tsky dietro la Luna - Tsky di riferimento, se positivo) + Sole + Te del ricevitore."));

            b.GTot = new Label();
            b.Info1 = new Label(); b.Info2 = new Label(); b.NfFriis = new Label();   // testi disegnati nella scheda
            b.Ground = new Spunta();
            b.Ground.Text = "";
            b.Ground.AutoSize = true;
            b.GroundH = NudBU(0m, 100m, 0.5m, 1, "m", "0.#");
            b.GroundH.Value = 10m;
            b.GroundH.Enabled = false;
            b.GroundH.Visible = false;
            b.Ground.CheckedChanged += (s, e) =>
            {
                bb.GroundH.Enabled = bb.Ground.Checked;
                bb.GroundH.Visible = bb.Ground.Checked;
                if (bb.Card != null) { bb.Card.PerformLayout(); bb.Card.Invalidate(); }
                if (!loadingB) RecalcBudget();
            };
            tip.SetToolTip(b.Ground, Lang.T("Antenna fissa sull'orizzonte (senza rotore di elevazione): aggiunge al guadagno il\n\"ground gain\" dovuto alla riflessione sul terreno, calcolato all'elevazione della Luna.\nModello: terreno piano e riflettente, polarizzazione orizzontale (massimo +6 dB)."));
            tip.SetToolTip(b.GroundH, Lang.T("Altezza del centro elettrico dell'antenna sopra il terreno (m).\nDetermina gli angoli dei lobi: il primo lobo è a asin(λ/4h). Con 0 si applica +6 dB fisso."));
            b.Schema.AddRange(new Control[] { b.Tant, b.CavoAnt, b.LenAnt, b.Rele, b.ConnTx, b.ConnRx, b.P, b.CavoPa, b.LenPa, b.PreGain, b.Nf, b.CavoDis, b.LenDis, b.TvOn, b.TvMod, b.TvGain, b.TvNf, b.TvCavo, b.Mds, b.Modo, b.SnReq });

            PannelloDisegno card = new PannelloDisegno();
            card.Dock = DockStyle.Fill;
            card.Margin = new Padding(S(4), S(4), S(6), S(4));
            card.Tag = "carta";
            card.Controls.Add(b.GAnt); card.Controls.Add(b.NAnt); card.Controls.Add(b.Ground); card.Controls.Add(b.GroundH);
            b.Card = card;
            card.Layout += (s, e) => DisponiStazione(bb);
            card.Paint += (s, e) => DisegnaStazione(e.Graphics, bb, title, colore);
            return card;
        }

        float StazRiga(BudgetUi u) { return Math.Max(S(28), u.GAnt.Height + S(4)); }
        int StazAltezza(BudgetUi u) { return (int)(S(36) + 3 * StazRiga(u) + S(78)); }

        void DisponiStazione(BudgetUi u)
        {
            Control c = u.Card;
            if (c == null) return;
            int pad = S(16), fw = S(86);
            float rh = StazRiga(u), y0 = S(36);
            NumericUpDown[] n = { u.GAnt, u.NAnt };
            for (int k = 0; k < 2; k++)
            {
                n[k].Width = fw;
                n[k].Location = new Point(c.Width - pad - fw, (int)(y0 + k * rh + (rh - n[k].Height) / 2));
            }
            u.Ground.Location = new Point(c.Width - pad - u.Ground.Width + S(2), (int)(y0 + 2 * rh + (rh - u.Ground.Height) / 2));
            u.GroundH.Width = S(70);
            u.GroundH.Location = new Point(u.Ground.Left - S(10) - u.GroundH.Width, (int)(y0 + 2 * rh + (rh - u.GroundH.Height) / 2));
            u.GroundH.Visible = u.Ground.Checked;
        }

        void DisegnaStazione(Graphics g, BudgetUi u, string title, Color col)
        {
            Control c = u.Card;
            PreparaGrafica(g);
            g.Clear(Tema.Back);
            RectangleF r = new RectangleF(S(2), S(2), c.Width - S(6), c.Height - S(7));
            Scheda(g, r, Color.Empty);
            using (GraphicsPath p = Arrotondato(r, S(12)))
            {
                Region old = g.Clip;
                g.SetClip(p, CombineMode.Intersect);
                using (Brush bc = new SolidBrush(col)) g.FillRectangle(bc, r.Left, r.Top, r.Width, S(4));
                g.Clip = old;
            }
            int pad = S(16);
            float rh = StazRiga(u), y0 = S(36);
            using (Font ft = FontPx(Lang.FontUi, S(13), true))
            using (Font fs = FontPx(Lang.FontUi, S(11.5f), false))
            using (Font fl = FontPx(Lang.FontUi, S(13.5f), false))
            using (Font fi = FontPx(Lang.FontUi, S(12.5f), false))
            {
                string tt = title.ToUpper(Lang.Cultura);
                float wt = g.MeasureString(tt, ft).Width;
                Testo(g, tt, ft, col, new RectangleF(r.Left + pad, r.Top + S(10), wt + S(6), S(22)), StringAlignment.Near, StringAlignment.Center);
                Testo(g, u.Sotto, fs, Tema.Muted, new RectangleF(r.Left + pad + wt + S(12), r.Top + S(10), Math.Max(1, r.Width - 2 * pad - wt - S(12)), S(22)), StringAlignment.Far, StringAlignment.Center);
                string[] et = { Lang.T("Guadagno singola antenna"), Lang.T("Numero di antenne"), Lang.T("BETA- antenna senza elevazione") };
                for (int k = 0; k < 3; k++)
                {
                    float wl = r.Width - 2 * pad - S(96) - (k == 2 && u.GroundH.Visible ? u.GroundH.Width + S(10) : 0);
                    Testo(g, et[k], fl, Tema.Fore, new RectangleF(r.Left + pad, y0 + k * rh, Math.Max(1, wl), rh), StringAlignment.Near, StringAlignment.Center);
                }
                float yi = y0 + 3 * rh + S(2);
                string i1 = u.Info1.Text ?? "", d1 = "";
                int ip = i1.LastIndexOf(" (");
                if (ip > 0 && i1.EndsWith(")")) { d1 = i1.Substring(ip + 1); i1 = i1.Substring(0, ip); }
                if (d1.Length > 0) Testo(g, d1, fs, Tema.Muted, new RectangleF(r.Left + pad, yi, r.Width - 2 * pad, S(20)), StringAlignment.Far, StringAlignment.Center);
                Testo(g, i1, fi, Tema.Muted, new RectangleF(r.Left + pad, yi, r.Width - 2 * pad - (d1.Length > 0 ? g.MeasureString(d1, fs).Width + S(8) : 0), S(20)), StringAlignment.Near, StringAlignment.Center);
                using (Brush bi = new SolidBrush(Tema.Accent))
                    g.DrawString(u.Info2.Text ?? "", fi, bi, new RectangleF(r.Left + pad, yi + S(22), r.Width - 2 * pad, Math.Max(1, r.Bottom - yi - S(26))));
            }
        }

        ComboBox ComboCavi()
        {
            Tendina c = new Tendina();
            c.SuCarta = true;
            c.DropDownStyle = ComboBoxStyle.DropDownList;
            c.DropDownWidth = S(380);
            c.MaxDropDownItems = 20;
            RiempiTendinaCavi(c);
            return c;
        }

        // Voce di una tendina dei cavi: il testo e la posizione del cavo in CaviDb.Elenco
        class VoceCavo
        {
            public int I; public string T;
            public override string ToString() { return T; }
        }

        // Le tendine dei cavi sono ordinate per diametro (a parità di diametro, per nome)
        static void RiempiTendinaCavi(ComboBox c)
        {
            c.Items.Clear();
            List<int> ord = new List<int>();
            for (int i = 0; i < CaviDb.Elenco.Count; i++) ord.Add(i);
            ord.Sort((x, y) =>
            {
                int d = CaviDb.Elenco[x].Diam.CompareTo(CaviDb.Elenco[y].Diam);
                if (d != 0) return d;
                d = string.Compare(CaviDb.Elenco[x].Etichetta, CaviDb.Elenco[y].Etichetta, StringComparison.CurrentCultureIgnoreCase);
                return d != 0 ? d : x.CompareTo(y);
            });
            foreach (int i in ord) { VoceCavo v = new VoceCavo(); v.I = i; v.T = CaviDb.Elenco[i].Etichetta; c.Items.Add(v); }
        }

        public static int IndiceCavo(ComboBox c)
        {
            VoceCavo v = c.SelectedItem as VoceCavo;
            return v == null ? -1 : v.I;
        }

        public static void ScegliCavo(ComboBox c, int indice)
        {
            for (int k = 0; k < c.Items.Count; k++)
            {
                VoceCavo v = c.Items[k] as VoceCavo;
                if (v != null && v.I == indice) { c.SelectedIndex = k; return; }
            }
            if (c.Items.Count > 0 && c.SelectedIndex < 0) c.SelectedIndex = 0;
        }

        // Aggiorna l'elenco dei cavi in tutte le tendine (dopo un cavo personalizzato aggiunto o tolto)
        void RicaricaTendineCavi()
        {
            foreach (BudgetUi u in new BudgetUi[] { bMe, bDx })
            {
                if (u == null) continue;
                foreach (ComboBox c in new ComboBox[] { u.CavoAnt, u.CavoPa, u.CavoDis })
                {
                    int i = IndiceCavo(c);
                    loadingB = true;
                    RiempiTendinaCavi(c);
                    ScegliCavo(c, Math.Min(Math.Max(0, i), CaviDb.Elenco.Count - 1));
                    loadingB = false;
                }
            }
            RecalcBudget();
        }

