        // ---- schema dell'impianto: riquadri calcolati dai testi (si adattano a caratteri dal 90 al 150 %)
        RectangleF RAnt, RCavoAnt, RRele, RReleBox, RTx, RLna, RPre, RDis, RTv, RCavetti, RRadio;
        float impRh, impXl;
        TableLayoutPanel budgetRoot;
        int budgetSchemaLarg = 560;   // larghezza dello schema dell'impianto nel Budget EME (unità logiche, separatore trascinabile)
        // riquadri dello schema (0 cavo antenna, 1 relè, 2 TX, 3 preampli, 4 discesa): true = etichetta sopra la casella,
        // quando etichetta e casella non stanno sulla stessa riga (lingue con testi lunghi o finestra stretta)
        readonly bool[] impPila = new bool[5];
        int Linee(int box, int n) { return impPila[box] ? 2 * n : n; }
        int impRadioRighe = 1;
        bool impRadioUna = true;

        bool ModoPersonalizzato(BudgetUi u) { return u != null && u.Modo.SelectedIndex == u.Modo.Items.Count - 1; }

        void PosizionaSchema()
        {
            if (pnlImp == null || pnlImpHost == null || bMe == null || bDx == null) return;
            BudgetUi u = impSel == 0 ? bMe : bDx;
            // si lascia sempre il posto della barra di scorrimento verticale: così non compare mai quella orizzontale
            int W = Math.Max(S(400), pnlImpHost.ClientSize.Width - 2 - (pnlImpHost.VerticalScroll.Visible ? 0 : SystemInformation.VerticalScrollBarWidth));
            float avail = pnlImpHost.ClientSize.Height - 2;
            using (Graphics g = pnlImp.CreateGraphics())
            using (Font ft = FontPx(Lang.FontUi, S(13), true))
            using (Font fl = FontPx(Lang.FontUi, S(13), false))
            using (Font fr = FontPx(Lang.FontUi, S(12), true))
            {
                float pad = S(10);
                float rh = Math.Max(S(27), Math.Max(u.P.Height, u.CavoAnt.Height) + S(4));
                impRh = rh;
                int fn = S(84), fc = S(156), fm = S(170);
                Func<string, float> Lw = t => g.MeasureString(t, fl).Width;
                Func<string, float> Tw = t => g.MeasureString(t, ft).Width;
                // larghezza dei riquadri di destra: etichetta + casella, titolo
                float wR = Math.Max(Lw(Lang.T("Tipo")) + fc, Lw(Lang.T("Lunghezza")) + fn);
                foreach (string t in new string[] { Lang.T("Perdita di inserzione"), Lang.T("Connettori in TX"), Lang.T("Connettori in RX"), Lang.T("Guadagno"), Lang.T("Figura di rumore"), Lang.T("Cavetti fino alla radio") })
                    wR = Math.Max(wR, Lw(t) + fn);
                wR += 2 * pad + S(14);
                foreach (string t in new string[] { Lang.T("CAVO ANTENNA – RELÈ") + "  " + Lang.T("TX e RX"), Lang.T("RELÈ COASSIALE TX / RX"), Lang.T("PREAMPLIFICATORE"), Lang.T("CAVO DI DISCESA") })
                    wR = Math.Max(wR, Tw(t) + 2 * pad);
                wR = Math.Min(Math.Max(wR, W * 0.38f), W * 0.62f);
                float wTx = Math.Max(Lw(Lang.T("Potenza in uscita")) + fn, Math.Max(Lw(Lang.T("Cavo PA – relè")) + fc, Lw(Lang.T("Lunghezza")) + fn)) + 2 * pad + S(14);
                wTx = Math.Max(wTx, Tw(Lang.T("TRASMETTITORE · PA")) + 2 * pad);
                float spazio = W - S(16) - wR - S(80);   // tra il riquadro TX e quelli di destra passa la linea con il relè
                if (wTx > spazio) wTx = Math.Max(S(150), spazio);
                float xMin = S(8) + wTx + S(20), xMax = W - S(8) - wR - S(40);
                impXl = xMax >= xMin ? (xMin + xMax) / 2f : xMax;
                float xR = W - S(8) - wR;
                Func<string, float, float> Fh = (t, w) => string.IsNullOrEmpty(t) ? 0f : g.MeasureString(t, fr, (int)Math.Max(10, w - 2 * pad)).Height + S(4);
                // per ogni riquadro: etichetta e casella sulla stessa riga solo se ci stanno
                Func<string[], int[], float> Serve = (et, cw) =>
                {
                    float m = 0;
                    for (int k = 0; k < et.Length; k++) m = Math.Max(m, Lw(et[k]) + S(12) + cw[k]);
                    return m + 2 * pad;
                };
                impPila[0] = Serve(new string[] { Lang.T("Tipo"), Lang.T("Lunghezza") }, new int[] { fc, fn }) > wR;
                impPila[1] = Serve(new string[] { Lang.T("Perdita di inserzione"), Lang.T("Connettori in TX"), Lang.T("Connettori in RX") }, new int[] { fn, fn, fn }) > wR;
                impPila[2] = Serve(new string[] { Lang.T("Potenza in uscita"), Lang.T("Cavo PA – relè"), Lang.T("Lunghezza") }, new int[] { fn, fc, fn }) > wTx;
                impPila[3] = Serve(new string[] { Lang.T("Guadagno"), Lang.T("Figura di rumore") }, new int[] { fn, fn }) > wR;
                impPila[4] = Serve(new string[] { Lang.T("Tipo"), Lang.T("Lunghezza") }, new int[] { fc, fn }) > wR;
                float hCa = S(26) + Linee(0, 2) * rh + Fh(impCavoAnt, wR) + S(6);
                float hRe = S(26) + Linee(1, 3) * rh + Fh(impConn, wR) + S(6);
                float hTx = S(26) + Linee(2, 3) * rh + Fh(impTx, wTx) + S(6);
                float hPre = S(26) + Linee(3, 2) * rh + Fh(impPre, wR) + S(6);
                float hDis = S(26) + Linee(4, 2) * rh + Fh(impDis, wR) + S(6);
                float hTv = S(32) + 2 * rh + S(6);
                float hCav = rh + S(14);
                impRadioUna = 2 * pad + Lw(Lang.T("MDS della radio")) + fn + S(24) + Lw(Lang.T("Modo · S/N richiesto")) + fm + S(10) <= W - S(16);
                impRadioRighe = (impRadioUna ? 1 : 2) + (ModoPersonalizzato(u) ? 1 : 0);
                float hRad = S(26) + impRadioRighe * rh + Fh(impRadio, W - S(16)) + S(6);
                float hAnt = S(84);
                float extra = 0;
                for (int giro = 0; giro < 2; giro++)
                {
                    RAnt = new RectangleF(S(8), S(44), W - S(16), hAnt);
                    RCavoAnt = new RectangleF(xR, RAnt.Bottom + S(10) + extra, wR, hCa);
                    RReleBox = new RectangleF(xR, RCavoAnt.Bottom + S(14) + extra, wR, hRe);
                    RRele = new RectangleF(impXl - S(30), RReleBox.Top, S(60), S(60));
                    float relFondo = Math.Max(RRele.Bottom, RReleBox.Bottom);
                    RTx = new RectangleF(S(8), relFondo + S(44) + extra, wTx, hTx);
                    RPre = new RectangleF(xR, Math.Max(RTx.Top + S(64), relFondo + S(60)), wR, hPre);
                    RLna = new RectangleF(impXl - S(22), RPre.Top + (hPre - S(40)) / 2f, S(44), S(40));
                    RDis = new RectangleF(xR, Math.Max(RPre.Bottom, RTx.Bottom) + S(50) + extra, wR, hDis);
                    RTv = new RectangleF(S(8), RDis.Bottom + S(22) + extra, W - S(16), hTv);
                    RCavetti = new RectangleF(xR, RTv.Bottom + S(22) + extra, wR, hCav);
                    RRadio = new RectangleF(S(8), RCavetti.Bottom + S(22) + extra, W - S(16), hRad);
                    float tot = RRadio.Bottom + S(10);
                    if (giro == 0 && avail > tot) extra = (avail - tot) / 7f;   // lo schema riempie tutto il riquadro
                    else break;
                }
                int H = (int)Math.Max(RRadio.Bottom + S(10), avail);
                if (pnlImp.Size != new Size(W, H)) pnlImp.Size = new Size(W, H);

                foreach (BudgetUi v in new BudgetUi[] { bMe, bDx })
                {
                    Campo(v.Tant, RAnt.Right - fn, RAnt.Top + S(18), fn, rh);
                    Riga2(v.CavoAnt, RCavoAnt, 0, fc, 0); Riga2(v.LenAnt, RCavoAnt, 1, fn, 0);
                    Riga2(v.Rele, RReleBox, 0, fn, 1); Riga2(v.ConnTx, RReleBox, 1, fn, 1); Riga2(v.ConnRx, RReleBox, 2, fn, 1);
                    Riga2(v.P, RTx, 0, fn, 2); Riga2(v.CavoPa, RTx, 1, fc, 2); Riga2(v.LenPa, RTx, 2, fn, 2);
                    Riga2(v.PreGain, RPre, 0, fn, 3); Riga2(v.Nf, RPre, 1, fn, 3);
                    Riga2(v.CavoDis, RDis, 0, fc, 4); Riga2(v.LenDis, RDis, 1, fn, 4);
                    v.TvOn.Location = new Point((int)(RTv.Left + pad), (int)(RTv.Top + S(6)));
                    float xm = RTv.Left + pad + Lw(Lang.T("Modello")) + S(12);
                    Campo(v.TvMod, xm, RTv.Top + S(30), (int)Math.Min(S(330), RTv.Right - pad - xm), rh);
                    Campo(v.TvGain, RTv.Left + pad + Lw(Lang.T("Guadagno")) + S(12), RTv.Top + S(30) + rh, fn, rh);
                    Campo(v.TvNf, RTv.Right - pad - fn, RTv.Top + S(30) + rh, fn, rh);
                    Campo(v.TvCavo, RCavetti.Right - pad - fn, RCavetti.Top + (RCavetti.Height - rh) / 2f, fn, rh);
                    float yr = RRadio.Top + S(26);
                    Campo(v.Mds, RRadio.Left + pad + Lw(Lang.T("MDS della radio")) + S(12), yr, fn, rh);
                    Campo(v.Modo, RRadio.Right - pad - fm, impRadioUna ? yr : yr + rh, fm, rh);
                    Campo(v.SnReq, RRadio.Right - pad - fn, yr + (impRadioUna ? 1 : 2) * rh, fn, rh);
                }
            }
            pnlImp.Invalidate();
        }

        // controllo nella riga k di un riquadro, allineato a destra
        void Riga2(Control c, RectangleF r, int k, int w, int box)
        {
            int wl = (int)Math.Min(w, r.Width - S(20));
            int riga = impPila[box] ? 2 * k + 1 : k;
            Campo(c, r.Right - S(10) - wl, r.Top + S(26) + riga * impRh, wl, impRh);
        }

        void Campo(Control c, float x, float y, int w, float rh)
        {
            if (c.Width != w) c.Width = w;
            Point p = new Point((int)x, (int)(y + (rh - c.Height) / 2f));
            if (c.Location != p) c.Location = p;
        }

        void MostraSchema()
        {
            if (bMe == null || bDx == null) return;
            foreach (BudgetUi u in new BudgetUi[] { bMe, bDx })
            {
                bool vis = (u == bMe) == (impSel == 0);
                foreach (Control c in u.Schema) c.Visible = vis;
                u.SnReq.Visible = vis && ModoPersonalizzato(u);   // la soglia si scrive a mano solo nel modo personalizzato
            }
            PosizionaSchema();
        }

        void Riquadro(Graphics g, RectangleF r, Color c, string titolo, Font ft)
        {
            using (GraphicsPath p = Arrotondato(r, S(9)))
            {
                using (Brush b = new SolidBrush(Tema.Carta)) g.FillPath(b, p);
                using (Pen pn = new Pen(c, S(2))) g.DrawPath(pn, p);
            }
            if (titolo != null) Testo(g, titolo, ft, c, new RectangleF(r.Left + S(10), r.Top + S(4), r.Width - S(16), S(22)), StringAlignment.Near, StringAlignment.Center);
        }

        // etichetta della riga k: a sinistra della casella (larga wc) o, se il riquadro è stretto, sulla riga sopra
        void Etichetta(Graphics g, string t, RectangleF r, int k, Font f, int box, int wc)
        {
            bool pila = impPila[box];
            float w = pila ? r.Width - S(20) : Math.Max(S(20), r.Width - S(20) - wc - S(6));
            Testo(g, t, f, Tema.Fore, new RectangleF(r.Left + S(10), r.Top + S(26) + (pila ? 2 * k : k) * impRh, w, impRh), StringAlignment.Near, StringAlignment.Center);
        }

        // testo colorato in fondo al riquadro, sotto le righe dei campi
        void Piede(Graphics g, string t, Font f, Color c, RectangleF r, int righe)
        {
            if (string.IsNullOrEmpty(t)) return;
            float y = r.Top + S(26) + righe * impRh + S(1);
            using (Brush b = new SolidBrush(c)) g.DrawString(t, f, b, new RectangleF(r.Left + S(10), y, r.Width - S(20), Math.Max(1, r.Bottom - y - S(2))));
        }

        void DisegnaImpianto(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            PreparaGrafica(g);
            g.Clear(Tema.Back);
            impZone.Clear();
            Color cAnt = Color.FromArgb(31, 111, 209), cTx = Color.FromArgb(217, 119, 6), cRx = Color.FromArgb(91, 63, 168), cRad = Color.FromArgb(23, 128, 61), cLinea = Color.FromArgb(55, 65, 81);
            if (Tema.Scuro) cLinea = Color.FromArgb(190, 198, 210);
            float W = pnlImp.Width;
            using (Font ft = FontPx(Lang.FontUi, S(13), true))
            using (Font fl = FontPx(Lang.FontUi, S(13), false))
            using (Font fr = FontPx(Lang.FontUi, S(12), true))
            using (Font fs = FontPx(Lang.FontUi, S(14), true))
            using (Font fp = FontPx(Lang.FontUi, S(11), false))
            {
                // titolo e scelta della stazione
                string[] nomi = { Lang.T("La mia stazione"), Lang.T("Stazione DX") };
                float w1 = g.MeasureString(nomi[1], ft).Width + S(18), w0 = g.MeasureString(nomi[0], ft).Width + S(18);
                Testo(g, Lang.T("IMPIANTO DI TRASMISSIONE E RICEZIONE"), fs, Tema.Scuro ? Tema.Fore : Color.FromArgb(25, 65, 127),
                    new RectangleF(S(10), S(8), Math.Max(1, W - w0 - w1 - S(36)), S(28)), StringAlignment.Near, StringAlignment.Center);
                for (int i = 1; i >= 0; i--)
                {
                    RectangleF r = i == 1 ? new RectangleF(W - S(10) - w1, S(10), w1, S(26)) : new RectangleF(W - S(16) - w1 - w0, S(10), w0, S(26));
                    using (GraphicsPath p = Arrotondato(r, S(13)))
                    {
                        using (Brush b = new SolidBrush(i == impSel ? cAnt : Tema.Carta)) g.FillPath(b, p);
                        using (Pen pn = new Pen(i == impSel ? cAnt : Tema.Linea)) g.DrawPath(pn, p);
                    }
                    Testo(g, nomi[i], ft, i == impSel ? Color.White : Tema.Fore, r, StringAlignment.Center, StringAlignment.Center);
                    impZone.Add(new KeyValuePair<RectangleF, int>(r, i));
                }
                float xl = impXl, rh = impRh;
                // antenna: schiera di yagi, Tant a destra con il cielo dietro la Luna
                Testo(g, impAnt, ft, cAnt, new RectangleF(RAnt.Left + S(2), RAnt.Top - S(4), RAnt.Width * 0.62f, S(22)), StringAlignment.Near, StringAlignment.Near);
                float ya = RAnt.Top + S(44), xa = RAnt.Left + S(10);
                using (Pen pa = new Pen(cAnt, S(3)))
                {
                    g.DrawLine(pa, xa, ya, xa + S(200), ya);
                    for (int k = 0; k < 7; k++) { float xx = xa + S(10) + k * S(30); g.DrawLine(pa, xx, ya - S(18), xx, ya + S(18)); }
                }
                Testo(g, "Tant", fl, Tema.Fore, new RectangleF(RAnt.Right - S(84) - S(60), RAnt.Top + S(18), S(56), rh), StringAlignment.Far, StringAlignment.Center);
                Testo(g, impTsky, fp, Tema.Muted, new RectangleF(RAnt.Left + RAnt.Width * 0.45f, RAnt.Top + S(20) + rh, RAnt.Width * 0.55f, S(20)), StringAlignment.Far, StringAlignment.Near);
                float xf = xa + S(30);   // punto di alimentazione della schiera
                using (Pen pl = new Pen(cLinea, S(4)))
                {
                    g.DrawLine(pl, xf, ya, xf, RAnt.Bottom);
                    g.DrawLine(pl, xf, RAnt.Bottom, xl, RAnt.Bottom);
                    g.DrawLine(pl, xl, RAnt.Bottom, xl, RRele.Top);
                    g.DrawLine(pl, xl + S(16), RRele.Bottom, xl + S(16), RLna.Top);           // RX verso il preampli
                    g.DrawLine(pl, xl, RTv.Bottom, xl, RRadio.Top);
                }
                using (Brush bf = new SolidBrush(cTx)) g.FillRectangle(bf, xf - S(5), ya - S(5), S(10), S(10));
                using (Pen ptx = new Pen(cTx, S(4)))
                {
                    float xt = RTx.Left + RTx.Width * 0.5f, yt = RRele.Bottom + S(18);
                    g.DrawLine(ptx, xl - S(16), RRele.Bottom, xl - S(16), yt);
                    g.DrawLine(ptx, xl - S(16), yt, xt, yt);
                    g.DrawLine(ptx, xt, yt, xt, RTx.Top);
                }
                // relè
                using (GraphicsPath p = Arrotondato(RRele, S(6)))
                {
                    using (Brush b = new SolidBrush(Tema.Carta)) g.FillPath(b, p);
                    using (Pen pn = new Pen(cLinea, S(2))) g.DrawPath(pn, p);
                }
                using (Pen pc = new Pen(cRad, S(3)))
                {
                    g.DrawLine(pc, xl, RRele.Top + S(12), xl + S(14), RRele.Bottom - S(14));
                    using (Brush b = new SolidBrush(cLinea)) { g.FillEllipse(b, xl - S(4), RRele.Top + S(8), S(8), S(8)); g.FillEllipse(b, xl - S(20), RRele.Bottom - S(18), S(8), S(8)); g.FillEllipse(b, xl + S(12), RRele.Bottom - S(18), S(8), S(8)); }
                }
                Testo(g, "TX", fp, cTx, new RectangleF(xl - S(50), RRele.Bottom + S(2), S(28), S(16)), StringAlignment.Far, StringAlignment.Near);
                Testo(g, "RX", fp, cRx, new RectangleF(xl + S(24), RRele.Bottom + S(2), S(28), S(16)), StringAlignment.Near, StringAlignment.Near);
                // cavo di discesa ondulato, dal preampli al transverter
                using (Pen pw = new Pen(cLinea, S(4)))
                {
                    float y0 = RLna.Bottom, y1 = RTv.Top;
                    g.DrawLine(pw, xl + S(16), y0, xl + S(16), y0 + S(10));
                    g.DrawBezier(pw, xl + S(16), y0 + S(10), xl - S(40), y0 + (y1 - y0) * 0.35f, xl + S(40), y0 + (y1 - y0) * 0.65f, xl, y1);
                }
                // preampli (triangolo)
                PointF[] tri = { new PointF(xl + S(16) - RLna.Width / 2f, RLna.Top), new PointF(xl + S(16) + RLna.Width / 2f, RLna.Top), new PointF(xl + S(16), RLna.Bottom) };
                using (Brush b = new SolidBrush(Tema.Scuro ? Tema.Carta : Color.FromArgb(230, 238, 255))) g.FillPolygon(b, tri);
                using (Pen pn = new Pen(cAnt, S(2))) g.DrawPolygon(pn, tri);
                Testo(g, "LNA", FontDx(fp), cAnt, new RectangleF(tri[0].X, RLna.Top + S(3), RLna.Width, S(16)), StringAlignment.Center, StringAlignment.Near);

                // riquadri
                Riquadro(g, RCavoAnt, cLinea, Lang.T("CAVO ANTENNA – RELÈ"), ft);
                float wca = g.MeasureString(Lang.T("CAVO ANTENNA – RELÈ"), ft).Width;
                if (g.MeasureString(Lang.T("TX e RX"), fp).Width <= RCavoAnt.Width - wca - S(20))   // solo se c'è posto accanto al titolo
                    Testo(g, Lang.T("TX e RX"), fp, Tema.Muted, new RectangleF(RCavoAnt.Left + S(10) + wca, RCavoAnt.Top + S(5), Math.Max(1, RCavoAnt.Width - wca - S(20)), S(22)), StringAlignment.Near, StringAlignment.Center);
                Etichetta(g, Lang.T("Tipo"), RCavoAnt, 0, fl, 0, S(156)); Etichetta(g, Lang.T("Lunghezza"), RCavoAnt, 1, fl, 0, S(84));
                Piede(g, impCavoAnt, fr, cAnt, RCavoAnt, Linee(0, 2));
                Riquadro(g, RReleBox, cLinea, Lang.T("RELÈ COASSIALE TX / RX"), ft);
                Etichetta(g, Lang.T("Perdita di inserzione"), RReleBox, 0, fl, 1, S(84)); Etichetta(g, Lang.T("Connettori in TX"), RReleBox, 1, fl, 1, S(84)); Etichetta(g, Lang.T("Connettori in RX"), RReleBox, 2, fl, 1, S(84));
                Piede(g, impConn, fr, cLinea, RReleBox, Linee(1, 3));
                Riquadro(g, RTx, cTx, Lang.T("TRASMETTITORE · PA"), ft);
                Etichetta(g, Lang.T("Potenza in uscita"), RTx, 0, fl, 2, S(84)); Etichetta(g, Lang.T("Cavo PA – relè"), RTx, 1, fl, 2, S(156)); Etichetta(g, Lang.T("Lunghezza"), RTx, 2, fl, 2, S(84));
                Piede(g, impTx, fr, cTx, RTx, Linee(2, 3));
                Riquadro(g, RPre, cAnt, Lang.T("PREAMPLIFICATORE"), ft);
                Etichetta(g, Lang.T("Guadagno"), RPre, 0, fl, 3, S(84)); Etichetta(g, Lang.T("Figura di rumore"), RPre, 1, fl, 3, S(84));
                Piede(g, impPre, fr, cAnt, RPre, Linee(3, 2));
                Riquadro(g, RDis, cLinea, Lang.T("CAVO DI DISCESA"), ft);
                Etichetta(g, Lang.T("Tipo"), RDis, 0, fl, 4, S(156)); Etichetta(g, Lang.T("Lunghezza"), RDis, 1, fl, 4, S(84));
                Piede(g, impDis, fr, cAnt, RDis, Linee(4, 2));
                BudgetUi u = impSel == 0 ? bMe : bDx;
                bool tv = u != null && u.TvOn.Checked;
                Color cTv = tv ? cRx : Color.FromArgb(Tema.Scuro ? 110 : 150, cRx);
                Riquadro(g, RTv, cTv, null, ft);
                if (u != null)
                {
                    float xn = u.TvOn.Right + S(6);
                    Testo(g, string.Format(ci, Lang.T("(la radio non lavora direttamente su {0} MHz)"), curBand), fp, Tema.Muted,
                        new RectangleF(xn, RTv.Top + S(6), Math.Max(1, RTv.Right - xn - S(10)), u.TvOn.Height), StringAlignment.Near, StringAlignment.Center);
                    Color ctv = tv ? Tema.Fore : Tema.Muted;
                    Testo(g, Lang.T("Modello"), fl, ctv, new RectangleF(RTv.Left + S(10), RTv.Top + S(30), S(200), rh), StringAlignment.Near, StringAlignment.Center);
                    Testo(g, Lang.T("Guadagno"), fl, ctv, new RectangleF(RTv.Left + S(10), RTv.Top + S(30) + rh, S(200), rh), StringAlignment.Near, StringAlignment.Center);
                    float wnf = g.MeasureString(Lang.T("Figura di rumore"), fl).Width + S(4);
                    Testo(g, Lang.T("Figura di rumore"), fl, ctv, new RectangleF(u.TvNf.Left - S(10) - wnf, RTv.Top + S(30) + rh, wnf, rh), StringAlignment.Far, StringAlignment.Center);
                }
                Riquadro(g, RCavetti, cLinea, null, ft);
                Testo(g, Lang.T("Cavetti fino alla radio"), fl, Tema.Fore, new RectangleF(RCavetti.Left + S(10), RCavetti.Top, RCavetti.Width - S(110), RCavetti.Height), StringAlignment.Near, StringAlignment.Center);
                Riquadro(g, RRadio, cRad, Lang.T("RADIO"), ft);
                float yr = RRadio.Top + S(26);
                Testo(g, Lang.T("MDS della radio"), fl, Tema.Fore, new RectangleF(RRadio.Left + S(10), yr, RRadio.Width * 0.45f, rh), StringAlignment.Near, StringAlignment.Center);
                if (u != null)
                {
                    float wm = g.MeasureString(Lang.T("Modo · S/N richiesto"), fl).Width + S(4);
                    if (impRadioUna) Testo(g, Lang.T("Modo · S/N richiesto"), fl, Tema.Fore, new RectangleF(u.Modo.Left - S(10) - wm, yr, wm, rh), StringAlignment.Far, StringAlignment.Center);
                    else Testo(g, Lang.T("Modo · S/N richiesto"), fl, Tema.Fore, new RectangleF(RRadio.Left + S(10), yr + rh, wm, rh), StringAlignment.Near, StringAlignment.Center);
                    if (ModoPersonalizzato(u))
                        Testo(g, Lang.T("S/N richiesto in 2500 Hz"), fl, Tema.Fore, new RectangleF(RRadio.Left + S(10), yr + (impRadioUna ? 1 : 2) * rh, RRadio.Width * 0.6f, rh), StringAlignment.Near, StringAlignment.Center);
                }
                Piede(g, impRadio, fr, cRad, RRadio, impRadioRighe);
            }
        }

        // Indicatori principali sopra la tabella: il numero grande, l'unità piccola
        void DisegnaKpi(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            PreparaGrafica(g);
            g.Clear(Tema.Back);
            Rectangle cr = pnlKpi.ClientRectangle;
            // prima riga: collegamento, EIRP mia, EIRP del DX; seconda: perdita di tratta e S/N nei due sensi (con il Sole, se calcolato)
            string[] tit = { Lang.T("COLLEGAMENTO POSSIBILE"), Lang.T("EIRP mia").ToUpper(Lang.Cultura), Lang.T("EIRP del DX").ToUpper(Lang.Cultura),
                Lang.T("PERDITA DI TRATTA EME"), Lang.T("S/N io → DX").ToUpper(Lang.Cultura), Lang.T("S/N DX → io").ToUpper(Lang.Cultura) };
            float gap = S(10), w = (cr.Width - 4 * gap) / 3f, h = (cr.Height - 3 * gap) / 2f;
            using (Font fh = FontPx(Lang.FontUi, S(11), false))
            using (Font fv = FontPx(FamigliaNumeri, S(26), true))
            using (Font fu = FontPx(Lang.FontUi, S(14), false))
            using (Font fs = FontPx(Lang.FontUi, S(12), false))
            using (StringFormat tg = (StringFormat)StringFormat.GenericTypographic.Clone())
            {
                tg.FormatFlags |= StringFormatFlags.MeasureTrailingSpaces | StringFormatFlags.NoWrap;
                for (int i = 0; i < 6; i++)
                {
                    RectangleF r = new RectangleF(gap + (i % 3) * (w + gap), gap + (i / 3) * (h + gap), w, h);
                    Color c = kpiC[i].IsEmpty ? Tema.Accent : kpiC[i];
                    Scheda(g, r, c);
                    Testo(g, tit[i], fh, Tema.Muted, new RectangleF(r.Left + S(16), r.Top + S(6), r.Width - S(20), S(18)), StringAlignment.Near, StringAlignment.Near);
                    string v = kpiV[i] ?? "", gr = v, pic = "";
                    int sp = v.IndexOf(' ');
                    if (sp > 0) { gr = v.Substring(0, sp); pic = v.Substring(sp + 1); }
                    float yv = r.Top + S(22);
                    float wg = g.MeasureString(gr, fv, PointF.Empty, tg).Width;
                    using (Brush bv = new SolidBrush(c)) g.DrawString(gr, fv, bv, r.Left + S(16), yv, tg);
                    if (pic.Length > 0)
                    {
                        // unità allineata alla base del numero
                        float base1 = fv.FontFamily.GetCellAscent(fv.Style) * fv.Size / fv.FontFamily.GetEmHeight(fv.Style);
                        float base2 = fu.FontFamily.GetCellAscent(fu.Style) * fu.Size / fu.FontFamily.GetEmHeight(fu.Style);
                        using (Brush bu = new SolidBrush(Tema.Fore))
                            g.DrawString(pic, fu, bu, new RectangleF(r.Left + S(16) + wg + S(8), yv + base1 - base2, Math.Max(1, r.Width - wg - S(30)), fu.Height + S(2)), tg);
                    }
                    Testo(g, kpiS[i] ?? "", fs, Tema.Muted, new RectangleF(r.Left + S(16), r.Bottom - S(22), r.Width - S(20), S(20)), StringAlignment.Near, StringAlignment.Near);
                }
            }
        }

        // Tabella del Budget EME disegnata: intestazione maiuscola, fasce TRASMISSIONE / PERCORSO / RICEZIONE, valori colorati
        float TabBRiga { get { return S(25); } }

        void DimensionaTabB()
        {
            if (pnlTabB == null || pnlTabHost == null || lvB == null) return;
            int n = lvB.Items.Count;
            int h = (int)(S(16) + S(30) + n * TabBRiga + S(16));
            int w = pnlTabHost.ClientSize.Width;
            if (h > pnlTabHost.ClientSize.Height) w -= SystemInformation.VerticalScrollBarWidth;
            Size sz = new Size(Math.Max(S(300), w), Math.Max(h, pnlTabHost.ClientSize.Height));
            if (pnlTabB.Size != sz) pnlTabB.Size = sz;
            pnlTabB.Invalidate();
        }

        void DisegnaTabB(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            PreparaGrafica(g);
            g.Clear(Tema.Back);
            if (lvB == null) return;
            Rectangle cr = pnlTabB.ClientRectangle;
            float hTot = S(16) + S(30) + lvB.Items.Count * TabBRiga + S(10);
            RectangleF card = new RectangleF(S(4), S(4), cr.Width - S(12), Math.Min(cr.Height - S(8), hTot));
            Scheda(g, card, Color.Empty);
            Color blu = Color.FromArgb(25, 65, 127);
            using (GraphicsPath p = Arrotondato(card, S(12)))
            {
                Region old = g.Clip;
                g.SetClip(p, CombineMode.Intersect);
                using (Brush bc = new SolidBrush(blu)) g.FillRectangle(bc, card.Left, card.Top, card.Width, S(4));
                g.Clip = old;
            }
            float x = card.Left + S(16), w = card.Width - S(32);
            float[] cx = { x, x + w * 0.46f, x + w * 0.73f, x + w };
            Color riga = Tema.Scuro ? Color.FromArgb(60, 68, 80) : Color.FromArgb(232, 236, 242);
            Color fascia = Tema.Scuro ? Tema.Section : Color.FromArgb(232, 238, 248);
            using (Font fh = FontPx(Lang.FontUi, S(11), true))
            using (Font fr = FontPx(Lang.FontUi, S(13), false))
            using (Font fb = FontPx(Lang.FontUi, S(13), true))
            using (Font fz = FontPx(Lang.FontUi, S(11), true))
            using (Pen pl = new Pen(riga))
            {
                float y = card.Top + S(14);
                for (int k = 0; k < 3; k++)
                    Testo(g, lvB.Columns[k].Text.ToUpper(Lang.Cultura), fh, Tema.Muted, new RectangleF(cx[k], y, cx[k + 1] - cx[k] - S(6), S(26)), StringAlignment.Near, StringAlignment.Center);
                y += S(28);
                using (Pen ph = new Pen(Tema.Scuro ? Tema.Linea : Color.FromArgb(200, 208, 220), S(1.5f))) g.DrawLine(ph, x - S(4), y, x + w + S(4), y);
                float rh = TabBRiga;
                foreach (ListViewItem it in lvB.Items)
                {
                    bool sez = (it.Tag as string) == "sez";
                    if (sez)
                    {
                        using (Brush bf = new SolidBrush(fascia)) g.FillRectangle(bf, x - S(6), y + S(2), w + S(12), rh - S(3));
                        string t = it.Text.Trim().Replace("   (", " · ").Replace("  (", " · ");
                        if (t.EndsWith(")") && t.IndexOf(" · ", StringComparison.Ordinal) > 0) t = t.Substring(0, t.Length - 1);
                        Testo(g, t.ToUpper(Lang.Cultura), fz, Tema.Scuro ? Tema.Fore : blu, new RectangleF(x, y + S(2), w, rh - S(3)), StringAlignment.Near, StringAlignment.Center);
                    }
                    else
                    {
                        Font f = it.Font != null && it.Font.Bold ? fb : fr;
                        Testo(g, it.Text, f, Tema.Fore, new RectangleF(cx[0], y, cx[1] - cx[0] - S(8), rh), StringAlignment.Near, StringAlignment.Center);
                        for (int k = 1; k < 3 && k < it.SubItems.Count; k++)
                        {
                            Color cv = it.SubItems[k].ForeColor;
                            if (cv == Tema.FieldFore || cv.IsEmpty) cv = Tema.Fore;
                            Testo(g, it.SubItems[k].Text, f, cv, new RectangleF(cx[k], y, cx[k + 1] - cx[k] - S(6), rh), StringAlignment.Near, StringAlignment.Center);
                        }
                        g.DrawLine(pl, x - S(4), y + rh, x + w + S(4), y + rh);
                    }
                    y += rh;
                }
            }
        }

        static double Sn2500(double sn, double bw) { return sn + 10.0 * Math.Log10(bw / 2500.0); }

        // Testi dello schema e degli indicatori, ricalcolati con il budget
        void AggiornaSchemaEKpi(BudgetParams pm, BudgetParams pd, Riga r, Tratta a, Tratta b, double path, double pol, double bw, bool valido)
        {
            BudgetParams p = impSel == 0 ? pm : pd;
            double f = curBand;
            CultureInfo c = ci;
            string nomeAnt = p.CavoAnt >= 0 && p.CavoAnt < CaviDb.Elenco.Count ? CaviDb.Elenco[(int)p.CavoAnt].Nome : "";
            string nomeDis = p.CavoDis >= 0 && p.CavoDis < CaviDb.Elenco.Count ? CaviDb.Elenco[(int)p.CavoDis].Nome : "";
            double gt = p.GAnt + 10.0 * Math.Log10(p.NAnt);
            impAnt = Lang.T("ANTENNA") + " · " + p.NAnt + " × " + p.GAnt.ToString("F1", c) + " dBi = " + gt.ToString("F1", c) + " dBi";
            impCavoAnt = (nomeAnt.Length > 0 ? (p.LossAnt / Math.Max(0.001, p.LenAnt) * 100).ToString("F1", c) + " dB/100 m · " : "") + string.Format(c, "{0} MHz → {1:F2} dB", f, p.LossAnt);
            double txTot = p.CavoTx + p.AccTx;
            if (p.LossConn > 0 || p.LossConnRx > 0)
            {
                impTx = string.Format(c, Lang.T("cavo {0:F2} + relè {1:F2} + antenna {2:F2} + connettori {3:F2} = {4:F2} dB → {5} all'antenna"), p.LossPa, p.Rele, p.LossAnt, p.LossConn, txTot, FmtW(p.P * Math.Pow(10.0, -txTot / 10.0), c));
                impPre = string.Format(c, Lang.T("prima del preampli: {0:F2} + {1:F2} + connettori {2:F2} = {3:F2} dB"), p.LossAnt, p.Rele, p.LossConnRx, p.PreLoss);
                impConn = string.Format(c, Lang.T("TX {0} × {1:F2} dB = {2:F2} dB · RX {3} × {1:F2} dB = {4:F2} dB prima del preampli"), (int)Math.Round(p.ConnTx), BudgetParams.DbConnettore, p.LossConn, (int)Math.Round(p.ConnRx), p.LossConnRx);
            }
            else
            {
                impTx = string.Format(c, Lang.T("cavo {0:F2} + relè {1:F2} + antenna {2:F2} = {3:F2} dB → {4} all'antenna"), p.LossPa, p.Rele, p.LossAnt, txTot, FmtW(p.P * Math.Pow(10.0, -txTot / 10.0), c));
                impPre = string.Format(c, Lang.T("prima del preampli: {0:F2} + {1:F2} = {2:F2} dB"), p.LossAnt, p.Rele, p.PreLoss);
                impConn = "";
            }
            impDis = (nomeDis.Length > 0 ? (p.LossDis / Math.Max(0.001, p.LenDis) * 100).ToString("F1", c) + " dB/100 m · " : "") + string.Format(c, "{0} MHz → {1:F2} dB", f, p.LossDis);
            double nr, nft = NfFriis(p, bw, out nr);
            double te = 290.0 * (Math.Pow(10.0, nft / 10.0) - 1.0);
            impTsky = "";
            if (valido)
            {
                Tratta t = impSel == 0 ? b : a;   // tratta in cui questa stazione riceve
                double sn25 = Sn2500(t.SNb, bw);
                impTsky = string.Format(c, Lang.T("Tsky dietro la Luna {0:F0} K"), t.Tsky);
                impRadio = string.Format(c, Lang.T("Catena di ricezione (Friis): NF {0:F2} dB · Te {1:F0} K · NF radio dal MDS {2:F1} dB"), nft, te, nr) + "\n"
                    + string.Format(c, Lang.T("S/N {0} dB in {1:0} Hz · {2} dB in 2500 Hz (soglia tipica {3}: {4} dB)"), Segno(t.SNb, c), bw, Segno(sn25, c), p.NomeModo, p.SnReq.ToString("0.#", c));
            }
            else impRadio = string.Format(c, Lang.T("Catena di ricezione (Friis): NF {0:F2} dB · Te {1:F0} K · NF radio dal MDS {2:F1} dB"), nft, te, nr);
            foreach (KeyValuePair<BudgetUi, BudgetParams> kv in new KeyValuePair<BudgetUi, BudgetParams>[] {
                new KeyValuePair<BudgetUi, BudgetParams>(bMe, pm), new KeyValuePair<BudgetUi, BudgetParams>(bDx, pd) })
            {
                BudgetParams q = kv.Value;
                double tx = q.CavoTx + q.AccTx;
                kv.Key.Info1.Text = string.Format(c, Lang.T("Potenza {0} · perdite TX {1:F1} dB (dallo schema)"), FmtW(q.P, c), tx);
                kv.Key.Info2.Text = string.Format(c, Lang.T("Guadagno totale {0} × {1:F1} dBi = {2:F1} dBi · trasmissione e ricezione: schema a destra →"), q.NAnt, q.GAnt, q.GAnt + 10.0 * Math.Log10(q.NAnt));
            }
            // indicatori
            if (!valido)
            {
                for (int i = 0; i < 6; i++) { kpiV[i] = "–"; kpiS[i] = ""; kpiC[i] = Tema.Muted; }
                kpiS[0] = Lang.T("servono i locator delle due stazioni");
            }
            else
            {
                kpiV[0] = r.Ok ? Lang.T("SÌ") : Lang.T("NO");
                kpiS[0] = r.Ok ? Lang.T("Luna puntabile da entrambe") : Lang.T("la Luna non è puntabile da entrambe");
                kpiC[0] = r.Ok ? Tema.OkFg : Tema.BadFg;
                double e1 = Math.Pow(10.0, a.EirpDbW / 10.0), e2 = Math.Pow(10.0, b.EirpDbW / 10.0);
                kpiV[1] = FmtW(e1, c) + " · " + a.EirpDbW.ToString("F1", c) + " dBW";
                kpiS[1] = string.Format(c, Lang.T("{0} all'antenna (perdite TX {1:F1} dB) · {2:F1} dBi"), FmtW(a.PantW, c), a.LossTx, a.Gtx);
                kpiC[1] = Color.FromArgb(31, 111, 209);
                kpiV[2] = FmtW(e2, c) + " · " + b.EirpDbW.ToString("F1", c) + " dBW";
                kpiS[2] = string.Format(c, Lang.T("{0} all'antenna (perdite TX {1:F1} dB) · {2:F1} dBi"), FmtW(b.PantW, c), b.LossTx, b.Gtx);
                kpiC[2] = Color.FromArgb(217, 119, 6);
                kpiV[3] = path.ToString("F1", c) + " dB";
                kpiS[3] = chkPol.Checked ? string.Format(c, Lang.T("+ {0:F1} dB polarizzazione (Dpol {1:F0}°)"), pol, r.Dpol) : string.Format(c, Lang.T("polarizzazione non inclusa (Dpol {0:F0}°)"), r.Dpol);
                kpiC[3] = Color.FromArgb(107, 114, 128);
                KpiSn(a, b, bw, false);
                kpiC[4] = Color.FromArgb(15, 139, 141);
                kpiC[5] = Color.FromArgb(91, 63, 168);
            }
            // titolo delle schede delle stazioni: locator e posizione della Luna
            bMe.Sotto = (me != null && me.Ok ? me.Loc.Text.Trim() : "") + (valido && r != null ? string.Format(c, " · " + Lang.T("Luna") + " Az {0:F1}° El {1:F1}°", r.P.Az, r.P.El) : "");
            bDx.Sotto = (dx != null && dx.Ok && chkDx.Checked ? dx.Loc.Text.Trim() : "") + (valido && r != null ? string.Format(c, " · " + Lang.T("Luna") + " Az {0:F1}° El {1:F1}°", r.Q.Az, r.Q.El) : "");
            foreach (BudgetUi bu in new BudgetUi[] { bMe, bDx }) if (bu.Card != null) bu.Card.Invalidate();
            if (pnlKpi != null) pnlKpi.Invalidate();
            PosizionaSchema();   // i testi in fondo ai riquadri possono cambiare il numero di righe
        }

        static string Segno(double v, CultureInfo c) { return (v >= 0 ? "+" : "−") + Math.Abs(v).ToString("F1", c); }

        // S/N nei due sensi nella banda passante scelta (con il Sole quando è calcolato), con il valore riportato a 2500 Hz
        void KpiSn(Tratta a, Tratta b, double bw, bool sole)
        {
            CultureInfo c = ci;
            Tratta[] t = { a, b };
            for (int i = 0; i < 2; i++)
            {
                kpiV[4 + i] = Segno(t[i].SNb, c) + " dB";
                kpiS[4 + i] = string.Format(c, sole ? Lang.T("in {0:0} Hz con il Sole · {1} dB in 2500 Hz") : Lang.T("in {0:0} Hz · {1} dB in 2500 Hz"), bw, Segno(Sn2500(t[i].SNb, bw), c));
            }
            if (pnlKpi != null) pnlKpi.Invalidate();
        }


