        bool RigaSelezionata(out DateTime t)
        {
            t = DateTime.MinValue;
            if (lv.SelectedIndices.Count == 0 || lv.SelectedIndices[0] >= mostrate.Count)
            {
                Messaggio(this, Lang.T("Seleziona prima una riga nella tabella della linguetta \"Posizione della Luna\"."),
                    "YAEC", MessageBoxButtons.OK, MessageBoxIcon.Information);
                return false;
            }
            DateTime u = mostrate[lv.SelectedIndices[0]].Utc;
            t = new DateTime(u.Year, u.Month, u.Day, u.Hour, u.Minute, 0, DateTimeKind.Unspecified);
