            if (!RigaSelezionata(out t)) return;
            dtpB.Value = t;
            RecalcBudget();
        }

        static string FmtW(double w, CultureInfo c)
        {
            if (w >= 1e9) return (w / 1e9).ToString("F2", c) + " GW";
            if (w >= 1e6) return (w / 1e6).ToString("F2", c) + " MW";
            if (w >= 1e3) return (w / 1e3).ToString("F2", c) + " kW";
            if (w >= 10) return w.ToString("F0", c) + " W";
            return w.ToString("F2", c) + " W";
        }

        string Db(double v) { return v.ToString("F1", ci) + " dB"; }
        string Dbm(double v) { return v.ToString("F1", ci) + " dBm"; }
        string Dbw(double v) { return v.ToString("F1", ci) + " dBW"; }

        class Tratta
        {
            public double PdBW, LossTx, PantW, Gtx, EirpDbW, Grx, Sant, S1, S2, S3, S4, S5, MdsAnt, Margin, Mds;
            public double GgTx, GgRx, Extra, Tant, TskyEcc;
            public double Tsky, Tsun, Tr, Tloss, Tsys, Bw, Nb, SNb, NfTot, NfRadio;
        }

        const double KBOLTZ = 1.380649e-23;

        static double NoiseDbm(double tsys, double bw)
        {
            return 10.0 * Math.Log10(KBOLTZ * tsys * bw) + 30.0;
        }

        // Guadagno dovuto al terreno ("ground gain") per un'antenna a polarizzazione orizzontale
        // senza elevazione, alta h metri sopra un terreno piano e riflettente (coefficiente -1):
        // G = 20·log|2·sin(2π·h·sin(El)/λ)|, massimo +6 dB sui lobi. Con h = 0 si applica +6 dB fisso.
        public static double GroundGain(double hM, double elDeg, double fMHz)
        {
            if (hM <= 0) return 6.02;
            double el = Math.Max(0.05, elDeg);
            double lambda = 299.792458 / fMHz;
            double g = Math.Abs(2.0 * Math.Sin(2.0 * Math.PI * hM * Math.Sin(el * Math.PI / 180.0) / lambda));
            if (g < 0.01) g = 0.01;
            return 20.0 * Math.Log10(g);
        }

        // Elevazione del primo lobo di riflessione (gradi)
        public static double PrimoLobo(double hM, double fMHz)
        {
            if (hM <= 0) return double.NaN;
            double x = (299.792458 / fMHz) / (4.0 * hM);
            return x >= 1 ? 90.0 : Math.Asin(x) * 180.0 / Math.PI;
        }

        // tsky = cielo dietro la Luna visto dal ricevitore, tsun = temperatura aggiunta dal Sole (0 se ignorata),
        // ggTx/ggRx = ground gain delle due antenne, extra = altre perdite di tratta, bw = banda passante (Hz)
        public static double TskyRif(double freq) { return (200.0 - 2.7) * Math.Pow(144.0 / freq, 2.6) + 2.7; }

        static Tratta CalcTratta(BudgetParams tx, BudgetParams rx, double path, double pol, double tsky, double tsun,
            double bw, double ggTx, double ggRx, double extra, double freq)
        {
            Tratta t = new Tratta();
            t.GgTx = ggTx; t.GgRx = ggRx; t.Extra = extra; t.Bw = bw;
            t.PdBW = 10.0 * Math.Log10(tx.P);
            t.LossTx = tx.CavoTx + tx.AccTx;
            t.PantW = tx.P * Math.Pow(10.0, -t.LossTx / 10.0);
            t.Gtx = tx.GAnt + 10.0 * Math.Log10(tx.NAnt) + ggTx;
            t.EirpDbW = t.PdBW - t.LossTx + t.Gtx;
            t.Grx = rx.GAnt + 10.0 * Math.Log10(rx.NAnt) + ggRx;
            t.Sant = t.EirpDbW + 30.0 - path - pol - extra + t.Grx;
            t.S1 = t.Sant - rx.PreLoss;
            t.S2 = t.S1 + rx.PreGain;
            t.S3 = t.S2 - rx.PostLoss;
            t.S4 = t.S3 + rx.TvGain;
            t.S5 = t.S4 - rx.TvCavo;   // dopo i cavetti tra transverter e radio = ingresso della radio
            t.Mds = rx.Mds;
            t.MdsAnt = rx.Mds - (-rx.PreLoss + rx.PreGain - rx.PostLoss + rx.TvGain - rx.TvCavo);
            t.Margin = t.S5 - rx.Mds;
            // Rumore di sistema riferito ai morsetti dell'antenna: Tant (cielo + Sole) + temperatura
            // equivalente del ricevitore completo, con la formula di Friis (HP/Agilent AN 57-1)
            t.Tsky = tsky;
            t.Tsun = tsun;
            t.Tr = 290.0 * (Math.Pow(10.0, rx.Nf / 10.0) - 1.0);
            double nfRadio;
            t.NfTot = NfFriis(rx, bw, out nfRadio);
            t.NfRadio = nfRadio;
            t.Tloss = 290.0 * (Math.Pow(10.0, t.NfTot / 10.0) - 1.0);
            // Tant (tabelle VE7BQH, 30° di elevazione) comprende già un cielo di riferimento; si aggiunge
            // solo l'eccesso del cielo dietro la Luna rispetto a quel riferimento (200 K a 144 MHz, indice 2,6)
            t.Tant = rx.Tant;
            t.TskyEcc = Math.Max(0.0, tsky - TskyRif(freq));
            t.Tsys = t.Tant + t.TskyEcc + tsun + t.Tloss;
            t.Nb = NoiseDbm(t.Tsys, bw);
            t.SNb = t.Sant - t.Nb;
            return t;
        }

        // Figura di rumore complessiva della catena di ricezione (dB), formula di Friis
        // bw = banda passante impostata (Hz), usata per ricavare la NF della radio dal suo MDS
        static double NfFriis(BudgetParams rx, double bw, out double nfRadio)
        {
            nfRadio = Math.Max(0.5, rx.Mds + 174.0 - 10.0 * Math.Log10(bw));
            double[] f = {
                Math.Pow(10.0, rx.PreLoss / 10.0), Math.Pow(10.0, rx.Nf / 10.0), Math.Pow(10.0, rx.PostLoss / 10.0),
                rx.TvGain == 0 ? 1.0 : Math.Pow(10.0, rx.TvNf / 10.0), Math.Pow(10.0, rx.TvCavo / 10.0), Math.Pow(10.0, nfRadio / 10.0) };
            double[] g = {
                Math.Pow(10.0, -rx.PreLoss / 10.0), Math.Pow(10.0, rx.PreGain / 10.0), Math.Pow(10.0, -rx.PostLoss / 10.0),
                Math.Pow(10.0, rx.TvGain / 10.0), Math.Pow(10.0, -rx.TvCavo / 10.0), 1.0 };
            double ftot = f[0], gcum = g[0];
            for (int i = 1; i < f.Length; i++)
            {
                ftot += (f[i] - 1.0) / gcum;
                gcum *= g[i];
            }
            return 10.0 * Math.Log10(ftot);
        }

        string GainTxt(BudgetParams b, double gt)
        {
            if (b.NAnt <= 1) return gt.ToString("F1", ci) + " dBi";
            return string.Format(ci, "{0} × {1:F1} dBi = {2:F1} dBi", b.NAnt, b.GAnt, gt);
        }

        string GroundTxt(BudgetParams b, double gg, double el, double f)
        {
            if (b.GroundOn < 0.5) return Lang.T("non attivo (antenna con elevazione)");
            if (b.GroundH <= 0) return string.Format(ci, Lang.T("+{0:F1} dB (valore fisso)"), gg);
            return string.Format(ci, Lang.T("{0}{1:F1} dB  (h {2:0.#} m, El {3:F1}°, 1° lobo a {4:F1}°)"),
                gg >= 0 ? "+" : "", gg, b.GroundH, el, PrimoLobo(b.GroundH, f));
        }

        ListView lvCur;

        void RigaB(string a, string b, string c, Color back, bool bold, Color foreB, Color foreC)
        {
            ListViewItem it = new ListViewItem(a);
            it.UseItemStyleForSubItems = false;
            ListViewItem.ListViewSubItem sb = it.SubItems.Add(b);
            ListViewItem.ListViewSubItem sc = it.SubItems.Add(c);
            Font f = bold ? new Font(lvCur.Font, FontStyle.Bold) : lvCur.Font;
            it.Font = f; sb.Font = f; sc.Font = f;
            it.BackColor = back; sb.BackColor = back; sc.BackColor = back;
            it.ForeColor = Tema.FieldFore;
            sb.ForeColor = foreB; sc.ForeColor = foreC;
            bufB.Add(it);
        }

        void RigaB(string a, string b, string c) { RigaB(a, b, c, Tema.Field, false, Tema.FieldFore, Tema.FieldFore); }
        void SezioneB(string a)
        {
            RigaB(a, "", "", Tema.Section, true, Tema.FieldFore, Tema.FieldFore);
            bufB[bufB.Count - 1].Tag = "sez";
        }

        // Scrive le righe raccolte; con riduci = true per ogni capitolo mostra solo l'intestazione e la riga finale
        void FlushB(bool riduci)
        {
            ListViewItem ultima = null;
            bool inSez = false;
            foreach (ListViewItem it in bufB)
            {
                bool sez = (it.Tag as string) == "sez";
                if (!riduci) { lvCur.Items.Add(it); continue; }
                if (sez)
                {
                    if (ultima != null) lvCur.Items.Add(ultima);
                    ultima = null;
                    lvCur.Items.Add(it);
                    inSez = true;
                }
                else if (inSez) ultima = it;
                else lvCur.Items.Add(it);
            }
            if (riduci && ultima != null) lvCur.Items.Add(ultima);
            bufB.Clear();
        }
        void RigaSN(string a, double x, double y)
        {
            RigaB(a, (x >= 0 ? "+" : "") + Db(x), (y >= 0 ? "+" : "") + Db(y), Tema.SnBg, true,
                x >= 0 ? Tema.OkFg : Tema.BadFg, y >= 0 ? Tema.OkFg : Tema.BadFg);
        }
        static string K(double t) { return t.ToString("F0", CultureInfo.CurrentCulture) + " K"; }

        void RecalcBudget()
        {
            if (lvB == null || loadingB) return;
            FillBudget(lvB, false);
            DimensionaTabB();
            if (lvS != null) FillBudget(lvS, true);
            if (tabs != null && tpExcel != null && tabs.SelectedTab == tpExcel) RiempiExcel();
            RiempiDebug();
        }

        double LeggiBw()
        {
            double v;
            if (cmbBw != null && double.TryParse(cmbBw.Text.Trim(), NumberStyles.Float, inv, out v) && v >= 1 && v <= 100000) return v;
            return 2500;
        }

        void FillBudget(ListView target, bool solar)
        {
            lvCur = target;
            BudgetParams.Freq = curBand;
            BudgetParams pm = BudgetParams.FromUi(bMe), pd = BudgetParams.FromUi(bDx);
            // perdite calcolate dallo schema, mostrate anche nelle caselle (usate dal foglio Export in Excel dei calcoli)
            foreach (KeyValuePair<BudgetUi, BudgetParams> kv in new KeyValuePair<BudgetUi, BudgetParams>[] {
                new KeyValuePair<BudgetUi, BudgetParams>(bMe, pm), new KeyValuePair<BudgetUi, BudgetParams>(bDx, pd) })
            {
                bool lb = loadingB;
                loadingB = true;
                kv.Key.CavoTx.Value = (decimal)Math.Min(60.0, kv.Value.CavoTx); kv.Key.AccTx.Value = (decimal)Math.Min(60.0, kv.Value.AccTx);
                kv.Key.PreLoss.Value = (decimal)Math.Min(60.0, kv.Value.PreLoss); kv.Key.PostLoss.Value = (decimal)Math.Min(60.0, kv.Value.PostLoss);
                loadingB = lb;
            }
            if (target == lvB && (!me.Ok || !chkDx.Checked || !dx.Ok)) AggiornaSchemaEKpi(pm, pd, null, null, null, 0, 0, LeggiBw(), false);

            target.BeginUpdate();
            try
            {
                target.Items.Clear();
                bufB.Clear();
                if (!me.Ok || !chkDx.Checked || !dx.Ok)
                {
                    RigaB(Lang.T("Imposta un locator valido per la tua stazione e attiva la seconda stazione"), "", "");
                    RigaB(Lang.T("nella linguetta \"Posizione della Luna\": servono le posizioni di entrambe."), "", "");
                    return;
                }
                double freq = curBand;
                double bw = LeggiBw();
                double extra = 0;
                DateTime t = DateTime.SpecifyKind(dtpB.Value, DateTimeKind.Utc);
                Riga r = Calcola1(t, true, freq, chkRefr.Checked);
                double path = Moon.PathLoss(freq, r.P.DistTopo, r.Q.DistTopo);
                double pol = chkPol.Checked ? r.PolLoss : 0.0;
                double tskyDx = Moon.Tsky(r.Q.Lambda, freq);   // cielo visto dal DX
                double tskyMe = Moon.Tsky(r.P.Lambda, freq);   // cielo visto da me
                double ggMe = pm.GroundOn > 0.5 ? GroundGain(pm.GroundH, r.P.El, freq) : 0.0;
                double ggDx = pd.GroundOn > 0.5 ? GroundGain(pd.GroundH, r.Q.El, freq) : 0.0;
                Tratta a = CalcTratta(pm, pd, path, pol, tskyDx, 0, bw, ggMe, ggDx, extra, freq);   // io -> DX
                Tratta b = CalcTratta(pd, pm, path, pol, tskyMe, 0, bw, ggDx, ggMe, extra, freq);   // DX -> io
                if (target == lvB) AggiornaSchemaEKpi(pm, pd, r, a, b, path, pol, bw, true);
                // Rumore solare (stesso calcolo della linguetta "Rumore solare")
                SolarInfo sa = null, sb = null;
                Tratta a2 = null, b2 = null;
                if (lvS != null && (complessi || solar))
                {
                    sa = CalcSolar(t, r.Q, dx, pd, freq, false);  // ricevitore = DX
                    sb = CalcSolar(t, r.P, me, pm, freq, true);   // ricevitore = io
                    a2 = CalcTratta(pm, pd, path, pol, tskyDx, sa.Valid ? sa.Tsun : 0, bw, ggMe, ggDx, extra, freq);
                    b2 = CalcTratta(pd, pm, path, pol, tskyMe, sb.Valid ? sb.Tsun : 0, bw, ggDx, ggMe, extra, freq);
                }
                bool ground = pm.GroundOn > 0.5 || pd.GroundOn > 0.5;

                SezioneB(Lang.T("TRASMISSIONE  (") + curBand.ToString(inv) + " MHz)");
                RigaB(Lang.T("Potenza in uscita"), FmtW(pm.P, ci) + "   (" + Dbw(a.PdBW) + ")", FmtW(pd.P, ci) + "   (" + Dbw(b.PdBW) + ")");
                bool conConn = pm.LossConn > 0 || pd.LossConn > 0;
                RigaB(conConn ? Lang.T("Perdite TX (cavo PA–relè + relè + cavo antenna + connettori)") : Lang.T("Perdite TX (cavo PA–relè + relè + cavo antenna)"),
                    string.Format(ci, "{0:F2} + {1:F2} + {2:F2}", pm.LossPa, pm.Rele, pm.LossAnt) + (conConn ? string.Format(ci, " + {0:F2}", pm.LossConn) : "") + " = " + Db(a.LossTx),
                    string.Format(ci, "{0:F2} + {1:F2} + {2:F2}", pd.LossPa, pd.Rele, pd.LossAnt) + (conConn ? string.Format(ci, " + {0:F2}", pd.LossConn) : "") + " = " + Db(b.LossTx));
                RigaB(Lang.T("Potenza all'antenna"), FmtW(a.PantW, ci) + "   (" + Dbw(a.PdBW - a.LossTx) + ")",
                    FmtW(b.PantW, ci) + "   (" + Dbw(b.PdBW - b.LossTx) + ")");
                RigaB(Lang.T("Guadagno antenna TX (in spazio libero)"), GainTxt(pm, a.Gtx - ggMe), GainTxt(pd, b.Gtx - ggDx));
                if (ground)
                {
                    RigaB(Lang.T("BETA - ground gain antenna TX senza elevazione"), GroundTxt(pm, ggMe, r.P.El, freq), GroundTxt(pd, ggDx, r.Q.El, freq));
                    RigaB(Lang.T("Guadagno antenna TX totale"), a.Gtx.ToString("F1", ci) + " dBi", b.Gtx.ToString("F1", ci) + " dBi");
                }
                RigaB("EIRP", FmtW(Math.Pow(10.0, a.EirpDbW / 10.0), ci) + "   (" + Dbw(a.EirpDbW) + ")",
                    FmtW(Math.Pow(10.0, b.EirpDbW / 10.0), ci) + "   (" + Dbw(b.EirpDbW) + ")",
                    Tema.Field, true, Tema.Accent, Tema.Accent);

                SezioneB(Lang.T("PERCORSO TERRA - LUNA - TERRA   (") + FmtDT(t) + " UTC)");
                RigaB(Lang.T("Posizione Luna dalla stazione TX"),
                    string.Format(ci, "Az {0:F1}°  El {1:F1}°  ({2})", r.P.Az, r.P.El, r.StatoMe),
                    string.Format(ci, "Az {0:F1}°  El {1:F1}°  ({2})", r.Q.Az, r.Q.El, r.StatoDx));
                RigaB(Lang.T("Posizione Luna dalla stazione RX"),
                    string.Format(ci, "Az {0:F1}°  El {1:F1}°  ({2})", r.Q.Az, r.Q.El, r.StatoDx),
                    string.Format(ci, "Az {0:F1}°  El {1:F1}°  ({2})", r.P.Az, r.P.El, r.StatoMe));
                RigaB(Lang.T("Distanza Luna: TX / RX"),
                    r.P.DistTopo.ToString("N0", ci) + " km / " + r.Q.DistTopo.ToString("N0", ci) + " km",
                    r.Q.DistTopo.ToString("N0", ci) + " km / " + r.P.DistTopo.ToString("N0", ci) + " km");
                RigaB(Lang.T("Perdita di tratta EME"), Db(path), Db(path), Tema.Field, true, Tema.FieldFore, Tema.FieldFore);
                string polTxt = chkPol.Checked
                    ? string.Format(ci, "{0:F1} dB  (Dpol {1:F0}°)", r.PolLoss, r.Dpol)
                    : string.Format(ci, Lang.T("non inclusa  (Dpol {0:F0}° → {1:F1} dB)"), r.Dpol, r.PolLoss);
                RigaB(Lang.T("Perdita di polarizzazione spaziale"), polTxt, polTxt);
                string fin = r.Ok ? Lang.T("SÌ, finestra comune") : Lang.T("NO: la Luna non è puntabile da entrambe");
                Color cf = r.Ok ? Tema.OkFg : Tema.BadFg;
                RigaB(Lang.T("Collegamento possibile in questo istante"), fin, fin, Tema.Field, true, cf, cf);

                SezioneB(Lang.T("RICEZIONE"));
                RigaB(Lang.T("Guadagno antenna RX (in spazio libero)"), GainTxt(pd, a.Grx - ggDx), GainTxt(pm, b.Grx - ggMe));
                if (ground)
                {
                    RigaB(Lang.T("BETA - ground gain antenna RX senza elevazione"), GroundTxt(pd, ggDx, r.Q.El, freq), GroundTxt(pm, ggMe, r.P.El, freq));
                    RigaB(Lang.T("Guadagno antenna RX totale"), a.Grx.ToString("F1", ci) + " dBi", b.Grx.ToString("F1", ci) + " dBi");
                }
                RigaB(Lang.T("Segnale ai morsetti dell'antenna RX"), Dbm(a.Sant), Dbm(b.Sant));
                RigaB(Lang.T("Dopo le perdite ante preampli"), Dbm(a.S1), Dbm(b.S1));
                RigaB(Lang.T("Dopo il preampli"), Dbm(a.S2), Dbm(b.S2));
                RigaB(Lang.T("Dopo le perdite post preampli"), Dbm(a.S3), Dbm(b.S3));
                RigaB(Lang.T("Dopo il transverter"), Dbm(a.S4), Dbm(b.S4));
                RigaB(Lang.T("Perdita cavetti transverter-radio"), Db(pd.TvCavo), Db(pm.TvCavo));
                RigaB(Lang.T("All'ingresso della radio (dopo i cavetti)"), Dbm(a.S5), Dbm(b.S5),
                    Tema.Field, true, Tema.FieldFore, Tema.FieldFore);
                RigaB(Lang.T("MDS della radio"), Dbm(a.Mds), Dbm(b.Mds));
                RigaB(Lang.T("MDS riportato ai morsetti dell'antenna"), Dbm(a.MdsAnt), Dbm(b.MdsAnt));
                RigaB(Lang.T("Margine sopra il MDS"),
                    (a.Margin >= 0 ? "+" : "") + Db(a.Margin), (b.Margin >= 0 ? "+" : "") + Db(b.Margin),
                    Tema.MarginBg, true,
                    a.Margin >= 0 ? Tema.OkFg : Tema.BadFg, b.Margin >= 0 ? Tema.OkFg : Tema.BadFg);

                string bwTxt = bw.ToString("0", ci) + " Hz";
                SezioneB(Lang.T("RUMORE E RAPPORTO S/N STIMATO  (banda passante ") + bwTxt + ")");
                RigaB(Lang.T("Temperatura del cielo dietro la Luna (Tsky)"), K(a.Tsky), K(b.Tsky));
                RigaB(Lang.T("Temperatura d'antenna Tant (tabelle VE7BQH, 30° di elevazione)"), K(a.Tant), K(b.Tant));
                RigaB(Lang.T("Eccesso del cielo dietro la Luna rispetto al riferimento"), K(a.TskyEcc), K(b.TskyEcc));
                RigaB(Lang.T("Rumore del preampli (NF ") + pd.Nf.ToString("F2", ci) + " / " + pm.Nf.ToString("F2", ci) + " dB)",
                    K(a.Tr), K(b.Tr));
                RigaB(Lang.T("NF della radio stimata dal MDS (banda ") + bwTxt + ")", Db(a.NfRadio), Db(b.NfRadio));
                RigaB(Lang.T("Figura di rumore del ricevitore (Friis, HP/Agilent AN 57-1)"),
                    a.NfTot.ToString("F2", ci) + " dB  (Te " + K(a.Tloss) + ")", b.NfTot.ToString("F2", ci) + " dB  (Te " + K(b.Tloss) + ")",
                    Tema.Field, true, Tema.Accent, Tema.Accent);
                RigaB(Lang.T("Temperatura di sistema Tsys (senza il Sole)"), K(a.Tsys), K(b.Tsys));
                RigaB(Lang.T("Rumore in ") + bwTxt, Dbm(a.Nb), Dbm(b.Nb));
                RigaSN(Lang.T("S/N stimato in ") + bwTxt + Lang.T(" (senza il Sole)"), a.SNb, b.SNb);
                RigaB(string.Format(ci, Lang.T("S/N in 2500 Hz (soglia tipica {0} / {1})"), pd.NomeModo + " " + pd.SnReq.ToString("0.#", ci), pm.NomeModo + " " + pm.SnReq.ToString("0.#", ci) + " dB"),
                    Segno(Sn2500(a.SNb, bw), ci) + " dB", Segno(Sn2500(b.SNb, bw), ci) + " dB");
                if (a2 != null && !solar)
                {
                    RigaB(Lang.T("Tsys con il Sole (dalla linguetta Rumore solare)"), K(a2.Tsys), K(b2.Tsys));
                    RigaSN(Lang.T("S/N in ") + bwTxt + Lang.T(" con il Sole (dalla linguetta Rumore solare)"), a2.SNb, b2.SNb);
                }

                if (solar && a2 != null) AddSolarRows(a, b, a2, b2, sa, sb);
                // gli indicatori S/N del Budget usano l'S/N con il Sole, come l'ultima riga della tabella
                if (target == lvB && a2 != null && sa != null && sb != null && (sa.Valid || sb.Valid)) KpiSn(a2, b2, bw, true);
            }
            finally
            {
                FlushB((target == lvB || (lvX != null && target == lvX)) && !complessi);
                target.EndUpdate();
            }
        }

        // ---------- Linguetta 3 (sperimentale): rumore solare ----------

        internal const string SfuUrlDefault = "https://services.swpc.noaa.gov/json/solar-radio-flux.json";
        static readonly int[] SfuFreqs = { 245, 410, 610, 1415, 2695, 4995, 8800, 15400 };
        List<SfuStation> sfuStations = new List<SfuStation>();
        DateTime sfuDownloaded = DateTime.MinValue;
        string sfuCachePath;
        TextBox txtSfuUrl;
        Pillola btnSfu;
        Label lblSfu;
        CheckBox chkSfuAuto, chkSfuMan;
        ListView lvSfu, lvS;
        ComboBox cmbSfuMe, cmbSfuDx, cmbBand3;
        NumericUpDown nudSlMe, nudSlDx, nudSfuMan;
        DateTimePicker dtpS;
        Label lblSfuEst;
        bool syncing;
        Dictionary<int, double> sfuManual = new Dictionary<int, double>();

        class SolarInfo
        {
            public SfuStation Station;
            public bool Auto, Manual, Valid;
            public double Flux;          // SFU alla frequenza di lavoro
            public string Metodo;
            public double SunAz, SunEl, Sep, Beam, AttDb, Tsun;
            public string Zona;
        }

        // Stazioni della rete RSTN che pubblicano i flussi nel file NOAA SWPC
        // Flusso solare tipico (Sole calmo) per il valore manuale iniziale di ogni banda
        static double SfuPredefinito(int f)
        {
            switch (f)
            {
                case 50: return 3; case 70: return 4; case 144: return 8; case 222: return 14; case 432: return 25; case 1296: return 55; case 2320: return 75;
                case 5760: return 130; case 10368: return 270; case 24048: return 900; case 47088: return 3500;
                case 76032: return 9000; default: return 20000;
            }
        }

        static List<SfuStation> StazioniNote()
        {
            List<SfuStation> l = new List<SfuStation>();
            l.Add(new SfuStation("San Vito", Lang.T("San Vito dei Normanni (Italia)"), 40.65, 17.70));
            l.Add(new SfuStation("Learmonth", Lang.T("Learmonth (Australia)"), -22.22, 114.10));
            l.Add(new SfuStation("Kaena Point", Lang.T("Kaena Point, Hawaii (USA)"), 21.57, -158.27));
            l.Add(new SfuStation("Sagamore Hill", Lang.T("Sagamore Hill, Massachusetts (USA)"), 42.63, -70.82));
            return l;
        }

        // Fonti del flusso solare: 0 NOAA SWPC rete RSTN (consigliata), 1 NOAA F10.7, 2 Penticton (DRAO) F10.7,
        // 3 Learmonth (Australia, BoM): flussi del Sole quieto pubblicati ogni giorno alle 07:30 UT, 4 indirizzo personalizzato (formato RSTN)
        internal const string SfuUrlLearmonth = "https://listserver.ips.gov.au/pipermail/ips-iflux-dailyvalues/";
        const int SfuPersonale = 4;
        static readonly string[] SfuFontiUrl = { SfuUrlDefault, "https://services.swpc.noaa.gov/json/f107_cm_flux.json",
            "https://www.spaceweather.gc.ca/solar_flux_data/daily_flux_values/fluxtable.txt", SfuUrlLearmonth, "" };
        static readonly string[] SfuFontiCache = { "solar-radio-flux.json", "f107_cm_flux.json", "fluxtable.txt", "learmonth-iflux.html", "solar-radio-flux-personale.json" };

        // voce della tendina delle fonti: testo corto (casella chiusa), parte in grassetto e resto (elenco aperto)
        class VoceFonte
        {
            public string Corta, Grassetto, Resto;
            public VoceFonte(string corta, string grassetto, string resto) { Corta = corta; Grassetto = grassetto; Resto = resto; }
            public override string ToString() { return Corta; }
        }
        ComboBox cmbSfuFonte;
        PannelloDisegno pnlSfuKpi, pnlSfuSpettro;
        SolarInfo sfuInfoMe, sfuInfoDx;
        double sfuDbMe = double.NaN, sfuDbDx = double.NaN;
        static readonly Color[] ColStazioni = { Color.FromArgb(204, 51, 68), Color.FromArgb(31, 119, 180), Color.FromArgb(44, 160, 90), Color.FromArgb(230, 140, 20),
            Color.FromArgb(130, 80, 190), Color.FromArgb(120, 120, 120), Color.FromArgb(0, 150, 160), Color.FromArgb(180, 100, 60) };

        int FonteSfu { get { return cmbSfuFonte == null ? 0 : Math.Max(0, cmbSfuFonte.SelectedIndex); } }
        string CacheSfu { get { return Path.Combine(Path.GetDirectoryName(settingsPath), SfuFontiCache[FonteSfu]); } }

        void BuildSolarTab(TabPage tp)
        {
            sfuStations = StazioniNote();
            sfuCachePath = Path.Combine(Path.GetDirectoryName(settingsPath), "solar-radio-flux.json");
            foreach (int f in Bande) sfuManual[f] = SfuPredefinito(f);

            TableLayoutPanel root = new TableLayoutPanel();
            root.Dock = DockStyle.Fill;
            root.ColumnCount = 2;
            root.RowCount = 4;
            root.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 55f));
            root.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 45f));
            root.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            root.RowStyles.Add(new RowStyle(SizeType.Absolute, S(112)));
            root.RowStyles.Add(new RowStyle(SizeType.Percent, 62f));
            root.RowStyles.Add(new RowStyle(SizeType.Percent, 38f));
            root.Padding = new Padding(S(4));

            // Barra: banda e istante (sincronizzati con la linguetta Budget EME)
            FlowLayoutPanel bar = new FlowLayoutPanel();
            bar.AutoSize = true;
            bar.AutoSizeMode = AutoSizeMode.GrowAndShrink;
            bar.Dock = DockStyle.Fill;
            cmbBand3 = new Tendina();
            cmbBand3.DropDownStyle = ComboBoxStyle.DropDownList;
            foreach (int f in bandeAttive) cmbBand3.Items.Add(NomeBanda(f));
            cmbBand3.SelectedIndex = bandeAttive.IndexOf(curBand);
            cmbBand3.Width = S(120);
            cmbBand3.SelectedIndexChanged += (s, e) =>
            {
                if (!syncing && !ricostruzioneBande && cmbBand3.SelectedIndex >= 0) cmbBand.SelectedIndex = cmbBand3.SelectedIndex;
            };
            dtpS = new DateTimePicker();
            dtpS.Format = DateTimePickerFormat.Custom;
            dtpS.CustomFormat = "dd/MM/yyyy  HH:mm";
            dtpS.Width = S(150);
            dtpS.Value = dtpB.Value;
            dtpS.ValueChanged += (s, e) => { if (!syncing) dtpB.Value = dtpS.Value; };
            Pillola bNow = new Pillola(Lang.T("Adesso").ToUpper(Lang.Cultura), StilePillola.Pieno, ColPillola, new Font(Lang.FontUi, 9F * fontFactor, FontStyle.Bold));
            bNow.Margin = new Padding(S(6), S(2), S(3), S(2));
            bNow.Click += (s, e) => { dtpB.Value = NowUtcMinute(); RecalcBudget(); };
            Pillola bRow = new Pillola(Lang.T("Usa la riga della tabella").ToUpper(Lang.Cultura), StilePillola.Pieno, ColPillola, new Font(Lang.FontUi, 9F * fontFactor, FontStyle.Bold));
            bRow.Margin = new Padding(S(3), S(2), S(3), S(2));
            bRow.Click += (s, e) => UsaRigaSelezionata();
            Label nb = L(Lang.T("   Parametri delle stazioni: quelli della linguetta \"Budget EME\"."));
            nb.ForeColor = Tema.Muted;
            bar.Controls.Add(L(Lang.T("Banda"))); bar.Controls.Add(cmbBand3);
            bar.Controls.Add(L(Lang.T("Istante (UTC)"))); bar.Controls.Add(dtpS); bar.Controls.Add(bNow); bar.Controls.Add(bRow);
            bar.Controls.Add(nb);
            root.Controls.Add(bar, 0, 0);
            root.SetColumnSpan(bar, 2);

            // indicatori
            pnlSfuKpi = new PannelloDisegno();
            pnlSfuKpi.Dock = DockStyle.Fill;
            pnlSfuKpi.Paint += DisegnaSfuKpi;
            root.Controls.Add(pnlSfuKpi, 0, 1);
            root.SetColumnSpan(pnlSfuKpi, 2);

            // a sinistra: fonte dei dati e scelte per il calcolo
            TableLayoutPanel sx = new TableLayoutPanel();
            sx.Dock = DockStyle.Fill;
            sx.ColumnCount = 1; sx.RowCount = 2;
            sx.RowStyles.Add(new RowStyle(SizeType.Percent, 100f));
            sx.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            sx.Margin = new Padding(0);
            TableLayoutPanel gd = new TableLayoutPanel();
            gd.Dock = DockStyle.Fill;
            gd.ColumnCount = 1;
            gd.RowCount = 3;
            gd.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            gd.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            gd.RowStyles.Add(new RowStyle(SizeType.Percent, 100f));
            FlowLayoutPanel fu = new FlowLayoutPanel();
            fu.AutoSize = true;
            fu.AutoSizeMode = AutoSizeMode.GrowAndShrink;
            fu.Dock = DockStyle.Fill;
            cmbSfuFonte = new Tendina();
            cmbSfuFonte.DropDownStyle = ComboBoxStyle.DropDownList;
            cmbSfuFonte.Items.AddRange(new object[] {
                new VoceFonte(Lang.T("NOAA SWPC · rete RSTN, 245 – 15400 MHz (consigliata)"), "NOAA SWPC · " + Lang.T("rete RSTN, 245 – 15400 MHz"), " " + Lang.T("(consigliata: 4 stazioni, 8 frequenze)")),
                new VoceFonte(Lang.T("NOAA SWPC · F10.7 (2800 MHz), stima grossolana"), "NOAA SWPC · " + Lang.T("solo F10.7"), " " + Lang.T("(2800 MHz, Penticton): il resto dello spettro è stimato")),
                new VoceFonte(Lang.T("Penticton (Canada, DRAO) · F10.7 (2800 MHz), stima grossolana"), Lang.T("Penticton DRAO (Canada)") + " · F10.7", " " + Lang.T("osservato, tre misure al giorno")),
                new VoceFonte(Lang.T("Learmonth (Australia, BoM) · Sole quieto, 8 frequenze"), Lang.T("Learmonth (Australia, BoM)"), " · " + Lang.T("Sole quieto, 8 frequenze")),
                new VoceFonte(Lang.T("Indirizzo personalizzato (formato RSTN)"), Lang.T("Indirizzo personalizzato…"), " " + Lang.T("(file JSON nel formato SWPC)")) });
            cmbSfuFonte.SelectedIndex = 0;
            cmbSfuFonte.Width = S(390);
            cmbSfuFonte.DropDownWidth = S(560);
            cmbSfuFonte.DrawMode = DrawMode.OwnerDrawFixed;
            cmbSfuFonte.ItemHeight = S(22);
            cmbSfuFonte.DrawItem += (s, e) =>
            {
                e.DrawBackground();
                if (e.Index < 0) return;
                VoceFonte v = cmbSfuFonte.Items[e.Index] as VoceFonte;
                bool sel = (e.State & DrawItemState.Selected) != 0;
                Color ct = sel ? SystemColors.HighlightText : cmbSfuFonte.ForeColor;
                TextFormatFlags tf = TextFormatFlags.VerticalCenter | TextFormatFlags.Left | TextFormatFlags.NoPadding | TextFormatFlags.SingleLine;
                Rectangle r = new Rectangle(e.Bounds.X + S(4), e.Bounds.Y, e.Bounds.Width - S(6), e.Bounds.Height);
                if (v == null || (e.State & DrawItemState.ComboBoxEdit) != 0)
                {
                    TextRenderer.DrawText(e.Graphics, cmbSfuFonte.Items[e.Index].ToString(), cmbSfuFonte.Font, r, ct, tf | TextFormatFlags.EndEllipsis);
                    return;
                }
                using (Font fb = new Font(cmbSfuFonte.Font, FontStyle.Bold))
                {
                    int wb = TextRenderer.MeasureText(e.Graphics, v.Grassetto, fb, r.Size, tf).Width;
                    TextRenderer.DrawText(e.Graphics, v.Grassetto, fb, r, ct, tf);
                    TextRenderer.DrawText(e.Graphics, v.Resto, cmbSfuFonte.Font, new Rectangle(r.X + wb, r.Y, Math.Max(1, r.Width - wb), r.Height), ct, tf | TextFormatFlags.EndEllipsis);
                }
            };
            tip.SetToolTip(cmbSfuFonte, Lang.T("La rete RSTN misura il Sole da 245 a 15400 MHz: il flusso a 50 – 432 MHz si ricava dalle misure più basse. Con il solo F10.7 (2800 MHz) il flusso alle frequenze basse è stimato in proporzione a un Sole calmo tipico: è una stima grossolana, da confrontare con il valore manuale."));
            txtSfuUrl = new TextBox();
            txtSfuUrl.Width = S(390);
            txtSfuUrl.Text = SfuUrlDefault;
            txtSfuUrl.ReadOnly = true;
            tip.SetToolTip(txtSfuUrl, Lang.T("Indirizzo del file con i flussi solari. Si modifica solo con \"Indirizzo personalizzato\"."));
            cmbSfuFonte.SelectedIndexChanged += (s, e) =>
            {
                int k = FonteSfu;
                txtSfuUrl.ReadOnly = k != SfuPersonale;
                if (k != SfuPersonale) txtSfuUrl.Text = SfuFontiUrl[k];
                CaricaCacheSfu();
                RecalcBudget();
                if (!caricamento) SaveSettings();
            };
            btnSfu = new Pillola("⟳ " + Lang.T("Aggiorna dal web").ToUpper(Lang.Cultura), StilePillola.Pieno, Color.FromArgb(31, 111, 209), new Font(Lang.FontUi, 9F * fontFactor, FontStyle.Bold));
            btnSfu.Margin = new Padding(S(6), S(1), S(3), S(1));
            btnSfu.Click += (s, e) => ScaricaSfu();
            chkSfuAuto = new Spunta();
            chkSfuAuto.Text = Lang.T("all'avvio");
            chkSfuAuto.AutoSize = true;
            chkSfuAuto.Checked = true;
            chkSfuAuto.Margin = new Padding(S(10), S(6), S(3), S(3));
            tip.SetToolTip(chkSfuAuto, Lang.T("Aggiorna all'avvio"));
            lblSfu = L(Lang.T("Nessun dato: premi \"Aggiorna dal web\"."));
            lblSfu.ForeColor = Tema.OkFg;
            fu.Controls.Add(cmbSfuFonte); fu.Controls.Add(btnSfu); fu.Controls.Add(chkSfuAuto);
            fu.SetFlowBreak(chkSfuAuto, true);
            fu.Controls.Add(txtSfuUrl); fu.Controls.Add(lblSfu);
            gd.Controls.Add(fu, 0, 0);
            Label altre = L(Lang.T("Altre fonti nel menu: NOAA F10.7 · Penticton (Canada) · Learmonth (Australia) · indirizzo personalizzato."));
            altre.ForeColor = Tema.Muted;
            altre.MaximumSize = new Size(S(700), 0);
            gd.Controls.Add(altre, 0, 1);
            lvSfu = new DBListView();
            lvSfu.Dock = DockStyle.Fill;
            lvSfu.View = View.Details;
