            foreach (int f in SfuFreqs) lvSfu.Columns.Add(f.ToString(inv), S(50), HorizontalAlignment.Right);
            gd.Controls.Add(lvSfu, 0, 2);
            sx.Controls.Add(SchedaCampi(Lang.T("FONTE DEI DATI"), Color.FromArgb(25, 65, 127), gd, null, true), 0, 0);

            // Scelte per il calcolo
            TableLayoutPanel gc;
            Group(Lang.T("SCELTE PER IL CALCOLO"), 4, out gc);
            cmbSfuMe = new Tendina();
            cmbSfuDx = new Tendina();
