        {
            DSez(titolo);
            double lambda = 299.792458 / freq;
            DPasso(Lang.T("Potenza in uscita"), "P_{dBW} = 10 · log_{10} P", "10 · log_{10} " + Fd(tx.P, "0.###"), Fd(t.PdBW, "0.00") + " dBW");
            if (tx.LossConn > 0)
                DPasso(Lang.T("Perdite TX (cavo PA–relè + relè + cavo antenna + connettori)"), "L_{TX} = L_{PA} + L_{relè} + L_{ant} + n_{conn} · " + Fd(BudgetParams.DbConnettore, "0.00"), Fd(tx.LossPa, "0.00") + " + " + Fd(tx.Rele, "0.00") + " + " + Fd(tx.LossAnt, "0.00") + " + " + Fd(tx.ConnTx, "0") + " · " + Fd(BudgetParams.DbConnettore, "0.00"), Fd(t.LossTx, "0.00") + " dB");
            else
