            {
                Color fc = pnlGrigi.BackColor.GetBrightness() < 0.5f ? Color.FromArgb(226, 232, 240) : Color.FromArgb(29, 36, 51);
                foreach (Label l in new Label[] { l1, l2, lblOpacita, lblTonoPunt }) l.ForeColor = fc;
            };
