            puntTimer.Start();
        }

        // I limiti cambiati in altre linguette ridisegnano la mappa
        void AgganciaLimitiPunt()
        {
            foreach (NumericUpDown n in new NumericUpDown[] { me.Az1, me.Az2, me.El1, me.El2 })
                n.ValueChanged += (s, e) => { if (pnlPunt != null) pnlPunt.Invalidate(); };
            me.Loc.TextChanged += (s, e) => { puntPercorsoT0 = DateTime.MinValue; if (pnlPunt != null) pnlPunt.Invalidate(); };
        }

        // Senza locator la mappa si centra su JJ00AA: un clic sceglie il locator a 10 caratteri del punto
        int puntZoomVuoto = 3;
        double PuntCLat { get { double la, lo; if (me.Ok) return me.Lat; Locator.TryParse("JJ00AA", out la, out lo); return la; } }
        double PuntCLon { get { double la, lo; if (me.Ok) return me.Lon; Locator.TryParse("JJ00AA", out la, out lo); return lo; } }
        int PuntZ { get { return Math.Min(me.Ok ? puntZoom : puntZoomVuoto, PuntProv.MaxZoom); } }

        void DisegnaPuntVuota(Graphics g, int W, int H)
        {
            TileProvider prov = PuntProv;
            int z = PuntZ, n = 1 << z;
            double ox = LonToX(PuntCLon, z) - W / 2.0, oy = LatToY(PuntCLat, z) - H / 2.0;
            g.Clear(Color.FromArgb(14, 22, 40));
            g.InterpolationMode = InterpolationMode.HighQualityBilinear;
            int tx0 = (int)Math.Floor(ox / 256.0), tx1 = (int)Math.Floor((ox + W) / 256.0);
            int ty0 = Math.Max(0, (int)Math.Floor(oy / 256.0)), ty1 = Math.Min(n - 1, (int)Math.Floor((oy + H) / 256.0));
            for (int ty = ty0; ty <= ty1; ty++)
                for (int tx = tx0; tx <= tx1; tx++)
                {
                    Image img = Tessera(prov, z, ((tx % n) + n) % n, ty, true);
                    if (img != null) g.DrawImage(img, (float)(tx * 256 - ox), (float)(ty * 256 - oy), 256, 256);
                }
            PreparaGrafica(g);
            using (Font f = FontPx(Lang.FontUi, S(15), true))
            {
                string t = Lang.T("Nessun locator inserito: la mappa è centrata su JJ00AA. Clicca il punto della tua stazione per sceglierne il locator a 10 caratteri; con la rotella del mouse cambi lo zoom.");
                RectangleF r = new RectangleF(S(16), S(14), Math.Min(W - S(32), S(760)), S(58));
                using (GraphicsPath gp = Arrotondato(r, S(10)))
                using (Brush b = new SolidBrush(Color.FromArgb(225, 29, 36, 51))) g.FillPath(b, gp);
                Testo(g, t, f, Color.White, new RectangleF(r.X + S(14), r.Y, r.Width - S(28), r.Height), StringAlignment.Near, StringAlignment.Center);
            }
        }

        void CambiaZoomPunt(int d)
        {
            if (!me.Ok)
            {
                puntZoomVuoto = Math.Max(2, Math.Min(PuntProv.MaxZoom, puntZoomVuoto + d));
                if (pnlPunt != null) pnlPunt.Invalidate();
                return;
            }
            puntZoom = Math.Max(3, Math.Min(PuntProv.MaxZoom, puntZoom + d));
            AggiornaZoomPunt();
            if (!caricamento) SaveSettings();
        }

        void AggiornaZoomPunt()
        {
            if (lblPuntZoom != null) lblPuntZoom.Text = "zoom " + puntZoom.ToString(inv);
            if (pnlPunt != null) pnlPunt.Invalidate();
        }

        // Percorso della Luna nelle prossime 24 ore (passo 10 minuti), sorgere e tramonto
        void CalcolaPercorsoPunt(DateTime now)
        {
            DateTime t0 = new DateTime(now.Year, now.Month, now.Day, now.Hour, now.Minute / 10 * 10, 0, DateTimeKind.Utc);
            if (t0 == puntPercorsoT0 && puntPercorso.Count > 0) return;
            puntPercorsoT0 = t0;
            puntPercorso.Clear();
            puntSorgeAz = double.NaN; puntTramAz = double.NaN;
            double ePrec = double.NaN, aPrec = 0;
            for (int i = 0; i <= 144; i++)
            {
                DateTime t = t0.AddMinutes(10 * i);
                MoonPos p = Moon.Compute(t, me.Lat, me.Lon, (double)me.H.Value, chkRefr.Checked);
                puntPercorso.Add(new double[] { p.Az, p.El, i / 6.0 });
                if (!double.IsNaN(ePrec))
                {
                    double f = ePrec / (ePrec - p.El);
                    double az = aPrec + f * (((p.Az - aPrec + 540.0) % 360.0) - 180.0);
                    if (ePrec < 0 && p.El >= 0 && double.IsNaN(puntSorgeAz)) { puntSorgeAz = (az + 360.0) % 360.0; puntSorgeT = t.AddMinutes(-10 * (1 - f)); }
                    if (ePrec >= 0 && p.El < 0 && double.IsNaN(puntTramAz)) { puntTramAz = (az + 360.0) % 360.0; puntTramT = t.AddMinutes(-10 * (1 - f)); }
                }
                ePrec = p.El; aPrec = p.Az;
            }
        }

        static PointF Polare(PointF c, float R, double az, double el)
        {
            double r = R * (90.0 - Math.Max(0.0, Math.Min(90.0, el))) / 90.0;
            double a = az * Math.PI / 180.0;
            return new PointF(c.X + (float)(r * Math.Sin(a)), c.Y - (float)(r * Math.Cos(a)));
        }

        static float RaggioEl(float R, double el) { return (float)(R * (90.0 - Math.Max(0.0, Math.Min(90.0, el))) / 90.0); }

        void DisegnaPunt(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            int W = pnlPunt.ClientSize.Width, H = pnlPunt.ClientSize.Height;
            if (W < 50 || H < 50) return;
            if (!me.Ok) { DisegnaPuntVuota(g, W, H); return; }
            // 1. mappa centrata sulla stazione, disegnata fuori schermo (serve anche per la sfocatura)
            TileProvider prov = PuntProv;
            int z = Math.Min(puntZoom, prov.MaxZoom);
            int n = 1 << z;
            double ox = LonToX(me.Lon, z) - W / 2.0, oy = LatToY(me.Lat, z) - H / 2.0;
            using (Bitmap fondo = new Bitmap(W, H))
            {
                using (Graphics gb = Graphics.FromImage(fondo))
                {
                    gb.Clear(Color.FromArgb(14, 22, 40));
                    gb.InterpolationMode = InterpolationMode.HighQualityBilinear;
                    int tx0 = (int)Math.Floor(ox / 256.0), tx1 = (int)Math.Floor((ox + W) / 256.0);
                    int ty0 = Math.Max(0, (int)Math.Floor(oy / 256.0)), ty1 = Math.Min(n - 1, (int)Math.Floor((oy + H) / 256.0));
                    for (int ty = ty0; ty <= ty1; ty++)
                        for (int tx = tx0; tx <= tx1; tx++)
                        {
                            Image img = Tessera(prov, z, ((tx % n) + n) % n, ty, true);
                            if (img != null) gb.DrawImage(img, (float)(tx * 256 - ox), (float)(ty * 256 - oy), 256, 256);
                        }
                }
                g.DrawImage(fondo, 0, 0, W, H);
                PreparaGrafica(g);

                PointF c = new PointF(W / 2f, H / 2f);
                float R = Math.Min(W, H) * 0.43f;
                double az1 = (double)me.Az1.Value, az2 = (double)me.Az2.Value, el1 = (double)me.El1.Value, el2 = (double)me.El2.Value;
                bool azLibero = az2 - az1 >= 360.0 || az1 == az2;
                float sweep = (float)(((az2 - az1) % 360.0 + 360.0) % 360.0);
                float rOut = RaggioEl(R, el1), rIn = RaggioEl(R, el2);

                // 2. zone fuori dai limiti: mappa sfocata e velo grigio chiaro (si può spegnere)
                if (chkPuntSfuma.Checked)
                using (GraphicsPath disco = new GraphicsPath())
                using (GraphicsPath consentita = new GraphicsPath())
                {
                    disco.AddEllipse(c.X - R, c.Y - R, 2 * R, 2 * R);
                    if (azLibero) consentita.AddEllipse(c.X - rOut, c.Y - rOut, 2 * rOut, 2 * rOut);
                    else if (sweep > 0) consentita.AddPie(c.X - rOut, c.Y - rOut, 2 * rOut, 2 * rOut, (float)az1 - 90f, sweep);
                    using (Region fuori = new Region(disco))
                    {
                        if (rOut > 0.5f && (azLibero || sweep > 0))
                        {
                            using (Region ok = new Region(consentita))
                            {
                                if (rIn > 0.5f)
                                    using (GraphicsPath interno = new GraphicsPath())
                                    {
                                        interno.AddEllipse(c.X - rIn, c.Y - rIn, 2 * rIn, 2 * rIn);
                                        ok.Exclude(interno);
                                    }
                                fuori.Exclude(ok);
                            }
                        }
                        Region vecchia = g.Clip;
                        g.Clip = fuori;
                        using (Bitmap piccola = new Bitmap(Math.Max(1, W / 14), Math.Max(1, H / 14)))
                        {
                            using (Graphics gp = Graphics.FromImage(piccola))
                            {
                                gp.InterpolationMode = InterpolationMode.HighQualityBilinear;
                                gp.DrawImage(fondo, 0, 0, piccola.Width, piccola.Height);
                            }
                            g.InterpolationMode = InterpolationMode.HighQualityBilinear;
                            g.DrawImage(piccola, -W / 28f, -H / 28f, W + W / 14f, H + H / 14f);
                        }
                        if (grigioVelo)
                            using (Brush velo = new SolidBrush(Color.FromArgb(grigioOpacita * 255 / 100, GrigioRgb, GrigioRgb, Math.Min(255, GrigioRgb + 6)))) g.FillRegion(velo, fuori);
                        g.Clip = vecchia;
                    }
                }
                // fuori dall'orizzonte la mappa resta visibile ma un po' più scura (solo con il velo grigio)
                if (grigioVelo)
                using (GraphicsPath esterno = new GraphicsPath())
                {
                    esterno.AddRectangle(new RectangleF(0, 0, W, H));
                    esterno.AddEllipse(c.X - R, c.Y - R, 2 * R, 2 * R);
                    using (Brush b = new SolidBrush(Color.FromArgb(70, 0, 0, 0))) g.FillPath(b, esterno);
                }

                // 3. orizzonte, cerchi di elevazione ogni 30°, punti cardinali
                using (Pen ph = new Pen(Color.FromArgb(200, 255, 255, 255), 1.5f)) g.DrawEllipse(ph, c.X - R, c.Y - R, 2 * R, 2 * R);
                using (Pen pe = new Pen(Color.FromArgb(110, 255, 255, 255), 1f))
                {
                    pe.DashStyle = DashStyle.Dot;
                    foreach (int el in new int[] { 30, 60 })
                    {
                        float r = RaggioEl(R, el);
                        g.DrawEllipse(pe, c.X - r, c.Y - r, 2 * r, 2 * r);
                    }
                    g.DrawLine(pe, c.X, c.Y - R, c.X, c.Y + R);
                    g.DrawLine(pe, c.X - R, c.Y, c.X + R, c.Y);
                }
                using (Font fc = FontPx(Lang.FontUi, S(13), true))
                {
                    string[] pc = { "N", "E", "S", Lang.T("O") };
                    for (int i = 0; i < 4; i++)
                    {
                        PointF p = Polare(c, R + S(16), i * 90, 0);
                        RectangleF rb = new RectangleF(p.X - S(11), p.Y - S(11), S(22), S(22));
                        using (Brush b = new SolidBrush(Color.FromArgb(235, 255, 255, 255))) g.FillRectangle(b, rb);
                        Testo(g, pc[i], fc, Color.FromArgb(20, 25, 35), rb, StringAlignment.Center, StringAlignment.Center);
                    }
                }

                // 4. limiti dell'antenna (gialli) con le maniglie
                Color cl = Color.FromArgb(255, 209, 72);
                using (Pen ps = new Pen(Color.FromArgb(150, 0, 0, 0), S(7)))
                using (Pen pl = new Pen(cl, S(4)))
                {
                    ps.StartCap = pl.StartCap = LineCap.Round;
                    ps.EndCap = pl.EndCap = LineCap.Round;
                    foreach (Pen p in new Pen[] { ps, pl })
                    {
                        if (!azLibero)
                        {
                            PointF a1i = Polare(c, R, az1, el2 >= 90 ? 90 : el2), a1o = Polare(c, R, az1, Math.Max(0, el1));
                            PointF a2i = Polare(c, R, az2, el2 >= 90 ? 90 : el2), a2o = Polare(c, R, az2, Math.Max(0, el1));
                            g.DrawLine(p, a1i, a1o);
                            g.DrawLine(p, a2i, a2o);
                            if (sweep > 0)
                            {
                                if (rOut > 1) g.DrawArc(p, c.X - rOut, c.Y - rOut, 2 * rOut, 2 * rOut, (float)az1 - 90f, sweep);
                                if (rIn > 1) g.DrawArc(p, c.X - rIn, c.Y - rIn, 2 * rIn, 2 * rIn, (float)az1 - 90f, sweep);
                            }
                        }
                        else
                        {
                            if (rOut > 1) g.DrawEllipse(p, c.X - rOut, c.Y - rOut, 2 * rOut, 2 * rOut);
                            if (rIn > 1) g.DrawEllipse(p, c.X - rIn, c.Y - rIn, 2 * rIn, 2 * rIn);
                        }
                    }
                }
                double azMezzo = azLibero ? 180.0 : az1 + sweep / 2.0;
                hAz1 = Polare(c, R, az1, 0);
                hAz2 = Polare(c, R, azLibero ? az1 + 1 : az2, 0);
                hEl1 = Polare(c, R, azMezzo, Math.Max(0, el1));
                hEl2 = Polare(c, R, azMezzo, Math.Min(90, el2));
                hEl2Vis = el2 < 90;
                using (Font fh = new Font(Lang.FontUi, 10F, FontStyle.Bold))
                {
                    Maniglia(g, hAz1, cl, Lang.T("Azimut da (°)").Replace("(°)", "").Trim() + " " + az1.ToString("0", ci) + "°", fh);
                    Maniglia(g, hAz2, cl, azLibero ? "" : "→ " + az2.ToString("0", ci) + "°", fh);
                    Maniglia(g, hEl1, cl, "El min " + el1.ToString("0", ci) + "°", fh);
                    if (hEl2Vis) Maniglia(g, hEl2, cl, "El max " + el2.ToString("0", ci) + "°", fh);
                }

                // 5. percorso della Luna, sorgere e tramonto
                DateTime now = DateTime.UtcNow;
                CalcolaPercorsoPunt(now);
                using (Font fs = new Font(Lang.FontUi, 9.5F, FontStyle.Bold))
                {
                    if (!double.IsNaN(puntSorgeAz)) LineaOrizzonte(g, c, R, puntSorgeAz, Color.FromArgb(235, 120, 40), Lang.T("sorge") + " " + OraLoc(puntSorgeT), fs);
                    if (!double.IsNaN(puntTramAz)) LineaOrizzonte(g, c, R, puntTramAz, Color.FromArgb(220, 170, 30), Lang.T("tramonta") + " " + OraLoc(puntTramT), fs);
                    if (chkPuntPercorso.Checked && puntPercorso.Count > 1)
                    {
                        using (Pen ps = new Pen(Color.FromArgb(140, 0, 0, 0), S(7)))
                        using (Pen pp = new Pen(Color.FromArgb(235, 255, 220, 90), S(4)))
                        {
                            ps.StartCap = pp.StartCap = ps.EndCap = pp.EndCap = LineCap.Round;
                            for (int pass = 0; pass < 2; pass++)
                                for (int i = 1; i < puntPercorso.Count; i++)
                                {
                                    double[] p0 = puntPercorso[i - 1], p1 = puntPercorso[i];
                                    if (p0[1] < 0 || p1[1] < 0) continue;
                                    g.DrawLine(pass == 0 ? ps : pp, Polare(c, R, p0[0], p0[1]), Polare(c, R, p1[0], p1[1]));
                                }
                        }
                        // le ore vicine alla Luna di adesso non si scrivono: la sua etichetta resta leggibile
                        MoonPos mpOra = Moon.Compute(now, me.Lat, me.Lon, (double)me.H.Value, chkRefr.Checked);
                        PointF qLuna = Polare(c, R, mpOra.Az, mpOra.El);
                        for (int i = 6; i < puntPercorso.Count; i += 6)
                        {
                            double[] p = puntPercorso[i];
                            if (p[1] < 0) continue;
                            PointF q = Polare(c, R, p[0], p[1]);
                            if (mpOra.El >= 0 && Math.Abs(q.X - qLuna.X) < S(190) && Math.Abs(q.Y - qLuna.Y) < S(44)) continue;
                            using (Brush b = new SolidBrush(Color.White)) g.FillEllipse(b, q.X - S(4), q.Y - S(4), S(8), S(8));
                            using (Pen pn = new Pen(Color.Black, 1.5f)) g.DrawEllipse(pn, q.X - S(4), q.Y - S(4), S(8), S(8));
                            TestoBordato(g, puntPercorsoT0.AddMinutes(10 * i).ToString("HH", inv) + "h", fs, Color.White, q.X + S(6), q.Y - S(8));
                        }
                    }
                }

                // 6. la Luna adesso
                MoonPos mp = Moon.Compute(now, me.Lat, me.Lon, (double)me.H.Value, chkRefr.Checked);
                bool okMe;
                me.Valuta(mp, out okMe);
                int stato = okMe ? 0 : (mp.El < 0 ? 2 : 1);
                Color cs = stato == 0 ? Color.FromArgb(61, 220, 132) : (stato == 1 ? Color.FromArgb(255, 179, 64) : Color.FromArgb(150, 160, 180));
                PointF pm = Polare(c, R, mp.Az, mp.El);
                using (Pen pl = new Pen(Color.FromArgb(200, 255, 230, 120), S(3)))
                {
                    pl.DashStyle = mp.El >= 0 ? DashStyle.Solid : DashStyle.Dash;
                    g.DrawLine(pl, c, pm);
                }
                float rg = S(34);
                using (GraphicsPath alone = new GraphicsPath())
                {
                    alone.AddEllipse(pm.X - rg, pm.Y - rg, 2 * rg, 2 * rg);
                    using (PathGradientBrush pg = new PathGradientBrush(alone))
                    {
                        pg.CenterColor = Color.FromArgb(mp.El >= 0 ? 170 : 70, 255, 245, 200);
                        pg.SurroundColors = new Color[] { Color.FromArgb(0, 255, 245, 200) };
                        g.FillPath(pg, alone);
                    }
                }
                double saz, sel, sra, sdec;
                Moon.SunPos(now, me.Lat, me.Lon, out saz, out sel, out sra, out sdec);
                double elong = Moon.Separation(sra, sdec, mp.Ra, mp.Dec);
                float rmn = S(15);
                DisegnaFase(g, pm, rmn, (1 - Math.Cos(elong * Math.PI / 180.0)) / 2.0, ((mp.Ra - sra + 720.0) % 360.0) < 180.0);
                using (Pen pr = new Pen(cs, S(4))) g.DrawEllipse(pr, pm.X - rmn - S(3), pm.Y - rmn - S(3), 2 * rmn + S(6), 2 * rmn + S(6));
                using (Pen pr = new Pen(Color.Black, 1.5f)) g.DrawEllipse(pr, pm.X - rmn - S(6), pm.Y - rmn - S(6), 2 * rmn + S(12), 2 * rmn + S(12));
                using (Font fm = new Font(Lang.FontUi, 11F, FontStyle.Bold))
                {
                    string tl = string.Format(ci, Lang.T("LUNA  Az {0:F1}° El {1:F1}°"), mp.Az, mp.El);
                    SizeF sz = g.MeasureString(tl, fm);
                    float tx = pm.X + rmn + S(12);
                    if (tx + sz.Width > W - S(6)) tx = pm.X - rmn - S(12) - sz.Width;
                    TestoBordato(g, tl, fm, cs, tx, pm.Y - sz.Height / 2);
                }

                // 7. la mia stazione al centro
                float rs = S(9);
                using (Brush b = new SolidBrush(Color.White)) g.FillEllipse(b, c.X - rs, c.Y - rs, 2 * rs, 2 * rs);
                using (Pen p = new Pen(Color.FromArgb(220, 30, 30), S(3))) g.DrawEllipse(p, c.X - rs, c.Y - rs, 2 * rs, 2 * rs);
                using (Brush b = new SolidBrush(Color.FromArgb(220, 30, 30))) g.FillEllipse(b, c.X - S(3), c.Y - S(3), S(6), S(6));
                string call = txtCall == null ? "" : txtCall.Text.Trim();
                using (Font fm = new Font(Lang.FontUi, 10F, FontStyle.Bold))
                    TestoBordato(g, (call.Length > 0 ? call + "  " : "") + me.Loc.Text.Trim(), fm, Color.White, c.X + rs + S(6), c.Y + S(4));

                // 8. riquadro informativo e attribuzione della mappa
                string[] stTxt = { Lang.T("PUNTABILE"), Lang.T("FUORI LIMITI"), Lang.T("SOTTO L'ORIZZONTE") };
                string info1 = stTxt[stato] + string.Format(ci, "   Az {0:F1}°  El {1:F1}°", mp.Az, mp.El);
                string info2 = azLibero ? Lang.T("nessun limite di azimut") + string.Format(ci, " · El {0:0}° → {1:0}°", el1, el2)
                    : string.Format(ci, Lang.T("Limiti: azimut {0}° → {1}°, elevazione {2}° → {3}°"), az1.ToString("0", ci), az2.ToString("0", ci), el1.ToString("0", ci), el2.ToString("0", ci));
                string info3 = Lang.T("Zone grigie = fuori dai limiti della tua antenna");
                using (Font f1 = FontPx(Lang.FontUi, S(17), true))
                using (Font f2 = FontPx(Lang.FontUi, S(14), false))
                {
                    float wbox = Math.Max(g.MeasureString(info1, f1).Width, Math.Max(g.MeasureString(info2, f2).Width, g.MeasureString(info3, f2).Width)) + S(28);
                    RectangleF rb = new RectangleF(S(12), S(12), wbox, S(86));
                    using (GraphicsPath p = Arrotondato(rb, S(10)))
                    {
                        using (Brush b = new SolidBrush(Color.FromArgb(205, 14, 22, 40))) g.FillPath(b, p);
                        using (Pen pn = new Pen(cs, 2f)) g.DrawPath(pn, p);
                    }
                    Testo(g, info1, f1, cs, new RectangleF(rb.Left + S(14), rb.Top + S(8), wbox, S(26)), StringAlignment.Near, StringAlignment.Center);
                    Testo(g, info2, f2, Color.FromArgb(225, 230, 240), new RectangleF(rb.Left + S(14), rb.Top + S(36), wbox, S(22)), StringAlignment.Near, StringAlignment.Center);
                    Testo(g, info3, f2, Color.FromArgb(170, 180, 200), new RectangleF(rb.Left + S(14), rb.Top + S(58), wbox, S(22)), StringAlignment.Near, StringAlignment.Center);
                }
                using (Font fa = new Font(Lang.FontUi, 7.5F))
                {
                    SizeF sa = g.MeasureString(prov.Attribuzione, fa);
                    using (Brush b = new SolidBrush(Color.FromArgb(170, 255, 255, 255))) g.FillRectangle(b, W - sa.Width - S(6), H - sa.Height - S(4), sa.Width + S(4), sa.Height + S(2));
                    using (Brush b = new SolidBrush(Color.FromArgb(40, 40, 40))) g.DrawString(prov.Attribuzione, fa, b, W - sa.Width - S(4), H - sa.Height - S(3));
                }
            }
        }

        string OraLoc(DateTime utc)
        {
            return TimeZoneInfo.ConvertTimeFromUtc(DateTime.SpecifyKind(utc, DateTimeKind.Utc), TimeZoneInfo.Local).ToString("HH:mm", inv);
        }

        void LineaOrizzonte(Graphics g, PointF c, float R, double az, Color col, string testo, Font f)
        {
            PointF p = Polare(c, R, az, 0);
            using (Pen ps = new Pen(Color.FromArgb(140, 0, 0, 0), S(7))) g.DrawLine(ps, c, p);
            using (Pen pl = new Pen(col, S(4))) g.DrawLine(pl, c, p);
            // scritta oltre il cerchio, lontana dalle caselle dei punti cardinali e sempre dentro la finestra
            SizeF sz = g.MeasureString(testo, f);
            PointF q = Polare(c, R + S(40) + sz.Width / 2, az, 0);
            float tx = q.X - sz.Width / 2, ty = q.Y - sz.Height / 2;
            double resto = ((az % 90.0) + 90.0) % 90.0;
            if (resto < 8 || resto > 82) ty += (q.Y <= c.Y ? -S(18) : S(18));
            tx = Math.Max(S(4), Math.Min(pnlPunt.ClientSize.Width - sz.Width - S(4), tx));
            ty = Math.Max(S(104), Math.Min(pnlPunt.ClientSize.Height - sz.Height - S(20), ty));
            TestoBordato(g, testo, f, col, tx, ty);
        }

        void Maniglia(Graphics g, PointF p, Color col, string testo, Font f)
        {
            float r = S(9);
            using (Brush b = new SolidBrush(col)) g.FillEllipse(b, p.X - r, p.Y - r, 2 * r, 2 * r);
            using (Pen pn = new Pen(Color.FromArgb(30, 30, 30), 2f)) g.DrawEllipse(pn, p.X - r, p.Y - r, 2 * r, 2 * r);
            if (testo.Length > 0) TestoBordato(g, testo, f, col, p.X + r + S(4), p.Y - r - S(14));
        }

        int ManigliaVicina(Point m)
        {
            PointF[] h = { hAz1, hAz2, hEl1, hEl2 };
            int best = 0;
            double dmin = S(14);
            for (int i = 0; i < 4; i++)
            {
                double d = Math.Sqrt((m.X - h[i].X) * (m.X - h[i].X) + (m.Y - h[i].Y) * (m.Y - h[i].Y));
                if (d < dmin) { dmin = d; best = i + 1; }
            }
            return best;
        }

        void PuntMouseDown(object sender, MouseEventArgs e)
        {
            if (e.Button != MouseButtons.Left) return;
            if (!me.Ok) { puntDrag = 0; ProponiLocatorPunt(e.Location); return; }
            puntDrag = ManigliaVicina(e.Location);
            if (puntDrag == 0 && FuoriDalCerchioPunt(e.Location)) ProponiLocatorPunt(e.Location);
        }

        bool FuoriDalCerchioPunt(Point m)
        {
            int W = pnlPunt.ClientSize.Width, H = pnlPunt.ClientSize.Height;
            float R = Math.Min(W, H) * 0.43f;
            double dx0 = m.X - W / 2.0, dy0 = m.Y - H / 2.0;
            return Math.Sqrt(dx0 * dx0 + dy0 * dy0) > R + S(6);
        }

        // Clic fuori dal cerchio dei punti cardinali: locator a 10 caratteri del punto cliccato, segnaposto e domanda
        void ProponiLocatorPunt(Point m)
        {
            int W = pnlPunt.ClientSize.Width, H = pnlPunt.ClientSize.Height;
            int z = PuntZ;
            double ox = LonToX(PuntCLon, z) - W / 2.0, oy = LatToY(PuntCLat, z) - H / 2.0;
            double lon = XToLon(ox + m.X, z), lat = YToLat(oy + m.Y, z);
            lon = ((lon + 180.0) % 360.0 + 360.0) % 360.0 - 180.0;
            string nuovo = Locator.Da(lat, lon, 10);
            puntNuovoOn = true; puntNuovoLat = lat; puntNuovoLon = lon; puntNuovoLoc = nuovo;
            pnlPunt.Refresh();
            bool ok = ChiediSiNo(Lang.T("Cambio del locatore"),
                string.Format(Lang.T("Hai cambiato locatore, a favore di {0}: accetti la modifica?"), nuovo),
                Lang.T("Il nuovo locatore vale per tutti i calcoli del programma; la quota viene cercata di nuovo sul web e la mappa si centra sul nuovo punto."));
            puntNuovoOn = false;
            if (ok && txtTrkLoc != null)
            {
                txtTrkLoc.Text = nuovo;              // aggiorna anche il locator della Posizione della Luna e tutti i calcoli
                if (me.Loc.Text != nuovo) me.Loc.Text = nuovo;
                if (!caricamento) SaveSettings();
            }
            pnlPunt.Invalidate();
        }

        // Segnaposto del punto proposto, sopra la mappa
        void DisegnaNuovoLocPunt(object sender, PaintEventArgs e)
        {
            if (!puntNuovoOn) return;
            Graphics g = e.Graphics;
            PreparaGrafica(g);
            int W = pnlPunt.ClientSize.Width, H = pnlPunt.ClientSize.Height;
            int z = PuntZ;
            double ox = LonToX(PuntCLon, z) - W / 2.0, oy = LatToY(PuntCLat, z) - H / 2.0;
            float x = (float)(LonToX(puntNuovoLon, z) - ox), y = (float)(LatToY(puntNuovoLat, z) - oy);
            Color rosso = Color.FromArgb(220, 38, 38);
            using (Pen pn = new Pen(Color.White, S(3))) { g.DrawLine(pn, x, y, x, y - S(26)); }
            using (Pen pn = new Pen(rosso, S(2))) { g.DrawLine(pn, x, y, x, y - S(26)); }
            using (Brush b = new SolidBrush(rosso)) g.FillEllipse(b, x - S(9), y - S(40), S(18), S(18));
            using (Pen pn = new Pen(Color.White, S(2))) g.DrawEllipse(pn, x - S(9), y - S(40), S(18), S(18));
            using (Brush b = new SolidBrush(Color.FromArgb(120, 0, 0, 0))) g.FillEllipse(b, x - S(4), y - S(2), S(8), S(4));
            using (Font f = FontPx(FamigliaNumeri, S(15), true))
                TestoBordato(g, puntNuovoLoc, f, Color.White, x + S(12), y - S(44));
        }

        void PuntMouseMove(object sender, MouseEventArgs e)
        {
            if (puntDrag == 0)
            {
                pnlPunt.Cursor = !me.Ok ? Cursors.Cross : (ManigliaVicina(e.Location) != 0 ? Cursors.Hand : (FuoriDalCerchioPunt(e.Location) ? Cursors.Cross : Cursors.Default));
                return;
            }
            int W = pnlPunt.ClientSize.Width, H = pnlPunt.ClientSize.Height;
            float R = Math.Min(W, H) * 0.43f;
            double dx0 = e.X - W / 2.0, dy0 = e.Y - H / 2.0;
            double az = Math.Round((Math.Atan2(dx0, -dy0) * 180.0 / Math.PI + 360.0) % 360.0);
            double el = Math.Round(90.0 * (1.0 - Math.Sqrt(dx0 * dx0 + dy0 * dy0) / R));
            el = Math.Max(0, Math.Min(90, el));
            try
            {
                if (puntDrag == 1)
                {
                    if (az == (double)me.Az2.Value % 360.0) az = (az + 1) % 360.0;
                    me.Az1.Value = (decimal)az;
                }
                else if (puntDrag == 2)
                {
                    double a1 = (double)me.Az1.Value;
                    if (az == a1 % 360.0) az = (az + 359.0) % 360.0;
                    if (az == 0) az = 360;
                    me.Az2.Value = (decimal)az;
                }
                else if (puntDrag == 3) me.El1.Value = (decimal)Math.Min(el, (double)me.El2.Value);
                else if (puntDrag == 4) me.El2.Value = (decimal)Math.Max(el, (double)me.El1.Value);
            }
            catch { }
            pnlPunt.Invalidate();
        }

