            dtpMondoOra = new DateTimePicker();
            dtpMondoOra.Format = DateTimePickerFormat.Custom; dtpMondoOra.CustomFormat = "HH:mm"; dtpMondoOra.ShowUpDown = true; dtpMondoOra.Width = S(70);
            lblMondoLoc = L("");
            lblMondoLoc.ForeColor = Tema.Muted;
            g1.Controls.Add(L(Lang.T("Data (UTC)")), 0, 0); g1.Controls.Add(dtpMondoData, 1, 0);
            g1.Controls.Add(L(Lang.T("Ora (UTC)")), 2, 0); g1.Controls.Add(dtpMondoOra, 3, 0); g1.Controls.Add(lblMondoLoc, 4, 0);
            FlowLayoutPanel pills = new FlowLayoutPanel();
            pills.AutoSize = true; pills.AutoSizeMode = AutoSizeMode.GrowAndShrink; pills.WrapContents = true;
            pills.Margin = new Padding(0, S(8), 0, 0);
            Font fp = new Font(Lang.FontUi, 9F * fontFactor, FontStyle.Bold);
            Pillola bAdesso = new Pillola("▶ " + Lang.T("Adesso"), StilePillola.Pieno, Color.FromArgb(31, 111, 209), fp);
            Pillola bMeno = new Pillola("− 1 h", StilePillola.Pieno, Color.FromArgb(31, 111, 209), fp);
            Pillola bPiu = new Pillola("+ 1 h", StilePillola.Pieno, Color.FromArgb(31, 111, 209), fp);
            chkMondoSegui = new Pillola(Lang.T("Segui l'ora attuale"), StilePillola.Casella, Color.FromArgb(31, 111, 209), fp);
            tip.SetToolTip(chkMondoSegui, Lang.T("Aggiorna da sola la mappa con l'ora attuale, minuto per minuto."));
            foreach (Pillola pp in new Pillola[] { bAdesso, bMeno, bPiu, chkMondoSegui }) { pp.Margin = new Padding(0, S(2), S(8), S(2)); pills.Controls.Add(pp); }
            bAdesso.Click += (s, e) => { mondoDaTimer = true; try { dtp.Value = NowUtcMinute(); } finally { mondoDaTimer = false; } };
            bMeno.Click += (s, e) => { chkMondoSegui.Checked = false; dtp.Value = dtp.Value.AddHours(-1); };
            bPiu.Click += (s, e) => { chkMondoSegui.Checked = false; dtp.Value = dtp.Value.AddHours(1); };
            g1.Controls.Add(pills, 0, 1); g1.SetColumnSpan(pills, 5);
            Label nota1 = L("⇄ " + Lang.T("Stesso momento della linguetta Posizione della Luna: se lo cambi qui, cambia anche là."));
            nota1.ForeColor = Tema.Muted; nota1.Margin = new Padding(S(3), S(6), S(3), S(2));
            g1.Controls.Add(nota1, 0, 2); g1.SetColumnSpan(nota1, 5);
            top.Controls.Add(SchedaCampi(Lang.T("Momento di calcolo"), Color.FromArgb(31, 111, 209), g1, null), 0, 0);

            // LA MIA STAZIONE
            TableLayoutPanel g2;
            Group(Lang.T("La mia stazione"), 2, out g2);
