            lblMondoCoord = L(""); lblMondoCoord.ForeColor = Tema.Muted;
            lblMondoEl = new Label();
            lblMondoEl.AutoSize = true;
            lblMondoEl.Font = new Font(Lang.FontUi, 17F * fontFactor, FontStyle.Bold);
            lblMondoEl.Margin = new Padding(S(3), S(6), S(3), S(2));
            lblMondoNota = L(""); lblMondoNota.ForeColor = Tema.Muted;
            lblMondoNota.MaximumSize = new Size(S(380), 0);
            g2.Controls.Add(L(Lang.T("Locator WWL")), 0, 0); g2.Controls.Add(lblMondoLocBox, 1, 0);
            g2.Controls.Add(lblMondoCoord, 0, 1); g2.SetColumnSpan(lblMondoCoord, 2);
            g2.Controls.Add(lblMondoEl, 0, 2); g2.SetColumnSpan(lblMondoEl, 2);
            g2.Controls.Add(lblMondoNota, 0, 3); g2.SetColumnSpan(lblMondoNota, 2);
            top.Controls.Add(SchedaCampi(Lang.T("La mia stazione"), Color.FromArgb(31, 111, 209), g2, null), 1, 0);

            // LA LUNA IN QUEL MOMENTO
            TableLayoutPanel g3;
            Group(Lang.T("La Luna in quel momento"), 2, out g3);
