            Label[] vv = { lblMondoZenit, lblMondoDec, lblMondoDist, lblMondoTerre };
            string[] kk = { Lang.T("Allo zenit sopra"), Lang.T("Declinazione"), Lang.T("Distanza"), Lang.T("Terre che vedono la Luna") };
            for (int i = 0; i < 4; i++)
            {
                vv[i].Font = new Font(Lang.FontUi, 9.5F * fontFactor, FontStyle.Bold);
                vv[i].Anchor = AnchorStyles.Right;
                g3.Controls.Add(L(kk[i]), 0, i); g3.Controls.Add(vv[i], 1, i);
            }
            top.Controls.Add(SchedaCampi(Lang.T("La Luna in quel momento"), Color.FromArgb(217, 119, 6), g3, null), 2, 0);
            root.Controls.Add(top, 0, 0);

            // la mappa
            pnlMondo = new PannelloDisegno();
            pnlMondo.Dock = DockStyle.Fill;
            pnlMondo.Margin = new Padding(S(6), S(6), S(6), S(4));
            pnlMondo.Paint += DisegnaMondo;
            timerMondoDim = new Timer();
            timerMondoDim.Interval = 300;
            timerMondoDim.Tick += (s, e) => { timerMondoDim.Stop(); MondoAggiorna(); };
            pnlMondo.Resize += (s, e) => { timerMondoDim.Stop(); timerMondoDim.Start(); pnlMondo.Invalidate(); };
            pnlMondo.MouseMove += (s, e) =>
            {
                Point prima = mondoMouse;
                mondoMouse = mondoRett.Contains(e.Location) ? e.Location : new Point(-1, -1);
                pnlMondo.Cursor = mondoMouse.X >= 0 ? Cursors.Cross : Cursors.Default;
                if (prima != mondoMouse) pnlMondo.Invalidate();
            };
            pnlMondo.MouseLeave += (s, e) => { mondoMouse = new Point(-1, -1); pnlMondo.Invalidate(); };
            pnlMondo.MouseClick += (s, e) =>
            {
                // clic: quella località diventa la stazione DX (locator di 6 caratteri)
                if (e.Button != MouseButtons.Left || !mondoRett.Contains(e.Location)) return;
                double la, lo;
                MondoPuntoA(e.Location, out la, out lo);
                if (txtDxCall != null) { caricamento = true; try { txtDxCall.Text = ""; } finally { caricamento = false; } dxCallPrec = ""; }
                dx.Loc.Text = Locator.Da(la, lo, 6);
                if (!chkDx.Checked) chkDx.Checked = true;
                pnlMondo.Invalidate();
            };
            root.Controls.Add(pnlMondo, 0, 1);
            tp.Controls.Add(root);

            // collegamenti
            dtpMondoData.ValueChanged += (s, e) => MondoVersoPosizione();
            dtpMondoOra.ValueChanged += (s, e) => MondoVersoPosizione();
            dtp.ValueChanged += (s, e) => MondoDaPosizione();
            me.Loc.TextChanged += (s, e) => MondoAggiorna();
            me.H.ValueChanged += (s, e) => MondoAggiorna();
            foreach (NumericUpDown lim in new NumericUpDown[] { me.Az1, me.Az2, me.El1, me.El2 }) lim.ValueChanged += (s, e) => MondoAggiorna();
            dx.Loc.TextChanged += (s, e) => { if (pnlMondo != null) pnlMondo.Invalidate(); };
            chkRefr.CheckedChanged += (s, e) => MondoAggiorna();
            timerMondo = new Timer();
            timerMondo.Interval = 15000;
            timerMondo.Tick += (s, e) =>
            {
                if (tabs.SelectedTab != tpMondo) return;
                DateTime n = NowUtcMinute();
                if (dtp.Value == n) return;
                mondoDaTimer = true;
                try { dtp.Value = n; } finally { mondoDaTimer = false; }
            };
            chkMondoSegui.CheckedChanged += (s, e) =>
            {
                timerMondo.Enabled = chkMondoSegui.Checked;
                if (chkMondoSegui.Checked) { mondoDaTimer = true; try { dtp.Value = NowUtcMinute(); } finally { mondoDaTimer = false; } }
            };
            tabs.SelectedIndexChanged += (s, e) => { if (tabs.SelectedTab == tpMondo && mondoSporca) pnlMondo.Invalidate(); };
            MondoDaPosizione();
        }

        // punto del pannello → latitudine e longitudine
        void MondoPuntoA(Point p, out double lat, out double lon)
        {
            lon = -180.0 + (p.X - mondoRett.Left) / mondoRett.Width * 360.0;
            lat = MondoLatN - (p.Y - mondoRett.Top) / mondoRett.Height * (MondoLatN - MondoLatS);
        }

        PointF MondoXY(double lat, double lon)
        {
            return new PointF(mondoRett.Left + (float)((lon + 180.0) / 360.0 * mondoRett.Width),
                mondoRett.Top + (float)((MondoLatN - lat) / (MondoLatN - MondoLatS) * mondoRett.Height));
        }

        // ricalcola la mappa colorata (solo quando è cambiato il momento, la stazione o la dimensione)
        void MondoCalcola(Rectangle area)
        {
            DateTime t = MondoMomento();
            bool rifr = chkRefr != null && chkRefr.Checked;
            MoonPos g0 = Moon.Compute(t, 0, 0, 0, false);
            double ra = g0.RaGeo * Math.PI / 180.0, dec = g0.DecGeo * Math.PI / 180.0, gast = g0.Gast, dist = g0.Dist;
            mondoDec = g0.DecGeo; mondoDist = dist;
            mondoSubLat = g0.DecGeo;
            mondoSubLon = ((g0.RaGeo - gast) % 360.0 + 540.0) % 360.0 - 180.0;
            mondoMeOk = me.Ok;
            if (me.Ok) { mondoMe = Moon.Compute(t, me.Lat, me.Lon, (double)me.H.Value, rifr); mondoStato = me.Valuta(mondoMe, out mondoPuntabile); }

            MondoGeometria(area);
            mondoW = Math.Max(10, (int)mondoRett.Width); mondoH = Math.Max(10, (int)mondoRett.Height);

            byte[] m = TerreEmerse.Maschera;
            int W = TerreEmerse.W, H = TerreEmerse.H;
            // per colonna: cos dell'angolo orario e colonna della maschera; per riga: sin/cos della latitudine e riga della maschera
            double[] cosH = new double[mondoW]; int[] mx = new int[mondoW];
            for (int x = 0; x < mondoW; x++)
            {
                double lon = -180.0 + (x + 0.5) / mondoW * 360.0;
                cosH[x] = Math.Cos((gast + lon) * Math.PI / 180.0 - ra);
                mx[x] = Math.Min(W - 1, (int)((lon + 180.0) / 360.0 * W));
            }
            mondoEl = new float[mondoW * mondoH];
            bool[] terra = new bool[mondoW * mondoH];
            double sinD = Math.Sin(dec), cosD = Math.Cos(dec), kPar = 6378.14 / dist;
            for (int y = 0; y < mondoH; y++)
            {
                double lat = MondoLatN - (y + 0.5) / mondoH * (MondoLatN - MondoLatS);
                double phi = lat * Math.PI / 180.0, a = Math.Sin(phi) * sinD, b = Math.Cos(phi) * cosD;
                int my = Math.Min(H - 1, (int)((90.0 - lat) / 180.0 * H));
                for (int x = 0; x < mondoW; x++)
                {
                    double el = Math.Asin(Math.Max(-1, Math.Min(1, a + b * cosH[x]))) * 180.0 / Math.PI;
                    el -= kPar * Math.Cos(el * Math.PI / 180.0) * 180.0 / Math.PI;   // parallasse (asin x ≈ x per x ≤ 0,0166)
                    if (rifr && el > -1.5)
                    {
                        double r = 1.02 / Math.Tan((el + 10.3 / (el + 5.11)) * Math.PI / 180.0);
                        if (r > 0) el += r / 60.0;
                    }
                    mondoEl[y * mondoW + x] = (float)el;
                    terra[y * mondoW + x] = m[my * W + mx[x]] != 0;
                }
            }

            // percentuale delle terre (tutto il mondo, maschera a passo 2) che vedono la Luna
            double tot = 0, su = 0;
            for (int yy = 0; yy < H; yy += 2)
            {
                double lat = 90.0 - (yy + 0.5) / H * 180.0;
                double phi = lat * Math.PI / 180.0, a = Math.Sin(phi) * sinD, b = Math.Cos(phi) * cosD;
                for (int xx = 0; xx < W; xx += 2)
                {
                    if (m[yy * W + xx] == 0) continue;
                    double peso = Math.Cos(phi);   // area della cella
                    tot += peso;
                    double lon = -180.0 + (xx + 0.5) / W * 360.0;
                    double se = a + b * Math.Cos((gast + lon) * Math.PI / 180.0 - ra);
                    // el topocentrica > 0 (con la rifrazione l'orizzonte apparente scende di circa 0,5°)
                    if (se + (rifr ? 0.0084 : 0.0) > kPar * Math.Sqrt(Math.Max(0, 1 - se * se))) su += peso;
                }
            }

            // immagine: mari neutri, terre colorate (grigie con la Luna sotto l'orizzonte), coste, linee di 0° e 10°
            Color mare = Tema.Scuro ? Color.FromArgb(30, 38, 52) : Color.FromArgb(234, 241, 248);
            Color sotto = Tema.Scuro ? Color.FromArgb(78, 86, 100) : Color.FromArgb(206, 211, 219);
            Color costa = Tema.Scuro ? Color.FromArgb(150, 160, 175) : Color.FromArgb(120, 130, 145);
            Color linea = Tema.Scuro ? Color.FromArgb(235, 240, 248) : Color.FromArgb(40, 48, 64);
            int[] pix = new int[mondoW * mondoH];
            for (int y = 0; y < mondoH; y++)
                for (int x = 0; x < mondoW; x++)
                {
                    int i = y * mondoW + x;
                    float el = mondoEl[i];
                    Color c;
                    if (!terra[i]) c = mare;
                    else
                    {
                        bool bordo = (x + 1 < mondoW && !terra[i + 1]) || (y + 1 < mondoH && !terra[i + mondoW]) || (x > 0 && !terra[i - 1]) || (y > 0 && !terra[i - mondoW]);
                        c = bordo ? costa : (el >= 0 ? ColoreElevazione(el) : sotto);
                    }
                    // linea dell'orizzonte (continua) e dei 10° (tratteggiata)
                    if (x + 1 < mondoW && y + 1 < mondoH)
                    {
                        float e2 = mondoEl[i + 1], e3 = mondoEl[i + mondoW];
                        if ((el >= 0) != (e2 >= 0) || (el >= 0) != (e3 >= 0)) c = linea;
                        else if (((el >= 10) != (e2 >= 10) || (el >= 10) != (e3 >= 10)) && ((x + y) / S(5)) % 2 == 0) c = Color.FromArgb((c.R + linea.R) / 2, (c.G + linea.G) / 2, (c.B + linea.B) / 2);
                    }
                    pix[i] = c.ToArgb();
                }
            if (mondoBmp != null) mondoBmp.Dispose();
            mondoBmp = new Bitmap(mondoW, mondoH, System.Drawing.Imaging.PixelFormat.Format32bppArgb);
            System.Drawing.Imaging.BitmapData bd = mondoBmp.LockBits(new Rectangle(0, 0, mondoW, mondoH), System.Drawing.Imaging.ImageLockMode.WriteOnly, System.Drawing.Imaging.PixelFormat.Format32bppArgb);
            for (int y = 0; y < mondoH; y++) Marshal.Copy(pix, y * mondoW, new IntPtr(bd.Scan0.ToInt64() + (long)y * bd.Stride), mondoW);
            mondoBmp.UnlockBits(bd);

            // schede in alto
            CultureInfo c2 = ci;
            DateTime loc = TimeZoneInfo.ConvertTimeFromUtc(t, TimeZoneInfo.Local);
            lblMondoLoc.Text = Lang.T("ora locale") + " " + loc.ToString("HH:mm", inv);
            lblMondoLocBox.Text = me.Ok ? me.Loc.Text.Trim().ToUpperInvariant() : "—";
            lblMondoCoord.Text = me.Ok ? CoordText(me) : Lang.T("Locator non valido");
            if (me.Ok)
            {
                lblMondoEl.Text = "El " + mondoMe.El.ToString("0.0", c2) + "°   Az " + mondoMe.Az.ToString("0.0", c2) + "°";
                // stessi colori delle altre linguette: verde puntabile, arancione fuori dai limiti dell'antenna, grigio sotto l'orizzonte
                lblMondoEl.ForeColor = MondoColoreStato();
                if (mondoPuntabile) lblMondoNota.Text = mondoStato + " · " + Lang.T("La Luna è sopra il tuo orizzonte: le zone colorate possono vederla insieme a te.");
                else if (mondoMe.El < 0) lblMondoNota.Text = Lang.T("La Luna è sotto il tuo orizzonte: in questo momento non puoi fare collegamenti via Luna.");
                else lblMondoNota.Text = mondoStato.ToUpper(Lang.Cultura) + " · " + Lang.T("La Luna è sopra il tuo orizzonte ma fuori dai limiti della tua antenna: in questo momento non puoi puntarla.");
                lblMondoNota.ForeColor = mondoPuntabile || mondoMe.El < 0 ? Tema.Muted : Tema.WarnFg;
            }
            else { lblMondoEl.Text = "—"; lblMondoNota.Text = ""; }
            lblMondoZenit.Text = Math.Abs(mondoSubLat).ToString("0.0", c2) + "° " + (mondoSubLat >= 0 ? "N" : "S") + "   " + Math.Abs(mondoSubLon).ToString("0.0", c2) + "° " + (mondoSubLon >= 0 ? "E" : "W");
            lblMondoDec.Text = (mondoDec >= 0 ? "+" : "−") + Math.Abs(mondoDec).ToString("0.0", c2) + "°";
            lblMondoDist.Text = mondoDist.ToString("N0", c2) + " km";
            lblMondoTerre.Text = (tot > 0 ? 100.0 * su / tot : 0).ToString("0", c2) + " %";
            mondoSporca = false;
        }

        void DisegnaMondo(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            PreparaGrafica(g);
            Rectangle cr = pnlMondo.ClientRectangle;
            g.Clear(Tema.Back);
            if (cr.Width < S(100) || cr.Height < S(100)) return;
            RectangleF card = new RectangleF(S(2), S(2), cr.Width - S(6), cr.Height - S(7));
            Scheda(g, card, Color.Empty);
            Rectangle dentro = new Rectangle((int)card.Left + S(12), (int)card.Top + S(12), (int)card.Width - S(24), (int)card.Height - S(20));
            if (mondoSporca || mondoBmp == null) MondoCalcola(dentro);
            else MondoGeometria(dentro);   // durante il ridimensionamento: stessa bitmap, allargata, fino al ricalcolo
            g.InterpolationMode = InterpolationMode.NearestNeighbor;
            g.PixelOffsetMode = PixelOffsetMode.Half;
            g.DrawImage(mondoBmp, mondoRett.Left, mondoRett.Top, mondoRett.Width, mondoRett.Height);
            g.PixelOffsetMode = PixelOffsetMode.Default;
            g.InterpolationMode = InterpolationMode.HighQualityBicubic;
            using (Pen pb = new Pen(Tema.Scuro ? Tema.ChartGrid : Color.FromArgb(201, 208, 218))) g.DrawRectangle(pb, mondoRett.Left, mondoRett.Top, mondoRett.Width, mondoRett.Height);
            // riferimenti leggeri ogni 30° (non è il reticolo Maidenhead)
            using (Pen pg = new Pen(Color.FromArgb(Tema.Scuro ? 50 : 40, 90, 110, 140)))
            {
                for (int lo = -150; lo < 180; lo += 30) { PointF a = MondoXY(MondoLatN, lo), b = MondoXY(MondoLatS, lo); g.DrawLine(pg, a, b); }
                for (int la = -60; la <= 60; la += 30) { PointF a = MondoXY(la, -180), b = MondoXY(la, 180); g.DrawLine(pg, a, b); }
            }
            CultureInfo c2 = ci;
            using (Font fl = FontPx(Lang.FontUi, S(12), false))
            using (Font fb = FontPx(Lang.FontUi, S(12), true))
            {
                // Luna allo zenit
                PointF pl = MondoXY(mondoSubLat, mondoSubLon);
                float rl = S(13);
                using (Brush bl = new SolidBrush(Color.FromArgb(244, 241, 230))) g.FillEllipse(bl, pl.X - rl, pl.Y - rl, 2 * rl, 2 * rl);
                using (Brush bc = new SolidBrush(Color.FromArgb(207, 201, 184)))
                {
                    g.FillEllipse(bc, pl.X - S(8), pl.Y - S(7), S(6), S(6));
                    g.FillEllipse(bc, pl.X + S(2), pl.Y + S(2), S(5), S(5));
                }
                using (Pen pc = new Pen(Color.FromArgb(85, 85, 85), S(1.5f))) g.DrawEllipse(pc, pl.X - rl, pl.Y - rl, 2 * rl, 2 * rl);
                EtichettaMappa(g, Lang.T("Luna allo zenit (El 90°)"), fl, null, pl.X + rl + S(6), pl.Y - S(10));
                // stazione DX (se c'è)
                if (dx.Ok && chkDx.Checked)
                {
                    PointF pd = MondoXY(dx.Lat, dx.Lon);
                    using (Brush bd = new SolidBrush(Color.FromArgb(217, 119, 6))) g.FillEllipse(bd, pd.X - S(6), pd.Y - S(6), S(12), S(12));
                    using (Pen pw = new Pen(Color.White, S(1.5f))) g.DrawEllipse(pw, pd.X - S(6), pd.Y - S(6), S(12), S(12));
                    double eDx = MondoElevA(dx.Lat, dx.Lon);
                    string nomeDx = txtDxCall != null && txtDxCall.Text.Trim().Length > 0 ? txtDxCall.Text.Trim() + " · " : "";
                    EtichettaMappa(g, nomeDx + Locator.Da(dx.Lat, dx.Lon, 6), fb, " · El " + eDx.ToString("0.0", c2) + "°", pd.X + S(10), pd.Y + S(4));
                }
                // la mia stazione: stella blu
                if (mondoMeOk)
                {
                    PointF pm = MondoXY(me.Lat, me.Lon);
                    PointF[] st = new PointF[10];
                    for (int i = 0; i < 10; i++)
                    {
                        double ang = -Math.PI / 2 + i * Math.PI / 5;
                        float rr = i % 2 == 0 ? S(12) : S(5);
                        st[i] = new PointF(pm.X + (float)(rr * Math.Cos(ang)), pm.Y + (float)(rr * Math.Sin(ang)));
                    }
                    using (Brush bs = new SolidBrush(Color.FromArgb(31, 111, 209))) g.FillPolygon(bs, st);
                    using (Pen pw = new Pen(Color.White, S(1.5f))) g.DrawPolygon(pw, st);
                    EtichettaMappa(g, Locator.Da(me.Lat, me.Lon, 6), fb, " · El " + mondoMe.El.ToString("0.0", c2) + "°" + (mondoPuntabile ? "" : " · " + mondoStato), pm.X + S(14), pm.Y - S(28));
                    // anello del colore dello stato (verde, arancione, grigio) intorno alla stella
                    using (Pen ps = new Pen(MondoColoreStato(), S(2.5f))) g.DrawEllipse(ps, pm.X - S(16), pm.Y - S(16), S(32), S(32));
                }
                // riquadro al passaggio del mouse
                if (mondoMouse.X >= 0)
                {
                    Point pmz = mondoMouse;
                    double la, lo;
                    MondoPuntoA(pmz, out la, out lo);
                    using (Pen pk = new Pen(Tema.Fore, S(1.5f)))
                    {
                        g.DrawEllipse(pk, pmz.X - S(5), pmz.Y - S(5), S(10), S(10));
                        g.DrawLine(pk, pmz.X - S(8), pmz.Y, pmz.X + S(8), pmz.Y); g.DrawLine(pk, pmz.X, pmz.Y - S(8), pmz.X, pmz.Y + S(8));
                    }
                    double el, az;
                    MondoElAz(la, lo, out el, out az);
                    List<string> r = new List<string>();
                    r.Add(Locator.Da(la, lo, 4) + " · " + Math.Abs(la).ToString("0.0", c2) + "° " + (la >= 0 ? "N" : "S") + " " + Math.Abs(lo).ToString("0.0", c2) + "° " + (lo >= 0 ? "E" : "W"));
                    r.Add(el >= 0 ? Lang.T("Luna:") + " El " + el.ToString("0.0", c2) + "°   Az " + az.ToString("0", c2) + "°" : Lang.T("Luna sotto l'orizzonte"));
                    if (mondoMeOk) r.Add(Lang.T("Distanza da te:") + " " + GreatCircleKm(me.Lat, me.Lon, la, lo).ToString("N0", c2) + " km");
                    r.Add(Lang.T("clic: usa come stazione DX"));
                    float w = 0, h = S(8);
                    foreach (string x in r) { SizeF sz = g.MeasureString(x, fb); w = Math.Max(w, sz.Width); h += sz.Height; }
                    w += S(18);
                    float bx = pmz.X + S(14), by = pmz.Y + S(14);
                    if (bx + w > mondoRett.Right) bx = pmz.X - S(14) - w;
                    if (by + h > mondoRett.Bottom) by = pmz.Y - S(14) - h;
                    RectangleF rb = new RectangleF(bx, by, w, h);
                    using (GraphicsPath gp = Arrotondato(rb, S(8)))
                    {
                        using (Brush bo = new SolidBrush(Color.FromArgb(60, 0, 0, 0))) { g.TranslateTransform(S(2), S(3)); g.FillPath(bo, gp); g.TranslateTransform(-S(2), -S(3)); }
                        using (Brush bf = new SolidBrush(Tema.Carta)) g.FillPath(bf, gp);
                        using (Pen pf = new Pen(Color.FromArgb(31, 111, 209), S(1.5f))) g.DrawPath(pf, gp);
                    }
                    float yy = by + S(4);
                    for (int i = 0; i < r.Count; i++)
                    {
                        Font f = i == 0 || i == 1 ? fb : fl;
                        using (Brush bt = new SolidBrush(i == r.Count - 1 ? Tema.Muted : Tema.Fore)) g.DrawString(r[i], f, bt, bx + S(9), yy);
                        yy += g.MeasureString(r[i], f).Height;
                    }
                }
                // legenda
                float ly = mondoRett.Bottom + S(14), lx = mondoRett.Left;
                RectangleF barra = new RectangleF(lx, ly, S(300), S(12));
                for (int i = 0; i < (int)barra.Width; i++)
                {
                    double v = i / barra.Width * 90.0;
                    using (Pen pv = new Pen(ColoreElevazione(v))) g.DrawLine(pv, barra.Left + i, barra.Top, barra.Left + i, barra.Bottom);
                }
                using (Pen pb = new Pen(Tema.Muted)) g.DrawRectangle(pb, barra.Left, barra.Top, barra.Width, barra.Height);
                using (Font fs = FontPx(Lang.FontUi, S(10.5f), false))
                using (Brush tm = new SolidBrush(Tema.Muted))
                using (Brush tf = new SolidBrush(Tema.Fore))
                {
                    foreach (double v in MondoTappe)
                    {
                        float x = barra.Left + (float)(v / 90.0 * barra.Width);
                        string sv = v.ToString("0", c2) + "°";
                        float ws = g.MeasureString(sv, fs).Width;
                        g.DrawString(sv, fs, tm, Math.Min(barra.Right - ws, Math.Max(barra.Left, x - ws / 2)), barra.Bottom + S(1));
                    }
                    float x2 = barra.Right + S(16);
                    string t1 = Lang.T("Elevazione della Luna vista da ogni località");
                    g.DrawString(t1, fl, tf, x2, ly - S(2)); x2 += g.MeasureString(t1, fl).Width + S(18);
                    Color sotto = Tema.Scuro ? Color.FromArgb(78, 86, 100) : Color.FromArgb(206, 211, 219);
                    Color mare = Tema.Scuro ? Color.FromArgb(30, 38, 52) : Color.FromArgb(234, 241, 248);
                    Color linea = Tema.Scuro ? Color.FromArgb(235, 240, 248) : Color.FromArgb(40, 48, 64);
                    using (Brush b1 = new SolidBrush(sotto)) g.FillRectangle(b1, x2, ly, S(20), S(11));
                    x2 += S(26); string t2 = Lang.T("Luna sotto l'orizzonte"); g.DrawString(t2, fl, tf, x2, ly - S(2)); x2 += g.MeasureString(t2, fl).Width + S(18);
                    using (Pen p1 = new Pen(linea, S(2.5f))) g.DrawLine(p1, x2, ly + S(5), x2 + S(20), ly + S(5));
                    x2 += S(26); string t3 = Lang.T("orizzonte (0°)"); g.DrawString(t3, fl, tf, x2, ly - S(2)); x2 += g.MeasureString(t3, fl).Width + S(18);
                    using (Pen p2 = new Pen(linea, S(2.5f))) { p2.DashStyle = DashStyle.Dash; g.DrawLine(p2, x2, ly + S(5), x2 + S(20), ly + S(5)); }
                    x2 += S(26); g.DrawString("10°", fl, tf, x2, ly - S(2)); x2 += g.MeasureString("10°", fl).Width + S(18);
                    using (Brush b3 = new SolidBrush(mare)) g.FillRectangle(b3, x2, ly, S(20), S(11));
                    using (Pen pb = new Pen(Tema.Muted)) g.DrawRectangle(pb, x2, ly, S(20), S(11));
                    x2 += S(26); g.DrawString(Lang.T("mari (non colorati)"), fl, tf, x2, ly - S(2));
                }
            }
        }

        // area della mappa: proporzioni equirettangolari (360° × 156°), centrata nel pannello sopra la legenda;
        // in coordinate del pannello (servono anche al mouse), a pixel interi per la bitmap
        void MondoGeometria(Rectangle area)
        {
            float leg = S(46), marg = S(8);
            float wDisp = area.Width - 2 * marg, hDisp = area.Height - leg - 2 * marg;
            float rapp = (float)(360.0 / (MondoLatN - MondoLatS));
            float wm = wDisp, hm = wm / rapp;
            if (hm > hDisp) { hm = hDisp; wm = hm * rapp; }
            mondoRett = new RectangleF((int)(area.Left + marg + (wDisp - wm) / 2), (int)(area.Top + marg), (int)Math.Max(10, wm), (int)Math.Max(10, hm));
        }

        Color MondoColoreStato()
        {
            if (!mondoMeOk) return Tema.Muted;
            if (mondoPuntabile) return Tema.OkFg;
            return mondoMe.El < 0 ? Tema.SottoFg : Tema.WarnFg;
        }

        double MondoElevA(double lat, double lon) { double el, az; MondoElAz(lat, lon, out el, out az); return el; }

        // elevazione e azimut della Luna da un punto qualsiasi, nel momento della mappa (stesso calcolo della Posizione della Luna)
        void MondoElAz(double lat, double lon, out double el, out double az)
        {
            MoonPos p = Moon.Compute(MondoMomento(), lat, lon, 0, chkRefr != null && chkRefr.Checked);
            el = p.El; az = p.Az;
        }

        // etichetta su fondo bianco: parte in grassetto (o normale) e coda facoltativa
        void EtichettaMappa(Graphics g, string testo, Font f, string coda, float x, float y)
        {
            string tutto = testo + (coda ?? "");
            SizeF sz = g.MeasureString(tutto, f);
            RectangleF r = new RectangleF(x, y, sz.Width + S(10), sz.Height + S(4));
            using (GraphicsPath gp = Arrotondato(r, S(5)))
            {
                using (Brush b = new SolidBrush(Color.FromArgb(238, Tema.Carta))) g.FillPath(b, gp);
                using (Pen p = new Pen(Tema.Muted)) g.DrawPath(p, gp);
            }
            using (Brush bt = new SolidBrush(Tema.Fore)) g.DrawString(tutto, f, bt, x + S(5), y + S(2));
        }

