        // titoloASinistra: il titolo sta a sinistra e il valore accanto, allineato a sinistra (cella DATA)
        Panel Cella(string titolo, float pt, bool titoloASinistra, out Label valore)
        {
            Panel p = new Panel();
            p.Dock = DockStyle.Fill;
            p.BorderStyle = BorderStyle.FixedSingle;
            p.Margin = new Padding(S(2));
            Label t = new Label();
            t.Text = titolo;
            t.Dock = DockStyle.Top;
            t.Height = S(24);
            t.Font = new Font(Lang.FontUi, 11F * fontFactor, FontStyle.Bold);
            t.ForeColor = Tema.Muted;
            t.Padding = new Padding(S(6), S(3), 0, 0);
            valore = new Label();
            valore.Dock = DockStyle.Fill;
            valore.AutoSize = false;
            valore.TextAlign = ContentAlignment.MiddleCenter;
            valore.Font = new Font(Lang.FontUi, pt * fontFactor, FontStyle.Bold);
            valore.Text = "---";
            if (titoloASinistra)
            {
                t.Dock = DockStyle.Left;
                t.AutoSize = true;
                valore.TextAlign = ContentAlignment.MiddleLeft;
                valore.Padding = new Padding(S(6), 0, 0, 0);
            }
            p.Controls.Add(valore);
            p.Controls.Add(t);
            return p;
        }

