        static readonly Color ColBlu = Color.FromArgb(31, 111, 209), ColArancio = Color.FromArgb(217, 119, 6),
            ColGiallo = Color.FromArgb(242, 194, 0), ColValore = Color.FromArgb(25, 65, 127);
