        PannelloDisegno NuovaScheda()
        {
            PannelloDisegno p = new PannelloDisegno();
            p.Dock = DockStyle.Fill;
            p.Margin = new Padding(S(5), 0, S(5), 0);
            return p;
        }

        void BuildTrackTab(TabPage tp)
        {
            TableLayoutPanel root = new TableLayoutPanel();
