                new Font(Lang.FontUi, 9F * fontFactor, FontStyle.Bold));
            tip.SetToolTip(chkDatiMain, Lang.T("Mostra in basso a destra l'S/N stimato in questo istante, con i parametri della linguetta Budget EME per la banda scelta."));
            chkDatiMain.CheckedChanged += (s, e) =>
            {
