            tip.SetToolTip(btnBande, Lang.T("Sceglie le bande da usare nei calcoli: Budget EME, Rumore solare e tendine della frequenza."));
            btnBande.Click += (s, e) => ScegliBande();
            FlowLayoutPanel opz = new FlowLayoutPanel();
