            txtTrkDxCall.Font = new Font(FamigliaNumeri, 19F * fontFactor, FontStyle.Bold);
            txtTrkDxCall.MaxLength = 13;
            txtTrkDxCall.CharacterCasing = CharacterCasing.Upper;
            txtTrkDxCall.BorderStyle = BorderStyle.None;
