        TrkDati trk = new TrkDati();
        PannelloDisegno pnlTrk;
        static string famNumeri;

        // Cifre degli strumenti: Bahnschrift (Windows 10/11) se presente, altrimenti il carattere dell'interfaccia
        static string FamigliaNumeri
        {
            get
            {
                if (famNumeri == null)
                {
                    famNumeri = Lang.FontUi;
                    try
                    {
                        foreach (FontFamily ff in FontFamily.Families)
                            if (ff.Name == "Bahnschrift") { famNumeri = "Bahnschrift"; break; }
                    }
                    catch { }
                }
                return famNumeri;
            }
        }

        public static GraphicsPath Arrotondato(RectangleF r, float rag)
        {
            GraphicsPath p = new GraphicsPath();
            float d = Math.Max(1f, Math.Min(rag * 2, Math.Min(r.Width, r.Height)));
            p.AddArc(r.Left, r.Top, d, d, 180, 90);
            p.AddArc(r.Right - d, r.Top, d, d, 270, 90);
            p.AddArc(r.Right - d, r.Bottom - d, d, d, 0, 90);
            p.AddArc(r.Left, r.Bottom - d, d, d, 90, 90);
            p.CloseFigure();
            return p;
        }

        // Riquadro con angoli arrotondati; accento = fascia colorata a sinistra (Color.Empty = nessuna)
        void Scheda(Graphics g, RectangleF r, Color accento)
        {
            using (GraphicsPath p = Arrotondato(r, S(12)))
            {
                using (Brush ombra = new SolidBrush(Color.FromArgb(Tema.Scuro ? 70 : 28, 0, 0, 0)))
                using (GraphicsPath po = Arrotondato(new RectangleF(r.X + S(2), r.Y + S(3), r.Width, r.Height), S(12)))
                    g.FillPath(ombra, po);
                using (Brush b = new SolidBrush(Color.FromArgb(Tema.Scuro ? 238 : 245, Tema.Carta))) g.FillPath(b, p);
                if (accento != Color.Empty)
                {
                    Region old = g.Clip;
                    g.SetClip(p, CombineMode.Intersect);
                    using (Brush b = new SolidBrush(accento)) g.FillRectangle(b, r.Left, r.Top, S(6), r.Height);
                    g.Clip = old;
                }
                using (Pen pn = new Pen(Tema.Linea, 1f)) g.DrawPath(pn, p);
            }
        }

        static Color ColoreStato(int stato)
        {
            switch (stato)
            {
                case 0: return Tema.OkFg;
                case 1: return Tema.WarnFg;
                case 3: return Tema.Accent;
                default: return Tema.SottoFg;
            }
        }

        static void Testo(Graphics g, string t, Font f, Color c, RectangleF r, StringAlignment oriz, StringAlignment vert)
        {
            using (StringFormat sf = new StringFormat())
            using (Brush b = new SolidBrush(c))
            {
                sf.Alignment = oriz;
                sf.LineAlignment = vert;
                sf.Trimming = StringTrimming.EllipsisWord;
                g.DrawString(t, f, b, r, sf);
            }
        }

        Font FontPx(string fam, float px, bool grassetto)
        {
            return new Font(fam, Math.Max(6f, px), grassetto ? FontStyle.Bold : FontStyle.Regular, GraphicsUnit.Pixel);
        }

        void PreparaGrafica(Graphics g)
        {
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.AntiAliasGridFit;
            g.InterpolationMode = InterpolationMode.HighQualityBicubic;
        }

        // Fascia di stato, bussola, elevazione, riquadri dei dati e barra delle prossime 24 ore
        void DisegnaTrk(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            PreparaGrafica(g);
            Rectangle cr = pnlTrk.ClientRectangle;
            if (cr.Width < 200 || cr.Height < 200) return;
            float gap = S(12);
            float x0 = cr.Left + S(1), y0 = cr.Top + S(2), w = cr.Width - S(5), h = cr.Height - S(7);
            trkZone.Clear();
            if (!trk.MeOk)
            {
                RectangleF rr = new RectangleF(x0, y0, w, S(50));
                using (GraphicsPath p = Arrotondato(rr, S(10)))
                using (Brush b = new SolidBrush(Tema.BadFg)) g.FillPath(b, p);
                using (Font f = FontPx(Lang.FontUi, S(20), true))
                    Testo(g, Lang.T("locator non valido"), f, Color.White, new RectangleF(rr.Left + S(20), rr.Top, rr.Width - S(30), rr.Height), StringAlignment.Near, StringAlignment.Center);
                return;
            }
            float hBan = S(48), hTl = S(110);
            RectangleF ban = new RectangleF(x0, y0, w, hBan);
            RectangleF tl = new RectangleF(x0, y0 + h - hTl, w, hTl);
            float yMid = ban.Bottom + gap, hMid = tl.Top - gap - yMid;
            float wA = (w - 2 * gap) * 330f / 1444f, wE = (w - 2 * gap) * 260f / 1444f;
            RectangleF ra = new RectangleF(x0, yMid, wA, hMid);
            RectangleF re = new RectangleF(ra.Right + gap, yMid, wE, hMid);
            RectangleF rs = new RectangleF(re.Right + gap, yMid, x0 + w - re.Right - gap, hMid);
            Color cs = ColoreStato(trk.Stato);
            DisegnaFascia(g, ban, cs);
            DisegnaBussola(g, ra);
            DisegnaElevazione(g, re);
            DisegnaLato(g, rs);
            DisegnaStriscia(g, tl);
        }

        // Fascia piena del colore dello stato: titolo, spiegazione e conto alla rovescia in una pillola a destra
        void DisegnaFascia(Graphics g, RectangleF r, Color cs)
        {
            using (GraphicsPath p = Arrotondato(r, S(10)))
            using (Brush b = new SolidBrush(cs)) g.FillPath(b, p);
            string[] tit = { Lang.T("PUNTABILE"), Lang.T("FUORI LIMITI"), Lang.T("SOTTO L'ORIZZONTE"), Lang.T("FINESTRA COMUNE") };
            string pt = trk.Stato >= 0 && trk.Stato < 4 ? tit[trk.Stato] : "";
            Color bianco = Tema.Scuro ? Color.FromArgb(14, 18, 28) : Color.White;
            using (Font fp = FontPx(Lang.FontUi, S(21), true))
            using (Font ft = FontPx(Lang.FontUi, S(16), false))
            using (Font fc = FontPx(Lang.FontUi, S(19), true))
            {
                float x = r.Left + S(18);
                float wp = g.MeasureString(pt, fp).Width;
                Testo(g, pt, fp, bianco, new RectangleF(x, r.Top, wp + S(6), r.Height), StringAlignment.Near, StringAlignment.Center);
                float wc = g.MeasureString(trk.Conto, fc).Width + S(26);
                RectangleF rc = new RectangleF(r.Right - S(16) - wc, r.Top + (r.Height - S(32)) / 2, wc, S(32));
                if (trk.Conto.Length > 0)
                {
                    using (GraphicsPath pp = Arrotondato(rc, S(7)))
                    using (Brush b = new SolidBrush(Color.FromArgb(46, 255, 255, 255))) g.FillPath(b, pp);
                    Testo(g, trk.Conto, fc, bianco, rc, StringAlignment.Center, StringAlignment.Center);
                }
                float xt = x + wp + S(18);
                Testo(g, trk.StatoTesto, ft, bianco, new RectangleF(xt, r.Top, Math.Max(10, rc.Left - S(12) - xt), r.Height), StringAlignment.Near, StringAlignment.Center);
            }
        }

        bool AzLibero { get { return trk.Az2 - trk.Az1 >= 360.0 || trk.Az1 == trk.Az2; } }

        // Valore grande in blu e, sotto, il valore del DX in arancio
        void ValoriStrumento(Graphics g, RectangleF r, string v, string vdx)
        {
            using (Font fv = FontPx(FamigliaNumeri, S(40), true))
            using (Font fd = FontPx(Lang.FontUi, S(14), true))
            {
                float yb = r.Bottom - S(10) - (vdx.Length > 0 ? S(20) : 0);
                Testo(g, v, fv, ColBlu, new RectangleF(r.Left, yb - S(50), r.Width, S(50)), StringAlignment.Center, StringAlignment.Center);
                if (vdx.Length > 0) Testo(g, vdx, fd, ColArancio, new RectangleF(r.Left, yb, r.Width, S(20)), StringAlignment.Center, StringAlignment.Center);
            }
        }

        // Ago blu con la maniglia tonda in punta
        void Ago(Graphics g, PointF a, PointF b, float rm)
        {
            using (Pen p = new Pen(ColBlu, S(5))) { p.StartCap = LineCap.Round; p.EndCap = LineCap.Round; g.DrawLine(p, a, b); }
            using (Brush br = new SolidBrush(Tema.Scuro ? Tema.Section : Color.FromArgb(233, 237, 243))) g.FillEllipse(br, b.X - rm, b.Y - rm, 2 * rm, 2 * rm);
            using (Pen p = new Pen(ColBlu, (S(5) / 2f))) g.DrawEllipse(p, b.X - rm, b.Y - rm, 2 * rm, 2 * rm);
        }

        void DisegnaBussola(Graphics g, RectangleF r)
        {
            Scheda(g, r, Color.Empty);
            using (Font fh = FontPx(Lang.FontUi, S(12), false))
                Testo(g, Lang.T("AZIMUT LOCALE"), fh, Tema.Muted, new RectangleF(r.Left + S(12), r.Top + S(8), r.Width - S(20), S(18)), StringAlignment.Near, StringAlignment.Near);
            float hVal = S(60) + (trk.UsaDx ? S(20) : 0);
            float top = r.Top + S(30), bot = r.Bottom - hVal - S(6);
            float R = Math.Max(S(30), Math.Min(r.Width - S(36), bot - top) / 2f);
            PointF c = new PointF(r.Left + r.Width / 2f, top + (bot - top) / 2f);
            float k = R / 132f;
            using (Brush b = new SolidBrush(Tema.Field)) g.FillEllipse(b, c.X - R, c.Y - R, 2 * R, 2 * R);
            using (Pen p = new Pen(Tema.Linea, S(2))) g.DrawEllipse(p, c.X - R, c.Y - R, 2 * R, 2 * R);
            // limiti di azimut dell'antenna: arco giallo
            if (!AzLibero)
            {
                float sweep = (float)(((trk.Az2 - trk.Az1) % 360.0 + 360.0) % 360.0);
                float ry = 124 * k;
                if (sweep > 0)
                    using (Pen p = new Pen(ColGiallo, S(6))) { p.StartCap = LineCap.Round; p.EndCap = LineCap.Round; g.DrawArc(p, c.X - ry, c.Y - ry, 2 * ry, 2 * ry, (float)trk.Az1 - 90f, sweep); }
            }
            // tacche ogni 10°, lunghe ogni 30°
            using (Pen pt = new Pen(Color.FromArgb(138, 148, 166), 1f))
            using (Pen pt2 = new Pen(Color.FromArgb(138, 148, 166), 1.6f))
                for (int a = 0; a < 360; a += 10)
                {
                    double ar = a * Math.PI / 180.0;
                    float r1 = 118 * k, r2 = (a % 30 == 0 ? 106 : 112) * k;
                    float sx = (float)Math.Sin(ar), cy = (float)-Math.Cos(ar);
                    g.DrawLine(a % 30 == 0 ? pt2 : pt, c.X + sx * r1, c.Y + cy * r1, c.X + sx * r2, c.Y + cy * r2);
                }
            using (Font fp = FontPx(Lang.FontUi, Math.Max(S(11), 17 * k), true))
            {
                string[] pc = { "N", "E", "S", Lang.T("O") };
                for (int i = 0; i < 4; i++)
                {
                    double ar = i * Math.PI / 2;
                    float ddx = (float)Math.Sin(ar) * 90 * k, ddy = (float)-Math.Cos(ar) * 90 * k;
                    Testo(g, pc[i], fp, Tema.Scuro ? Tema.Fore : Color.FromArgb(55, 65, 81), new RectangleF(c.X + ddx - S(20), c.Y + ddy - S(12), S(40), S(24)), StringAlignment.Center, StringAlignment.Center);
                }
            }
            // azimut della Luna per il DX: linea arancio tratteggiata
            if (trk.UsaDx)
            {
                double ad = trk.AzDx * Math.PI / 180.0;
                float rd = 110 * k;
                using (Pen p = new Pen(ColArancio, (S(5) / 2f)))
                {
                    p.DashPattern = new float[] { 2.4f, 1.6f };
                    g.DrawLine(p, c.X, c.Y, c.X + (float)Math.Sin(ad) * rd, c.Y - (float)Math.Cos(ad) * rd);
                }
                using (Font fd = FontPx(Lang.FontUi, S(12), true))
                {
                    float rl = 124 * k + S(4);
                    Testo(g, "DX", fd, ColArancio, new RectangleF(c.X + (float)Math.Sin(ad) * rl - S(16), c.Y - (float)Math.Cos(ad) * rl - S(9), S(32), S(18)), StringAlignment.Center, StringAlignment.Center);
                }
            }
            // la mia Luna: ago blu
            double am = trk.Az * Math.PI / 180.0;
            float rn = 108 * k;
            Ago(g, c, new PointF(c.X + (float)Math.Sin(am) * rn, c.Y - (float)Math.Cos(am) * rn), Math.Max(S(6), 9 * k));
            using (Brush b = new SolidBrush(ColBlu)) g.FillEllipse(b, c.X - 6 * k, c.Y - 6 * k, 12 * k, 12 * k);
            ValoriStrumento(g, r, trk.Az.ToString("F1", ci) + "°", trk.UsaDx ? "DX " + trk.AzDx.ToString("F1", ci) + "°" : "");
        }

        void DisegnaElevazione(Graphics g, RectangleF r)
        {
            Scheda(g, r, Color.Empty);
            using (Font fh = FontPx(Lang.FontUi, S(12), false))
                Testo(g, Lang.T("ELEVAZIONE LOCALE"), fh, Tema.Muted, new RectangleF(r.Left + S(12), r.Top + S(8), r.Width - S(20), S(18)), StringAlignment.Near, StringAlignment.Near);
            float hVal = S(60) + (trk.UsaDx ? S(20) : 0);
            float top = r.Top + S(36), bot = r.Bottom - hVal - S(10);
            float R = Math.Max(S(30), Math.Min(r.Width - S(50), bot - top));
            float k = R / 175f;
            PointF o = new PointF(r.Left + (r.Width - R) / 2f - S(4), top + (bot - top + R) / 2f);
            // quarto di cerchio
            using (GraphicsPath gp = new GraphicsPath())
            {
                gp.AddLine(o.X, o.Y, o.X + R, o.Y);
                gp.AddArc(o.X - R, o.Y - R, 2 * R, 2 * R, 0, -90);
                gp.CloseFigure();
                using (Brush b = new SolidBrush(Tema.Field)) g.FillPath(b, gp);
                using (Pen p = new Pen(Tema.Linea, S(2))) g.DrawPath(p, gp);
            }
            // limiti di elevazione: arco giallo appena fuori
            double e1 = Math.Max(0, trk.El1), e2 = Math.Min(90, trk.El2);
            if (e2 > e1)
            {
                float ry = 180 * k;
                using (Pen p = new Pen(ColGiallo, S(6))) { p.StartCap = LineCap.Round; p.EndCap = LineCap.Round; g.DrawArc(p, o.X - ry, o.Y - ry, 2 * ry, 2 * ry, (float)-e2, (float)(e2 - e1)); }
            }
            using (Pen pt = new Pen(Color.FromArgb(138, 148, 166), 1f))
            using (Font fs = FontPx(Lang.FontUi, Math.Max(S(10), 13 * k), false))
                for (int a = 0; a <= 90; a += 10)
                {
                    double ar = a * Math.PI / 180.0;
                    float cx = (float)Math.Cos(ar), sy = (float)-Math.Sin(ar);
                    float r2 = (a % 30 == 0 ? 163 : 169) * k;
                    g.DrawLine(pt, o.X + cx * R, o.Y + sy * R, o.X + cx * r2, o.Y + sy * r2);
                    if (a % 30 == 0)
                    {
                        float rt = (a == 0 ? 148 : (a == 90 ? 150 : 144)) * k;
                        float tx = o.X + cx * rt, ty = o.Y + sy * rt;
                        if (a == 0) ty -= S(6);
                        if (a == 90) ty += S(4);
                        Testo(g, a.ToString(ci) + "°", fs, Tema.Muted, new RectangleF(tx - S(20), ty - S(9), S(40), S(18)), StringAlignment.Center, StringAlignment.Center);
                    }
                }
            // elevazione della Luna per il DX: linea arancio tratteggiata
            if (trk.UsaDx)
            {
                double ed = Math.Max(0, Math.Min(90, trk.ElDx)) * Math.PI / 180.0;
                using (Pen p = new Pen(ColArancio, (S(5) / 2f)))
                {
                    p.DashPattern = new float[] { 2.4f, 1.6f };
                    g.DrawLine(p, o.X, o.Y, o.X + (float)Math.Cos(ed) * 167 * k, o.Y - (float)Math.Sin(ed) * 167 * k);
                }
            }
            double em = Math.Max(0, Math.Min(90, trk.El)) * Math.PI / 180.0;
            Ago(g, o, new PointF(o.X + (float)Math.Cos(em) * 165 * k, o.Y - (float)Math.Sin(em) * 165 * k), Math.Max(S(6), 8 * k));
            ValoriStrumento(g, r, trk.El.ToString("F1", ci) + "°", trk.UsaDx ? "DX " + trk.ElDx.ToString("F1", ci) + "°" : "");
        }

        // Direzione del DX sul cerchio massimo (gradi da Nord)
        double BearingDx()
        {
            double la1 = me.Lat * Math.PI / 180, la2 = dx.Lat * Math.PI / 180, dl = (dx.Lon - me.Lon) * Math.PI / 180;
            double y = Math.Sin(dl) * Math.Cos(la2), x = Math.Cos(la1) * Math.Sin(la2) - Math.Sin(la1) * Math.Cos(la2) * Math.Cos(dl);
            return (Math.Atan2(y, x) * 180 / Math.PI + 360) % 360;
        }

        // Disco della Luna con la parte illuminata (emisfero nord: crescente illuminata a destra)
        static void DisegnaFase(Graphics g, PointF c, float R, double k, bool crescente)
        {
            using (Brush b = new SolidBrush(Color.FromArgb(42, 47, 58))) g.FillEllipse(b, c.X - R, c.Y - R, 2 * R, 2 * R);
            if (k < 0.01) { using (Pen p = new Pen(Color.FromArgb(90, 100, 120), 1f)) g.DrawEllipse(p, c.X - R, c.Y - R, 2 * R, 2 * R); return; }
            using (GraphicsPath p = new GraphicsPath())
            {
                float wt = Math.Max(0.5f, (float)(R * Math.Abs(1 - 2 * k)));
                p.AddArc(c.X - R, c.Y - R, 2 * R, 2 * R, -90, 180);
                RectangleF el = new RectangleF(c.X - wt, c.Y - R, 2 * wt, 2 * R);
                if (k >= 0.5) p.AddArc(el, 90, 180);
                else p.AddArc(el, 90, -180);
                p.CloseFigure();
                if (!crescente)
                    using (Matrix m = new Matrix(-1, 0, 0, 1, 2 * c.X, 0)) p.Transform(m);
                using (Brush b = new SolidBrush(Color.FromArgb(236, 233, 220))) g.FillPath(b, p);
            }
        }

        void Barretta(Graphics g, RectangleF r, string etichetta, string valore, double frazione, Color cv, Font fl, Font fv)
        {
            Testo(g, etichetta, fl, Tema.Muted, new RectangleF(r.Left, r.Top, r.Width * 0.7f, S(20)), StringAlignment.Near, StringAlignment.Near);
            Testo(g, valore, fv, cv, new RectangleF(r.Left + r.Width * 0.5f, r.Top, r.Width * 0.5f, S(20)), StringAlignment.Far, StringAlignment.Near);
            RectangleF b = new RectangleF(r.Left, r.Top + S(23), r.Width, S(9));
            using (GraphicsPath p = Arrotondato(b, S(4)))
            {
                using (Brush bb = new SolidBrush(Tema.Section)) g.FillPath(bb, p);
                float wf = (float)(b.Width * Math.Max(0.02, Math.Min(1.0, frazione)));
                if (wf > 2)
                {
                    RectangleF bf = new RectangleF(b.Left, b.Top, wf, b.Height);
                    using (GraphicsPath pf = Arrotondato(bf, S(4)))
                    using (LinearGradientBrush lb = new LinearGradientBrush(new RectangleF(b.Left - 1, b.Top, b.Width + 2, b.Height), Tema.WarnFg, Tema.OkFg, LinearGradientMode.Horizontal))
                        g.FillPath(lb, pf);
                }
                using (Pen pn = new Pen(Tema.Linea)) g.DrawPath(pn, p);
            }
        }

        // Zone cliccabili della schermata principale: pulsanti e casella disegnati
        readonly List<KeyValuePair<RectangleF, Action>> trkZone = new List<KeyValuePair<RectangleF, Action>>();

        static readonly Color ColLuna = Color.FromArgb(123, 138, 168), ColCfom = Color.FromArgb(15, 139, 141),
            ColCielo = Color.FromArgb(57, 73, 171), ColCalcoli = Color.FromArgb(91, 63, 168);

        // Pulsante disegnato con azione al clic
        void PulsanteTrk(Graphics g, RectangleF r, string t, Color c, Font f, Action az)
        {
            using (GraphicsPath p = Arrotondato(r, S(7)))
            {
                using (Brush b = new SolidBrush(Color.FromArgb(40, 0, 0, 0)))
                using (GraphicsPath po = Arrotondato(new RectangleF(r.X, r.Y + S(2), r.Width, r.Height), S(7))) g.FillPath(b, po);
                using (Brush b = new SolidBrush(c)) g.FillPath(b, p);
            }
            Testo(g, t, f, Color.White, r, StringAlignment.Center, StringAlignment.Center);
            trkZone.Add(new KeyValuePair<RectangleF, Action>(r, az));
        }

        string FmtDg(double v) { return double.IsNaN(v) ? "–" : v.ToString("F2", ci).Replace("-", "−") + " dB"; }

        // Riga etichetta / valore con una linea sottile sotto
        void RigaDato(Graphics g, float x, float y, float w, float h, string et, string val, Font fl, Font fv, Color cv)
        {
            Testo(g, et, fl, Tema.Fore, new RectangleF(x, y, w * 0.55f, h), StringAlignment.Near, StringAlignment.Center);
            Testo(g, val, fv, cv, new RectangleF(x + w * 0.35f, y, w * 0.65f, h), StringAlignment.Far, StringAlignment.Center);
            using (Pen p = new Pen(Color.FromArgb(Tema.Scuro ? 60 : 255, Tema.Linea))) g.DrawLine(p, x, y + h, x + w, y + h);
        }

        // Quattro riquadri: Luna, Eco e frequenze (CFOM), Cielo e geometria, S/N stimato
        void DisegnaLato(Graphics g, RectangleF r)
        {
            float gap = S(10);
            float cw = (r.Width - gap) / 2f;
            float h1 = Math.Max(S(130), (r.Height - gap) * 0.40f), h2 = r.Height - gap - h1;
            RectangleF rl = new RectangleF(r.Left, r.Top, cw, h1), rc = new RectangleF(r.Left + cw + gap, r.Top, cw, h1);
            RectangleF rg = new RectangleF(r.Left, r.Top + h1 + gap, cw, h2), rn = new RectangleF(r.Left + cw + gap, r.Top + h1 + gap, cw, h2);
            Color cSn = Color.FromArgb(15, 139, 141);   // senza colori di esito: la soglia del modo non è un limite netto
            Scheda(g, rl, ColLuna); Scheda(g, rc, ColCfom); Scheda(g, rg, ColCielo); Scheda(g, rn, cSn);
            using (Font fh = FontPx(Lang.FontUi, S(12), false))
            using (Font fb = FontPx(Lang.FontUi, S(19), true))
            using (Font fs = FontPx(Lang.FontUi, S(13), false))
            using (Font fi = FontPx(Lang.FontUi, S(14), false))
            using (Font fl = FontPx(Lang.FontUi, S(14), false))
            using (Font fv = FontPx(Lang.FontUi, S(14), true))
            using (Font fbtn = FontPx(Lang.FontUi, S(14), true))
            using (Font fsn = FontPx(FamigliaNumeri, S(30), true))
            using (Font fpic = FontPx(Lang.FontUi, S(11), false))
            {
                float pad = S(17), lh = S(25);
                // --- Luna
                float x = rl.Left + pad, y = rl.Top + S(8), wi = rl.Width - pad - S(12);
                Testo(g, Lang.T("LUNA"), fh, Tema.Muted, new RectangleF(x, y, wi, S(18)), StringAlignment.Near, StringAlignment.Near);
                float Rf = Math.Max(S(16), Math.Min(S(46), (rl.Bottom - y - S(30)) / 2f));
                float cyf = y + S(22) + (rl.Bottom - S(10) - y - S(22)) / 2f;
                DisegnaFase(g, new PointF(x + Rf, cyf), Rf, trk.Illum, trk.Crescente);
                float xt = x + 2 * Rf + S(14), wt = rl.Right - S(12) - xt;
                Testo(g, trk.Fase, fb, Tema.Fore, new RectangleF(xt, cyf - S(34), wt, S(28)), StringAlignment.Near, StringAlignment.Center);
                Testo(g, string.Format(ci, Lang.T("illuminata {0} %"), (trk.Illum * 100).ToString("0", ci)), fi, Tema.Fore, new RectangleF(xt, cyf - S(6), wt, S(20)), StringAlignment.Near, StringAlignment.Center);
                Testo(g, trk.SorgeTramonta, fs, Tema.Muted, new RectangleF(xt, cyf + S(16), wt, S(38)), StringAlignment.Near, StringAlignment.Near);
                // --- Eco e frequenze (CFOM)
                x = rc.Left + pad; y = rc.Top + S(8); wi = rc.Width - pad - S(14);
                // frequenza (MHz . kHz) a destra del titolo, che si accorcia per lasciarle posto
                float wTitCfom = cmbTrkMhz != null ? Math.Max(S(40), rc.Right - S(14) - cmbTrkKhz.Width - lblTrkPunto.Width - cmbTrkMhz.Width - S(8) - x) : wi;
                Testo(g, Lang.T("ECO E FREQUENZE (CFOM)"), fh, Tema.Muted, new RectangleF(x, y, wTitCfom, S(18)), StringAlignment.Near, StringAlignment.Near);
                if (cmbTrkMhz != null)
                {
                    int yc = (int)(y - S(3));
                    int xfk = (int)(rc.Right - S(14) - cmbTrkKhz.Width);
                    int xfp = xfk - lblTrkPunto.Width;
                    int xfm = xfp - cmbTrkMhz.Width;
                    if (cmbTrkMhz.Location != new Point(xfm, yc)) cmbTrkMhz.Location = new Point(xfm, yc);
                    if (cmbTrkKhz.Location != new Point(xfk, yc)) cmbTrkKhz.Location = new Point(xfk, yc);
                    Point pfp = new Point(xfp, yc + (cmbTrkMhz.Height - lblTrkPunto.Height) / 2);
                    if (lblTrkPunto.Location != pfp) lblTrkPunto.Location = pfp;
                }
                y += cmbTrkMhz != null ? Math.Max(S(22), cmbTrkMhz.Height + S(2)) : S(22);
                RigaDato(g, x, y, wi, lh, Lang.T("Eco proprio"), trk.EcoTxt, fl, fv, Tema.Fore); y += lh + S(2);
                if (trk.UsaDx) { RigaDato(g, x, y, wi, lh, Lang.T("DX → io"), trk.DxIoTxt, fl, fv, Tema.Fore); y += lh + S(2); }
                RigaDato(g, x, y, wi, lh, Lang.T("CFOM · trasmetti su"), trk.CfomTx, fl, fv, Tema.BadFg); y += lh + S(2);
                RigaDato(g, x, y, wi, lh, Lang.T("CFOM · ricevi su"), trk.CfomRx, fl, fv, Tema.OkFg);
                // --- Cielo e geometria
                x = rg.Left + pad; y = rg.Top + S(8); wi = rg.Width - pad - S(14);
                Testo(g, Lang.T("CIELO E GEOMETRIA"), fh, Tema.Muted, new RectangleF(x, y, wi, S(18)), StringAlignment.Near, StringAlignment.Near);
                y += S(22);
                foreach (string[] d in trk.Info)
                {
                    if (y + lh > rg.Bottom - S(110)) break;
                    RigaDato(g, x, y, wi, lh, d[0], d[1], fl, fv, Tema.Fore);
                    y += lh + S(2);
                }
                y += S(6);
                Testo(g, "DGRD", fh, Tema.Muted, new RectangleF(x, y, wi, S(16)), StringAlignment.Near, StringAlignment.Near);
                // scala della barra: minimo e massimo della Dgrd nel grafico della linguetta Distanza e Dgrd
                // (se non è ancora calcolato, da -10 a 0 dB); in alto a destra il valore di adesso
                double dmin = -10, dmax = 0;
                if (dgDgrd.Count > 1)
                {
                    dmin = double.MaxValue; dmax = double.MinValue;
                    foreach (double v in dgDgrd) if (!double.IsNaN(v)) { dmin = Math.Min(dmin, v); dmax = Math.Max(dmax, v); }
                    if (dmin > dmax) { dmin = -10; dmax = 0; }
                    if (dmax - dmin < 0.1) { dmin -= 0.05; dmax += 0.05; }
                }
                using (Font fdv = FontPx(Lang.FontUi, S(13), true))
                    Testo(g, Lang.T("adesso") + " " + FmtDg(trk.Dgrd), fdv, Tema.Fore, new RectangleF(x, y - S(2), wi, S(20)), StringAlignment.Far, StringAlignment.Near);
                RectangleF bd = new RectangleF(x, y + S(20), wi, S(12));
                using (GraphicsPath p = Arrotondato(bd, S(6)))
                using (LinearGradientBrush lb = new LinearGradientBrush(new RectangleF(bd.Left - 1, bd.Top, bd.Width + 2, bd.Height), Color.Red, Color.Green, LinearGradientMode.Horizontal))
                {
                    ColorBlend cb = new ColorBlend(3);
                    cb.Colors = new Color[] { Color.FromArgb(198, 40, 40), Color.FromArgb(224, 142, 11), Color.FromArgb(58, 163, 90) };
                    cb.Positions = new float[] { 0f, 0.5f, 1f };
                    lb.InterpolationColors = cb;
                    g.FillPath(lb, p);
                }
                float fr = (float)Math.Max(0.0, Math.Min(1.0, (trk.Dgrd - dmin) / (dmax - dmin)));
                float xm = bd.Left + fr * bd.Width;
                using (GraphicsPath p = Arrotondato(new RectangleF(xm - S(2), bd.Top - S(4), S(4), bd.Height + S(8)), S(2)))
                using (Brush b = new SolidBrush(Tema.Scuro ? Color.White : Color.FromArgb(29, 36, 51))) g.FillPath(b, p);
                Testo(g, "min " + FmtDg(dmin), fpic, Tema.Muted, new RectangleF(bd.Left, bd.Bottom + S(3), bd.Width / 2f, S(16)), StringAlignment.Near, StringAlignment.Near);
                Testo(g, "max " + FmtDg(dmax), fpic, Tema.Muted, new RectangleF(bd.Left + bd.Width / 2f, bd.Bottom + S(3), bd.Width / 2f, S(16)), StringAlignment.Far, StringAlignment.Near);
                float wb = Math.Min(wi, g.MeasureString(Lang.T("VAI A VOLTA CELESTE") + " ➜", fbtn).Width + S(32));
                PulsanteTrk(g, new RectangleF(rg.Right - S(14) - wb, rg.Bottom - S(48), wb, S(34)), Lang.T("VAI A VOLTA CELESTE") + " ➜", ColCielo, fbtn, () => { tabs.SelectedTab = tpSky; });
                // --- S/N stimato
                x = rn.Left + pad; y = rn.Top + S(8); wi = rn.Width - pad - S(14);
                Testo(g, (trk.SnTitolo.Length > 0 ? trk.SnTitolo : Lang.T("S/N STIMATO ADESSO")).ToUpper(Lang.Cultura), fh, Tema.Muted, new RectangleF(x, y, wi, S(18)), StringAlignment.Near, StringAlignment.Near);
                y += S(20);
                if (trk.SnOn && trk.SnValido)
                {
                    string v = SnTxt(trk.SnB, ci).Replace("-", "−");
                    float wv = g.MeasureString(v, fsn).Width;
                    Testo(g, v, fsn, cSn, new RectangleF(x - S(4), y, wv + S(8), S(42)), StringAlignment.Near, StringAlignment.Center);
                    // "−26,3 dB in 2500 Hz · soglia tipica JT65:" e la soglia in grassetto
                    string m = string.Format(ci, Lang.T("{0} dB in 2500 Hz · soglia tipica {1}: {2} dB"), Segno(trk.SnMargine, ci), trk.SnNomeModo, trk.SnSoglia.ToString("0.#", ci));
                    int ic = m.LastIndexOf(':');
                    string m1 = ic > 0 ? m.Substring(0, ic + 1) + " " : m, m2 = ic > 0 ? m.Substring(ic + 1).Trim() : "";
                    float xm1 = x + wv + S(10);
                    float w1 = g.MeasureString(m1, fs).Width;
                    Testo(g, m1, fs, Tema.Fore, new RectangleF(xm1, y + S(6), Math.Max(10, Math.Min(w1 + S(2), rn.Right - S(14) - xm1)), S(34)), StringAlignment.Near, StringAlignment.Center);
                    using (Font fsb = FontPx(Lang.FontUi, S(13), true))
                        if (xm1 + w1 < rn.Right - S(40))
                            Testo(g, m2, fsb, cSn, new RectangleF(xm1 + w1, y + S(6), rn.Right - S(14) - xm1 - w1, S(34)), StringAlignment.Near, StringAlignment.Center);
                    y += S(46);
                }
                else
                {
                    string m = trk.SnOn ? trk.SnMsg : Lang.T("Spunta \"ATTIVA VISIONE DATI COMPLESSI NELLA SCHERMATA PRINCIPALE\" per vedere l'S/N stimato adesso.");
                    SizeF sz = g.MeasureString(m, fs, (int)wi);
                    Testo(g, m, fs, Tema.Muted, new RectangleF(x, y, wi, sz.Height + S(4)), StringAlignment.Near, StringAlignment.Near);
                    y += sz.Height + S(8);
                }
                float yMax = rn.Bottom - S(56);
                if (trk.UsaDx && y + lh < yMax)
                {
                    RigaDato(g, x, y, wi, lh, "DX · " + Lang.T("Luna"), string.Format(ci, "Az {0:F1}° · El {1:F1}°", trk.AzDx, trk.ElDx), fl, fv, Tema.Fore);
                    y += lh + S(2);
                    if (y + lh < yMax) { RigaDato(g, x, y, wi, lh, Lang.T("DX · Sole"), trk.DxSole, fl, fv, Tema.Fore); y += lh + S(2); }
                }
                if (trk.Avvisi.Length > 0 && y + S(18) < yMax)
                    Testo(g, trk.Avvisi, fs, Tema.WarnFg, new RectangleF(x, y + S(2), wi, yMax - y), StringAlignment.Near, StringAlignment.Near);
                // casella CALCOLI APPROFONDITI (la stessa del Budget EME) e pulsante VAI AI CALCOLI
                bool on = chkComplessi != null && chkComplessi.Checked;
                string tc = Lang.T("CALCOLI APPROFONDITI"), tl = "⇄ Budget";
                float wg = g.MeasureString(Lang.T("VAI AI CALCOLI") + " ➜", fbtn).Width + S(32);
                float disp = wi - wg - S(10);
                // la scritta non si sovrappone mai: prima si toglie "⇄ Budget", poi si rimpicciolisce il carattere
                Font fcb = fbtn;
                float wtc = g.MeasureString(tc, fcb).Width, wtl = g.MeasureString(tl, fh).Width;
                bool conLink = S(46) + wtc + S(12) + wtl + S(10) <= disp;
                if (!conLink)
                {
                    float px = S(14);
                    while (S(46) + wtc + S(10) > disp && px > S(10))
                    {
                        px -= 0.5f;
                        if (fcb != fbtn) fcb.Dispose();
                        fcb = FontPx(Lang.FontUi, px, true);
                        wtc = g.MeasureString(tc, fcb).Width;
                    }
                }
                float wc = conLink ? S(46) + wtc + S(12) + wtl + S(10) : Math.Min(disp, S(46) + wtc + S(10));
                RectangleF rcb = new RectangleF(x, rn.Bottom - S(48), Math.Max(S(60), wc), S(34));
                using (GraphicsPath p = Arrotondato(rcb, S(9)))
                {
                    using (Brush b = new SolidBrush(on ? (Tema.Scuro ? Color.FromArgb(60, ColCalcoli) : Color.FromArgb(246, 242, 255)) : Tema.Field)) g.FillPath(b, p);
                    using (Pen pn = new Pen(on ? ColCalcoli : Tema.Muted, S(2))) g.DrawPath(pn, p);
                }
                RectangleF box = new RectangleF(rcb.Left + S(8), rcb.Top + S(7), S(20), S(20));
                using (GraphicsPath p = Arrotondato(box, S(4)))
                {
                    using (Brush b = new SolidBrush(on ? ColCalcoli : Tema.Carta)) g.FillPath(b, p);
                    using (Pen pn = new Pen(on ? ColCalcoli : Tema.Muted, S(2))) g.DrawPath(pn, p);
                }
                if (on) Testo(g, "✓", fbtn, Color.White, box, StringAlignment.Center, StringAlignment.Center);
                Testo(g, tc, fcb, on ? ColCalcoli : Tema.Fore, new RectangleF(box.Right + S(8), rcb.Top, wtc + S(4), rcb.Height), StringAlignment.Near, StringAlignment.Center);
                if (conLink) Testo(g, tl, fh, Tema.Muted, new RectangleF(rcb.Left, rcb.Top, rcb.Width - S(10), rcb.Height), StringAlignment.Far, StringAlignment.Center);
                if (fcb != fbtn) fcb.Dispose();
                trkZone.Add(new KeyValuePair<RectangleF, Action>(rcb, () => { chkComplessi.Checked = !chkComplessi.Checked; }));
                trkTipZona = rcb;
                PulsanteTrk(g, new RectangleF(rn.Right - S(14) - wg, rn.Bottom - S(48), wg, S(34)), Lang.T("VAI AI CALCOLI") + " ➜", Tema.OkFg, fbtn, () => { tabs.SelectedTab = tpBudget; });
            }
        }

        RectangleF trkTipZona;

        Font fontDx;
        Font FontDx(Font base_)
        {
            if (fontDx == null || Math.Abs(fontDx.Size - base_.Size * 0.85f) > 0.1f)
            {
                if (fontDx != null) fontDx.Dispose();
                fontDx = new Font(base_.FontFamily, base_.Size * 0.85f, FontStyle.Bold, GraphicsUnit.Pixel);
            }
            return fontDx;
        }

        // Prossime 24 ore del giorno UTC: Luna nei miei limiti (verde), Luna sopra l'orizzonte del DX (arancio), finestra comune (azzurro)
        static readonly Color ColVerde24 = Color.FromArgb(58, 163, 90), ColArancio24 = Color.FromArgb(217, 130, 43);

        void DisegnaStriscia(Graphics g, RectangleF r)
        {
            Scheda(g, r, Color.Empty);
            using (Font fh = FontPx(Lang.FontUi, S(13), true))
            using (Font fs = FontPx(Lang.FontUi, S(13), false))
            using (Font fx = FontPx(Lang.FontUi, S(12), false))
            using (Font fa = FontPx(Lang.FontUi, S(12), true))
            {
                // titolo e legenda sulla stessa riga
                float x = r.Left + S(14), y = r.Top + S(7);
                string tt = trk.Diretta ? Lang.T("Prossime 24 ore (UTC)") : trk.StrisciaT0.ToString("ddd dd/MM/yyyy", Lang.Cultura) + " (UTC)";
                float wt = g.MeasureString(tt, fh).Width;
                Testo(g, tt, fh, Tema.Scuro ? Tema.Fore : Color.FromArgb(55, 65, 81), new RectangleF(x, y, wt + S(4), S(20)), StringAlignment.Near, StringAlignment.Center);
                x += wt + S(18);
                string[] lt = { Lang.T("Luna nei limiti (io)"), Lang.T("Luna sopra l'orizzonte (DX)"), Lang.T("finestra comune con il DX") };
                for (int i = 0; i < 3; i++)
                {
                    if (i > 0 && !trk.UsaDx) break;
                    RectangleF sq = new RectangleF(x, y + S(5), S(22), S(10));
                    using (GraphicsPath p = Arrotondato(sq, S(3)))
                    {
                        if (i == 2)
                        {
                            using (Brush b = new SolidBrush(Color.FromArgb(90, ColBlu))) g.FillPath(b, p);
                            using (Pen pn = new Pen(ColBlu)) g.DrawPath(pn, p);
                        }
                        else using (Brush b = new SolidBrush(i == 0 ? ColVerde24 : ColArancio24)) g.FillPath(b, p);
                    }
                    float wl = g.MeasureString(lt[i], fs).Width;
                    Testo(g, lt[i], fs, Tema.Muted, new RectangleF(x + S(27), y, wl + S(4), S(20)), StringAlignment.Near, StringAlignment.Center);
                    x += S(27) + wl + S(18);
                }
                // barre
                float bx = r.Left + S(20), bw = r.Width - S(40);
                float yb1 = r.Top + S(38), yb2 = yb1 + S(18), hb = S(14);
                trkStrBx = bx; trkStrBw = bw;
                trkStrRett = new RectangleF(bx - S(6), yb1 - S(10), bw + S(12), r.Bottom - (yb1 - S(10)));
                byte[] st = trk.Striscia;
                if (st != null && st.Length > 0)
                {
                    float dw = bw / st.Length;
                    Action<int, float, Color> riga = (bit, yy, col) =>
                    {
                        int i = 0;
                        while (i < st.Length)
                        {
                            if ((st[i] & bit) == 0) { i++; continue; }
                            int j = i;
                            while (j < st.Length && (st[j] & bit) != 0) j++;
                            RectangleF rr = new RectangleF(bx + i * dw, yy, (j - i) * dw, hb);
                            if (bit == 4)
                            {
                                RectangleF ro = new RectangleF(rr.Left, yb1 - S(4), rr.Width, yb2 + hb + S(4) - (yb1 - S(4)));
                                using (GraphicsPath p = Arrotondato(ro, S(5)))
                                {
                                    using (Brush b = new SolidBrush(Color.FromArgb(46, ColBlu))) g.FillPath(b, p);
                                    using (Pen pn = new Pen(ColBlu)) g.DrawPath(pn, p);
                                }
                            }
                            else
                                using (GraphicsPath p = Arrotondato(rr, S(4)))
                                using (Brush b = new SolidBrush(col)) g.FillPath(b, p);
                            i = j;
                        }
                    };
                    riga(1, yb1, ColVerde24);
                    if (trk.UsaDx) riga(2, yb2, ColArancio24);
                    if (trk.UsaDx) riga(4, 0, Color.Empty);
                }
                // asse delle ore: dalle 00:00 alle 24:00 UTC ogni 3 ore
                float ya = yb2 + hb + S(4);
                using (Pen pt = new Pen(Color.FromArgb(138, 148, 166)))
                    for (int kk = 0; kk <= 24; kk += 3)
                    {
                        float xx = bx + kk / 24f * bw;
                        g.DrawLine(pt, xx, ya, xx, ya + S(6));
                        Testo(g, (kk % 24).ToString("00", inv) + ":00", fx, Tema.Muted, new RectangleF(xx - S(30), ya + S(7), S(60), S(16)), StringAlignment.Center, StringAlignment.Near);
                    }
                // adesso
                if (trk.StrisciaT0 != DateTime.MinValue)
                {
                    float xa = bx + (float)((trk.Utc - trk.StrisciaT0).TotalHours / 24.0 * bw);
                    Color rosso = Color.FromArgb(198, 40, 40);
                    using (Pen pa = new Pen(rosso, S(5) / 2f)) g.DrawLine(pa, xa, yb1 - S(8), xa, ya + S(2));
                    // maniglia: si trascina per scegliere l'ora
                    using (Brush bm = new SolidBrush(rosso)) g.FillEllipse(bm, xa - S(5), yb1 - S(13), S(10), S(10));
                    string et = trk.Diretta ? Lang.T("adesso") : trk.Utc.ToString("HH:mm", inv) + " UTC";
                    float we = g.MeasureString(et, fa).Width + S(8);
                    float xe = xa + S(4) + we > r.Right - S(6) ? xa - S(4) - we : xa + S(4);
                    Testo(g, et, fa, rosso, new RectangleF(xe, ya + S(21), we, S(16)), xe < xa ? StringAlignment.Far : StringAlignment.Near, StringAlignment.Near);
                }
            }
        }

        // Fase della Luna: frazione illuminata e nome
        static string NomeFase(double k, bool crescente)
        {
            if (k < 0.03) return Lang.T("Luna nuova");
            if (k > 0.97) return Lang.T("Luna piena");
            if (Math.Abs(k - 0.5) < 0.06) return crescente ? Lang.T("Primo quarto") : Lang.T("Ultimo quarto");
            if (k < 0.5) return crescente ? Lang.T("Luna crescente") : Lang.T("Luna calante");
            return crescente ? Lang.T("Gibbosa crescente") : Lang.T("Gibbosa calante");
        }

        // Prossimo sorgere e tramonto della Luna (ora locale), entro 36 ore
        string SorgeTramonta(DateTime t0)
        {
            DateTime? sorge = null, tram = null;
            double ePrec = Moon.Compute(t0, me.Lat, me.Lon, (double)me.H.Value, chkRefr.Checked).El;
            for (int m = 10; m <= 36 * 60 && (sorge == null || tram == null); m += 10)
            {
                DateTime t = t0.AddMinutes(m);
                double el = Moon.Compute(t, me.Lat, me.Lon, (double)me.H.Value, chkRefr.Checked).El;
                if (ePrec < 0 && el >= 0 && sorge == null) sorge = t.AddMinutes(-10 * el / (el - ePrec));
                if (ePrec >= 0 && el < 0 && tram == null) tram = t.AddMinutes(-10 * el / (el - ePrec));
                ePrec = el;
            }
            Func<DateTime?, string> fmt = v => v.HasValue ? TimeZoneInfo.ConvertTimeFromUtc(v.Value, TimeZoneInfo.Local).ToString("HH:mm", inv) : "--:--";
            return string.Format(ci, Lang.T("Sorge {0} · Tramonta {1} (ora locale)"), fmt(sorge), fmt(tram));
        }

        // Finestra in corso o prossima (stessa regola di ProssimaFinestra), passo 2 minuti fino a 3 giorni
        bool CercaFinestra(DateTime t0, out bool inCorso, out DateTime a, out DateTime b)
        {
            Func<DateTime, bool> ok = tt =>
            {
                bool okMe;
                MoonPos p = Moon.Compute(tt, me.Lat, me.Lon, (double)me.H.Value, chkRefr.Checked);
                me.Valuta(p, out okMe);
                if (!okMe || !(chkDx.Checked && dx.Ok)) return okMe;
                bool okDx;
                MoonPos q = Moon.Compute(tt, dx.Lat, dx.Lon, (double)dx.H.Value, chkRefr.Checked);
                dx.Valuta(q, out okDx);
                return okDx;
            };
            DateTime lim = t0.AddDays(3);
            DateTime t = t0;
            inCorso = ok(t);
            a = t0; b = t0;
            if (inCorso)
            {
                while (t < lim && ok(t)) t = t.AddMinutes(2);
                b = t;
                return true;
            }
            while (t < lim && !ok(t)) t = t.AddMinutes(2);
            if (t >= lim) return false;
            a = t;
            while (t < lim && ok(t)) t = t.AddMinutes(2);
            b = t;
            return true;
        }

        // Giorno UTC in corso a passi di 5 minuti: bit 1 Luna nei miei limiti, bit 2 Luna sopra l'orizzonte del DX, bit 4 finestra comune
        void CalcolaStriscia(DateTime now, bool useDx)
        {
            DateTime t0 = new DateTime(now.Year, now.Month, now.Day, 0, 0, 0, DateTimeKind.Utc);
            byte[] st = new byte[288];
            for (int i = 0; i < st.Length; i++)
            {
                DateTime t = t0.AddMinutes(5 * i);
                MoonPos p = Moon.Compute(t, me.Lat, me.Lon, (double)me.H.Value, chkRefr.Checked);
                bool okMe, okDx = false;
                me.Valuta(p, out okMe);
                byte b = (byte)(okMe ? 1 : 0);
                if (useDx)
                {
                    MoonPos q = Moon.Compute(t, dx.Lat, dx.Lon, (double)dx.H.Value, chkRefr.Checked);
                    dx.Valuta(q, out okDx);
                    if (q.El >= 0) b |= 2;
                    if (okMe && okDx) b |= 4;
                }
                st[i] = b;
            }
            trk.Striscia = st;
            trk.StrisciaT0 = t0;
        }

        // "40,556° N 14,234° E · 10 caratteri · ±18 m"
        string SottoLocator(string loc, double lat, double lon)
        {
            string t = (loc ?? "").Trim();
            string r = CoordBreve(lat, lon, ci);
            double m = Locator.ErroreMetri(t, lat);
            if (!double.IsNaN(m)) r += " · " + string.Format(ci, Lang.T("{0} caratteri"), t.Length) + " · " + Locator.TestoErrore(m, ci);
            return r;
        }

        void AggiornaTracciamento(bool forzaFinestra)
        {
            if (pnlTrk == null || me == null) return;
            DateTime now = trkScelto.HasValue ? trkScelto.Value : DateTime.UtcNow;
            trk.Utc = now;
            trk.Diretta = !trkScelto.HasValue;
            if (dtpTrkGiorno != null && dtpTrkGiorno.Value.Date != now.Date)
            {
                trkSyncGiorno = true;
                try { dtpTrkGiorno.Value = now.Date; } catch { }
                trkSyncGiorno = false;
            }
            if (btnTrkAdesso != null && btnTrkAdesso.Visible == trk.Diretta) { btnTrkAdesso.Visible = !trk.Diretta; cardFreq.Invalidate(); }
            if (txtTrkLoc.ForeColor != CVal) txtTrkLoc.ForeColor = CVal;
            if (txtTrkDx.ForeColor != ColArancio) { txtTrkDx.ForeColor = ColArancio; txtTrkDxCall.ForeColor = ColArancio; }
            if (txtTrkLoc.BackColor != Tema.Field) { txtTrkLoc.BackColor = Tema.Field; txtTrkDx.BackColor = Tema.Field; txtTrkDxCall.BackColor = Tema.Field; }
            // riga sotto il locator del DX
            string g3c;
            int st3 = StatoCall3(out g3c);
            subDxTag = "";
            if (st3 == 2) { subDx = string.Format(Lang.T("CALL3.TXT: {0} · Invio sul nominativo per usarlo"), g3c); subDxCol = Tema.Scuro ? ColArancio : Color.FromArgb(194, 124, 14); }
            else if (txtTrkDx.Text.Trim().Length == 0 && st3 == 3) { subDx = Lang.T("nominativo non presente nel CALL3.TXT: inserisci il locator"); subDxCol = Tema.Muted; }
            else if (txtTrkDx.Text.Trim().Length == 0) { subDx = Lang.T("inserisci il locator della stazione da ascoltare"); subDxCol = Tema.Muted; }
            else if (!dx.Ok)
            {
                string c3, g3 = ProponiCall3(txtTrkDx.Text, out c3);
                if (g3 != null) { subDx = string.Format(Lang.T("{0} nel CALL3.TXT: {1} (premi Invio per usarlo)"), c3, g3); subDxCol = Tema.OkFg; }
                else { subDx = Lang.T("locator non valido"); subDxCol = Tema.BadFg; }
            }
            else
            {
                if (st3 == 1) subDxTag = "CALL3.TXT";
                subDx = SottoLocator(txtTrkDx.Text, dx.Lat, dx.Lon) + (chkDx.Checked ? "" : Lang.T("   (seconda stazione disattivata)"));
                subDxCol = Tema.Muted;
            }
            trk.DxValido = dx.Ok;
            trk.DxTz = dx.Ok ? dx.Tz : null;
            trk.DxTzNome = dx.TzNome ?? "";
            trk.MeOk = me.Ok;
            AggiornaSottoFreq();
            if (!me.Ok)
            {
                subMe = Lang.T("locator non valido"); subMeCol = Tema.BadFg; badgeMe = "";
                trk.Stato = -1;
                InvalidaSchede();
                pnlTrk.Invalidate();
                return;
            }
            string tl = txtTrkLoc.Text.Trim();
            subMe = SottoLocator(tl, me.Lat, me.Lon) + (tl.Length >= 8 ? "" : " · " + Lang.T("per gli ostacoli usa 8 o 10 caratteri"));
            subMeCol = Tema.Muted;
            badgeMe = tl.Length >= 8 ? Lang.T("adatto agli ostacoli") : "";
            double f;
            if (!ReadFreq(out f)) f = 144;
            bool useDx = chkDx.Checked && dx.Ok;
            Riga r = Calcola1(now, useDx, f, chkRefr.Checked);
            trk.UsaDx = useDx;
            trk.Az = r.P.Az; trk.El = r.P.El;
            trk.Az1 = (double)me.Az1.Value; trk.Az2 = (double)me.Az2.Value;
            trk.El1 = (double)me.El1.Value; trk.El2 = (double)me.El2.Value;
            trk.Stato = useDx && r.Ok ? 3 : (r.OkMe ? 0 : (r.P.El < 0 ? 2 : 1));
            bool dxLibero = (double)dx.El1.Value <= 0 && (double)dx.El2.Value >= 90
                && ((double)dx.Az2.Value - (double)dx.Az1.Value >= 360.0 || dx.Az1.Value == dx.Az2.Value);
            trk.StatoTesto = useDx && r.Ok ? (dxLibero ? Lang.T("Luna nei limiti per te e sopra l'orizzonte per il DX") : Lang.T("Luna nei limiti per te e per il DX"))
                : (r.OkMe ? Lang.T("Luna nei limiti della tua antenna") : (r.P.El < 0 ? Lang.T("Luna sotto l'orizzonte") : string.Format(ci, Lang.T("Luna sopra l'orizzonte ma fuori dai limiti ({0})"), r.StatoMe)));
            trk.Info.Clear();
            const double C_KMS = 299792.458;
            trk.EcoTxt = Hz(2 * r.DopMe, ci).Replace("-", "−") + " Hz · " + (2.0 * r.P.DistTopo / C_KMS).ToString("F2", ci) + " s";
            trk.DxIoTxt = useDx ? Hz(r.DopMe + r.DopDx, ci).Replace("-", "−") + " Hz · " + ((r.P.DistTopo + r.Q.DistTopo) / C_KMS).ToString("F2", ci) + " s" : "";
            trk.CfomTx = ((f * 1e6 - r.DopMe) / 1000.0).ToString("N3", ci) + " MHz";
            trk.CfomRx = ((f * 1e6 + r.DopMe) / 1000.0).ToString("N3", ci) + " MHz";
            trk.Info.Add(new string[] { Lang.T("Tsky dietro la Luna"), r.Tsky.ToString("F0", ci) + " K" });
            trk.Info.Add(new string[] { Lang.T("Distanza"), r.P.DistTopo.ToString("N0", ci) + " km" });
            trk.Info.Add(new string[] { Lang.T("Declinazione"), r.P.Dec.ToString("F1", ci).Replace("-", "−") + "°" });
            trk.Info.Add(new string[] { Lang.T("Angolo orario"), r.P.Ha.ToString("F1", ci).Replace("-", "−") + "°" });
            trk.Dgrd = r.DgrdMe;
            if (useDx)
            {
                trk.AzDx = r.Q.Az; trk.ElDx = r.Q.El;
                trk.DxStato = r.OkDx ? 0 : (r.Q.El < 0 ? 2 : 1);
                trk.DxTitolo = "DX " + dx.Loc.Text.Trim() + " · " + r.StatoDx;
                trk.DxRiga = string.Format(ci, "{0:F0}° / {1:F1} dB", r.Dpol, r.Mnr);
                double dsaz, dsel, dsra, dsdec;
                Moon.SunPos(now, dx.Lat, dx.Lon, out dsaz, out dsel, out dsra, out dsdec);
                trk.DxSole = dsel < 0 ? Lang.T("sotto l'orizzonte") : string.Format(ci, "Az {0:F1}° · El {1:F1}°", dsaz, dsel);
            }
            // fase della Luna dalla distanza angolare Sole-Luna
            double saz, sel, sra, sdec;
            Moon.SunPos(now, me.Lat, me.Lon, out saz, out sel, out sra, out sdec);
            double elong = Moon.Separation(sra, sdec, r.P.Ra, r.P.Dec);
            trk.Illum = (1 - Math.Cos(elong * Math.PI / 180.0)) / 2.0;
            trk.Crescente = ((r.P.Ra - sra + 720.0) % 360.0) < 180.0;
            trk.Fase = NomeFase(trk.Illum, trk.Crescente);
            if (forzaFinestra || trkTrascina || Math.Abs((now - trkWinCalc).TotalSeconds) >= 60)
            {
                DateTime t0 = new DateTime(now.Year, now.Month, now.Day, now.Hour, now.Minute, 0, DateTimeKind.Utc);
                trkWinTxt = ProssimaFinestra(t0);
                bool inC; DateTime fa, fb;
                trk.FinTrovata = CercaFinestra(t0, out inC, out fa, out fb);
                trk.FinInCorso = inC; trk.FinA = fa; trk.FinB = fb;
                // la striscia del giorno si ricalcola solo se cambia il giorno o i dati (non a ogni passo del trascinamento)
                if (!trkTrascina || trk.StrisciaT0 != now.Date) CalcolaStriscia(now, useDx);
                trk.SorgeTramonta = SorgeTramonta(t0);
                trkWinCalc = now;
            }
            trk.Finestra = trkWinTxt;
            string avMe = AvvisoZona(me, Lang.T("La mia stazione")), avDx = useDx ? AvvisoZona(dx, "DX") : "";
            trk.Avvisi = (avMe + (avMe.Length > 0 && avDx.Length > 0 ? "\n" : "") + avDx);
            if (!trk.FinTrovata) trk.Conto = Lang.T("Nessuna finestra nei prossimi 3 giorni");
            else if (trk.FinInCorso) trk.Conto = string.Format(ci, Lang.T("termina tra {0}"), Durata(trk.FinB > now ? trk.FinB - now : TimeSpan.Zero));
            else trk.Conto = string.Format(ci, Lang.T("inizia tra {0}"), Durata(trk.FinA > now ? trk.FinA - now : TimeSpan.Zero));
            trk.SnOn = chkDatiMain != null && chkDatiMain.Checked;
            if (trk.SnOn) AggiornaSnTracciamento(now);
            InvalidaSchede();
            pnlTrk.Invalidate();
        }

        // "· 10 caratteri · ±18 m", con un consiglio per la mia stazione se il locator è corto
        string PrecisioneLoc(string loc, double lat, bool mia)
        {
            string t = (loc ?? "").Trim();
            double m = Locator.ErroreMetri(t, lat);
            if (double.IsNaN(m)) return "";
            string r = "   · " + string.Format(ci, Lang.T("{0} caratteri"), t.Length) + " · " + Locator.TestoErrore(m, ci);
            if (mia) r += t.Length >= 8 ? "  ✓ " + Lang.T("adatto agli ostacoli") : "  · " + Lang.T("per gli ostacoli usa 8 o 10 caratteri");
            return r;
        }

        static string SnTxt(double v, CultureInfo c) { return (v >= 0 ? "+" : "") + v.ToString("F1", c) + " dB"; }

        // S/N stimato in questo istante con i parametri del Budget EME (banda e banda passante scelte)
        void AggiornaSnTracciamento(DateTime now)
        {
            if (bMe == null || bDx == null) { trk.SnValido = false; trk.SnMsg = ""; return; }
            if (!me.Ok || !chkDx.Checked || !dx.Ok)
            {
                trk.SnValido = false;
                trk.SnMsg = Lang.T("S/N: servono un locator valido per la tua stazione e il DX attivo.");
                return;
            }
            BudgetParams.Freq = curBand;
            BudgetParams pm = BudgetParams.FromUi(bMe), pd = BudgetParams.FromUi(bDx);
            double freq = curBand;
            double bw = LeggiBw();
            Riga r = Calcola1(now, true, freq, chkRefr.Checked);
            double path = Moon.PathLoss(freq, r.P.DistTopo, r.Q.DistTopo);
            double pol = chkPol.Checked ? r.PolLoss : 0.0;
            double tskyDx = Moon.Tsky(r.Q.Lambda, freq), tskyMe = Moon.Tsky(r.P.Lambda, freq);
            double ggMe = pm.GroundOn > 0.5 ? GroundGain(pm.GroundH, r.P.El, freq) : 0.0;
            double ggDx = pd.GroundOn > 0.5 ? GroundGain(pd.GroundH, r.Q.El, freq) : 0.0;
            Tratta a = CalcTratta(pm, pd, path, pol, tskyDx, 0, bw, ggMe, ggDx, 0, freq);
            Tratta b = CalcTratta(pd, pm, path, pol, tskyMe, 0, bw, ggDx, ggMe, 0, freq);
            trk.SnA = a.SNb; trk.SnB = b.SNb;
            trk.SnSoleA = double.NaN; trk.SnSoleB = double.NaN;
            if (complessi)
            {
                SolarInfo xa = CalcSolar(now, r.Q, dx, pd, freq, false);
                SolarInfo xb = CalcSolar(now, r.P, me, pm, freq, true);
                if (xa.Valid || xb.Valid)
                {
                    Tratta a2 = CalcTratta(pm, pd, path, pol, tskyDx, xa.Valid ? xa.Tsun : 0, bw, ggMe, ggDx, 0, freq);
                    Tratta b2 = CalcTratta(pd, pm, path, pol, tskyMe, xb.Valid ? xb.Tsun : 0, bw, ggDx, ggMe, 0, freq);
                    trk.SnSoleA = a2.SNb; trk.SnSoleB = b2.SNb;
                }
            }
            trk.SnValido = true;
            trk.SnComune = r.Ok;
            trk.SnMargine = Sn2500(b.SNb, bw);   // S/N riportato a 2500 Hz con cui io ricevo il DX (non più un margine sul modo)
            trk.SnSoglia = pm.SnReq;
            trk.SnNomeModo = pm.NomeModo;
            trk.SnRiga = string.Format(ci, Lang.T("{0} dB in 2500 Hz · soglia tipica {1}: {2} dB"), Segno(trk.SnMargine, ci), pm.NomeModo, pm.SnReq.ToString("0.#", ci)) + "\n"
                + Lang.T("Io → DX") + " " + SnTxt(trk.SnA, ci)
                + (double.IsNaN(trk.SnSoleB) ? "" : " · " + Lang.T("Sole") + " " + SnTxt(trk.SnSoleB, ci));
            trk.SnTitolo = string.Format(ci, Lang.T("S/N stimato adesso ({0} Hz)"), bw.ToString("0", ci));
        }

        // ---------- Download del log da LoTW (ARRL Logbook of the World) ----------

        Button btnLotw;
        string lotwUtente = "", lotwPassword = "";   // la password è cifrata con DPAPI di Windows (utente corrente)

        static string CifraPassword(string p)
        {
            if (string.IsNullOrEmpty(p)) return "";
            try
            {
                byte[] b = System.Security.Cryptography.ProtectedData.Protect(Encoding.UTF8.GetBytes(p), null,
                    System.Security.Cryptography.DataProtectionScope.CurrentUser);
                return Convert.ToBase64String(b);
            }
            catch { return ""; }
        }

        internal static string DecifraPassword(string c)
        {
            if (string.IsNullOrEmpty(c)) return "";
            try
            {
                byte[] b = System.Security.Cryptography.ProtectedData.Unprotect(Convert.FromBase64String(c), null,
                    System.Security.Cryptography.DataProtectionScope.CurrentUser);
                return Encoding.UTF8.GetString(b);
            }
            catch { return ""; }
        }

        bool ChiediCredenzialiLotw(ref string utente, ref string password, out bool memorizza)
        {
            memorizza = true;
            using (Form f = new Form())
            {
                f.Text = Lang.T("Download da LoTW");
                f.FormBorderStyle = FormBorderStyle.FixedDialog;
                f.MaximizeBox = false;
                f.MinimizeBox = false;
                f.ShowInTaskbar = false;
                f.StartPosition = FormStartPosition.CenterParent;
                f.Font = this.Font;
                f.AutoSize = true;
                f.AutoSizeMode = AutoSizeMode.GrowAndShrink;
                f.BackColor = Tema.Back;
                f.ForeColor = Tema.Fore;
                TableLayoutPanel g = new TableLayoutPanel();
                g.AutoSize = true;
                g.AutoSizeMode = AutoSizeMode.GrowAndShrink;
                g.ColumnCount = 2;
                g.Padding = new Padding(S(12));
                Label l0 = new Label();
                l0.Text = Lang.T("Inserisci nome utente e password di LoTW.");
                l0.AutoSize = true;
                l0.Margin = new Padding(S(3), S(3), S(3), S(10));
                g.Controls.Add(l0, 0, 0); g.SetColumnSpan(l0, 2);
                TextBox tu = new TextBox(); tu.Width = S(220); tu.Text = utente;
                TextBox tpw = new TextBox(); tpw.Width = S(220); tpw.UseSystemPasswordChar = true; tpw.Text = password;
                g.Controls.Add(L(Lang.T("Nome utente LoTW")), 0, 1); g.Controls.Add(tu, 1, 1);
                g.Controls.Add(L(Lang.T("Password LoTW")), 0, 2); g.Controls.Add(tpw, 1, 2);
                CheckBox cm = new Spunta();
                cm.Text = Lang.T("Memorizza nome utente e password nelle impostazioni");
                cm.AutoSize = true;
                cm.Checked = true;
                cm.Margin = new Padding(S(3), S(8), S(3), S(3));
                g.Controls.Add(cm, 0, 3); g.SetColumnSpan(cm, 2);
                FlowLayoutPanel bt = new FlowLayoutPanel();
                bt.AutoSize = true;
                bt.Margin = new Padding(S(3), S(10), S(3), S(3));
                Button ok = new Pulsante(); ok.Text = "OK"; ok.AutoSize = true; ok.DialogResult = DialogResult.OK; ok.BackColor = Tema.Button;
                Button an = new Pulsante(); an.Text = Lang.T("Annulla"); an.AutoSize = true; an.DialogResult = DialogResult.Cancel; an.BackColor = Tema.Button;
                StileDialogo(f, g, ok, an);
                f.AcceptButton = ok;
                f.CancelButton = an;
                if (f.ShowDialog(this) != DialogResult.OK) return false;
                utente = tu.Text.Trim();
                password = tpw.Text;
                memorizza = cm.Checked;
                return utente.Length > 0 && password.Length > 0;
            }
        }

        void ScaricaLotw()
        {
            string u = lotwUtente, p = DecifraPassword(lotwPassword);
            bool mem;
            if (!ChiediCredenzialiLotw(ref u, ref p, out mem)) return;
            if (mem) { lotwUtente = u; lotwPassword = CifraPassword(p); }
            else { lotwUtente = ""; lotwPassword = ""; }
            SaveSettings();
            string url = "https://lotw.arrl.org/lotwuser/lotwreport.adi?login=" + Uri.EscapeDataString(u)
                + "&password=" + Uri.EscapeDataString(p)
                + "&qso_query=1&qso_qsl=no&qso_qsldetail=yes&qso_mydetail=yes&qso_withown=yes";
            try
            {
                ServicePointManager.SecurityProtocol = (SecurityProtocolType)3072 | (SecurityProtocolType)768 | SecurityProtocolType.Tls;
            }
            catch { }
            WebClient wc = new WebClient();
            wc.Headers.Add("User-Agent", "YAEC/27 (EME calculator for radio amateurs)");
            btnLotw.Enabled = false;
            lblAdif.Text = Lang.T("Scaricamento da LoTW in corso… (può richiedere qualche minuto)");
            string dest = Path.Combine(Path.GetDirectoryName(settingsPath), "lotw.adi");
            wc.DownloadDataCompleted += (s, e) =>
            {
                btnLotw.Enabled = true;
                ((WebClient)s).Dispose();
                if (e.Error != null)
                {
                    lblAdif.Text = Lang.T("LoTW: errore di scaricamento: ") + e.Error.Message;
                    Messaggio(this, lblAdif.Text, "YAEC", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    return;
                }
                string txt = Encoding.GetEncoding(28591).GetString(e.Result);
                if (txt.IndexOf("<eoh>", StringComparison.OrdinalIgnoreCase) < 0)
                {
                    lblAdif.Text = Lang.T("LoTW: accesso non riuscito (nome utente o password errati?).");
                    Messaggio(this, lblAdif.Text, "YAEC", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }
                try { File.WriteAllBytes(dest, e.Result); }
                catch (Exception ex)
                {
                    Messaggio(this, Lang.T("Impossibile salvare il file:\n") + ex.Message, "YAEC", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    return;
                }
                CaricaAdif(dest, true);
                SaveSettings();
            };
            try { wc.DownloadDataAsync(new Uri(url)); }
            catch (Exception ex)
            {
                btnLotw.Enabled = true;
                lblAdif.Text = Lang.T("LoTW: errore di scaricamento: ") + ex.Message;
                wc.Dispose();
            }
        }

