        static string[] TestiMnrCfom()
        {
            return new string[] {
                Lang.T("MNR (Maximum Non-Reciprocity, massima non reciprocità). Con antenne a polarizzazione lineare il segnale EME subisce due rotazioni del piano di polarizzazione: quella geometrica (Dpol), dovuta al fatto che le due stazioni vedono la Luna da punti diversi della Terra, e la rotazione di Faraday nella ionosfera, che dipende dal campo magnetico terrestre e dallo stato della ionosfera e non si può prevedere."),
                Lang.T("La rotazione di Faraday ha lo stesso verso nei due sensi del collegamento, mentre la rotazione geometrica si inverte: per questo l'angolo totale può essere diverso andando da te al DX e dal DX a te. Il collegamento diventa non reciproco: uno dei due sente bene e l'altro male."),
                Lang.T("MNR = -20·log|cos(2·Dpol)| è il caso peggiore di questa differenza, in dB. Con MNR 0 dB i due sensi sono sempre uguali; con MNR alto (Dpol vicino a ±45°) può succedere che tu senta il DX e lui non senta te, o il contrario, anche con stazioni identiche. Conviene scegliere i momenti con MNR basso, oppure usare antenne a polarizzazione regolabile o circolare."),
                Lang.T("CFOM = Constant Frequency On the Moon, frequenza costante sulla Luna. Il moto della Luna e la rotazione della Terra spostano la frequenza per effetto Doppler, in modo diverso per ogni stazione e variabile nel tempo (a 144 MHz fino a circa ±400 Hz in sola andata, il doppio per la propria eco)."),
                Lang.T("Con il metodo CFOM ogni stazione corregge solo il proprio Doppler: trasmette su f0 - Doppler (così il segnale arriva sulla Luna esattamente a f0) e riceve su f0 + Doppler. Se entrambe le stazioni fanno così si incontrano sempre sulla frequenza f0 \"sulla Luna\", senza conoscere il Doppler dell'altro: è come se la Luna fosse un ripetitore fisso su f0."),
                Lang.T("Nel programma f0 è la frequenza impostata (MHz + kHz); le colonne TX io CFOM e RX io CFOM e i valori della schermata principale indicano le frequenze da impostare sulla radio. WSJT-X applica lo stesso schema con il Doppler tracking in modalità \"Constant frequency on Moon\".")
            };
        }

        // ---------- Quota del terreno dal web (solo con locator a 10 caratteri) ----------

        Dictionary<string, double> quoteCache = new Dictionary<string, double>();
        List<StationUi> quoteAttese = new List<StationUi>();
        Timer quotaTimer;

        // Chiede la quota qualche istante dopo l'ultima modifica del locator
        void ProgrammaQuota(StationUi st)
        {
            if (caricamento || st == null || st.Loc == null) return;
            string loc = st.Loc.Text.Trim().ToUpperInvariant();
            double la, lo;
            if (loc.Length < 10 || !Locator.TryParse(loc, out la, out lo)) return;
            if (!quoteAttese.Contains(st)) quoteAttese.Add(st);
            if (quotaTimer == null)
            {
                quotaTimer = new Timer();
                quotaTimer.Interval = 1200;
                quotaTimer.Tick += (s, e) =>
                {
                    quotaTimer.Stop();
                    StationUi[] da = quoteAttese.ToArray();
                    quoteAttese.Clear();
                    for (int i = 0; i < da.Length; i++)
                    {
                        StationUi x = da[i];
                        int ritardo = i;
                        if (ritardo == 0) ChiediQuota(x);
                        else
                        {
                            // Open Topo Data accetta al massimo una richiesta al secondo
                            Timer t2 = new Timer();
                            t2.Interval = 1300 * ritardo;
                            t2.Tick += (s2, e2) => { t2.Stop(); t2.Dispose(); ChiediQuota(x); };
                            t2.Start();
                        }
                    }
                };
            }
            quotaTimer.Stop();
            quotaTimer.Start();
        }

        void ScaricaTesto(string url, Action<string, string> fatto)
        {
            try
            {
                ServicePointManager.SecurityProtocol = (SecurityProtocolType)3072 | (SecurityProtocolType)768 | SecurityProtocolType.Tls;
            }
            catch { }
            WebClient wc = new WebClient();
            wc.Encoding = Encoding.UTF8;
            wc.Headers.Add("User-Agent", "YAEC/27 (EME calculator for radio amateurs)");
            wc.DownloadStringCompleted += (s, e) =>
            {
                ((WebClient)s).Dispose();
                if (e.Error != null) fatto(null, e.Error.Message);
                else fatto(e.Result, null);
            };
            try { wc.DownloadStringAsync(new Uri(url)); }
            catch (Exception ex) { wc.Dispose(); fatto(null, ex.Message); }
        }

        static double QuotaOpenTopo(string json)
        {
            try
            {
                if (string.IsNullOrEmpty(json)) return double.NaN;
                JavaScriptSerializer js = new JavaScriptSerializer();
                Dictionary<string, object> d = js.DeserializeObject(json) as Dictionary<string, object>;
                if (d == null || !d.ContainsKey("results")) return double.NaN;
                object[] r = d["results"] as object[];
                if (r == null || r.Length == 0) return double.NaN;
                Dictionary<string, object> r0 = r[0] as Dictionary<string, object>;
                if (r0 == null || !r0.ContainsKey("elevation") || r0["elevation"] == null) return double.NaN;
                return ToD(r0["elevation"]);
            }
            catch { return double.NaN; }
        }

        static double QuotaOpenMeteo(string json)
        {
            try
            {
                if (string.IsNullOrEmpty(json)) return double.NaN;
                JavaScriptSerializer js = new JavaScriptSerializer();
                Dictionary<string, object> d = js.DeserializeObject(json) as Dictionary<string, object>;
                if (d == null || !d.ContainsKey("elevation")) return double.NaN;
                object[] r = d["elevation"] as object[];
                if (r == null || r.Length == 0 || r[0] == null) return double.NaN;
                return ToD(r[0]);
            }
            catch { return double.NaN; }
        }

        void ChiediQuota(StationUi st)
        {
            string loc = st.Loc.Text.Trim().ToUpperInvariant();
            double la, lo;
            if (loc.Length < 10 || !Locator.TryParse(loc, out la, out lo)) return;
            double h;
            if (quoteCache.TryGetValue(loc, out h)) { ApplicaQuota(st, loc, h, Lang.T("memorizzata")); return; }
            bool europa = la >= 34 && la <= 72 && lo >= -25 && lo <= 45;
            string ds = europa ? "eudem25m" : "srtm30m";
            string fonte1 = europa ? "EU-DEM 25 m (Open Topo Data)" : "SRTM 30 m (Open Topo Data)";
            string url1 = "https://api.opentopodata.org/v1/" + ds + "?locations=" + la.ToString("F6", inv) + "," + lo.ToString("F6", inv);
            string url2 = "https://api.open-meteo.com/v1/elevation?latitude=" + la.ToString("F6", inv) + "&longitude=" + lo.ToString("F6", inv);
            lblStatus.Text = Lang.T("Ricerca della quota dal web per ") + loc + "…";
            ScaricaTesto(url1, (t1, err1) =>
            {
                double v1 = QuotaOpenTopo(t1);
                if (!double.IsNaN(v1))
                {
                    quoteCache[loc] = v1;
                    ApplicaQuota(st, loc, v1, fonte1);
                    return;
                }
                ScaricaTesto(url2, (t2, err2) =>
                {
                    double v2 = QuotaOpenMeteo(t2);
                    if (!double.IsNaN(v2))
                    {
                        quoteCache[loc] = v2;
                        ApplicaQuota(st, loc, v2, "Copernicus GLO-90 (Open-Meteo)");
                    }
                    else lblStatus.Text = Lang.T("Quota dal web non disponibile per ") + loc + (err2 != null ? ": " + err2 : (err1 != null ? ": " + err1 : ""));
                });
            });
        }

        void ApplicaQuota(StationUi st, string loc, double h, string fonte)
        {
            if (st.Loc.Text.Trim().ToUpperInvariant() != loc) return;   // locator cambiato nel frattempo
            decimal d = (decimal)Math.Round(h);
            if (d < st.H.Minimum) d = st.H.Minimum;
            if (d > st.H.Maximum) d = st.H.Maximum;
            st.H.Value = d;
            lblStatus.Text = string.Format(ci, Lang.T("Quota del terreno per {0} dal web: {1:F0} m s.l.m. ({2})."), loc, h, fonte);
            UpdateLive();
            if (!caricamento) SaveSettings();
        }

        // Applica la casella "CALCOLI APPROFONDITI"
        void ApplicaComplessi()
        {
            if (chkComplessiB != null && chkComplessiB.Checked != chkComplessi.Checked) chkComplessiB.Checked = chkComplessi.Checked;
            if (pnlTrk != null) pnlTrk.Invalidate();
            if (caricamento) return;
            SetupColumns(tutte.Count > 0 ? calcDx : chkDx.Checked);
            ApplyFilter();
            RecalcBudget();
            RiempiTabellaDg();
            if (tabs != null)
            {
                if (!complessi && (tabs.SelectedTab == tpSolar || tabs.SelectedTab == tpDebug || tabs.SelectedTab == tpExcel)) tabs.SelectedTab = tpTrack;
                tabs.Invalidate();
                if (pnlNav != null) pnlNav.Invalidate();
            }
            if (complessi && chkSfuAuto != null && chkSfuAuto.Checked && !sfuSessione) ScaricaSfu();
            AggiornaTracciamento(false);
            SaveSettings();
        }

        // Ricostruisce le tendine con le bande scelte (interattivo = cambia banda se quella attuale è stata tolta)
        void ApplicaBande(List<int> nuove, bool interattivo)
        {
            List<int> l = new List<int>();
            foreach (int f in Bande) if (nuove.Contains(f)) l.Add(f);
            if (l.Count == 0) return;
            ricostruzioneBande = true;
            try
            {
                bandeAttive = l;
                foreach (ComboBox c in new ComboBox[] { cmbBand, cmbBand3 })
                {
                    if (c == null) continue;
                    c.Items.Clear();
                    foreach (int f in bandeAttive) c.Items.Add(NomeBanda(f));
                }
                foreach (ComboBox c in new ComboBox[] { cmbFreq, cmbTrkMhz })
                {
                    if (c == null) continue;
                    string t = c.Text;
                    c.Items.Clear();
                    foreach (int f in bandeAttive) c.Items.Add(f.ToString(inv));
                    if (c.Text != t) c.Text = t;
                }
                if (bandeAttive.Contains(curBand))
                {
                    if (cmbBand != null) cmbBand.SelectedIndex = bandeAttive.IndexOf(curBand);
                    if (cmbBand3 != null) cmbBand3.SelectedIndex = bandeAttive.IndexOf(curBand);
                }
            }
            finally { ricostruzioneBande = false; }
            if (interattivo && !bandeAttive.Contains(curBand) && cmbBand != null)
                cmbBand.SelectedIndex = 0;   // passa alla prima banda scelta (CambiaBanda)
        }

        // Finestra di scelta delle bande
        void ScegliBande()
        {
            using (Form f = new Form())
            {
                f.Text = Lang.T("Scelta delle bande");
                f.FormBorderStyle = FormBorderStyle.FixedDialog;
                f.MaximizeBox = false;
                f.MinimizeBox = false;
                f.ShowInTaskbar = false;
                f.StartPosition = FormStartPosition.CenterParent;
                f.Font = this.Font;
                f.AutoSize = true;
                f.AutoSizeMode = AutoSizeMode.GrowAndShrink;
                f.BackColor = Tema.Back;
                f.ForeColor = Tema.Fore;
                FlowLayoutPanel p = new FlowLayoutPanel();
                p.FlowDirection = FlowDirection.TopDown;
                p.WrapContents = false;
                p.AutoSize = true;
                p.AutoSizeMode = AutoSizeMode.GrowAndShrink;
                p.Padding = new Padding(S(12));
                Label l = new Label();
                l.Text = Lang.T("Scegli le bande da usare nei calcoli (Budget EME, Rumore solare e tendine dei MHz):");
                l.AutoSize = true;
                l.MaximumSize = new Size(S(380), 0);
                l.Margin = new Padding(S(3), S(3), S(3), S(8));
                p.Controls.Add(l);
                List<CheckBox> cbs = new List<CheckBox>();
                foreach (int b in Bande)
                {
                    CheckBox c = new Spunta();
                    c.Text = b >= 47000 ? (b / 1000).ToString(inv) + " GHz" : b.ToString(inv) + " MHz";
                    c.AutoSize = true;
                    c.Checked = bandeAttive.Contains(b);
                    c.Tag = b;
                    c.Font = new Font(this.Font, FontStyle.Bold);
                    c.Margin = new Padding(S(10), S(2), S(3), S(2));
                    cbs.Add(c);
                    p.Controls.Add(c);
                }
                FlowLayoutPanel bt = new FlowLayoutPanel();
                bt.AutoSize = true;
                bt.AutoSizeMode = AutoSizeMode.GrowAndShrink;
                bt.Margin = new Padding(S(3), S(10), S(3), S(3));
                Button ok = new Pulsante();
                ok.Text = "OK";
                ok.AutoSize = true;
                ok.DialogResult = DialogResult.OK;
                ok.BackColor = Tema.Button;
                Button an = new Pulsante();
                an.Text = Lang.T("Annulla");
                an.AutoSize = true;
                an.DialogResult = DialogResult.Cancel;
                an.BackColor = Tema.Button;
                StileDialogo(f, p, ok, an);
                f.AcceptButton = ok;
                f.CancelButton = an;
                while (true)
                {
                    if (f.ShowDialog(this) != DialogResult.OK) return;
                    List<int> scelte = new List<int>();
                    foreach (CheckBox c in cbs) if (c.Checked) scelte.Add((int)c.Tag);
                    if (scelte.Count == 0)
                    {
                        Messaggio(this, Lang.T("Seleziona almeno una banda."), "YAEC", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        continue;
                    }
                    ApplicaBande(scelte, true);
                    SaveSettings();
                    return;
                }
            }
        }

        // ---------- Linguetta "ABOUT e imp.generali" ----------

        RichTextBox rtAbout;
        TextBox txtCall;
        ComboBox cmbLingua;
        ComboBox cmbFontNome;
        ComboBox cmbTema;
        NumericUpDown nudFontTab, nudFontMod;

        void BuildAboutTab(TabPage tp)
        {
            TableLayoutPanel root = new TableLayoutPanel();
            root.Dock = DockStyle.Fill;
            root.ColumnCount = 1;
            root.RowCount = 2;
            root.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            root.RowStyles.Add(new RowStyle(SizeType.Percent, 100f));
            root.Padding = new Padding(S(8));

            cmbTema = new Tendina();
            cmbTema.DropDownStyle = ComboBoxStyle.DropDownList;
            cmbTema.Items.AddRange(new object[] { Lang.T("Chiaro"), Lang.T("Notte"), Lang.T("Nero") });
            foreach (string pn in Tema.PastelloNome) cmbTema.Items.Add(Lang.T(pn));
            cmbTema.DropDownWidth = S(200);
            cmbTema.SelectedIndex = Tema.Schema;
            cmbTema.Width = S(100);
            cmbTema.SelectedIndexChanged += (s, e) =>
            {
                if (caricamento) return;
                Tema.Imposta(cmbTema.SelectedIndex);
                ApplicaTema();
                SaveSettings();
            };
            nudFontTab = Nud(7, 18, (decimal)fontTabelle, 1, 60);
            nudFontTab.ValueChanged += (s, e) =>
            {
                if (caricamento) return;
                fontTabelle = (float)nudFontTab.Value;
                ApplicaFontTabelle();
                SaveSettings();
            };
            nudFontMod = Nud(8, 14, (decimal)(9F * fontFactor), 1, 60);
            nudFontMod.Increment = 0.5m;
            txtCall = new TextBox();
            txtCall.Width = S(120);
            txtCall.CharacterCasing = CharacterCasing.Upper;
            txtCall.MaxLength = 15;
            tip.SetToolTip(txtCall, Lang.T("Il tuo nominativo radioamatoriale: compare nella linguetta Posizione live e +- 24h, sulla mappa e nel titolo della finestra."));
            txtCall.TextChanged += (s, e) =>
            {
                if (caricamento) return;
                AggiornaTracciamento(false);
                this.Text = TitoloFinestra();
                if (map != null) map.Invalidate();
            };
            cmbLingua = new Tendina();
            cmbLingua.DropDownStyle = ComboBoxStyle.DropDownList;
            cmbLingua.Items.AddRange(Lang.Nomi);
            cmbLingua.SelectedIndex = Lang.Idx;
            cmbLingua.Width = S(130);
            cmbLingua.SelectedIndexChanged += (s, e) =>
            {
                if (caricamento) return;
                SaveSettings();
                BeginInvoke(new Action(Ricostruisci));   // si applica subito, senza riavviare
            };
            // Tipo di carattere: elenco con intestazione e nota, ogni nome scritto nel suo carattere
            cmbFontNome = new Tendina();
            cmbFontNome.DropDownStyle = ComboBoxStyle.DropDownList;
            cmbFontNome.Width = S(160);
            cmbFontNome.DrawMode = DrawMode.OwnerDrawVariable;
            cmbFontNome.MeasureItem += (s, e) => { e.ItemHeight = S(e.Index >= 0 && cmbFontNome.Items[e.Index] is VoceFont && ((VoceFont)cmbFontNome.Items[e.Index]).Tipo == 0 ? 24 : 22); };
            cmbFontNome.DrawItem += DisegnaVoceFont;
            cmbFontNome.MaxDropDownItems = 25;
            cmbFontNome.DropDownWidth = S(260);
            string consigliato = Lang.FontAuto;
            cmbFontNome.Items.Add(new VoceFont(Lang.T("Caratteri consigliati per YAEC"), 0, false));
            cmbFontNome.Items.Add(new VoceFont(Lang.T("Predefinito del sistema"), 1, false));
            List<string> installati = new List<string>();
            try
            {
                using (System.Drawing.Text.InstalledFontCollection fc = new System.Drawing.Text.InstalledFontCollection())
                    foreach (FontFamily ff in fc.Families)
                        if (ff.IsStyleAvailable(FontStyle.Regular) && ff.IsStyleAvailable(FontStyle.Bold)) installati.Add(ff.Name);
            }
            catch { }
            // solo una selezione ragionata (al massimo 10): caratteri senza grazie, leggibili a 9 pt, con grassetto vero,
            // cifre della stessa larghezza e i simboli usati (° ± √ ² µ → ⇄ ≈), larghi quanto Segoe UI così nessuna linguetta
            // taglia etichette o pulsanti; per le scritture non latine, i caratteri che contengono quella scrittura
            List<string> prima = new List<string>();
            string fsalvato = LeggiImpostazione("font_nome");
            foreach (string n0 in Lang.CaratteriConsigliati())
            {
                string trovato = null;
                foreach (string n in n0.Split('|')) if (trovato == null && installati.Contains(n)) trovato = n;
                if (trovato != null && !prima.Contains(trovato) && prima.Count < 10) prima.Add(trovato);
            }
            if (installati.Contains(consigliato) && !prima.Contains(consigliato)) { prima.Insert(0, consigliato); if (prima.Count > 10) prima.RemoveAt(10); }
            // un carattere scelto in passato e non più in elenco resta visibile, così la scelta non si perde
            if (!string.IsNullOrEmpty(fsalvato) && installati.Contains(fsalvato) && !prima.Contains(fsalvato) && Lang.CarattereAdatto(fsalvato)) prima.Add(fsalvato);
            foreach (string n in prima) cmbFontNome.Items.Add(new VoceFont(n, 2, n == consigliato));
            cmbFontNome.Items.Add(new VoceFont(Lang.T("ogni nome è scritto nel suo carattere"), 3, false));
            int fi = 1;
            for (int i = 0; i < cmbFontNome.Items.Count; i++)
            {
                VoceFont v = (VoceFont)cmbFontNome.Items[i];
                if (v.Tipo == 2 && v.Nome == fsalvato) fi = i;
            }
            cmbFontNome.SelectedIndex = fi;
            int fontPrec = fi;
            tip.SetToolTip(cmbFontNome, Lang.T("Carattere usato in tutto il programma (si applica subito). Con \"Predefinito del sistema\" si usa quello adatto alla lingua scelta."));
            cmbFontNome.SelectedIndexChanged += (s, e) =>
            {
                VoceFont v = cmbFontNome.SelectedItem as VoceFont;
                if (v == null || v.Tipo == 0 || v.Tipo == 3) { cmbFontNome.SelectedIndex = fontPrec; return; }
                if (cmbFontNome.SelectedIndex == fontPrec) return;
                fontPrec = cmbFontNome.SelectedIndex;
                if (caricamento) return;
                SaveSettings();
                BeginInvoke(new Action(Ricostruisci));   // si applica subito, senza riavviare
            };
            // Caratteri: una sola dimensione in percentuale per tabelle, finestre, caselle e pulsanti
            ComboBox cmbCaratteri = new Tendina();
            cmbCaratteri.DropDownStyle = ComboBoxStyle.DropDownList;
            cmbCaratteri.Width = S(80);
            int[] perc = { 90, 100, 110, 125, 150 };
            foreach (int pp in perc) cmbCaratteri.Items.Add(pp.ToString(inv) + " %");
            int sel = 1;
            for (int i = 0; i < perc.Length; i++) if (Math.Abs(perc[i] / 100f - fontFactor) < Math.Abs(perc[sel] / 100f - fontFactor)) sel = i;
            cmbCaratteri.SelectedIndex = sel;
            int carPrec = sel;
            tip.SetToolTip(cmbCaratteri, Lang.T("Dimensione di tutti i caratteri del programma: si applica subito a tabelle, finestre e caselle."));
            cmbCaratteri.SelectedIndexChanged += (s, e) =>
            {
                if (cmbCaratteri.SelectedIndex == carPrec || cmbCaratteri.SelectedIndex < 0) return;
                carPrec = cmbCaratteri.SelectedIndex;
                if (caricamento) return;
                float p = perc[cmbCaratteri.SelectedIndex] / 100f;
                nudFontTab.Value = (decimal)Math.Round(9F * p, 1);
                nudFontMod.Value = (decimal)Math.Round(9F * p, 1);
                SaveSettings();
                BeginInvoke(new Action(Ricostruisci));   // si applica subito, senza riavviare
            };
            // impostazioni generali su una riga, nella fascia bianca in alto della linguetta Tracciamento
            FlowLayoutPanel gb = new FlowLayoutPanel();
            gb.AutoSize = true;
            gb.AutoSizeMode = AutoSizeMode.GrowAndShrink;
            gb.WrapContents = true;
            gb.MaximumSize = new Size(S(1500), 0);
            gb.Margin = new Padding(0);
            Action<string, Control> Coppia = (testo, c) =>
            {
                if (c is ComboBox) c = new CorniceTonda((ComboBox)c);   // tendine con gli angoli arrotondati
                Label l = L(testo);
                l.Anchor = AnchorStyles.Left;
                l.Margin = new Padding(S(10), S(6), S(3), S(3));
                c.Margin = new Padding(S(2), S(3), S(4), S(3));
                gb.Controls.Add(l);
                gb.Controls.Add(c);
            };
            Coppia(Lang.T("Nominativo"), txtCall);
            Coppia(Lang.T("Lingua"), cmbLingua);
            Coppia(Lang.T("Colori"), cmbTema);
            Coppia(Lang.T("Caratteri"), cmbCaratteri);
            Coppia(Lang.T("Tipo di carattere"), cmbFontNome);
            trkImpHost.Controls.Add(gb);   // le impostazioni generali stanno nella linguetta Tracciamento

            rtAbout = new RichTextBox();
            rtAbout.Dock = DockStyle.Fill;
            rtAbout.ReadOnly = true;
            rtAbout.BorderStyle = BorderStyle.None;
            rtAbout.DetectUrls = true;
            rtAbout.LinkClicked += (s, e) => ApriLink(e.LinkText);
            root.Controls.Add(rtAbout, 0, 1);
            tp.Controls.Add(root);
            ScriviAbout();
        }

        // Voce dell'elenco dei caratteri: 0 intestazione, 1 predefinito del sistema, 2 carattere installato, 3 nota in fondo
        class VoceFont
        {
            public string Nome; public int Tipo; public bool Consigliato;
            public VoceFont(string n, int t, bool c) { Nome = n; Tipo = t; Consigliato = c; }
            public override string ToString() { return Nome; }
        }

        readonly Dictionary<string, Font> fontVoci = new Dictionary<string, Font>();

        // Ogni carattere dell'elenco è scritto con sé stesso; intestazione e nota in piccolo e in grigio
        void DisegnaVoceFont(object sender, DrawItemEventArgs e)
        {
            if (e.Index < 0) return;
            ComboBox c = (ComboBox)sender;
            VoceFont v = c.Items[e.Index] as VoceFont;
            if (v == null) return;
            bool chiusa = (e.State & DrawItemState.ComboBoxEdit) != 0;
            bool sel = (e.State & DrawItemState.Selected) != 0 && (v.Tipo == 1 || v.Tipo == 2);
            Color fondo = sel && !chiusa ? Color.FromArgb(227, 238, 252) : c.BackColor;
            using (Brush b = new SolidBrush(fondo)) e.Graphics.FillRectangle(b, e.Bounds);
            Rectangle r = new Rectangle(e.Bounds.X + S(v.Tipo == 0 || v.Tipo == 3 ? 8 : 10), e.Bounds.Y, e.Bounds.Width - S(12), e.Bounds.Height);
            if (v.Tipo == 0 || v.Tipo == 3)
            {
                if (v.Tipo == 3) using (Pen p = new Pen(Tema.Linea)) e.Graphics.DrawLine(p, e.Bounds.Left, e.Bounds.Top, e.Bounds.Right, e.Bounds.Top);
                using (Font f = new Font(Lang.FontUi, c.Font.Size * 0.8f))
                    TextRenderer.DrawText(e.Graphics, v.Tipo == 0 ? v.Nome.ToUpper(Lang.Cultura) : v.Nome, f, r, Tema.Muted,
                        TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.EndEllipsis);
                return;
            }
            Font fv = c.Font;
            if (v.Tipo == 2 && !fontVoci.TryGetValue(v.Nome, out fv))
            {
                try { fv = new Font(v.Nome, c.Font.Size); } catch { fv = c.Font; }
                fontVoci[v.Nome] = fv;
            }
            if (sel && !chiusa) fv = new Font(fv, FontStyle.Bold);
            Color cf = sel && !chiusa ? Color.FromArgb(15, 79, 168) : c.ForeColor;
            TextRenderer.DrawText(e.Graphics, v.Nome, fv, r, cf, TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.EndEllipsis);
            if (v.Consigliato && !chiusa)
            {
                int wn = TextRenderer.MeasureText(e.Graphics, v.Nome, fv, r.Size, TextFormatFlags.NoPrefix).Width;
                using (Font fc = new Font(Lang.FontUi, c.Font.Size * 0.8f))
                    TextRenderer.DrawText(e.Graphics, Lang.T("consigliato"), fc, new Rectangle(r.X + wn + S(4), r.Y, Math.Max(10, r.Width - wn - S(4)), r.Height), Tema.OkFg,
                        TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix);
            }
            if (sel && !chiusa && fv != c.Font && !fontVoci.ContainsValue(fv)) fv.Dispose();
        }

        static void ApriLink(string url)
        {
            try { System.Diagnostics.Process.Start(url); } catch { }
        }

        void Scrivi(RichTextBox rt, string t, float pt, bool bold)
        {
            rt.SelectionStart = rt.TextLength;
            rt.SelectionFont = new Font(Lang.FontUi, pt * fontFactor, bold ? FontStyle.Bold : FontStyle.Regular);
            rt.SelectionColor = Tema.FieldFore;
            rt.AppendText(t + "\n");
        }

        void ScriviAbout()
        {
            RichTextBox rt = rtAbout;
            rt.Clear();
            rt.BackColor = Tema.Field;
            Scrivi(rt, TitoloProgramma, 15F, true);
            Scrivi(rt, Lang.T("Calcolatore per il traffico radioamatoriale EME (Terra-Luna-Terra). Gli indirizzi web sono cliccabili."), 9.5F, false);
            Scrivi(rt, "", 6F, false);
            Scrivi(rt, Lang.T("CREDITI PER GLI ALGORITMI, LE FORMULE E I DATI USATI"), 10.5F, true);
            Scrivi(rt, Lang.T("I crediti, con gli autori, le opere e i collegamenti, sono nel capitolo «Fonti, dati e crediti» di TEORIA E CONSIGLI SULL'EME."), 9.5F, false);
            Scrivi(rt, "", 6F, false);
            Scrivi(rt, Lang.T("STORIA DELLE VERSIONI"), 10.5F, true);
            foreach (string v in AboutVersioni) Scrivi(rt, "• " + v, 9.5F, false);
            Scrivi(rt, "", 6F, false);
            Scrivi(rt, Lang.T("NOTE"), 10.5F, true);
            Scrivi(rt, Lang.T("Gli algoritmi elencati sono stati riscritti in C# per questo programma: non contiene librerie esterne compilate. Le tabelle di dati incorporate (temperatura del cielo, fusi orari, immagine della Luna) sono state convertite in forma compatta dai file originali indicati. I valori indicati come \"indicativi\", \"sperimentali\" o \"BETA\" servono per confronto e pianificazione, non come misure."), 9.5F, false);
            Scrivi(rt, Lang.T("Il codice sorgente del programma è stato scritto con l'assistenza di Claude (Anthropic) su indicazioni di Costantino IC8TEM."), 9.5F, false);
            rt.SelectionStart = 0;
            rt.ScrollToCaret();
        }

