        // fumetto di una pastiglia: opere e paragrafi del manuale TEORIA E CONSIGLI SULL'EME
        static string FumettoGrazie(string call, string nome, string opere, string par)
        {
            List<string> p = new List<string>();
            foreach (string x in par.Split(','))
            {
                string t = x.Trim();
                if (t == "PREF") p.Add(Lang.T("Prefazione dell'autore"));
                else if (t == "2") p.Add("§ 2");
                else p.Add("§ " + t);
            }
            return call + "  " + nome + "\u0001" + opere + "\n\n" + Lang.T("Citato nel manuale TEORIA E CONSIGLI SULL'EME:") + " " + string.Join(", ", p.ToArray());
        }

        Bitmap contLuna, contCielo;

        void DisegnaContatti(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            PreparaGrafica(g);
            float prima = contAltezza;
            ContenutoContatti(g, pnlContatti.ClientRectangle, true);
            if (Math.Abs(contAltezza - prima) > 1) BeginInvoke((Action)DimensionaContatti);
        }

        void ContenutoContatti(Graphics g, Rectangle cr, bool disegna)
        {
            contattiLink.Clear();
            contattiTip.Clear();
            // sfondo: la sfera celeste arcobaleno, a tutta pagina (cover)
            if (contCielo == null) { try { contCielo = SplashForm.CieloImg(); } catch { contCielo = null; } }
            if (contLuna == null) contLuna = SplashForm.LunaImg();
            if (contCielo != null)
            {
                float k = Math.Max(cr.Width / 360f, cr.Height / 180f);
                g.DrawImage(contCielo, (cr.Width - 360 * k) / 2, (cr.Height - 180 * k) / 2, 360 * k, 180 * k);
            }
            else g.Clear(Tema.Back);

            float x = S(62), y = S(34);
            Color blu = Color.FromArgb(25, 65, 127), link = Color.FromArgb(31, 111, 209);
            Color testo = Tema.Scuro ? Tema.Fore : Color.FromArgb(75, 85, 99);
            Color titCard = Tema.Scuro ? Tema.Fore : blu;
            using (Font ft = FontPx(Lang.FontUi, S(30), true))
            using (Font fs = FontPx(Lang.FontUi, S(15), true))
            using (Font fk = FontPx(Lang.FontUi, S(12), false))
            using (Font fl = FontPx(Lang.FontUi, S(18), true))
            using (Font fd = FontPx(Lang.FontUi, S(13.5f), false))
            using (Font fdb = FontPx(Lang.FontUi, S(13.5f), true))
            using (Font fb = FontPx(Lang.FontUi, S(13), true))
            using (Font fch = FontPx(Lang.FontUi, S(14.5f), false))
            using (Font fchb = FontPx(Lang.FontUi, S(14.5f), true))
            using (Font fpu = new Font(fl, FontStyle.Bold | FontStyle.Underline))
            {
                // la Luna al posto del bollino, con il titolo bianco ombreggiato
                float dl = S(104);
                RectangleF av = new RectangleF(x, y, dl, dl);
                using (Brush om = new SolidBrush(Color.FromArgb(110, 0, 0, 0))) g.FillEllipse(om, av.X - S(1), av.Y + S(5), dl + S(2), dl + S(2));
                using (Brush al = new SolidBrush(Color.FromArgb(140, 255, 255, 255))) g.FillEllipse(al, av.X - S(4), av.Y - S(4), dl + S(8), dl + S(8));
                if (contLuna != null)
                {
                    // la Luna dentro il cerchio con un pennello a trama (niente SetClip: con Mono, nella pagina
                    // scorrevole, il ritaglio con un tracciato dava OutOfMemory di GDI+)
                    float lw = contLuna.Width, lh = contLuna.Height, kk = Math.Max(dl / lw, dl / lh);
                    using (TextureBrush tb = new TextureBrush(contLuna, WrapMode.Clamp))
                    {
                        tb.TranslateTransform(av.X + (dl - lw * kk) / 2, av.Y + (dl - lh * kk) / 2);
                        tb.ScaleTransform(kk, kk);
                        g.FillEllipse(tb, av);
                    }
                }
                float xt = av.Right + S(26);
                RectangleF rt1 = new RectangleF(xt, y + S(22), cr.Width - xt - S(20), S(42));
                RectangleF rt2 = new RectangleF(xt, y + S(64), cr.Width - xt - S(20), S(24));
                string t1 = Lang.T("Contatti dell'autore e ringraziamenti");
                string t2 = "Costantino IC8TEM · Capri · " + Lang.T("autore di") + " YAEC – Yet Another EME Calc";
                using (Brush ob = new SolidBrush(Color.FromArgb(170, 0, 0, 0)))
                {
                    foreach (PointF o in new PointF[] { new PointF(S(1), S(2)), new PointF(0, S(2)), new PointF(S(1), S(1)) })
                    {
                        g.DrawString(t1, ft, ob, new RectangleF(rt1.X + o.X, rt1.Y + o.Y, rt1.Width, rt1.Height));
                        g.DrawString(t2, fs, ob, new RectangleF(rt2.X + o.X, rt2.Y + o.Y, rt2.Width, rt2.Height));
                    }
                }
                g.DrawString(t1, ft, Brushes.White, rt1);
                g.DrawString(t2, fs, Brushes.White, rt2);
                y += S(130);

                float wtot = Math.Min(S(900), cr.Width - 2 * x - S(10));
                float cw = (wtot - S(22)) / 2f, ch = S(182);
                RectangleF c1 = new RectangleF(x, y, cw, ch), c2 = new RectangleF(x + cw + S(22), y, cw, ch);
                Scheda(g, c1, Color.Empty); Scheda(g, c2, Color.Empty);
                string[][] voci = {
                    new string[] { "Q", Lang.T("PROFILO QRZ.COM"), "www.qrz.com/db/ic8tem", "https://www.qrz.com/db/ic8tem", Lang.T("Scheda del nominativo, QSL e recapiti aggiornati."), Lang.T("Apri nel browser") + " ↗" },
                    new string[] { "✉", Lang.T("POSTA ELETTRONICA"), "ccerrotta@gmail.com", "mailto:ccerrotta@gmail.com", Lang.T("Per segnalazioni, correzioni, traduzioni e nuovi dati."), Lang.T("Scrivi una mail") + " ↗" } };
                RectangleF[] cc = { c1, c2 };
                Color[] ci_ = { Color.FromArgb(43, 95, 180), Color.FromArgb(192, 57, 43) };
                for (int i = 0; i < 2; i++)
                {
                    RectangleF c = cc[i];
                    RectangleF ic = new RectangleF(c.Left + S(22), c.Top + S(20), S(30), S(30));
                    IconaQuadra(g, ic, ci_[i], voci[i][0], fb);
                    Testo(g, Spaziato(voci[i][1]), fk, Tema.Muted, new RectangleF(ic.Right + S(10), ic.Top, c.Width - S(80), ic.Height), StringAlignment.Near, StringAlignment.Center);
                    float yy = ic.Bottom + S(6);
                    SizeF sz = g.MeasureString(voci[i][2], fpu);
                    Testo(g, voci[i][2], fpu, link, new RectangleF(c.Left + S(22), yy, sz.Width + S(4), S(28)), StringAlignment.Near, StringAlignment.Near);
                    contattiLink.Add(new KeyValuePair<RectangleF, string>(new RectangleF(c.Left + S(22), yy, sz.Width, S(26)), voci[i][3]));
                    yy += S(26);
                    if (i == 1)
                    {
                        string m2 = "ic8tem@gmail.com";
                        SizeF s2 = g.MeasureString(m2, fpu);
                        Testo(g, m2, fpu, link, new RectangleF(c.Left + S(22), yy, s2.Width + S(4), S(28)), StringAlignment.Near, StringAlignment.Near);
                        contattiLink.Add(new KeyValuePair<RectangleF, string>(new RectangleF(c.Left + S(22), yy, s2.Width, S(26)), "mailto:ic8tem@gmail.com"));
                        yy += S(26);
                    }
                    yy += S(4);
                    Testo(g, voci[i][4], fd, testo, new RectangleF(c.Left + S(22), yy, c.Width - S(30), S(22)), StringAlignment.Near, StringAlignment.Near);
                    yy += S(30);
                    SizeF sb = g.MeasureString(voci[i][5], fb);
                    RectangleF bt = new RectangleF(c.Left + S(22), yy, sb.Width + S(24), S(26));
                    using (GraphicsPath p = Arrotondato(bt, S(7))) using (Brush b = new SolidBrush(Color.FromArgb(227, 238, 252))) g.FillPath(b, p);
                    Testo(g, voci[i][5], fb, Color.FromArgb(15, 79, 168), bt, StringAlignment.Center, StringAlignment.Center);
                    contattiLink.Add(new KeyValuePair<RectangleF, string>(bt, voci[i][3]));
                    if (i == 1)
                    {
                        string cp = Lang.T("Copia indirizzo");
                        SizeF scp = g.MeasureString(cp, fb);
                        RectangleF bc = new RectangleF(bt.Right + S(6), yy, scp.Width + S(24), S(26));
                        using (GraphicsPath p = Arrotondato(bc, S(7))) using (Brush b = new SolidBrush(Color.FromArgb(238, 240, 243))) g.FillPath(b, p);
                        Testo(g, cp, fb, Color.FromArgb(55, 65, 81), bc, StringAlignment.Center, StringAlignment.Center);
                        contattiLink.Add(new KeyValuePair<RectangleF, string>(bc, "copia:ccerrotta@gmail.com"));
                    }
                }
                y += ch + S(22);

                // invito per i transverter (riquadro giallo, capitolo 3.7.2)
                string nt = Lang.T("Se hai interesse a far conoscere altri transverter o il tuo transverter, scrivi una mail all'autore: i dati verranno aggiunti al capitolo 1.7.1 del manuale «TEORIA E CONSIGLI SULL'EME», con la citazione della fonte.");
                string ntb = Lang.T("Hai un transverter da far conoscere?");
                string ntr = "**" + ntb + "** " + nt;
                float hn = Math.Max(S(58), TestoRicco(g, ntr, fd, fdb, Color.Black, 0, 0, wtot - S(36), 1.45f, false) + S(22));
                RectangleF nota = new RectangleF(x, y, wtot, hn);
                using (GraphicsPath p = Arrotondato(nota, S(12)))
                {
                    using (Brush b = new SolidBrush(Color.FromArgb(255, 248, 230))) g.FillPath(b, p);
                    using (Pen pn = new Pen(Color.FromArgb(240, 195, 109))) g.DrawPath(pn, p);
                }
                TestoRicco(g, ntr, fd, fdb, Color.FromArgb(29, 36, 51), nota.Left + S(18), nota.Top + S(11), nota.Width - S(36), 1.45f, true);
                y += hn + S(20);

                // ringraziamenti (bozzetto approvato): patrocinio, beta-tester, NJ9R, il ricordo di IK1UWL
                // e gli autori di articoli e di prodotti hardware o software; nominativi come pastiglie con fumetto
                List<string[]> grazie = new List<string[]>();
                grazie.Add(new string[] { Lang.T("per il patrocinio della"), "Sezione ARI \"Valle del Liri\"", "IZ0JNY|Ivan" });
                grazie.Add(new string[] { Lang.T("per il controllo in regime di"), Lang.T("beta-tester"), "IZ7NLJ|Fabio", "I2NOY|Maurizio", "IK4GNG|Gilberto" });
                grazie.Add(new string[] { Lang.T("per l'incitamento a non mollare"), Lang.T("nell'ambiente dell'EME"),
                    "NJ9R|Relu|0|" + FumettoGrazie("NJ9R", "Relu", "“2M EME the easy way… the secret sauce to success”", "PREF, 1.6, 1.7, 1.8, 1.11, 1.12, 1.13, 1.14") });
                grazie.Add(new string[] { Lang.T("un pensiero e un ricordo a"), Lang.T("Giorgio IK1UWL, pioniere italiano dell'EME"),
                    "IK1UWL|Giorgio †|2|" + FumettoGrazie("IK1UWL", "Giorgio †", "“EME (Earth-Moon-Earth) – Guida operativa”, “Considerazioni sull'effetto suolo (Ground Gain)”", "1.6, 1.7") });
                List<string> aut = new List<string>();
                aut.Add(Lang.T("a tutti gli autori degli articoli e di prodotti hardware o software"));
                aut.Add(Lang.T("che comunemente si trovano negli impianti degli operatori EME di tutto il mondo"));
                foreach (string[] ga in GrazieAutori)
                    aut.Add(ga[0] + "|" + ga[1] + "|" + (ga.Length > 4 ? ga[4] : "0") + "|" + FumettoGrazie(ga[0], ga[1], ga[2], ga[3]));
                grazie.Add(aut.ToArray());

                float colLab = Math.Min(S(330), wtot * 0.34f);
                float xc0 = x + S(22) + colLab + S(22), xcMax = x + wtot - S(22);
                // altezza di ogni riga: etichetta a capo nella colonna, pastiglie che vanno a capo nello spazio a destra
                float[] hRiga = new float[grazie.Count];
                for (int i = 0; i < grazie.Count; i++)
                {
                    float hl = S(10) + TestoRicco(g, grazie[i][0], fd, fd, testo, 0, 0, colLab, 1.4f, false)
                             + TestoRicco(g, grazie[i][1], fdb, fdb, titCard, 0, 0, colLab, 1.4f, false) + S(12);
                    float xc = xc0, yc = S(15);
                    for (int j = 2; j < grazie[i].Length; j++)
                    {
                        string[] pz = grazie[i][j].Split('|');
                        float wc = g.MeasureString(pz[0], fchb).Width + g.MeasureString(pz[1], fch).Width + S(26);
                        if (xc > xc0 && xc + wc > xcMax) { xc = xc0; yc += S(38); }
                        xc += wc + S(10);
                    }
                    hRiga[i] = Math.Max(Math.Max(S(62), hl), yc + S(30) + S(15));
                }
                float ht = S(70);
                foreach (float hr in hRiga) ht += hr;
                RectangleF thx = new RectangleF(x, y, wtot, ht);
                Scheda(g, thx, Color.Empty);
                RectangleF ich = new RectangleF(thx.Left + S(22), thx.Top + S(16), S(30), S(30));
                IconaQuadra(g, ich, Color.FromArgb(214, 48, 49), "♥", fb);
                Testo(g, Spaziato(Lang.T("RINGRAZIAMENTI")), fk, Color.FromArgb(214, 48, 49), new RectangleF(ich.Right + S(10), ich.Top, thx.Width - S(80), ich.Height), StringAlignment.Near, StringAlignment.Center);
                float yr = ich.Bottom + S(12);
                using (Pen lin = new Pen(Tema.Scuro ? Color.FromArgb(70, 80, 95) : Color.FromArgb(237, 240, 245)))
                    for (int i = 0; i < grazie.Count; i++)
                    {
                        g.DrawLine(lin, thx.Left + S(22), yr, thx.Right - S(22), yr);
                        float hl0 = TestoRicco(g, grazie[i][0], fd, fd, testo, thx.Left + S(22), yr + S(10), colLab, 1.4f, true);
                        TestoRicco(g, grazie[i][1], fdb, fdb, titCard, thx.Left + S(22), yr + S(10) + hl0, colLab, 1.4f, true);
                        float xc = xc0, yc = yr + S(15);
                        for (int j = 2; j < grazie[i].Length; j++)
                        {
                            string[] pz = grazie[i][j].Split('|');
                            float w1 = g.MeasureString(pz[0], fchb).Width, w2 = g.MeasureString(pz[1], fch).Width;
                            float wc = w1 + w2 + S(26);
                            if (xc > xc0 && xc + wc > xcMax) { xc = xc0; yc += S(38); }
                            RectangleF chip = new RectangleF(xc, yc, wc, S(30));
                            string tipo = pz.Length > 2 ? pz[2] : "0";
                            Color fondo = tipo == "1" ? Color.FromArgb(227, 236, 255) : tipo == "2" ? Color.FromArgb(243, 238, 252) : Color.FromArgb(241, 245, 251);
                            Color bordo = tipo == "1" ? Color.FromArgb(159, 182, 232) : tipo == "2" ? Color.FromArgb(201, 182, 234) : Color.FromArgb(214, 224, 239);
                            using (GraphicsPath p = Arrotondato(chip, S(15)))
                            {
                                using (Brush b = new SolidBrush(fondo)) g.FillPath(b, p);
                                using (Pen pn = new Pen(bordo)) g.DrawPath(pn, p);
                            }
                            Testo(g, pz[0], fchb, blu, new RectangleF(chip.X + S(10), chip.Y, w1 + S(4), chip.Height), StringAlignment.Near, StringAlignment.Center);
                            Testo(g, pz[1], fch, Color.FromArgb(29, 36, 51), new RectangleF(chip.X + S(12) + w1, chip.Y, w2 + S(6), chip.Height), StringAlignment.Near, StringAlignment.Center);
                            if (pz.Length > 3) contattiTip.Add(new KeyValuePair<RectangleF, string>(chip, string.Join("|", pz, 3, pz.Length - 3)));
                            xc = chip.Right + S(10);
                        }
                        yr += hRiga[i];
                    }
                y += ht;

                // patrocinio in basso a destra
                SizeF s1 = g.MeasureString(Lang.T("Il programma ha il patrocinio della"), fd), s3 = g.MeasureString("Sezione ARI \"Valle del Liri\"", fl);
                float wp = Math.Max(s1.Width, s3.Width) + S(150), hp = S(112);
                RectangleF pat = new RectangleF(cr.Width - wp - S(36), cr.Height - hp - S(30), wp, hp);
                if (pat.Left < x + wtot + S(20) && pat.Top < y + S(20)) pat.Y = y + S(20);
                Scheda(g, pat, Color.Empty);
                if (logoAri != null) g.DrawImage(logoAri, pat.Left + S(14), pat.Top + S(10), S(92), S(92));
                float xp = pat.Left + S(122);
                Testo(g, Lang.T("Il programma ha il patrocinio della"), fd, testo, new RectangleF(xp, pat.Top + S(22), pat.Width - S(126), S(22)), StringAlignment.Near, StringAlignment.Near);
                Testo(g, "Sezione ARI \"Valle del Liri\"", fl, titCard, new RectangleF(xp, pat.Top + S(44), pat.Width - S(126), S(28)), StringAlignment.Near, StringAlignment.Near);
                using (Font fu = new Font(fd, FontStyle.Underline))
                {
                    SizeF sa = g.MeasureString("www.ari.it", fu);
                    Testo(g, "www.ari.it", fu, link, new RectangleF(xp, pat.Top + S(76), sa.Width + S(4), S(22)), StringAlignment.Near, StringAlignment.Near);
                    contattiLink.Add(new KeyValuePair<RectangleF, string>(new RectangleF(xp, pat.Top + S(76), sa.Width, S(22)), "https://www.ari.it"));
                    float xb = xp + sa.Width + S(18);
                    SizeF sl = g.MeasureString("www.ariliri.it", fu);
                    Testo(g, "www.ariliri.it", fu, link, new RectangleF(xb, pat.Top + S(76), sl.Width + S(4), S(22)), StringAlignment.Near, StringAlignment.Near);
                    contattiLink.Add(new KeyValuePair<RectangleF, string>(new RectangleF(xb, pat.Top + S(76), sl.Width, S(22)), "https://www.ariliri.it"));
                }
                contAltezza = Math.Max(y, pat.Bottom) + S(30);
            }
        }

        void IconaQuadra(Graphics g, RectangleF ic, Color c, string s, Font f)
        {
            using (GraphicsPath p = Arrotondato(ic, S(8))) using (Brush b = new SolidBrush(c)) g.FillPath(b, p);
            // TextRenderer: i simboli ✉ e ♥ arrivano anche dai caratteri di riserva di Windows
            TextRenderer.DrawText(g, s, f, new Rectangle((int)ic.X, (int)ic.Y, (int)ic.Width, (int)ic.Height), Color.White,
                TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.SingleLine | TextFormatFlags.NoPadding);
        }

        // maiuscoletto spaziato delle etichette delle schede
        static string Spaziato(string s)
        {
            foreach (char c in s) if (c >= '\u0530') return s.ToUpper();
            StringBuilder sb = new StringBuilder();
            foreach (char c in s.ToUpper()) { if (sb.Length > 0) sb.Append(' '); sb.Append(c); }
            return sb.ToString();
        }

        // Pagina della licenza disegnata come nel bozzetto approvato: sigillo e titolo, introduzione,
        // quattro schede dei principi, condizioni su due colonne, riquadro "In breve" e piede
        Panel pnlLicScroll;
        PannelloDisegno pnlLicenza;

        void BuildLicenzaTab(TabPage tp)
        {
            pnlLicScroll = new Panel();
            pnlLicScroll.Dock = DockStyle.Fill;
            pnlLicScroll.AutoScroll = true;
            pnlLicenza = new PannelloDisegno();
            pnlLicenza.Location = new Point(0, 0);
            pnlLicenza.Paint += (s, e) => { PreparaGrafica(e.Graphics); PaginaLicenza(e.Graphics, pnlLicenza.Width, true); };
            pnlLicScroll.Controls.Add(pnlLicenza);
            pnlLicScroll.Resize += (s, e) => DimensionaLicenza();
            tp.Controls.Add(pnlLicScroll);
            DimensionaLicenza();
        }

        void DimensionaLicenza()
        {
            if (pnlLicScroll == null || pnlLicenza == null) return;
            int w = Math.Max(S(600), pnlLicScroll.ClientSize.Width);
            float h;
            using (Graphics g = pnlLicenza.CreateGraphics()) { PreparaGrafica(g); h = PaginaLicenza(g, w, false); }
            int hh = Math.Max(pnlLicScroll.ClientSize.Height, (int)Math.Ceiling(h));
            if (pnlLicenza.Width != w || pnlLicenza.Height != hh) pnlLicenza.Size = new Size(w, hh);
            pnlLicenza.Invalidate();
        }

        // Testo con parti in grassetto (**...**) che va a capo parola per parola; restituisce l'altezza
        // Testo a capo automatico con parti in **grassetto**, allineato a sinistra.
        // L'interlinea è un multiplo della grandezza del carattere (come line-height nei bozzetti);
        // le parole consecutive con lo stesso carattere si disegnano insieme, così gli spazi restano regolari.
        float TestoRicco(Graphics g, string t, Font fr, Font fb, Color c, float x, float y, float w, float interlinea, bool disegna)
        {
            using (StringFormat sf = (StringFormat)StringFormat.GenericTypographic.Clone())
            using (Brush br = new SolidBrush(c))
            {
                sf.FormatFlags |= StringFormatFlags.MeasureTrailingSpaces | StringFormatFlags.NoWrap;
                List<KeyValuePair<string, bool>> par = new List<KeyValuePair<string, bool>>();
                bool gr = false;
                foreach (string pezzo in (t ?? "").Split(new string[] { "**" }, StringSplitOptions.None))
                {
                    foreach (string p in pezzo.Split(' '))
                        if (p.Length > 0) par.Add(new KeyValuePair<string, bool>(p, gr));
                    gr = !gr;
                }
                float em = fr.Unit == GraphicsUnit.Pixel ? fr.Size : fr.SizeInPoints * g.DpiY / 72f;
                float lh = em * interlinea;
                float sp = g.MeasureString(" ", fr, 1000, sf).Width;
                // righe: elenco di parole con il loro carattere
                List<List<KeyValuePair<string, bool>>> righe = new List<List<KeyValuePair<string, bool>>>();
                List<KeyValuePair<string, bool>> cur = new List<KeyValuePair<string, bool>>();
                float xx = 0;
                foreach (KeyValuePair<string, bool> p in par)
                {
                    float wp = g.MeasureString(p.Key, p.Value ? fb : fr, 10000, sf).Width;
                    if (cur.Count > 0 && xx + wp > w) { righe.Add(cur); cur = new List<KeyValuePair<string, bool>>(); xx = 0; }
                    cur.Add(p);
                    xx += wp + sp;
                }
                if (cur.Count > 0) righe.Add(cur);
                if (disegna)
                {
                    // spostamento verticale: la riga si centra nella sua interlinea
                    float dy = Math.Max(0, (lh - fr.GetHeight(g)) / 2f);
                    for (int r = 0; r < righe.Count; r++)
                    {
                        float xr = x, yr = y + r * lh + dy;
                        int i = 0;
                        while (i < righe[r].Count)
                        {
                            bool b = righe[r][i].Value;
                            StringBuilder run = new StringBuilder();
                            while (i < righe[r].Count && righe[r][i].Value == b)
                            {
                                if (run.Length > 0) run.Append(' ');
                                run.Append(righe[r][i].Key);
                                i++;
                            }
                            if (i < righe[r].Count) run.Append(' ');
                            Font f = b ? fb : fr;
                            string sr = run.ToString();
                            g.DrawString(sr, f, br, xr, yr, sf);
                            xr += g.MeasureString(sr, f, 10000, sf).Width;
                        }
                    }
                }
                return Math.Max(1, righe.Count) * lh;
            }
        }

        float PaginaLicenza(Graphics g, float W, bool disegna)
        {
            Color blu = Color.FromArgb(25, 65, 127);
            Color cTit = Tema.Scuro ? Tema.Fore : blu, cTesto = Tema.Scuro ? Tema.Fore : Color.FromArgb(29, 36, 51), cGrigio = Tema.Scuro ? Tema.Muted : Color.FromArgb(75, 85, 99);
            Color cScheda = Tema.Scuro ? Tema.Carta : Color.White, cBordo = Tema.Scuro ? Tema.Linea : Color.FromArgb(225, 231, 240);
            if (disegna)
            {
                RectangleF tutto = new RectangleF(0, 0, W, pnlLicenza.Height);
                Color a = Tema.Scuro ? Tema.Back : Color.FromArgb(247, 249, 252), b = Tema.Scuro ? Tema.Section : Color.FromArgb(234, 240, 248);
                using (LinearGradientBrush lb = new LinearGradientBrush(tutto, a, b, 70f)) g.FillRectangle(lb, tutto);
            }
            float mx = S(60), x = mx, y = S(30), wi = W - 2 * mx;
            using (Font fSeal = FontPx(Lang.FontUi, S(21), true))
            using (Font fSeal2 = FontPx(Lang.FontUi, S(10), true))
            using (Font fH1 = FontPx(Lang.FontUi, S(32), true))
            using (Font fSub = FontPx(Lang.FontUi, S(16), false))
            using (Font fIntro = FontPx(Lang.FontUi, S(16), false))
            using (Font fIntroB = FontPx(Lang.FontUi, S(16), true))
            using (Font fIc = FontPx(Lang.FontUi, S(19), true))
            using (Font fH3 = FontPx(Lang.FontUi, S(17), true))
            using (Font fP = FontPx(Lang.FontUi, S(14), false))
            using (Font fPB = FontPx(Lang.FontUi, S(14), true))
            using (Font fH2 = FontPx(Lang.FontUi, S(18), true))
            using (Font fFoot = FontPx(Lang.FontUi, S(13), false))
            {
                // sigillo, titolo e sottotitolo
                RectangleF seal = new RectangleF(x, y, S(84), S(84));
                if (disegna)
                {
                    using (Brush b = new SolidBrush(Color.FromArgb(55, blu))) g.FillEllipse(b, seal.X + S(2), seal.Y + S(4), seal.Width, seal.Height);
                    using (Brush b = new SolidBrush(blu)) g.FillEllipse(b, seal);
                    Testo(g, "YAEC", fSeal, Color.White, new RectangleF(seal.X, seal.Y + S(18), seal.Width, S(28)), StringAlignment.Center, StringAlignment.Center);
                    Testo(g, Lang.T("LICENZA"), fSeal2, Color.White, new RectangleF(seal.X, seal.Y + S(46), seal.Width, S(16)), StringAlignment.Center, StringAlignment.Center);
                    Testo(g, Lang.T("Licenza d'uso"), fH1, cTit, new RectangleF(x + S(106), y + S(10), wi - S(106), S(44)), StringAlignment.Near, StringAlignment.Center);
                    Testo(g, "YAEC – Yet Another EME Calc · " + Lang.T("a cura di Costantino IC8TEM"), fSub, cGrigio, new RectangleF(x + S(106), y + S(52), wi - S(106), S(24)), StringAlignment.Near, StringAlignment.Center);
                }
                y += S(84) + S(16);
                // introduzione
                string intro = Lang.T("YAEC è un programma libero, scritto da un radioamatore per i radioamatori. Il suo codice è stato sviluppato anche con l'aiuto di un assistente di intelligenza artificiale, e la licenza ne riprende il modo di lavorare: essere davvero utile, dire sempre come stanno le cose, mostrare il proprio ragionamento, non nuocere a nessuno e riconoscere il lavoro degli altri. Sotto ci sono i principi e poi le condizioni vere e proprie.");
                y += TestoRicco(g, intro, fIntro, fIntroB, cTesto, x, y, Math.Min(wi, S(1300)), 1.5f, disegna) + S(18);
                // quattro schede dei principi
                string[][] pr = {
                    new string[] { "✦", Lang.T("Utile e gratuito"), Lang.T("Il programma è gratuito e lo puoi usare senza limiti per la tua attività radioamatoriale, per studio e per insegnamento. Serve a far nascere QSO, non a vendere qualcosa.") },
                    new string[] { "◎", Lang.T("Trasparente"), Lang.T("Il sorgente è sempre consegnato insieme al programma; ogni formula è visibile nella linguetta Controllo dei calcoli e ogni dato riporta la sua fonte. Niente scatole nere.") },
                    new string[] { "≈", Lang.T("Onesto"), Lang.T("I valori misurati, quelli ricavati e quelli stimati sono distinti; ciò che non è verificato viene dichiarato come tale. Un risultato incerto è indicato come incerto, non presentato come certo.") },
                    new string[] { "✓", Lang.T("Rispettoso"), Lang.T("Rispetta il lavoro di chi ha misurato, scritto e pubblicato prima di noi, la privacy di chi lo usa (nessun dato raccolto, niente pubblicità) e le regole del servizio di radioamatore.") } };
                Color[] cpr = { Color.FromArgb(31, 111, 209), Color.FromArgb(23, 128, 61), Color.FromArgb(180, 83, 9), Color.FromArgb(91, 63, 168) };
                float gap = S(16), cw = (wi - 3 * gap) / 4f, pad = S(18);
                float hTesto = 0;
                for (int i = 0; i < 4; i++) hTesto = Math.Max(hTesto, TestoRicco(g, pr[i][2], fP, fPB, cTesto, 0, 0, cw - 2 * pad, 1.45f, false));
                float hCard = S(5) + S(16) + S(38) + S(8) + S(26) + hTesto + S(18);
                for (int i = 0; i < 4 && disegna; i++)
                {
                    RectangleF c = new RectangleF(x + i * (cw + gap), y, cw, hCard);
                    using (GraphicsPath p = Arrotondato(c, S(14)))
                    {
                        using (Brush b = new SolidBrush(Color.FromArgb(18, 30, 50, 90)))
                        using (GraphicsPath po = Arrotondato(new RectangleF(c.X, c.Y + S(2), c.Width, c.Height), S(14))) g.FillPath(b, po);
                        using (Brush b = new SolidBrush(cScheda)) g.FillPath(b, p);
                        Region old = g.Clip;
                        g.SetClip(p, CombineMode.Intersect);
                        using (Brush b = new SolidBrush(cpr[i])) g.FillRectangle(b, c.Left, c.Top, c.Width, S(5));
                        g.Clip = old;
                        using (Pen pn = new Pen(cBordo)) g.DrawPath(pn, p);
                    }
                    RectangleF ic = new RectangleF(c.Left + pad, c.Top + S(21), S(38), S(38));
                    using (GraphicsPath p = Arrotondato(ic, S(10))) using (Brush b = new SolidBrush(cpr[i])) g.FillPath(b, p);
                    Testo(g, pr[i][0], fIc, Color.White, ic, StringAlignment.Center, StringAlignment.Center);
                    TestoRicco(g, pr[i][1], fH3, fH3, cpr[i], c.Left + pad, ic.Bottom + S(6), c.Width - 2 * pad, 1.5f, true);   // allineato al testo sotto
                    TestoRicco(g, pr[i][2], fP, fPB, cTesto, c.Left + pad, ic.Bottom + S(36), c.Width - 2 * pad, 1.45f, true);
                }
                y += hCard + S(20);
                // condizioni su due colonne
                string[][] cond = {
                    new string[] { Lang.T("Uso."), Lang.T("Puoi usare, copiare e installare YAEC gratuitamente, su quanti computer vuoi.") },
                    new string[] { Lang.T("Modifiche."), Lang.T("Puoi studiare il sorgente, correggerlo e migliorarlo per uso personale o del tuo radio club.") },
                    new string[] { Lang.T("Ridistribuzione."), Lang.T("Puoi ridistribuire il programma, originale o modificato, solo insieme al suo sorgente completo e con questa stessa licenza.") },
                    new string[] { Lang.T("Dichiarare le modifiche."), Lang.T("Una versione modificata deve dirlo chiaramente nel titolo o nelle note di versione, indicando chi l'ha modificata e che cosa è cambiato, così nessuno scambia il tuo lavoro per quello dell'autore, o viceversa.") },
                    new string[] { Lang.T("Attribuzione."), Lang.T("Vanno mantenuti il nome dell'autore (Costantino IC8TEM), il capitolo «Fonti, dati e crediti» del manuale e tutte le citazioni delle fonti di terzi: dati, tabelle, articoli e misure appartengono a chi li ha prodotti.") },
                    new string[] { Lang.T("Niente uso commerciale."), Lang.T("Non è consentito vendere YAEC o versioni derivate, né includerlo in prodotti a pagamento, senza il permesso scritto dell'autore.") },
                    new string[] { Lang.T("Niente dati nascosti."), Lang.T("Nessuna versione distribuita può raccogliere dati degli utenti, mostrare pubblicità o inviare informazioni a terzi senza dirlo apertamente.") },
                    new string[] { Lang.T("Uso corretto della radio."), Lang.T("Il programma aiuta a pianificare: le frequenze, le potenze e le modalità usate restano sotto la responsabilità dell'operatore e della sua licenza di radioamatore.") },
                    new string[] { Lang.T("Nessuna garanzia."), Lang.T("YAEC è fornito così com'è. I calcoli sono fatti con cura e con fonti dichiarate, ma possono contenere errori: verifica i dati importanti prima di affidarti a essi.") },
                    new string[] { Lang.T("Segnalazioni."), Lang.T("Se trovi un errore o un dato migliore, scrivilo all'autore (linguetta CONTATTI DELL'AUTORE E RINGRAZIAMENTI): sarà corretto citandoti come fonte.") } };
                float padC = S(24), gapC = S(40), num = S(26);
                float colW = (wi - 2 * padC - gapC) / 2f, wTxt = colW - num;
                float[] hItem = new float[10];
                for (int i = 0; i < 10; i++) hItem[i] = TestoRicco(g, "**" + cond[i][0] + "** " + cond[i][1], fP, fPB, cTesto, 0, 0, wTxt, 1.48f, false) + S(7);
                float hCol1 = 0, hCol2 = 0;
                for (int i = 0; i < 5; i++) { hCol1 += hItem[i]; hCol2 += hItem[i + 5]; }
                float hCond = S(16) + S(30) + Math.Max(hCol1, hCol2) + S(10);
                if (disegna)
                {
                    RectangleF c = new RectangleF(x, y, wi, hCond);
                    using (GraphicsPath p = Arrotondato(c, S(14)))
                    {
                        using (Brush b = new SolidBrush(Color.FromArgb(18, 30, 50, 90)))
                        using (GraphicsPath po = Arrotondato(new RectangleF(c.X, c.Y + S(2), c.Width, c.Height), S(14))) g.FillPath(b, po);
                        using (Brush b = new SolidBrush(cScheda)) g.FillPath(b, p);
                        using (Pen pn = new Pen(cBordo)) g.DrawPath(pn, p);
                    }
                    Testo(g, Lang.T("Condizioni"), fH2, cTit, new RectangleF(c.Left + padC, c.Top + S(14), c.Width - 2 * padC, S(28)), StringAlignment.Near, StringAlignment.Center);
                    for (int col = 0; col < 2; col++)
                    {
                        float yy = c.Top + S(16) + S(34);
                        float xc = c.Left + padC + col * (colW + gapC);
                        for (int i = col * 5; i < col * 5 + 5; i++)
                        {
                            Testo(g, (i + 1).ToString(inv) + ".", fP, cTesto, new RectangleF(xc, yy, num - S(6), fP.GetHeight(g) * 1.48f), StringAlignment.Far, StringAlignment.Near);
                            TestoRicco(g, "**" + cond[i][0] + "** " + cond[i][1], fP, fPB, cTesto, xc + num, yy, wTxt, 1.48f, true);
                            yy += hItem[i];
                        }
                    }
                }
                y += hCond + S(16);
                // riquadro "In breve"
                string breve = "**" + Lang.T("In breve:") + "** " + Lang.T("usalo liberamente, impara dal codice, miglioralo e condividilo, ma sempre con il sorgente, con le fonti citate, dicendo cosa hai cambiato e senza farne commercio. Se dubiti di un risultato, la risposta giusta è controllare, non fidarsi.");
                float hB = TestoRicco(g, breve, fP, fPB, cTesto, 0, 0, wi - S(36), 1.45f, false) + S(24);
                if (disegna)
                {
                    RectangleF c = new RectangleF(x, y, wi, hB);
                    using (GraphicsPath p = Arrotondato(c, S(12)))
                    {
                        using (Brush b = new SolidBrush(Tema.Scuro ? Color.FromArgb(60, 240, 195, 109) : Color.FromArgb(255, 248, 230))) g.FillPath(b, p);
                        using (Pen pn = new Pen(Color.FromArgb(240, 195, 109))) g.DrawPath(pn, p);
                    }
                    TestoRicco(g, breve, fP, fPB, cTesto, c.Left + S(18), c.Top + S(12), wi - S(36), 1.45f, true);
                }
                y += hB + S(14);
                // piede: a sinistra il copyright, a destra la nota sulle traduzioni
                string f1 = "© 2026 Costantino IC8TEM · " + Lang.T("Licenza d'uso YAEC, versione 1");
                string f2 = Lang.T("Il testo è tradotto in tutte le lingue del programma; in caso di dubbio fa fede la versione italiana.");
                float w1 = g.MeasureString(f1, fFoot).Width, w2 = g.MeasureString(f2, fFoot).Width;
                bool unaRiga = w1 + w2 + S(30) < wi;
                if (disegna)
                {
                    Testo(g, f1, fFoot, Tema.Muted, new RectangleF(x, y, unaRiga ? w1 + S(4) : wi, S(20)), StringAlignment.Near, StringAlignment.Near);
                    Testo(g, f2, fFoot, Tema.Muted, new RectangleF(unaRiga ? x + wi - w2 - S(4) : x, unaRiga ? y : y + S(20), unaRiga ? w2 + S(4) : wi, S(20)), unaRiga ? StringAlignment.Far : StringAlignment.Near, StringAlignment.Near);
                }
                y += (unaRiga ? S(20) : S(40)) + S(24);
            }
            return y;
        }

        // Descrizione di ogni linguetta, nello stesso ordine delle linguette
        string[][] DescrizioniLinguette()
        {
            return new string[][] {
                new string[] { Lang.T("Posizione live e +- 24h"), Lang.T("La schermata principale, aggiornata ogni secondo. In alto le impostazioni generali (nominativo, lingua, colori, caratteri e tipo di carattere), il pulsante SCELTA BANDE e la casella dei dati complessi; sotto, i locator tuo e del DX (da 4 a 14 caratteri, con la precisione della posizione), la frequenza e gli orologi UTC, locale e del DX. La fascia di stato (verde = puntabile, arancione = fuori dai limiti, grigio = sotto l'orizzonte, blu = finestra comune) ha il conto alla rovescia; seguono la bussola e l'arco dell'elevazione con i limiti dell'antenna in giallo e quattro riquadri: Luna (fase, sorgere e tramonto), Eco e frequenze (Doppler, ritardo dell'eco e frequenze CFOM), Cielo e geometria (Tsky, distanza, declinazione, angolo orario, Dgrd e il pulsante VAI A VOLTA CELESTE) e S/N stimato (in 2500 Hz con la soglia tipica del modo come riferimento, dati del DX, la casella CALCOLI APPROFONDITI e il pulsante VAI AI CALCOLI). In basso le prossime 24 ore.") + " " + Lang.T("Accanto al locator del DX c'è la casella del nominativo: se il nominativo è nel CALL3.TXT il locator si riempie da solo, e il pulsante CALL3 aggiorna l'elenco o lo copia nella cartella di WSJT-X. Trascinando la linea rossa delle 24 ore o scegliendo il giorno nel calendario la schermata mostra un istante passato o futuro; ▶ Adesso torna alla diretta. La frequenza si sceglie nel riquadro Eco e frequenze.") },
                new string[] { Lang.T("Distanza e Dgrd"), Lang.T("Grafico da 7 a 61 giorni della Dgrd (0 dB in basso, -15 dB in alto) e della distanza media giornaliera della Luna, con perigeo, apogeo, luna nuova e i tre giorni migliori (★). La classifica tiene conto solo delle ore in cui la Luna è davvero puntabile con i tuoi limiti.") + " " + Lang.T("Il simbolo ☀ segna i giorni in cui la Luna è vicina al Sole (rosso: entro 3 larghezze del fascio, arancione: entro 6): il rumore solare può peggiorare la ricezione. Colore e spessore delle due curve si cambiano nella barra sopra il grafico.") + " " + Lang.T("La tabella a destra elenca i giorni con gli stessi colori delle fasce del grafico (verde i tre giorni migliori, rosso e arancione il Sole vicino alla Luna). La curva blu della declinazione si sovrappone al grafico, con la sua scala dentro il bordo sinistro; la casella \"Ore utili in verde sulla Dgrd\" colora le ore con la Luna dentro i limiti dell'antenna.") },
                new string[] { Lang.T("Volta celeste"), Lang.T("Il cielo visto dal tuo QTH, con l'orizzonte piatto e i colori del rumore del cielo (dal blu al rosso) alla frequenza scelta, i limiti della tua antenna, l'orizzonte del DX, le radiosorgenti, il Sole e il percorso della Luna nelle prossime 24 ore.") + " " + Lang.T("Le zone fuori dai limiti della tua antenna sono coperte da righe diagonali grigio chiaro.") },
                new string[] { Lang.T("Ricognizione dei miei ostacoli"), Lang.T("Mappa aerofotografica o topografica centrata sulla tua stazione, con sopra la volta celeste in pianta (orizzonte = cerchio esterno, zenit = centro): posizione attuale della Luna, percorso nelle prossime 24 ore con sorgere e tramonto, limiti dell'antenna in giallo e zone fuori dai limiti sfocate in grigio chiaro. Le maniglie gialle si trascinano con il mouse per regolare i limiti direttamente sulla mappa; la rotella cambia lo zoom.") + " " + Lang.T("La casella \"Sfuma le zone fuori dai limiti\" accende o spegne la sfocatura.") + " " + Lang.T("In alto a destra due cursori regolano l'opacità e il tono del grigio delle zone fuori dai limiti (il tono vale anche per la Volta celeste).") },
                new string[] { Lang.T("Luna sul mondo"), Lang.T("Mappa del mondo con le terre colorate secondo l'elevazione della Luna vista da ogni località, nello stesso momento della Posizione della Luna; passando il mouse si leggono elevazione, azimut e distanza, con un clic il punto diventa la stazione DX.") },
                new string[] { Lang.T("Posizione della Luna"), Lang.T("Tabella per il periodo scelto (in giorni, con l'intervallo in minuti) con il colore della puntabilità; passando il mouse sull'intestazione di una colonna compare la sua spiegazione. Esportazione CSV per Excel.") },
                new string[] { Lang.T("Budget EME"), Lang.T("Bilancio del collegamento per ogni banda scelta (da 50 a 432 MHz), con i dati di ogni banda memorizzati separatamente. A sinistra le due stazioni (antenna e guadagno, BETA per le antenne senza elevazione), sei indicatori (collegamento possibile, EIRP mia e del DX, perdita di tratta, S/N io → DX e DX → io nella banda passante scelta e con il Sole, riportato anche a 2500 Hz) e la tabella con tutti i passaggi; a destra lo schema dell'impianto di trasmissione e ricezione della stazione scelta: antenna e Tant, cavo antenna – relè, relè coassiale, trasmettitore con il suo cavo, preamplificatore, cavo di discesa, transverter facoltativo, cavetti e radio con MDS e modo. I cavi si scelgono dal database della linguetta CAVI COASSIALI e le perdite si calcolano da sole. In alto a destra la casella CALCOLI APPROFONDITI, la stessa della schermata principale.") },
                new string[] { Lang.T("Rumore solare"), Lang.T("Scarica dal web i flussi solari misurati dalla rete RSTN e stima quanto il Sole aumenta il rumore del ricevitore, in base alla distanza angolare tra Sole e Luna e al diagramma dell'antenna. Utile vicino alla luna nuova.") + " " + Lang.T("In alto quattro indicatori, a sinistra la fonte dei dati (NOAA RSTN consigliata, oppure F10.7 di NOAA o di Penticton, oppure un indirizzo personalizzato) con le stazioni, a destra lo spettro del flusso solare con l'estrapolazione alla frequenza di lavoro.") },
                new string[] { Lang.T("Mappa WWL e ADIF"), Lang.T("Mappa del mondo con il reticolo Maidenhead; caricando il file ADIF del log si colorano i quadrati lavorati (arancione), confermati via LoTW (verde) o solo con QSL (blu), anche per banda e solo EME.") + " " + Lang.T("Con \"Scarica da LoTW…\" il log viene scaricato direttamente da LoTW (nome utente e password vengono chiesti e memorizzati nelle impostazioni).") },
                new string[] { Lang.T("INFORMAZIONI E CREDITI"), Lang.T("Crediti con i link e storia delle versioni.") },
                new string[] { Lang.T("CAVI COASSIALI"), Lang.T("Il database dei cavi coassiali a 50 Ω con l'attenuazione a 50, 70, 144, 222 e 432 MHz e le fonti di ogni valore; si ordina per diametro, perdita, nome, costruttore o tipo (anche cliccando l'intestazione delle colonne), si filtra per tipo e diametro e si cerca per nome. A destra il calcolo della perdita di una tratta e il grafico dei cavi spuntati; il pulsante \"usa nel Budget EME\" porta il cavo nel Budget. Si possono aggiungere cavi personalizzati.") },
                new string[] { Lang.T("CONTATTI DELL'AUTORE E RINGRAZIAMENTI"), Lang.T("I recapiti dell'autore (e-mail, profilo QRZ.com) e i ringraziamenti a chi ha contribuito al programma.") },
                new string[] { Lang.T("LICENZA D'USO"), Lang.T("Il testo della licenza con cui il programma è distribuito.") },
                new string[] { Lang.T("MANUALE D'USO"), Lang.T("Questo manuale, dentro il programma e in tutte le lingue: indice cliccabile, ricerca, formule e fonti.") },
                new string[] { Lang.T("TEORIA E CONSIGLI SULL'EME"), Lang.T("Come funziona l'EME e come lavorarlo al meglio: rumore del cielo e Dgrd, Sole, polarizzazione, budget del collegamento, Doppler, procedure operative e fonti; indice cliccabile, ricerca e formule, come il manuale.") },
