        void CentraMappa(double lat, double lon, int z)
        {
            mapZoom = Math.Max(1, Math.Min(MapZoomMax, z));
            mapCx = LonToX(lon, mapZoom);
            mapCy = LatToY(lat, mapZoom);
            mapInit = true;
            tileQueue.Clear();
            map.Invalidate();
        }

        void ZoomMappa(int d, Point p)
        {
            int nz = Math.Max(1, Math.Min(Math.Min(MapZoomMax, MappaCorrente().MaxZoom), mapZoom + d));
            if (nz == mapZoom) return;
            double wx = mapCx + (p.X - map.Width / 2.0), wy = mapCy + (p.Y - map.Height / 2.0);
            double lon = XToLon(wx, mapZoom), lat = YToLat(wy, mapZoom);
            mapZoom = nz;
            mapCx = LonToX(lon, nz) - (p.X - map.Width / 2.0);
            mapCy = LatToY(lat, nz) - (p.Y - map.Height / 2.0);
            LimitaMappa();
            tileQueue.Clear();
            map.Invalidate();
        }

        void LimitaMappa()
        {
            double size = MapSize(mapZoom);
            mapCx = ((mapCx % size) + size) % size;
            double half = map.Height / 2.0;
            if (size < map.Height) mapCy = size / 2.0;
            else mapCy = Math.Max(half, Math.Min(size - half, mapCy));
        }

        TileProvider MappaCorrente()
        {
            int i = cmbMappa == null ? 0 : Math.Max(0, cmbMappa.SelectedIndex);
            return Mappe[i];
        }

        void Map_MouseMove(object sender, MouseEventArgs e)
        {
            if (dragging)
            {
                mapCx -= e.X - dragStart.X;
                mapCy -= e.Y - dragStart.Y;
                dragStart = e.Location;
                LimitaMappa();
                map.Invalidate();
                return;
            }
            double wx = mapCx + (e.X - map.Width / 2.0), wy = mapCy + (e.Y - map.Height / 2.0);
            double lon = XToLon(wx, mapZoom), lat = YToLat(wy, mapZoom);
            lon = ((lon + 180.0) % 360.0 + 360.0) % 360.0 - 180.0;
            string q = Quadrato(lat, lon);
            if (q == mapTipKey) return;
            mapTipKey = q;
            if (q == null) { mapTip.Hide(map); return; }
            QuadratoInfo qi;
            string t = q;
            if (quadrati.TryGetValue(q, out qi))
            {
                t += string.Format(ci, Lang.T("   {0} QSO, confermati: {1} via LoTW, {2} con QSL"), qi.Qso, qi.Lotw, qi.Qsl);
                int n = Math.Min(12, qi.Call.Count);
                if (n > 0) t += "\n" + string.Join(", ", qi.Call.GetRange(0, n).ToArray()) + (qi.Call.Count > n ? " …" : "");
            }
            else t += Lang.T("   non lavorato") + (adifQso.Count == 0 ? Lang.T(" (nessun file ADIF)") : "");
            Fumetto.Ultimo = t;
            mapTip.Show(t, map, e.X + 16, e.Y + 16, 20000);
        }

        static string Quadrato(double lat, double lon)
        {
            if (lat < -90 || lat >= 90 || lon < -180 || lon >= 180) return null;
            int fx = (int)((lon + 180) / 20), fy = (int)((lat + 90) / 10);
            int sx = (int)(((lon + 180) % 20) / 2), sy = (int)((lat + 90) % 10);
            return new string(new char[] { (char)('A' + fx), (char)('A' + fy), (char)('0' + sx), (char)('0' + sy) });
        }

        static bool QuadratoValido(string g)
        {
            return g.Length >= 4 && g[0] >= 'A' && g[0] <= 'R' && g[1] >= 'A' && g[1] <= 'R'
                && char.IsDigit(g[2]) && char.IsDigit(g[3]);
        }

        // ----- ADIF -----

        // Elimina dalla mappa e dalla memoria i dati del file ADIF
        void CancellaAdif()
        {
            adifQso = new List<AdifQso>();
            quadrati = new Dictionary<string, QuadratoInfo>();
            adifPath = "";
            tabBande.TabPages.Clear();
            tabBande.TabPages.Add(Lang.T("Tutte le bande"));
            lblAdif.Text = Lang.T("Nessun file ADIF caricato.");
            lblMapInfo.Text = Lang.T("Dati ADIF cancellati. Rotella del mouse o doppio clic = zoom, trascina = sposta.");
            mapTipKey = "";
            map.Invalidate();
        }

        void ScegliAdif()
        {
            OpenFileDialog dlg = new OpenFileDialog();
            dlg.Filter = Lang.T("File ADIF (*.adi;*.adif)|*.adi;*.adif|Tutti i file (*.*)|*.*");
            dlg.Title = Lang.T("Scegli il file ADIF del log");
            if (adifPath.Length > 0)
            {
                try { dlg.InitialDirectory = Path.GetDirectoryName(adifPath); } catch { }
            }
            if (dlg.ShowDialog(this) != DialogResult.OK) return;
            CaricaAdif(dlg.FileName, true);
        }

        void CaricaAdif(string path, bool avvisi)
        {
            try
            {
                Cursor = Cursors.WaitCursor;
                string txt = File.ReadAllText(path, Encoding.GetEncoding(28591)); // 1 byte = 1 carattere (lunghezze ADIF in byte)
                List<AdifQso> nuovi = LeggiAdif(txt);
                CancellaAdif();   // i dati del file precedente vengono eliminati
                adifQso = nuovi;
                adifPath = path;
                // linguette delle bande presenti nel file
                List<string> bande = new List<string>();
                foreach (AdifQso q in adifQso) if (q.Band.Length > 0 && !bande.Contains(q.Band)) bande.Add(q.Band);
                bande.Sort((a, b) => OrdineBanda(a).CompareTo(OrdineBanda(b)));
                string prima = "";
                tabBande.TabPages.Clear();
                tabBande.TabPages.Add(Lang.T("Tutte le bande"));
                foreach (string bn in bande) tabBande.TabPages.Add(bn);
                int conGrid = 0;
                foreach (AdifQso q in adifQso) if (q.Grids.Count > 0) conGrid++;
                lblAdif.Text = string.Format(ci, Lang.T("{0}: {1:N0} QSO, {2:N0} con locator"), Path.GetFileName(path), adifQso.Count, conGrid);
                for (int i = 0; i < tabBande.TabPages.Count; i++)
                    if (tabBande.TabPages[i].Text == prima) tabBande.SelectedIndex = i;
                FiltraAdif();
            }
            catch (Exception ex)
            {
                if (avvisi) Messaggio(this, Lang.T("Impossibile leggere il file ADIF:\n") + ex.Message, "YAEC",
                    MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
            finally { Cursor = Cursors.Default; }
        }

        static List<AdifQso> LeggiAdif(string s)
        {
            List<AdifQso> list = new List<AdifQso>();
            int i = 0;
            if (s.Length > 0 && s[0] != '<')
            {
                int h = s.IndexOf("<eoh>", StringComparison.OrdinalIgnoreCase);
                if (h >= 0) i = h + 5;
            }
            Dictionary<string, string> rec = new Dictionary<string, string>();
            while (i < s.Length)
            {
                int j = s.IndexOf('<', i);
                if (j < 0) break;
                int k = s.IndexOf('>', j);
                if (k < 0) break;
                string tag = s.Substring(j + 1, k - j - 1);
                string[] parts = tag.Split(':');
                string name = parts[0].Trim().ToLowerInvariant();
                if (name == "eor")
                {
                    AdifQso q = CreaQso(rec);
                    if (q != null) list.Add(q);
                    rec = new Dictionary<string, string>();
                    i = k + 1;
                    continue;
                }
                if (name == "eoh") { rec.Clear(); i = k + 1; continue; }
                int len = 0;
                if (parts.Length > 1) int.TryParse(parts[1].Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out len);
                if (len < 0) len = 0;
                int start = k + 1;
                if (start + len > s.Length) len = s.Length - start;
                rec[name] = s.Substring(start, len);
                i = start + len;
            }
            return list;
        }

        static string Campo(Dictionary<string, string> r, string k)
        {
            string v;
            return r.TryGetValue(k, out v) ? v.Trim() : "";
        }

        static AdifQso CreaQso(Dictionary<string, string> r)
        {
            if (r.Count == 0) return null;
            AdifQso q = new AdifQso();
            q.Call = Campo(r, "call").ToUpperInvariant();
            q.Mode = Campo(r, "mode").ToUpperInvariant();
            q.Band = Campo(r, "band").ToLowerInvariant();
            if (q.Band.Length == 0)
            {
                double f;
                if (double.TryParse(Campo(r, "freq").Replace(',', '.'), NumberStyles.Float, CultureInfo.InvariantCulture, out f))
                    q.Band = BandaDaFreq(f);
            }
            q.Eme = string.Equals(Campo(r, "prop_mode"), "EME", StringComparison.OrdinalIgnoreCase);
            q.Lotw = Campo(r, "lotw_qsl_rcvd").ToUpperInvariant() == "Y";
            q.Qsl = Campo(r, "qsl_rcvd").ToUpperInvariant() == "Y";
            // file scaricato da LoTW: QSL_RCVD = Y vuol dire confermato via LoTW
            bool daLotw = false;
            foreach (string kk in r.Keys) if (kk.StartsWith("app_lotw_", StringComparison.Ordinal)) { daLotw = true; break; }
            if (daLotw && q.Qsl) { q.Lotw = true; q.Qsl = false; }
            q.Confermato = q.Lotw || q.Qsl;
            string g = Campo(r, "gridsquare").ToUpperInvariant();
            if (QuadratoValido(g)) q.Grids.Add(g.Substring(0, 4));
            foreach (string vg in Campo(r, "vucc_grids").ToUpperInvariant().Split(','))
            {
                string x = vg.Trim();
                if (QuadratoValido(x) && !q.Grids.Contains(x.Substring(0, 4))) q.Grids.Add(x.Substring(0, 4));
            }
            return q;
        }

        static readonly string[] BandeNomi = { "2190m", "630m", "160m", "80m", "60m", "40m", "30m", "20m", "17m", "15m", "12m", "10m",
            "6m", "4m", "2m", "1.25m", "70cm", "33cm", "23cm", "13cm", "9cm", "6cm", "3cm", "1.25cm", "6mm", "4mm", "2.5mm", "2mm", "1mm" };
        static readonly double[,] BandeLimiti = { { 0.135, 0.138 }, { 0.47, 0.48 }, { 1.8, 2.0 }, { 3.5, 4.0 }, { 5.0, 5.5 }, { 7.0, 7.3 },
            { 10.1, 10.15 }, { 14.0, 14.35 }, { 18.068, 18.168 }, { 21.0, 21.45 }, { 24.89, 24.99 }, { 28.0, 29.7 },
            { 50, 54 }, { 70, 71 }, { 144, 148 }, { 222, 225 }, { 420, 450 }, { 902, 928 }, { 1240, 1300 }, { 2300, 2450 },
            { 3300, 3500 }, { 5650, 5925 }, { 10000, 10500 }, { 24000, 24250 }, { 47000, 47200 }, { 75500, 81000 },
            { 119980, 120020 }, { 142000, 149000 }, { 241000, 250000 } };

        static string BandaDaFreq(double mhz)
        {
            for (int i = 0; i < BandeNomi.Length; i++)
                if (mhz >= BandeLimiti[i, 0] && mhz <= BandeLimiti[i, 1]) return BandeNomi[i];
            return "";
        }

        static int OrdineBanda(string b)
        {
            int i = Array.IndexOf(BandeNomi, b);
            return i >= 0 ? i : 1000;
        }

        void FiltraAdif()
        {
            quadrati = new Dictionary<string, QuadratoInfo>();
            string banda = tabBande.SelectedIndex > 0 ? tabBande.SelectedTab.Text : null;
            int nq = 0;
            foreach (AdifQso q in adifQso)
            {
                if (banda != null && q.Band != banda) continue;
                if (chkSoloEme.Checked && !q.Eme) continue;
                if (q.Grids.Count == 0) continue;
                nq++;
                foreach (string g in q.Grids)
                {
                    QuadratoInfo qi;
                    if (!quadrati.TryGetValue(g, out qi)) { qi = new QuadratoInfo(); quadrati[g] = qi; }
                    qi.Qso++;
                    if (q.Confermato) qi.Confermati++;
                    if (q.Lotw) qi.Lotw++;
                    if (q.Qsl) qi.Qsl++;
                    if (q.Call.Length > 0 && !qi.Call.Contains(q.Call)) qi.Call.Add(q.Call);
                }
            }
            int conf = 0, lotw = 0;
            foreach (QuadratoInfo qi in quadrati.Values) { if (qi.Confermati > 0) conf++; if (qi.Lotw > 0) lotw++; }
            if (adifQso.Count > 0)
                lblMapInfo.Text = string.Format(ci, Lang.T("{0}{1}: {2:N0} QSO con locator, {3:N0} quadrati lavorati, {4:N0} confermati via LoTW, {5:N0} confermati in totale (LoTW o QSL).   Rotella o doppio clic = zoom, trascina = sposta, passa il mouse su un quadrato per i dettagli."),
                    banda ?? Lang.T("Tutte le bande"), chkSoloEme.Checked ? Lang.T(" (solo EME)") : "", nq, quadrati.Count, lotw, conf);
            mapTipKey = "";
            if (map != null) map.Invalidate();
        }

        // ----- Tessere della mappa -----

        Image Tessera(TileProvider p, int z, int x, int y, bool scarica)
        {
            string key = p.Nome + "|" + z + "|" + x + "|" + y;
            Image img;
            if (tileMem.TryGetValue(key, out img)) return img;
            string file = Path.Combine(tileDir, Path.Combine(Array.IndexOf(Mappe, p).ToString(CultureInfo.InvariantCulture),
                Path.Combine(z.ToString(CultureInfo.InvariantCulture), x.ToString(CultureInfo.InvariantCulture) + "_" + y.ToString(CultureInfo.InvariantCulture) + ".png")));
            if (File.Exists(file))
            {
                try
                {
                    using (MemoryStream ms = new MemoryStream(File.ReadAllBytes(file)))
                    using (Image tmp = Image.FromStream(ms))
                        img = new Bitmap(tmp);
                    MemorizzaTessera(key, img);
                    return img;
                }
                catch { try { File.Delete(file); } catch { } }
            }
            if (scarica && !tilePending.Contains(key) && !tileFailed.Contains(key))
            {
                tilePending.Add(key);
                tileQueue.Add(key + "|" + file);
                AvviaScaricamenti();
            }
            return null;
        }

        void MemorizzaTessera(string key, Image img)
        {
            if (tileMem.Count > 500)
            {
                foreach (Image im in tileMem.Values) im.Dispose();
                tileMem.Clear();
            }
            tileMem[key] = img;
        }

        void AvviaScaricamenti()
        {
            try { ServicePointManager.SecurityProtocol = (SecurityProtocolType)3072 | (SecurityProtocolType)768 | SecurityProtocolType.Tls; }
            catch { }
            while (tileActive < 4 && tileQueue.Count > 0)
            {
                // le tessere richieste per ultime sono quelle della vista attuale
                string job = tileQueue[tileQueue.Count - 1];
                tileQueue.RemoveAt(tileQueue.Count - 1);
                string[] p = job.Split('|');   // nome, z, x, y, file
                TileProvider prov = null;
                foreach (TileProvider tpv in Mappe) if (tpv.Nome == p[0]) prov = tpv;
                if (prov == null || prov.Url == null) continue;
                string key = p[0] + "|" + p[1] + "|" + p[2] + "|" + p[3];
                string file = p[4];
                string url = prov.Url.Replace("{z}", p[1]).Replace("{x}", p[2]).Replace("{y}", p[3]);
                WebClient wc = new WebClient();
                wc.Headers.Add("User-Agent", "YAEC/27 (EME calculator for radio amateurs)");
                tileActive++;
                wc.DownloadDataCompleted += (s, e) =>
                {
                    tileActive--;
                    tilePending.Remove(key);
                    if (e.Error == null && e.Result != null && e.Result.Length > 0)
                    {
                        try
                        {
                            Image img;
                            using (MemoryStream ms = new MemoryStream(e.Result))
                            using (Image tmp = Image.FromStream(ms))
                                img = new Bitmap(tmp);
                            MemorizzaTessera(key, img);
                            Directory.CreateDirectory(Path.GetDirectoryName(file));
                            File.WriteAllBytes(file, e.Result);
                        }
                        catch { tileFailed.Add(key); }
                    }
                    else tileFailed.Add(key);
                    ((WebClient)s).Dispose();
                    if (map != null) map.Invalidate();
                    if (pnlPunt != null && tabs != null && tabs.SelectedTab == tpPunt) pnlPunt.Invalidate();
                    AvviaScaricamenti();
                };
                try { wc.DownloadDataAsync(new Uri(url)); }
                catch { tileActive--; tilePending.Remove(key); tileFailed.Add(key); wc.Dispose(); }
            }
        }

        void Map_Paint(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            if (!mapInit)
            {
                CentraMappa(me.Ok ? me.Lat : 40, me.Ok ? me.Lon : 14, 4);
            }
            LimitaMappa();
            int W = map.Width, H = map.Height;
            int z = mapZoom;
            double size = MapSize(z);
            int n = 1 << z;
            double ox = mapCx - W / 2.0, oy = mapCy - H / 2.0;   // pixel mondo dell'angolo in alto a sinistra
            TileProvider prov = MappaCorrente();

            // Tessere
            if (prov.Url != null)
            {
                g.InterpolationMode = InterpolationMode.HighQualityBilinear;
                int tx0 = (int)Math.Floor(ox / 256.0), tx1 = (int)Math.Floor((ox + W) / 256.0);
                int ty0 = Math.Max(0, (int)Math.Floor(oy / 256.0)), ty1 = Math.Min(n - 1, (int)Math.Floor((oy + H) / 256.0));
                for (int ty = ty0; ty <= ty1; ty++)
                    for (int tx = tx0; tx <= tx1; tx++)
                    {
                        int wxp = ((tx % n) + n) % n;
                        float sx = (float)(tx * 256 - ox), sy = (float)(ty * 256 - oy);
                        Image img = Tessera(prov, z, wxp, ty, true);
                        if (img != null) { g.DrawImage(img, sx, sy, 256, 256); continue; }
                        // in attesa: usa una tessera di livello inferiore già disponibile, ingrandita
                        for (int up = 1; up <= 4 && z - up >= 0; up++)
                        {
                            int f = 1 << up;
                            Image par = Tessera(prov, z - up, wxp / f, ty / f, false);
                            if (par == null) continue;
                            float sub = 256f / f;
                            RectangleF src = new RectangleF((wxp % f) * sub, (ty % f) * sub, sub, sub);
                            g.DrawImage(par, new RectangleF(sx, sy, 256, 256), src, GraphicsUnit.Pixel);
                            break;
                        }
                    }
            }
            else
            {
                using (Brush b = new SolidBrush(Color.FromArgb(225, 232, 240))) g.FillRectangle(b, 0, 0, W, H);
            }
            g.SmoothingMode = SmoothingMode.AntiAlias;

            // Limiti visibili in gradi (la longitudine può uscire da ±180 per la ripetizione orizzontale)
            double lonMin = ox / size * 360.0 - 180.0, lonMax = (ox + W) / size * 360.0 - 180.0;
            double latMax = YToLat(Math.Max(0, oy), z), latMin = YToLat(Math.Min(size, oy + H), z);
            Func<double, float> SX = lon => (float)(LonToXr(lon, z) - ox);
            Func<double, float> SY = lat => (float)(LatToY(lat, z) - oy);
            Font fq = new Font(Lang.FontUi, 7.5F, FontStyle.Bold);
            Font ff = new Font(Lang.FontUi, 12F, FontStyle.Bold);

            // Quadrati dal file ADIF
            float sqW = (float)(2.0 / 360.0 * size);
            using (Brush bLav = new SolidBrush(Color.FromArgb(120, 255, 140, 0)))
            using (Brush bConf = new SolidBrush(Color.FromArgb(130, 0, 170, 60)))
            using (Brush bQsl = new SolidBrush(Color.FromArgb(120, 40, 110, 230)))
            using (Brush bTxt = new SolidBrush(Color.FromArgb(220, 105, 105, 105)))
            {
                foreach (KeyValuePair<string, QuadratoInfo> kv in quadrati)
                {
                    string q = kv.Key;
                    double lon0 = (q[0] - 'A') * 20 - 180 + (q[2] - '0') * 2;
                    double lat0 = (q[1] - 'A') * 10 - 90 + (q[3] - '0');
                    if (lat0 + 1 < latMin || lat0 > latMax) continue;
                    for (double k = Math.Floor((lonMin - lon0 - 2) / 360.0); lon0 + k * 360 <= lonMax; k++)
                    {
                        double l = lon0 + k * 360;
                        if (l + 2 < lonMin) continue;
                        float x0 = SX(l), x1 = SX(l + 2), y0 = SY(lat0 + 1), y1 = SY(lat0);
                        Brush fill = bLav;
                        if (chkConf.Checked && kv.Value.Lotw > 0) fill = bConf;
                        else if (chkConf.Checked && kv.Value.Qsl > 0) fill = bQsl;
                        g.FillRectangle(fill, x0, y0, x1 - x0, y1 - y0);
                        if (sqW >= 46 && (y1 - y0) >= 30)
                        {
                            string t = kv.Value.Qso.ToString(ci);
                            SizeF sz = g.MeasureString(t, fq);
                            g.DrawString(t, fq, bTxt, (x0 + x1 - sz.Width) / 2, y1 - sz.Height - 2);
                        }
                    }
                }
            }

            // Reticolo Maidenhead
            if (chkGrid.Checked)
            {
                using (Pen pf = new Pen(Color.FromArgb(210, 180, 0, 0), 2.8f))
                using (Pen ps = new Pen(Color.FromArgb(140, 60, 60, 140), 1f))
                using (Pen pss = new Pen(Color.FromArgb(90, 60, 60, 140), 1f))
                using (Brush bf = new SolidBrush(Color.FromArgb(170, 160, 0, 0)))
                using (Brush bs = new SolidBrush(Color.FromArgb(220, 105, 105, 105)))
                {
                    // sottoquadrati (5' x 2,5')
                    float ssW = (float)(1.0 / 12.0 / 360.0 * size);
                    if (ssW >= 12)
                    {
                        for (double l = Math.Floor(lonMin * 12) / 12; l <= lonMax; l += 1.0 / 12) g.DrawLine(pss, SX(l), 0, SX(l), H);
                        for (double a = Math.Floor(latMin * 24) / 24; a <= latMax; a += 1.0 / 24) g.DrawLine(pss, 0, SY(a), W, SY(a));
                    }
                    // quadrati (2° x 1°)
                    if (sqW >= 8)
                    {
                        for (double l = Math.Floor(lonMin / 2) * 2; l <= lonMax; l += 2) g.DrawLine(ps, SX(l), 0, SX(l), H);
                        for (double a = Math.Floor(latMin); a <= latMax; a += 1) g.DrawLine(ps, 0, SY(a), W, SY(a));
                    }
                    // campi (20° x 10°)
                    for (double l = Math.Floor((lonMin + 180) / 20) * 20 - 180; l <= lonMax; l += 20) g.DrawLine(pf, SX(l), 0, SX(l), H);
                    for (double a = Math.Floor((latMin + 90) / 10) * 10 - 90; a <= latMax; a += 10) g.DrawLine(pf, 0, SY(a), W, SY(a));

                    // etichette
                    float fW = (float)(20.0 / 360.0 * size);
                    if (sqW >= 34)
                    {
                        for (double l = Math.Floor(lonMin / 2) * 2; l <= lonMax; l += 2)
                            for (double a = Math.Floor(latMin); a <= latMax; a += 1)
                            {
                                double ln = ((l + 180) % 360 + 360) % 360 - 180;
                                string q = Quadrato(a + 0.5, ln + 1);
                                if (q == null) continue;
                                g.DrawString(q, fq, bs, SX(l) + 2, SY(a + 1) + 1);
                            }
                    }
                    else if (fW >= 26)
                    {
                        for (double l = Math.Floor((lonMin + 180) / 20) * 20 - 180; l <= lonMax; l += 20)
                            for (double a = Math.Floor((latMin + 90) / 10) * 10 - 90; a <= latMax; a += 10)
                            {
                                double ln = ((l + 180) % 360 + 360) % 360 - 180;
                                string q = Quadrato(a + 5, ln + 10);
                                if (q == null) continue;
                                string t = q.Substring(0, 2);
                                SizeF sz = g.MeasureString(t, ff);
                                float cx = (SX(l) + SX(l + 20)) / 2, cy = (SY(a) + SY(a + 10)) / 2;
                                if (fW >= sz.Width + 4) g.DrawString(t, ff, bf, cx - sz.Width / 2, cy - sz.Height / 2);
                            }
                    }
                }
            }

            // Stazioni
            string mioNome = txtCall != null && txtCall.Text.Trim().Length > 0 ? txtCall.Text.Trim() : Lang.T("IO");
            DisegnaStazione(g, me, mioNome + " " + me.Loc.Text.Trim(), Color.Blue, SX, SY, lonMin, lonMax);
            if (chkDx.Checked && dx.Ok) DisegnaStazione(g, dx, "DX " + dx.Loc.Text.Trim(), Color.Purple, SX, SY, lonMin, lonMax);

            // Attribuzione della mappa
            if (prov.Attribuzione.Length > 0)
            {
                Font fa = new Font(Lang.FontUi, 7.5F);
                SizeF sz = g.MeasureString(prov.Attribuzione, fa);
                using (Brush b = new SolidBrush(Color.FromArgb(200, 255, 255, 255))) g.FillRectangle(b, W - sz.Width - 6, H - sz.Height - 4, sz.Width + 6, sz.Height + 4);
                g.DrawString(prov.Attribuzione, fa, Brushes.Black, W - sz.Width - 3, H - sz.Height - 2);
                fa.Dispose();
            }
            using (Brush b = new SolidBrush(Color.FromArgb(200, 255, 255, 255))) g.FillRectangle(b, 4, H - S(20), S(70), S(18));
            g.DrawString(Lang.T("zoom ") + z.ToString(inv), fq, Brushes.Black, 7, H - S(18));
            fq.Dispose();
            ff.Dispose();
        }

        // longitudine -> pixel mondo senza riportarla in ±180 (serve per la ripetizione orizzontale)
        static double LonToXr(double lon, int z) { return (lon + 180.0) / 360.0 * MapSize(z); }

        void DisegnaStazione(Graphics g, StationUi st, string nome, Color c, Func<double, float> SX, Func<double, float> SY, double lonMin, double lonMax)
        {
            if (!st.Ok) return;
            for (double k = Math.Floor((lonMin - st.Lon) / 360.0); st.Lon + k * 360 <= lonMax; k++)
            {
                double l = st.Lon + k * 360;
                if (l < lonMin) continue;
                float x = SX(l), y = SY(st.Lat), r = S(10);
                using (Brush b = new SolidBrush(c)) g.FillEllipse(b, x - r / 2, y - r / 2, r, r);
                using (Pen p = new Pen(Color.White, 2)) g.DrawEllipse(p, x - r / 2, y - r / 2, r, r);
                using (Font f = new Font(Lang.FontUi, 8.5F, FontStyle.Bold))
                {
                    SizeF sz = g.MeasureString(nome, f);
                    using (Brush bg = new SolidBrush(Color.FromArgb(210, 255, 255, 255))) g.FillRectangle(bg, x + r, y - sz.Height / 2, sz.Width, sz.Height);
                    using (Brush b = new SolidBrush(c)) g.DrawString(nome, f, b, x + r, y - sz.Height / 2);
                }
            }
        }

        public MainForm()
        {
            settingsPath = PercorsoImpostazioni();
            Fumetto.Stile(tip);
            Fumetto.Stile(mapTip);
            // impostazioni generali lette prima di costruire le finestre: caratteri dei moduli e tema
            float fm = 9F;
            float.TryParse(LeggiImpostazione("font_moduli"), NumberStyles.Float, inv, out fm);
            if (fm < 8 || fm > 14) fm = 9F;
            fontFactor = fm / 9F;
            float.TryParse(LeggiImpostazione("font_tabelle"), NumberStyles.Float, inv, out fontTabelle);
            if (fontTabelle < 7 || fontTabelle > 18) fontTabelle = 9F;
            string tm = LeggiImpostazione("tema");
            Tema.Imposta(Tema.DaChiave(tm));
            this.Font = new Font(Lang.FontUi, fm);
            this.AutoScaleMode = AutoScaleMode.None;
            using (Graphics g = this.CreateGraphics()) scale = g.DpiX / 96f;

            this.Text = TitoloProgramma;
            if (Lang.Rtl) this.RightToLeft = RightToLeft.Yes;
            try { Icon ic = SplashForm.IconaLuna(); if (ic != null) this.Icon = ic; } catch { }
            this.ClientSize = new Size(S(1200), S(780));
            this.MinimumSize = new Size(S(900), S(600));
            this.StartPosition = FormStartPosition.CenterScreen;

            BuildUi();
            // colore delle caselle di spunta: quello dominante di ogni linguetta
            {
                Color verde = Color.FromArgb(23, 128, 61), blu = Color.FromArgb(31, 111, 209), viola = Color.FromArgb(91, 63, 168), aranc = Color.FromArgb(217, 119, 6);
                Control[] pg = { tpTrack, tpPos, tpBudget, tpSolar, tpSky, tpDgrd, tpMap, tpPunt };
                Color[] cl = { verde, blu, viola, aranc, blu, verde, blu, blu };
                for (int i = 0; i < pg.Length; i++) if (pg[i] != null) Spunta.ColoriLinguette[pg[i]] = cl[i];
                Spunta sdx = chkDx as Spunta;
                if (sdx != null) sdx.Colore = Color.FromArgb(217, 119, 6);
            }
            caricamento = true;
            LoadSettings();
            caricamento = false;
            SetupColumns(true);
            AgganciaLocatorTracciamento();
            AgganciaLimitiPunt();
            AgganciaAvvisiZone();
            this.Text = TitoloFinestra();
            ApplicaTema();
            ApplicaFontTabelle();
            UpdateLocators();
            gbDx.Enabled = true;
            EnableDx();
            ControllaZone(false);   // le stazioni già impostate all'avvio non danno l'avviso
            ControllaDpol(false);

            timer = new Timer();
            timer.Interval = 2000;
            timer.Tick += (s, e) => UpdateLive();
            timer.Start();
            UpdateLive();

            // solo per le prove automatiche: YAEC_LINGUETTA=<nome> apre quella linguetta all'avvio
            string lgProva = Environment.GetEnvironmentVariable("YAEC_LINGUETTA");
            if (!string.IsNullOrEmpty(lgProva)) this.Shown += (s, e) => ApriLinguettaPerNome(this, lgProva);
            // solo per le prove automatiche: YAEC_GIRO=<cartella> apre una linguetta alla volta; per ognuna scrive
            // <n>.txt con il nome e aspetta che la prova crei ok<n> (dopo la schermata), poi passa alla successiva
            string giro = Environment.GetEnvironmentVariable("YAEC_GIRO");
            if (!string.IsNullOrEmpty(giro)) this.Shown += (s, e) =>
            {
                TabPage[] tutte = { tpTrack, tpPos, tpBudget, tpSolar, tpSky, tpPunt, tpDgrd, tpMondo, tpMap, tpExcel, tpDebug, tpIstr, tpEme, tpCavi, tpContatti, tpLicenza, tpAbout };
                int n = -1;
                System.Windows.Forms.Timer tg = new System.Windows.Forms.Timer();
                tg.Interval = 3000;
                tg.Tick += (s2, e2) =>
                {
                    try
                    {
                        if (n >= 0 && !File.Exists(Path.Combine(giro, "ok" + n))) return;
                        do n++; while (n < tutte.Length && (tutte[n] == null || PaginaSpenta(tutte[n])));
                        if (n >= tutte.Length) { tg.Stop(); File.WriteAllText(Path.Combine(giro, "fine"), "ok"); return; }
                        ApriLinguettaPerNome(this, tutte[n].Text.Trim());
                        tg.Stop();
                        System.Windows.Forms.Timer t2 = new System.Windows.Forms.Timer();
                        t2.Interval = 4000;
                        t2.Tick += (s3, e3) => { t2.Stop(); t2.Dispose(); File.WriteAllText(Path.Combine(giro, n + ".txt"), tutte[n].Text.Trim()); tg.Start(); };
                        t2.Start();
                    }
                    catch { tg.Stop(); }
                };
                tg.Start();
            };

            this.Load += (s, e) =>
            {
                int d = split.Height - S(170);
                if (d > S(100)) split.SplitterDistance = d;
                if (chkSfuAuto.Checked && complessi) ScaricaSfu();
            };
            this.FormClosing += (s, e) =>
            {
                if (ricostruzione) return;
                if (e.CloseReason == CloseReason.UserClosing)
                {
                    if (!ChiediChiusura()) { e.Cancel = true; return; }
                }
                SaveSettings();
            };
            this.FormClosed += (s, e) => FermaTimer();
        }

        bool ricostruzione;

        // Cambio di lingua, carattere o grandezza: la finestra si ricostruisce nella stessa posizione,
        // sulla stessa linguetta, senza chiudere il programma e senza schermata di avvio.
        void Ricostruisci()
        {
            if (ricostruzione) return;
            SaveSettings();
            ricostruzione = true;
            int linguetta = tabs != null && tabs.SelectedIndex >= 0 ? tabs.SelectedIndex : 0;
            Rectangle pos = this.WindowState == FormWindowState.Normal ? this.Bounds : this.RestoreBounds;
            FormWindowState stato = this.WindowState == FormWindowState.Minimized ? FormWindowState.Normal : this.WindowState;
            Cursor.Current = Cursors.WaitCursor;
            MainForm nf;
            try
            {
                Program.ApplicaLinguaECarattere();
                nf = new MainForm();
            }
            catch (Exception ex)
            {
                ricostruzione = false;
                Cursor.Current = Cursors.Default;
                Messaggio(this, ex.Message, "YAEC", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }
            nf.StartPosition = FormStartPosition.Manual;
            nf.Bounds = pos;
            nf.WindowState = stato;
            nf.Shown += (s, e) =>
            {
                try { if (nf.tabs != null && linguetta < nf.tabs.TabPages.Count) nf.tabs.SelectedIndex = linguetta; } catch { }
            };
            if (Program.Contesto != null) Program.Contesto.MainForm = nf;
            nf.Show();
            this.Close();
            Cursor.Current = Cursors.Default;
        }

        // Ferma tutti i timer della finestra chiusa, così non lavorano su controlli ormai eliminati
        void FermaTimer()
        {
            foreach (System.Reflection.FieldInfo fi in GetType().GetFields(System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic))
            {
                if (fi.FieldType != typeof(Timer)) continue;
                try { Timer t = fi.GetValue(this) as Timer; if (t != null) { t.Stop(); t.Dispose(); } } catch { }
            }
        }

        // Finestra di chiusura: domanda e ringraziamento
        bool ChiediChiusura()
        {
            return ChiediSiNo(Lang.T("Chiusura del programma"), Lang.T("Vuoi chiudere YAEC?"), Lang.T("Grazie per avermi usato: spero di esserti stato utile."));
        }

        // Finestra Sì/No nello stile della chiusura: icona, domanda, nota in corsivo, barra grigia con i pulsanti.
        // L'altezza si calcola sommando il contenuto e la barra dei pulsanti, così i pulsanti sono sempre visibili.
        bool ChiediSiNo(string titolo, string domanda, string nota)
        {
            return FinestraStile(this, titolo, domanda, nota, SystemIcons.Question, true) == DialogResult.Yes;
        }

        // Avvisi del programma nello stesso stile della finestra di chiusura (al posto dei messaggi di Windows):
        // la prima riga è il messaggio, le righe seguenti la nota in corsivo; un solo pulsante OK (Sì/No per le domande)
        DialogResult Messaggio(IWin32Window owner, string testo, string titolo, MessageBoxButtons pulsanti, MessageBoxIcon icona)
        {
            testo = testo ?? "";
            int k = testo.IndexOf('\n');
            string prima = k > 0 ? testo.Substring(0, k) : testo, resto = k > 0 ? testo.Substring(k + 1).Trim() : null;
            Icon ic = icona == MessageBoxIcon.Error ? SystemIcons.Error : (icona == MessageBoxIcon.Warning ? SystemIcons.Warning : (icona == MessageBoxIcon.Question ? SystemIcons.Question : SystemIcons.Information));
            bool siNo = pulsanti == MessageBoxButtons.YesNo;
            return FinestraStile(owner ?? this, string.IsNullOrEmpty(titolo) ? "YAEC" : titolo, prima, resto, ic, siNo);
        }

        // Finestre di dialogo con campi (LoTW, bande, cavo personalizzato, colonne) nello stesso stile:
        // fondo bianco, contenuto in alto, riga sottile e barra grigia con i pulsanti a destra
        void StileDialogo(Form f, Control contenuto, params Button[] pulsanti)
        {
            f.AutoSize = false;
            f.AutoScaleMode = AutoScaleMode.None;
            f.Font = new Font(Lang.FontUi, 10F);
            f.BackColor = Tema.Scuro ? Tema.Back : Color.White;
            f.ForeColor = Tema.Fore;
            f.RightToLeft = Lang.Rtl ? RightToLeft.Yes : RightToLeft.No;
            try { f.Icon = this.Icon; } catch { }
            contenuto.BackColor = f.BackColor;
            Panel linea = new Panel(); linea.Height = 1; linea.BackColor = Tema.Scuro ? Tema.Linea : Color.FromArgb(222, 226, 232);
            // barra dei pulsanti disposta a mano: con le dimensioni automatiche i pulsanti potevano
            // sovrapporsi o uscire dal fondo della finestra (schermi con ingrandimento al 125-150%)
            Panel bt = new Panel();
            bt.BackColor = Tema.Scuro ? Tema.Section : Color.FromArgb(240, 240, 240);
            foreach (Button b in pulsanti)
            {
                if (b.Parent != null) b.Parent.Controls.Remove(b);
                b.AutoSize = false;
                b.BackColor = bt.BackColor;
                b.ForeColor = Tema.Fore;
                b.UseVisualStyleBackColor = false;
                bt.Controls.Add(b);
            }
            f.Controls.Add(contenuto); f.Controls.Add(linea); f.Controls.Add(bt);
            Action disponi = () =>
            {
                int pad = S(14), gap = S(14);
                int hb = S(34), wtot = 0;
                int[] wb = new int[pulsanti.Length];
                for (int i = 0; i < pulsanti.Length; i++)
                {
                    Size ps = pulsanti[i].GetPreferredSize(Size.Empty);
                    wb[i] = Math.Max(S(100), ps.Width + S(8));
                    hb = Math.Max(hb, ps.Height + S(4));
                    wtot += wb[i] + (i > 0 ? gap : 0);
                }
                Size sc = contenuto.GetPreferredSize(Size.Empty);
                int w = Math.Max(Math.Max(sc.Width, wtot + 2 * pad), S(380));
                int hbar = hb + 2 * S(12);
                contenuto.Location = new Point(0, 0);
                linea.SetBounds(0, sc.Height, w, 1);
                bt.SetBounds(0, sc.Height + 1, w, hbar);
                // in ordine da destra: l'ultimo pulsante (Annulla) sta a destra, come prima
                int x = w - pad;
                for (int i = pulsanti.Length - 1; i >= 0; i--)
                {
                    x -= wb[i];
                    pulsanti[i].SetBounds(x, (hbar - hb) / 2, wb[i], hb);
                    x -= gap;
                }
                f.ClientSize = new Size(w, sc.Height + 1 + hbar);
            };
            disponi();
            f.Load += (s, e) => disponi();   // di nuovo con i caratteri e la scala definitivi
        }

        DialogResult FinestraStile(IWin32Window owner, string titolo, string domanda, string nota, Icon icona, bool siNo)
        {
            using (Form f = new Form())
            {
                f.Text = titolo;
                f.FormBorderStyle = FormBorderStyle.FixedDialog;
                f.MaximizeBox = false; f.MinimizeBox = false; f.ShowInTaskbar = false;
                f.StartPosition = FormStartPosition.CenterParent;
                f.AutoScaleMode = AutoScaleMode.None;
                f.Font = new Font(Lang.FontUi, 10F);
                f.RightToLeft = Lang.Rtl ? RightToLeft.Yes : RightToLeft.No;
                try { f.Icon = this.Icon; } catch { }
                f.BackColor = Color.White;
                TableLayoutPanel t = new TableLayoutPanel();
                t.AutoSize = true; t.AutoSizeMode = AutoSizeMode.GrowAndShrink;
                t.ColumnCount = 2; t.RowCount = 1;
                t.Padding = new Padding(S(18), S(18), S(22), S(16));
                t.BackColor = Color.White;
                PictureBox pb = new PictureBox();
                pb.Image = icona.ToBitmap();
                pb.SizeMode = PictureBoxSizeMode.AutoSize;
                pb.Margin = new Padding(0, 0, S(14), 0);
                Label q = new Label();
                q.Text = domanda;
                q.AutoSize = true;
                q.MaximumSize = new Size(S(440), 0);
                q.Font = new Font(Lang.FontUi, 11.5F);
                q.Margin = new Padding(0, S(4), 0, S(8));
                Label gz = new Label();
                gz.Text = nota ?? "";
                gz.AutoSize = true;
                gz.MaximumSize = new Size(S(440), 0);
                gz.Font = new Font(Lang.FontUi, 10F, FontStyle.Italic);
                gz.ForeColor = Color.FromArgb(75, 85, 99);
                gz.Margin = new Padding(0);
                FlowLayoutPanel testi = new FlowLayoutPanel();
                testi.FlowDirection = FlowDirection.TopDown; testi.AutoSize = true; testi.WrapContents = false;
                testi.Margin = new Padding(0);
                testi.Controls.Add(q);
                if (!string.IsNullOrEmpty(nota)) testi.Controls.Add(gz);
                t.Controls.Add(pb, 0, 0); t.Controls.Add(testi, 1, 0);
                // linea sottile e barra grigia dei pulsanti
                Panel linea = new Panel(); linea.Height = 1; linea.BackColor = Color.FromArgb(222, 226, 232);
                FlowLayoutPanel bt = new FlowLayoutPanel();
                bt.FlowDirection = FlowDirection.RightToLeft;   // con la finestra da destra a sinistra si rispecchia da sola
                bt.WrapContents = false;
                bt.AutoSize = true; bt.AutoSizeMode = AutoSizeMode.GrowAndShrink;
                bt.BackColor = Color.FromArgb(240, 240, 240);
                bt.Padding = new Padding(S(12), S(10), S(12), S(10));
                Button no = new Pulsante(); no.Text = Lang.T("No"); no.DialogResult = DialogResult.No;
                Button si = new Pulsante(); si.Text = siNo ? Lang.T("Sì") : "OK"; si.DialogResult = siNo ? DialogResult.Yes : DialogResult.OK;
                foreach (Button b in new Button[] { no, si })
                {
                    b.AutoSize = true; b.MinimumSize = new Size(S(96), S(32));
                    b.Margin = new Padding(S(6), 0, 0, 0);
                    b.BackColor = Color.FromArgb(252, 252, 252);
                    b.UseVisualStyleBackColor = false;
                }
                if (siNo) bt.Controls.Add(no);
                bt.Controls.Add(si);
                f.Controls.Add(t); f.Controls.Add(linea); f.Controls.Add(bt);
                // misure: contenuto sopra, barra sotto, larghezza della parte più larga
                Size st = t.GetPreferredSize(Size.Empty), sb = bt.GetPreferredSize(Size.Empty);
                int w = Math.Max(Math.Max(st.Width, sb.Width), S(380));
                t.Location = new Point(0, 0); t.Width = w;
                bt.AutoSize = false;
                linea.SetBounds(0, st.Height, w, 1);
                bt.SetBounds(0, st.Height + 1, w, sb.Height);
                f.ClientSize = new Size(w, st.Height + 1 + sb.Height);
                f.AcceptButton = si; f.CancelButton = siNo ? no : si;
                f.StartPosition = owner is Form && ((Form)owner).Visible ? FormStartPosition.CenterParent : FormStartPosition.CenterScreen;
                f.Shown += (s2, e2) => si.Focus();
                return f.ShowDialog(owner);
            }
        }

        // ---------- Interfaccia ----------

        Label L(string text)
        {
            Label l = new Label();
            l.Text = text;
            l.AutoSize = true;
            l.Anchor = AnchorStyles.Left;
            l.Margin = new Padding(S(3), S(6), S(3), S(3));
            return l;
        }

        NumericUpDown Nud(decimal min, decimal max, decimal val, int decimals, int width)
        {
            NudUnita n = new NudUnita();
            n.Minimum = min; n.Maximum = max; n.DecimalPlaces = decimals;
            n.Value = val; n.Width = S(width);
            n.Increment = decimals > 0 ? 0.5m : 1m;
            n.SenzaFrecce = true;
            n.TextAlign = HorizontalAlignment.Right;
            n.Anchor = AnchorStyles.Left;
            return n;
        }

        NumericUpDown NudU(decimal min, decimal max, decimal val, int decimals, int width, string unita, string formato)
        {
            NudUnita n = new NudUnita();
            n.Minimum = min; n.Maximum = max; n.DecimalPlaces = decimals;
            n.Value = val; n.Width = S(width);
            n.Increment = decimals > 0 ? 0.5m : 1m;
            n.TextAlign = HorizontalAlignment.Right;
            n.Anchor = AnchorStyles.Left;
            n.Formato = formato; n.Unita = unita; n.SenzaFrecce = true;
            return n;
        }

        // Scheda bianca con bordo superiore colorato e titolo maiuscolo (bozzetto della Posizione della Luna)
        Control SchedaCampi(string titolo, Color col, TableLayoutPanel grid, Control destra) { return SchedaCampi(titolo, col, grid, destra, false); }

        Control SchedaCampi(string titolo, Color col, TableLayoutPanel grid, Control destra, bool riempi)
        {
            PannelloDisegno pn = new PannelloDisegno();
            pn.Dock = DockStyle.Fill;
            pn.Margin = new Padding(S(6), S(6), S(6), S(4));
            pn.Padding = new Padding(S(14), S(38), S(14), S(10));
            pn.Tag = "carta";   // i controlli dentro la scheda prendono il fondo bianco
            pn.AutoSize = true;
            pn.AutoSizeMode = AutoSizeMode.GrowAndShrink;
            if (riempi) { pn.AutoSize = false; grid.Dock = DockStyle.Fill; }
            else { grid.Dock = DockStyle.None; grid.Location = new Point(pn.Padding.Left, pn.Padding.Top); }
            pn.Controls.Add(grid);
            if (destra != null) pn.Controls.Add(destra);
            pn.Layout += (s, e) =>
            {
                if (destra != null) destra.Location = new Point(pn.Width - S(16) - destra.Width, S(10));
            };
            pn.Paint += (s, e) =>
            {
                Graphics g = e.Graphics;
                PreparaGrafica(g);
                g.Clear(Tema.Back);
                RectangleF r = new RectangleF(S(2), S(2), pn.Width - S(6), pn.Height - S(7));
                Scheda(g, r, Color.Empty);
                using (GraphicsPath gp = Arrotondato(r, S(12)))
                {
                    Region old = g.Clip;
                    g.SetClip(gp, CombineMode.Intersect);
                    using (Brush bc = new SolidBrush(col)) g.FillRectangle(bc, r.Left, r.Top, r.Width, S(4));
                    g.Clip = old;
                }
                using (Font ft = FontPx(Lang.FontUi, S(13), true))
                    Testo(g, titolo.ToUpper(Lang.Cultura), ft, col, new RectangleF(r.Left + S(14), r.Top + S(10), r.Width * 0.7f, S(22)), StringAlignment.Near, StringAlignment.Center);
            };
            return pn;
        }

        GroupBox Group(string title, int cols, out TableLayoutPanel grid)
        {
            GroupBox gb = new GroupBox();
            gb.Text = title;
            gb.AutoSize = true;
            gb.AutoSizeMode = AutoSizeMode.GrowAndShrink;
            gb.Padding = new Padding(S(8), S(4), S(8), S(6));
            gb.Margin = new Padding(S(6), S(4), S(6), S(4));
            grid = new TableLayoutPanel();
            grid.ColumnCount = cols;
            grid.AutoSize = true;
            grid.AutoSizeMode = AutoSizeMode.GrowAndShrink;
            grid.Dock = DockStyle.Fill;
            for (int i = 0; i < cols; i++) grid.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
            gb.Controls.Add(grid);
            return gb;
        }

        // Riquadro stazione: locator, quota, limiti di puntamento
        StationUi BuildStation(TableLayoutPanel g, int row0, string locDefault, decimal hDefault)
        {
            StationUi st = new StationUi();
            st.Loc = new TextBox();
            st.Loc.Width = S(95);
            st.Loc.MaxLength = 14;
            st.Loc.CharacterCasing = CharacterCasing.Upper;
            st.Loc.Text = locDefault;
            st.Loc.TextChanged += (s, e) => { UpdateLocators(); UpdateLive(); ProgrammaQuota(st); };
            tip.SetToolTip(st.Loc, Lang.T("Locator WWL Maidenhead") + "\u0001" + Lang.T("Da 4 a 14 caratteri. Per i QSO bastano 6 (±4,4 km); per valutare gli ostacoli vicini usa 8 (±450 m) o meglio 10 caratteri (±20 m). Oltre 10 la precisione supera quella di un GPS comune. Vedi il manuale, § 2.2."));
            st.H = NudU(-100, 9000, hDefault, 0, 70, "m", null);
            tip.SetToolTip(st.H, Lang.T("Quota sul livello del mare in metri (influisce pochissimo sulla parallasse).") + "\n"
                + Lang.T("Con un locator di 10 caratteri la quota del terreno viene presa automaticamente dal web (Open Topo Data, Open-Meteo)."));
            st.Az1 = NudU(0, 360, 0, 1, 95, "°", null);
            st.Az2 = NudU(0, 360, 360, 1, 95, "°", null);
            st.El1 = NudU(-5, 90, 0, 1, 95, "°", null);
            st.El2 = NudU(-5, 90, 90, 1, 95, "°", null);
            tip.SetToolTip(st.Az1, Lang.T("Inizio del settore azimutale utile, percorso in senso orario.") + "\n" + Lang.T("Azimut: settore in senso orario da → a (0 → 360 = nessun limite)"));
            tip.SetToolTip(st.Az2, Lang.T("Fine del settore azimutale utile. Es. da 270 a 90 = settore nord passando per 0°. Da 0 a 360 = giro completo."));
            tip.SetToolTip(st.El1, Lang.T("Elevazione minima raggiungibile (orizzonte, ostacoli, limite del rotore)."));
            tip.SetToolTip(st.El2, Lang.T("Elevazione massima raggiungibile (0 per antenna fissa sull'orizzonte, 90 con rotore di elevazione completo)."));
            st.Coord = new Label();
            st.Coord.AutoSize = true;
            st.Coord.Margin = new Padding(S(3), S(2), S(3), S(5));
            st.Coord.ForeColor = Tema.Muted;
            st.Coord.Font = new Font(Lang.FontUi, 8F * fontFactor);
            st.Loc.Font = new Font(FamigliaNumeri, 9.5F * fontFactor, FontStyle.Bold);
            st.Loc.Width = S(128);
            Func<Label> freccia = () => { Label lf = L("→"); lf.Margin = new Padding(S(6), S(6), S(6), S(3)); return lf; };

            g.Controls.Add(L(Lang.T("Locator WWL")), 0, row0); g.Controls.Add(st.Loc, 1, row0);
            g.Controls.Add(L(Lang.T("Quota")), 2, row0); g.Controls.Add(st.H, 3, row0);
            g.Controls.Add(st.Coord, 0, row0 + 1); g.SetColumnSpan(st.Coord, 4);
            g.Controls.Add(L(Lang.T("Azimut")), 0, row0 + 2); g.Controls.Add(st.Az1, 1, row0 + 2);
            g.Controls.Add(freccia(), 2, row0 + 2); g.Controls.Add(st.Az2, 3, row0 + 2);
            g.Controls.Add(L(Lang.T("Elevazione")), 0, row0 + 3); g.Controls.Add(st.El1, 1, row0 + 3);
            g.Controls.Add(freccia(), 2, row0 + 3); g.Controls.Add(st.El2, 3, row0 + 3);
            return st;
        }

        void BuildUi()
        {
            TableLayoutPanel root = new TableLayoutPanel();
            root.Dock = DockStyle.Fill;
            root.ColumnCount = 1;
            root.RowCount = 3;
            root.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            root.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            root.RowStyles.Add(new RowStyle(SizeType.Percent, 100f));
            root.Padding = new Padding(S(4));

            // tre schede bianche affiancate: la mia stazione (blu), il DX (arancione), periodo e calcolo (viola)
            TableLayoutPanel top = new TableLayoutPanel();
            top.AutoSize = true;
            top.AutoSizeMode = AutoSizeMode.GrowAndShrink;
            top.Dock = DockStyle.Fill;
            top.ColumnCount = 3;
            top.RowCount = 1;
            top.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 33f));
            top.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 34f));
            top.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 33f));
            top.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            top.Margin = new Padding(0);

            // La mia stazione
            TableLayoutPanel g1;
            Group(Lang.T("La mia stazione"), 4, out g1);
            me = BuildStation(g1, 0, "", 0);
            top.Controls.Add(SchedaCampi(Lang.T("La mia stazione"), Color.FromArgb(31, 111, 209), g1, null), 0, 0);

            // Stazione DX: la casella CONFRONTA sta nel titolo
            TableLayoutPanel g2;
            Group(Lang.T("Seconda stazione (DX)"), 4, out g2);
            chkDx = new Spunta();
            chkDx.Text = Lang.T("CONFRONTA");
            chkDx.AutoSize = true;
            chkDx.Font = new Font(Lang.FontUi, 8.5F * fontFactor, FontStyle.Bold);
            chkDx.ForeColor = Color.FromArgb(55, 65, 81);
            chkDx.Checked = true;
            tip.SetToolTip(chkDx, Lang.T("Confronta con la seconda stazione"));
            chkDx.CheckedChanged += (s, e) => { EnableDx(); UpdateLive(); };
            dx = BuildStation(g2, 1, "", 0);
            AgganciaCall3(dx.Loc);
            txtDxCall = new TextBox();
            txtDxCall.MaxLength = 13;
            txtDxCall.CharacterCasing = CharacterCasing.Upper;
            txtDxCall.Font = new Font(FamigliaNumeri, 9.5F * fontFactor, FontStyle.Bold);
            txtDxCall.Width = S(128);
            tip.SetToolTip(txtDxCall, Lang.T("Nominativo del DX") + "\u0001" + Lang.T("Se il nominativo è nel CALL3.TXT il locator si riempie da solo. Se il locator l'hai scritto tu e il CALL3.TXT ne indica un altro, premi Invio sul nominativo per usare quello del CALL3.TXT."));
            g2.Controls.Add(L(Lang.T("Nominativo")), 0, 0); g2.Controls.Add(txtDxCall, 1, 0);
            Pillola btnGraves = new Pillola("GRAVES", StilePillola.Pieno, Color.FromArgb(124, 58, 237), new Font(Lang.FontUi, 8F * fontFactor, FontStyle.Bold));
            btnGraves.Margin = new Padding(S(6), S(1), S(3), S(1));
            tip.SetToolTip(btnGraves, Lang.T("Radar GRAVES come stazione DX") + "\u0001" + Lang.T("Mette come DX il radar francese GRAVES (143,050 MHz, locator JN27SI): le finestre comuni con GRAVES sono i momenti in cui puoi ricevere la sua eco dalla Luna e verificare ricevitore e puntamento. Vedi il manuale TEORIA E CONSIGLI SULL'EME, § 1.11."));
            btnGraves.Click += (s, e) => ImpostaGraves();
            g2.Controls.Add(btnGraves, 2, 0);
            AgganciaNominativo(txtDxCall);
            // stazione attiva (chat N0UK): bordo arancione 3 volte più spesso intorno alla casella del nominativo
            g2.Paint += (s, e) =>
            {
                if (!dxAttivo || !txtDxCall.Visible) return;
                Rectangle rc = txtDxCall.Bounds;
                rc.Inflate(S(2), S(2));
                using (Pen pn = new Pen(ColAttivo, 3f)) { pn.Alignment = PenAlignment.Inset; e.Graphics.DrawRectangle(pn, rc); }
            };
            txtDxCall.Margin = new Padding(S(4), S(4), S(4), S(4));
            AvviaAttivi();
            gbDx = SchedaCampi(Lang.T("Seconda stazione (DX)"), Color.FromArgb(217, 119, 6), g2, chkDx);
            top.Controls.Add(gbDx, 1, 0);

            // Periodo e calcolo
            TableLayoutPanel g3;
            Group(Lang.T("Periodo e calcolo"), 4, out g3);
            dtp = new DateTimePicker();
            dtp.Format = DateTimePickerFormat.Custom;
            dtp.CustomFormat = "dd/MM/yyyy  HH:mm";
            dtp.Width = S(150);
            dtp.Anchor = AnchorStyles.Left;
            dtp.Value = NowUtcMinute();
            Pillola btnNow = new Pillola(Lang.T("Adesso"), StilePillola.Pieno, ColPillola, new Font(Lang.FontUi, 9F * fontFactor));
            btnNow.Margin = new Padding(S(6), S(1), S(3), S(1));
            btnNow.Click += (s, e) => { dtp.Value = NowUtcMinute(); };
            nudDur = NudU(0.1m, 31m, 1m, 1, 100, Lang.T("giorni"), "0.#");
            tip.SetToolTip(nudDur, Lang.T("Durata del periodo di calcolo in giorni (anche frazioni, es. 0,5 = 12 ore)."));
            nudStep = NudU(1, 1440, 10, 0, 80, "min", null);
            tip.SetToolTip(nudStep, Lang.T("Passo della tabella in minuti."));
            cmbFreq = new Tendina();
            cmbFreq.DropDownStyle = ComboBoxStyle.DropDown;
            foreach (int f in bandeAttive) cmbFreq.Items.Add(f.ToString(inv));
            cmbFreq.Text = "144";
            cmbFreq.Width = S(70);
            cmbFreq.Anchor = AnchorStyles.Left;
            tip.SetToolTip(cmbFreq, Lang.T("Frequenza di lavoro, parte in MHz (es. 144).\nServe per Tsky/Dgrd e, insieme ai kHz, per il Doppler e le frequenze CFOM."));
            cmbKhz = new Tendina();
            cmbKhz.DropDownStyle = ComboBoxStyle.DropDown;
            for (int kh = 0; kh <= 999; kh++) cmbKhz.Items.Add(kh.ToString("000", inv));
            cmbKhz.MaxDropDownItems = 20;
            cmbKhz.Text = "000";
            cmbKhz.Width = S(65);
            cmbKhz.Anchor = AnchorStyles.Left;
            tip.SetToolTip(cmbKhz, Lang.T("kHz da sommare ai MHz: es. 144 MHz + 180 kHz = 144,180 MHz.\nÈ la frequenza CFOM usata per il Doppler e per le frequenze TX/RX."));
            cmbFreq.TextChanged += (s, e) => { UpdateLive(); FreqCambiata(); };
            cmbKhz.TextChanged += (s, e) => { UpdateLive(); FreqCambiata(); };
            chkRefr = new Spunta();
            chkRefr.Text = Lang.T("rifrazione");
            chkRefr.AutoSize = true;
            chkRefr.ForeColor = Tema.Muted;
            tip.SetToolTip(chkRefr, Lang.T("Correggi la rifrazione atmosferica") + "\u0001" + Lang.T("Senza spunta: elevazione geometrica topocentrica, come nei programmi EME più diffusi."));
            chkOnly = new Spunta();
