            chkOnly.ForeColor = Tema.Muted;
            chkOnly.Margin = new Padding(S(18), S(3), S(3), S(3));
            tip.SetToolTip(chkOnly, Lang.T("Mostra solo le righe puntabili (comuni, se c'è il DX)"));
            chkOnly.CheckedChanged += (s, e) => ApplyFilter();
            g3.Controls.Add(L(Lang.T("Inizio (UTC)")), 0, 0); g3.Controls.Add(dtp, 1, 0); g3.Controls.Add(btnNow, 2, 0);
            g3.SetColumnSpan(btnNow, 2);
            g3.Controls.Add(L(Lang.T("Durata")), 0, 1); g3.Controls.Add(nudDur, 1, 1);
            g3.Controls.Add(L(Lang.T("Intervallo")), 2, 1); g3.Controls.Add(nudStep, 3, 1);
            g3.Controls.Add(L(Lang.T("Frequenza")), 0, 2); g3.Controls.Add(cmbFreq, 1, 2);
            g3.Controls.Add(L("kHz"), 2, 2); g3.Controls.Add(cmbKhz, 3, 2);
            FlowLayoutPanel opzPer = new FlowLayoutPanel();
            opzPer.AutoSize = true; opzPer.AutoSizeMode = AutoSizeMode.GrowAndShrink; opzPer.WrapContents = false;
            opzPer.Margin = new Padding(0, S(4), 0, 0);
            opzPer.Controls.Add(chkRefr); opzPer.Controls.Add(chkOnly);
            g3.Controls.Add(opzPer, 0, 3); g3.SetColumnSpan(opzPer, 4);
            top.Controls.Add(SchedaCampi(Lang.T("Periodo e calcolo"), Color.FromArgb(91, 63, 168), g3, null), 2, 0);

            root.Controls.Add(top, 0, 0);

            // Pulsanti e posizione attuale
            TableLayoutPanel barT = new TableLayoutPanel();
            barT.AutoSize = true;
            barT.AutoSizeMode = AutoSizeMode.GrowAndShrink;
            barT.Dock = DockStyle.Fill;
            barT.ColumnCount = 2;
            barT.RowCount = 1;
            barT.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
            barT.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100f));
            barT.Margin = new Padding(0, S(4), 0, S(4));
            FlowLayoutPanel bar = new FlowLayoutPanel();
            bar.AutoSize = true;
            bar.AutoSizeMode = AutoSizeMode.GrowAndShrink;
            bar.WrapContents = false;
            bar.Margin = new Padding(S(4), 0, 0, 0);
            Pillola btnCalc = new Pillola("▶ " + Lang.T("Calcola tabella"), StilePillola.Pieno, Color.FromArgb(31, 111, 209), new Font(Lang.FontUi, 10F * fontFactor, FontStyle.Bold));
            btnCalc.Margin = new Padding(S(2), S(2), S(6), S(2));
            btnCalc.Click += (s, e) => Calcola();
            this.AcceptButton = btnCalc;
            Pillola btnCsv = new Pillola(Lang.T("Esporta CSV…"), StilePillola.Pieno, Color.FromArgb(75, 85, 99), new Font(Lang.FontUi, 9.5F * fontFactor));
            btnCsv.Margin = new Padding(S(4), S(2), S(6), S(2));
            btnCsv.Click += (s, e) => EsportaCsv();
            pnlLive = new PannelloDisegno();
            pnlLive.Dock = DockStyle.Fill;
            pnlLive.Margin = new Padding(S(10), 0, S(4), 0);
            pnlLive.Paint += DisegnaLive;
            bar.Controls.Add(btnCalc);
            bar.Controls.Add(btnCsv);
            btnColonne = new Pillola("", StilePillola.Pieno, Color.FromArgb(31, 111, 209), new Font(Lang.FontUi, 9.5F * fontFactor, FontStyle.Bold));
            btnColonne.Margin = new Padding(S(4), S(2), S(6), S(2));
            btnColonne.Click += (s, e) => ScegliColonne();
            tip.SetToolTip(btnColonne, Lang.T("Sceglie le colonne aggiuntive della tabella (da Data a MNR sono sempre visibili). La scelta viene salvata e vale anche per Esporta CSV. Le colonne aggiuntive si vedono con la casella CALCOLI APPROFONDITI."));
            bar.Controls.Add(btnColonne);
            TestoPulsanteColonne();
            barT.Controls.Add(bar, 0, 0);
            barT.Controls.Add(pnlLive, 1, 0);
            root.Controls.Add(barT, 0, 1);

            // Tabella + finestre utili
            split = new SplitContainer();
            split.Dock = DockStyle.Fill;
            split.Orientation = Orientation.Horizontal;

            lv = new DBListView();
            lv.Dock = DockStyle.Fill;
            lv.View = View.Details;
            lv.FullRowSelect = true;
            lv.GridLines = true;
            lv.HideSelection = false;
            lv.VirtualMode = true;
            lv.VirtualListSize = 0;
            lv.RetrieveVirtualItem += Lv_RetrieveVirtualItem;
            // intestazione disegnata: fondo azzurro, lucchetto sulle colonne sempre visibili (da Data a MNR)
            lv.OwnerDraw = true;
            lv.DrawItem += (s, e) => { e.DrawDefault = true; };
            lv.DrawSubItem += (s, e) => { e.DrawDefault = true; };
            lv.DrawColumnHeader += DisegnaTestataPos;
            headerTip = new HeaderToolTip(lv, col => (col >= 0 && col < visCols.Count) ? ColTip[visCols[col]] : null);
            split.Panel1.Controls.Add(lv);

