            txtWin.ScrollBars = ScrollBars.Both;
            txtWin.WordWrap = false;
            txtWin.Dock = DockStyle.Fill;
            txtWin.Font = new Font("Consolas", 9.5F);
            txtWin.BackColor = Tema.Field;
            gbWin.Controls.Add(txtWin);
            split.Panel2.Controls.Add(gbWin);
            root.Controls.Add(split, 0, 2);

            StatusStrip ss = new StatusStrip();
            lblStatus = new ToolStripStatusLabel(Lang.T("Imposta i parametri e premi \"Calcola tabella\"."));
            ss.Items.Add(lblStatus);

            tabs = new TabControl();
            tabs.Dock = DockStyle.Fill;
            tabs.DrawItem += Tabs_DrawItem;
            tpTrack = new TabPage(Lang.T("Posizione live e +- 24h"));
            BuildTrackTab(tpTrack);
            tpPos = new TabPage(Lang.T("Posizione della Luna"));
            tpPos.Controls.Add(root);
            tpBudget = new TabPage(Lang.T("Budget EME"));
            BuildBudgetTab(tpBudget);
            tpSolar = new TabPage(Lang.T("Rumore solare"));
            BuildSolarTab(tpSolar);
            tpSky = new TabPage(Lang.T("Volta celeste"));
            BuildSkyTab(tpSky);
            tpPunt = new TabPage(Lang.T("Ricognizione dei miei ostacoli"));
            BuildPuntTab(tpPunt);
            tpDgrd = new TabPage(Lang.T("Distanza e Dgrd"));
            BuildDgrdTab(tpDgrd);
            tpMondo = new TabPage(Lang.T("Luna sul mondo"));
            tpMap = new TabPage(Lang.T("Mappa WWL e ADIF"));
            BuildMapTab(tpMap);
            tpAbout = new TabPage(Lang.T("INFORMAZIONI E CREDITI"));
            BuildAboutTab(tpAbout);
            tpCavi = new TabPage(Lang.T("CAVI COASSIALI"));
            BuildCaviTab(tpCavi);
            tpContatti = new TabPage(Lang.T("CONTATTI DELL'AUTORE E RINGRAZIAMENTI"));
            BuildContattiTab(tpContatti);
            tpLicenza = new TabPage(Lang.T("LICENZA D'USO"));
            BuildLicenzaTab(tpLicenza);
            tpIstr = new TabPage(Lang.T("MANUALE D'USO"));
            tpEme = new TabPage(Lang.T("TEORIA E CONSIGLI SULL'EME"));
            tpExcel = new TabPage(Lang.T("Export in Excel dei calcoli"));
            BuildExcelTab(tpExcel);
            tpDebug = new TabPage(Lang.T("Controllo dei calcoli"));
            BuildDebugTab(tpDebug);
            foreach (TabPage tpx in new TabPage[] { tpTrack, tpDgrd, tpSky, tpPunt, tpPos, tpMondo, tpBudget, tpSolar, tpMap, tpAbout, tpIstr, tpEme, tpExcel, tpDebug, tpCavi, tpContatti, tpLicenza })
                tabs.TabPages.Add(tpx);
            BuildMondoTab(tpMondo);   // dopo che tabs esiste: segue il cambio di linguetta
            BuildManualeTab(tpIstr, false);   // dopo le altre linguette: il manuale ne mostra le schermate
            BuildManualeTab(tpEme, true);
            CostruisciNav();
            tabs.Selecting += (s, e) =>
            {
                if (e.TabPage == tpSolar && !complessi)
                {
                    e.Cancel = true;
                    Messaggio(this, Lang.T("La linguetta Rumore solare si attiva con la casella \"CALCOLI APPROFONDITI\" nella linguetta Posizione live e +- 24h."),
                        "YAEC", MessageBoxButtons.OK, MessageBoxIcon.Information);
                }
                else if (e.TabPage == tpDebug && !complessi)
                {
                    e.Cancel = true;
                    Messaggio(this, Lang.T("La linguetta Controllo dei calcoli si attiva con la casella \"CALCOLI APPROFONDITI\" nella linguetta Posizione live e +- 24h."),
                        "YAEC", MessageBoxButtons.OK, MessageBoxIcon.Information);
                }
                else if (e.TabPage == tpExcel && !complessi)
                {
                    e.Cancel = true;
                    Messaggio(this, Lang.T("La linguetta Export in Excel dei calcoli si attiva con la casella \"CALCOLI APPROFONDITI\" nella linguetta Posizione live e +- 24h."),
                        "YAEC", MessageBoxButtons.OK, MessageBoxIcon.Information);
                }
            };
            tabs.SelectedIndexChanged += (s, e) =>
            {
                TabPage sel = tabs.SelectedTab;
                if (sel == tpTrack) AggiornaTracciamento(true);
                if (sel == tpSolar) AggiornaTabellaSfu();
                if (sel == tpSky) RecalcSky();
                if (sel == tpDgrd) RecalcDgrd();
                if (sel == tpMap) map.Invalidate();
                if (sel == tpPunt) pnlPunt.Invalidate();
                if (sel == tpBudget || sel == tpSolar) RecalcBudget();
                if (sel == tpExcel) RiempiExcel();
                if (sel == tpDebug) RiempiDebug();
            };

            this.Controls.Add(tabs);
            this.Controls.Add(ss);
            this.Controls.Add(pnlNav);

            SetupColumns(true);
        }

        void SetupColumns(bool withDx)
        {
            lv.BeginUpdate();
            lv.Columns.Clear();
            visCols.Clear();
            for (int i = 0; i < ColTitle.Length; i++)
            {
                if (ColDx[i] && !withDx) continue;
                if (i >= ColFisse && (!complessi || !colScelte[i])) continue;   // aggiuntive: scelte con "Colonne" e solo con "CALCOLI APPROFONDITI"
                ColumnHeader ch = lv.Columns.Add(ColTitle[i], S(ColWidth[i]));
                if (ColRight[i]) ch.TextAlign = HorizontalAlignment.Right;
                visCols.Add(i);
            }
            lv.EndUpdate();
        }

        void EnableDx()
        {
            bool on = chkDx.Checked;
            foreach (Control c in new Control[] { dx.Loc, dx.H, dx.Az1, dx.Az2, dx.El1, dx.El2, dx.Coord })
                c.Enabled = on;
            UpdateLocators();
        }

        static DateTime NowUtcMinute()
        {
            DateTime n = DateTime.UtcNow;
            return new DateTime(n.Year, n.Month, n.Day, n.Hour, n.Minute, 0, DateTimeKind.Unspecified);
        }

        // ---------- Logica ----------

        void ParseStation(StationUi st)
        {
            double la, lo;
            st.Ok = Locator.TryParse(st.Loc.Text, out la, out lo);
            if (st.Ok) { st.Lat = la; st.Lon = lo; }
        }

        string CoordText(StationUi st)
        {
            return string.Format(ci, "Lat {0:F3}° {1}   Lon {2:F3}° {3}",
                Math.Abs(st.Lat), st.Lat >= 0 ? "N" : "S", Math.Abs(st.Lon), st.Lon >= 0 ? "E" : "W");
        }

        static double GreatCircleKm(double la1, double lo1, double la2, double lo2)
        {
            double r = Math.PI / 180.0;
            double a = Math.Sin((la2 - la1) * r / 2);
            double b = Math.Sin((lo2 - lo1) * r / 2);
            double h = a * a + Math.Cos(la1 * r) * Math.Cos(la2 * r) * b * b;
            return 2 * 6371.0 * Math.Asin(Math.Min(1.0, Math.Sqrt(h)));
        }

        void UpdateLocators()
        {
            ParseStation(me);
            ParseStation(dx);
            if (me.Ok) { me.Coord.ForeColor = Tema.Fore; me.Coord.Text = CoordText(me); }
            else { me.Coord.ForeColor = Color.Firebrick; me.Coord.Text = Lang.T("Locator non valido"); }
            if (dx.Ok)
            {
                dx.Coord.ForeColor = Tema.Fore;
                string t = CoordText(dx);
                if (me.Ok) t += string.Format(ci, Lang.T("   Distanza {0:N0} km"), GreatCircleKm(me.Lat, me.Lon, dx.Lat, dx.Lon));
                dx.Tz = FusiOrari.Trova(dx.Lat, dx.Lon, out dx.TzNome, out dx.TzStimato);
                DateTime adesso = DateTime.UtcNow;
                TimeSpan off = dx.Tz.GetUtcOffset(adesso);
                t += Lang.T("\nFuso: ") + dx.TzNome + string.Format(ci, "  (UTC{0}{1:00}:{2:00}", off < TimeSpan.Zero ? "-" : "+",
                    Math.Abs(off.Hours), Math.Abs(off.Minutes)) + (dx.Tz.IsDaylightSavingTime(adesso) ? Lang.T(", ora legale") : "")
                    + Lang.T(")   ora locale ") + TimeZoneInfo.ConvertTimeFromUtc(adesso, dx.Tz).ToString("HH:mm", inv);
                dx.Coord.Text = t;
            }
            else
            {
                string c3, g3 = ProponiCall3(dx.Loc.Text, out c3);
                if (g3 != null) { dx.Coord.ForeColor = Tema.OkFg; dx.Coord.Text = string.Format(Lang.T("{0} nel CALL3.TXT: {1} (premi Invio per usarlo)"), c3, g3); }
                else { dx.Coord.ForeColor = Color.Firebrick; dx.Coord.Text = Lang.T("Locator non valido"); }
            }
            string gc;
            if (dx.Ok && txtDxCall != null && StatoCall3(out gc) == 1)
            {
                int k = dx.Coord.Text.IndexOf('\n');
                dx.Coord.Text = k < 0 ? dx.Coord.Text + Lang.T(" · locator dal CALL3.TXT") : dx.Coord.Text.Substring(0, k) + Lang.T(" · locator dal CALL3.TXT") + dx.Coord.Text.Substring(k);
            }
        }

        // Cerca la linguetta con quel titolo (anche dentro le macro linguette) e la apre
        static bool ApriLinguettaPerNome(Control c, string nome)
        {
            foreach (Control x in c.Controls)
            {
                TabControl tc = x as TabControl;
                if (tc != null)
                    foreach (TabPage tp in tc.TabPages)
                    {
                        if (string.Equals(tp.Text.Trim(), nome, StringComparison.OrdinalIgnoreCase) || ApriLinguettaPerNome(tp, nome))
                        {
                            tc.SelectedTab = tp;
                            return true;
                        }
                    }
                else if (ApriLinguettaPerNome(x, nome)) return true;
            }
            return false;
        }

        // Se il testo non è un locator ma un nominativo presente nel CALL3.TXT, il locator da proporre
        static string ProponiCall3(string testo, out string call)
        {
            call = null;
            double la, lo;
            string t = (testo ?? "").Trim();
            if (t.Length < 3 || Locator.TryParse(t, out la, out lo)) return null;
            return Call3.Cerca(t, out call);
        }

        // Stato del nominativo del DX rispetto al CALL3.TXT: 0 = nessun nominativo o elenco vuoto, 1 = locator uguale
        // a quello dell'elenco, 2 = l'elenco indica un altro locator, 3 = nominativo non presente nell'elenco
        int StatoCall3(out string grid)
        {
            grid = null;
            if (txtDxCall == null) return 0;
            string call = txtDxCall.Text.Trim(), c;
            if (call.Length < 3) return 0;
            grid = Call3.Cerca(call, out c);
            if (grid == null) return Call3.Conteggio > 0 ? 3 : 0;
            string loc = dx.Loc.Text.Trim().ToUpperInvariant();
            if (loc.Length >= 4 && (loc.StartsWith(grid, StringComparison.Ordinal) || grid.StartsWith(loc, StringComparison.Ordinal))) return 1;
            return 2;
        }

        // Locator dal CALL3.TXT per il nominativo scritto: si mette se la casella è vuota o conteneva il locator
        // del nominativo precedente (cioè non scritto a mano); con forza = true (Invio) si mette sempre
        void LocatorDaNominativo(bool forza)
        {
            string call = txtDxCall.Text.Trim(), c, cp;
            string g = call.Length >= 3 ? Call3.Cerca(call, out c) : null;
            string gPrec = dxCallPrec.Length >= 3 ? Call3.Cerca(dxCallPrec, out cp) : null;
            dxCallPrec = call;
            if (g == null) return;
            string loc = dx.Loc.Text.Trim().ToUpperInvariant();
            bool daElenco = gPrec != null && loc.Length >= 4 && (loc.StartsWith(gPrec, StringComparison.Ordinal) || gPrec.StartsWith(loc, StringComparison.Ordinal));
            if (forza || loc.Length == 0 || daElenco) dx.Loc.Text = g;
        }

        // Casella del nominativo del DX: le due caselle (schermata principale e Posizione della Luna) restano uguali
        // Stazione attiva negli ultimi 90 giorni secondo la chat EME di N0UK (elenco in data/attivi.gz)
        bool dxAttivo;
        static readonly Color ColAttivo = Color.FromArgb(234, 88, 12);
        System.Windows.Forms.Timer tmrAttivi;

        void AggiornaAttivo()
        {
            if (txtDxCall == null) return;
            DateTime ultimo;
            bool att = Attivi.Cerca(txtDxCall.Text, out ultimo);
            string corpo = Lang.T("Se il nominativo è nel CALL3.TXT il locator si riempie da solo. Se il locator l'hai scritto tu e il CALL3.TXT ne indica un altro, premi Invio sul nominativo per usare quello del CALL3.TXT.");
            if (att)
            {
                string pat = System.Text.RegularExpressions.Regex.Replace(Lang.Cultura.DateTimeFormat.ShortDatePattern, "[^dM]*y+[^dM]*", "").Trim();
                if (pat.Length == 0 || pat.IndexOf('d') < 0 || pat.IndexOf('M') < 0) pat = "dd/MM";
                string riga = string.Format(Lang.Cultura, Lang.T("Stazione attiva negli ultimi 90 giorni (chat EME di N0UK), ultimo messaggio il {0}"), ultimo.ToString(pat, Lang.Cultura));
                corpo = riga + "\n\n" + corpo;
            }
            string testo = Lang.T("Nominativo del DX") + "\u0001" + corpo;
            foreach (TextBox tb in new TextBox[] { txtDxCall, txtTrkDxCall })
                if (tb != null && tip.GetToolTip(tb) != testo) tip.SetToolTip(tb, testo);
            if (att == dxAttivo) return;
            dxAttivo = att;
            if (txtDxCall.Parent != null) txtDxCall.Parent.Invalidate();
            if (cardDx != null) cardDx.Invalidate();
        }

        // L'elenco si aggiorna in sottofondo: all'avvio e poi ogni volta che ha più di 20 ore
        void AvviaAttivi()
        {
            if (tmrAttivi != null) return;
            tmrAttivi = new System.Windows.Forms.Timer();
            tmrAttivi.Interval = 15000;
            tmrAttivi.Tick += (s, e) =>
            {
                tmrAttivi.Interval = 30 * 60 * 1000;
                AggiornaAttivo();
                if (!Attivi.DaAggiornare) return;
                System.Threading.ThreadPool.QueueUserWorkItem(_ =>
                {
                    if (!Attivi.Aggiorna()) return;
                    try { if (IsHandleCreated && !IsDisposed) BeginInvoke(new Action(AggiornaAttivo)); } catch { }
                });
            };
            tmrAttivi.Start();
            Disposed += (s, e) => tmrAttivi.Dispose();
        }

        void AgganciaNominativo(TextBox tb)
        {
            tb.TextChanged += (s, e) =>
            {
                if (syncCall) return;
                syncCall = true;
                if (txtDxCall != null && tb != txtDxCall) txtDxCall.Text = tb.Text;
                if (txtTrkDxCall != null && tb != txtTrkDxCall) txtTrkDxCall.Text = tb.Text;
                syncCall = false;
                if (txtDxCall == null) return;
                AggiornaAttivo();
                if (caricamento) return;
                LocatorDaNominativo(false);
                UpdateLocators();
                if (cardDx != null) { AggiornaTracciamento(false); cardDx.Invalidate(); }
                if (pnlMondo != null) pnlMondo.Invalidate();
            };
            tb.PreviewKeyDown += (s, e) => { if (e.KeyCode == Keys.Enter) e.IsInputKey = true; };
            tb.KeyDown += (s, e) =>
            {
                if (e.KeyCode != Keys.Enter) return;
                e.Handled = true; e.SuppressKeyPress = true;
                if (txtDxCall == null) return;
                LocatorDaNominativo(true);
                UpdateLocators();
                if (cardDx != null) { AggiornaTracciamento(false); cardDx.Invalidate(); }
            };
        }

        // Invio in una casella del locator del DX: se contiene un nominativo del CALL3.TXT, il nominativo va
        // nella sua casella e il locator al suo posto
        void AgganciaCall3(TextBox tb)
        {
            tb.PreviewKeyDown += (s, e) =>
            {
                string c;
                if (e.KeyCode == Keys.Enter && ProponiCall3(tb.Text, out c) != null) e.IsInputKey = true;
            };
            tb.KeyDown += (s, e) =>
            {
                if (e.KeyCode != Keys.Enter) return;
                string c, g = ProponiCall3(tb.Text, out c);
                if (g == null) return;
                e.Handled = true; e.SuppressKeyPress = true;
                tb.Text = g;
                tb.SelectionStart = tb.Text.Length;
                if (txtDxCall != null) { caricamento = true; try { txtDxCall.Text = c; } finally { caricamento = false; } dxCallPrec = c; UpdateLocators(); }
            };
        }

        // Finestra del CALL3.TXT: stato del file, aggiornamento dalle due fonti, copia nella cartella di WSJT-X
        void FinestraCall3()
        {
            using (Form f = new Form())
            {
                f.Text = "CALL3.TXT";
                f.FormBorderStyle = FormBorderStyle.FixedDialog;
                f.MaximizeBox = false; f.MinimizeBox = false; f.ShowInTaskbar = false;
                f.StartPosition = FormStartPosition.CenterParent;
                TableLayoutPanel t = new TableLayoutPanel(); t.AutoSize = true; t.ColumnCount = 1; t.Padding = new Padding(S(14));
                Label info = new Label(); info.AutoSize = true; info.MaximumSize = new Size(S(520), 0); info.Margin = new Padding(0, 0, 0, S(10));
                info.Text = Lang.T("Il CALL3.TXT è l'elenco dei nominativi delle stazioni EME con il loro locator, usato anche da WSJT-X. YAEC scarica sia la lista di W7GJ sia quella distribuita con WSJT-X Improved: se una delle due non risponde usa l'altra, se rispondono entrambe le fonde per nominativo (a parità di nominativo vale il locator di W7GJ). Il file si aggiorna da solo all'avvio quando ha più di 7 giorni.");
                Label stato = new Label(); stato.AutoSize = true; stato.MaximumSize = new Size(S(520), 0); stato.Font = new Font(Lang.FontUi, 10F, FontStyle.Bold);
                Label fonti = new Label(); fonti.AutoSize = true; fonti.MaximumSize = new Size(S(520), 0); fonti.ForeColor = Tema.Muted; fonti.Margin = new Padding(0, S(4), 0, S(4));
                Label esito = new Label(); esito.AutoSize = true; esito.MaximumSize = new Size(S(520), 0); esito.MinimumSize = new Size(S(520), S(44)); esito.Margin = new Padding(0, S(6), 0, 0);
                Label wsj = new Label(); wsj.AutoSize = true; wsj.MaximumSize = new Size(S(520), 0); wsj.ForeColor = Tema.Muted; wsj.Margin = new Padding(0, S(10), 0, 0);
                Action rinfresca = () =>
                {
                    DateTime d = Call3.DataFile;
                    stato.Text = d == DateTime.MinValue ? Lang.T("Nessun CALL3.TXT nella cartella data.")
                        : string.Format(ci, Lang.T("{0:N0} nominativi, file del {1}"), Call3.Conteggio, d.ToString("dd/MM/yyyy HH:mm", inv));
                    fonti.Text = Call3.Fonti[0][0] + ": " + (Call3.Esito[0].Length > 0 ? Call3.Esito[0] : "—") + "\n"
                        + Call3.Fonti[1][0] + ": " + (Call3.Esito[1].Length > 0 ? Call3.Esito[1] : "—");
                    string cw = Call3.CartellaWsjtx();
                    wsj.Text = Lang.T("Cartella di WSJT-X: ") + cw + (Directory.Exists(cw) ? "" : Lang.T("  (non trovata)"));
                };
                rinfresca();
                t.Controls.Add(info); t.Controls.Add(stato); t.Controls.Add(fonti); t.Controls.Add(esito); t.Controls.Add(wsj);
                Button agg = new Pulsante(); agg.Text = Lang.T("Aggiorna ora");
                Button cop = new Pulsante(); cop.Text = Lang.T("Copia in WSJT-X");
                Button chiudi = new Pulsante(); chiudi.Text = Lang.T("Chiudi"); chiudi.DialogResult = DialogResult.Cancel;
                agg.Click += (s, e) =>
                {
                    agg.Enabled = false; cop.Enabled = false;
                    esito.ForeColor = Tema.Fore;
                    esito.Text = Lang.T("Scaricamento da W7GJ e WSJT-X Improved…");
                    DateTime primaC3 = Call3.DataFile;
                    System.Threading.Thread th = new System.Threading.Thread(() =>
                    {
                        string m = Call3.Aggiorna(true);
                        try
                        {
                            f.BeginInvoke((Action)(() =>
                            {
                                esito.Text = m; agg.Enabled = true; cop.Enabled = true; rinfresca();
                                UpdateLocators(); AggiornaTracciamento(true);
                                // aggiornamento ottenuto: la finestra si chiude da sola dopo un attimo (il tempo di leggere l'esito)
                                if (Call3.DataFile > primaC3)
                                {
                                    esito.ForeColor = Tema.OkFg;
                                    Timer tc = new Timer(); tc.Interval = 1500;
                                    tc.Tick += (s2, e2) => { tc.Stop(); tc.Dispose(); if (!f.IsDisposed) f.Close(); };
                                    tc.Start();
                                }
                            }));
                        }
                        catch { }
                    });
                    th.IsBackground = true;
                    th.Start();
                };
                cop.Click += (s, e) =>
                {
                    if (!File.Exists(Call3.Percorso)) { esito.ForeColor = Tema.BadFg; esito.Text = Lang.T("Prima scarica il CALL3.TXT con Aggiorna ora."); return; }
                    string cw = Call3.CartellaWsjtx();
                    if (!Directory.Exists(cw))
                        using (FolderBrowserDialog fb = new FolderBrowserDialog())
                        {
                            fb.Description = Lang.T("Cartella di WSJT-X non trovata: scegli dove copiare il CALL3.TXT (in WSJT-X: File > Open log directory).");
                            if (fb.ShowDialog(f) != DialogResult.OK) return;
                            cw = fb.SelectedPath;
                        }
                    try
                    {
                        string dest = Path.Combine(cw, Call3.Nome);
                        if (File.Exists(dest))
                        {
                            string bak = Path.Combine(cw, "CALL3.TXT.bak");
                            File.Copy(dest, bak, true);
                        }
                        File.Copy(Call3.Percorso, dest, true);
                        esito.ForeColor = Tema.OkFg;
                        esito.Text = Lang.T("Copiato in ") + dest + Lang.T("  (il file precedente è in CALL3.TXT.bak). Riavvia WSJT-X per usarlo.");
                    }
                    catch (Exception ex) { esito.ForeColor = Tema.BadFg; esito.Text = Lang.T("Copia non riuscita: ") + ex.Message; }
                };
                StileDialogo(f, t, chiudi, cop, agg);
                f.CancelButton = chiudi;
                f.ShowDialog(this);
            }
        }

        // Frequenza di lavoro = MHz + kHz/1000
        bool ReadFreq(out double f)
        {
            string t = cmbFreq.Text.Trim().Replace(',', '.');
            if (!double.TryParse(t, NumberStyles.Float, inv, out f) || f < 10 || f > 200000) return false;
            string k = cmbKhz == null ? "" : cmbKhz.Text.Trim().Replace(',', '.');
            double kh = 0;
            if (k.Length > 0 && (!double.TryParse(k, NumberStyles.Float, inv, out kh) || kh < 0 || kh >= 1000)) return false;
            f += kh / 1000.0;
            return true;
        }

        // Doppler di sola andata stazione-Luna (Hz): -f·(dR/dt)/c, con dR/dt per differenza su ±30 s
        static double Doppler1(DateTime utc, StationUi st, double freqMHz)
        {
            double h = (double)st.H.Value;
            double d1 = Moon.Compute(utc.AddSeconds(-30), st.Lat, st.Lon, h, false).DistTopo;
            double d2 = Moon.Compute(utc.AddSeconds(30), st.Lat, st.Lon, h, false).DistTopo;
            double vr = (d2 - d1) / 60.0;   // km/s, positivo = la Luna si allontana
            return -freqMHz * 1e6 * vr / 299792.458;
        }

        static string Hz(double v, CultureInfo c)
        {
            return (v >= 0 ? "+" : "") + v.ToString("F0", c);
        }

        Riga Calcola1(DateTime utc, bool useDx, double freq, bool refr)
        {
            Riga r = new Riga();
            r.Utc = utc;
            r.P = Moon.Compute(utc, me.Lat, me.Lon, (double)me.H.Value, refr);
            r.StatoMe = me.Valuta(r.P, out r.OkMe);
            r.Tsky = Moon.Tsky(r.P.Lambda, freq);
            r.DgrdMe = Moon.Dgrd(r.P.Lambda, r.P.DistTopo, freq);
            r.Ok = r.OkMe;
            r.DopMe = Doppler1(utc, me, freq);
            if (useDx)
            {
                r.DopDx = Doppler1(utc, dx, freq);
                r.Q = Moon.Compute(utc, dx.Lat, dx.Lon, (double)dx.H.Value, refr);
                r.StatoDx = dx.Valuta(r.Q, out r.OkDx);
                r.DgrdDx = Moon.Dgrd(r.Q.Lambda, r.Q.DistTopo, freq);
                double p1 = Moon.PolAngle(me.Lat, r.P.Az, r.P.ElGeo);
                double p2 = Moon.PolAngle(dx.Lat, r.Q.Az, r.Q.ElGeo);
                r.Dpol = Moon.PolOffset(p1, p2);
                r.PolLoss = Moon.PolLoss(r.Dpol);
                r.Mnr = Moon.Mnr(r.Dpol);
                r.Ok = r.OkMe && r.OkDx;
            }
            return r;
        }

        void UpdateLive()
        {
            livePill.Clear();
            if (me.Ok)
            {
                double f;
                if (!ReadFreq(out f)) f = 144;
                bool useDx = chkDx.Checked && dx.Ok;
                Riga r = Calcola1(DateTime.UtcNow, useDx, f, chkRefr.Checked);
                livePill.Add(new string[] { "", r.Utc.ToString("ddd dd/MM HH:mm", Lang.Cultura) + " UTC", "" });
                livePill.Add(new string[] { Lang.T("io"), string.Format(ci, "Az {0:F1}° El {1:F1}°", r.P.Az, r.P.El), r.OkMe ? "ok" : "" });
                livePill.Add(new string[] { "Dgrd", r.DgrdMe.ToString("F2", ci).Replace("-", "−") + " dB", "" });
                if (useDx)
                {
                    livePill.Add(new string[] { "DX", string.Format(ci, "Az {0:F1}° El {1:F1}°", r.Q.Az, r.Q.El), r.OkDx ? "ok" : "" });
                    livePill.Add(new string[] { "Dpol", r.Dpol.ToString("F0", ci).Replace("-", "−") + "°", "" });
                    if (r.Ok) livePill.Add(new string[] { "", Lang.T("FINESTRA COMUNE"), "ok" });
                }
                else if (r.OkMe) livePill.Add(new string[] { "", Lang.T("PUNTABILE"), "ok" });
                livePill.Add(new string[] { "CFOM", "TX " + (f - r.DopMe / 1e6).ToString("F6", ci) + " / RX " + (f + r.DopMe / 1e6).ToString("F6", ci), "" });
            }
            if (pnlLive != null) pnlLive.Invalidate();
        }

        // Pastiglie bianche a destra della barra: istante, posizione della Luna, Dgrd, DX, Dpol, CFOM
        void DisegnaLive(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            PreparaGrafica(g);
            g.Clear(Tema.Back);
            Rectangle cr = pnlLive.ClientRectangle;
            using (Font fr = FontPx(Lang.FontUi, S(12.5f), false))
            using (Font fb = FontPx(Lang.FontUi, S(12.5f), true))
            using (StringFormat tg = (StringFormat)StringFormat.GenericTypographic.Clone())
            {
                tg.FormatFlags |= StringFormatFlags.MeasureTrailingSpaces | StringFormatFlags.NoWrap;
                float h = Math.Min(cr.Height - S(4), S(28)), y = (cr.Height - h) / 2f, x = cr.Right - S(2);
                for (int i = livePill.Count - 1; i >= 0; i--)
                {
                    string[] pz = livePill[i];
                    float w1 = pz[0].Length > 0 ? g.MeasureString(pz[0] + " ", fr, PointF.Empty, tg).Width : 0;
                    float w2 = g.MeasureString(pz[1], fb, PointF.Empty, tg).Width;
                    float w = w1 + w2 + S(24);
                    if (x - w < cr.Left) break;   // non c'è posto: le prime restano fuori
                    RectangleF r = new RectangleF(x - w, y, w, h);
                    bool ok = pz[2] == "ok";
                    using (GraphicsPath p = Arrotondato(r, h / 2f))
                    {
                        using (Brush b = new SolidBrush(ok ? (Tema.Scuro ? Tema.OkBg : Color.FromArgb(227, 244, 232)) : Tema.Carta)) g.FillPath(b, p);
                        using (Pen pn = new Pen(ok ? Tema.OkFg : (Tema.Scuro ? Tema.Linea : Color.FromArgb(210, 216, 226)))) g.DrawPath(pn, p);
                    }
                    float ty = y + (h - fb.Height) / 2f + S(1);
                    using (Brush bt = new SolidBrush(Tema.Fore)) g.DrawString(pz[0] + " ", fr, bt, r.Left + S(12), ty, tg);
                    using (Brush bv = new SolidBrush(ok ? Tema.OkFg : Tema.Fore)) g.DrawString(pz[1], fb, bv, r.Left + S(12) + w1, ty, tg);
                    x -= w + S(8);
                }
            }
        }

        void Calcola()
        {
            if (!me.Ok)
            {
                Messaggio(this, Lang.T("Il locator della tua stazione non è valido.\nUsa da 4 a 14 caratteri, es. JN70CN."),
                    "YAEC", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                me.Loc.Focus();
                return;
            }
            bool useDx = chkDx.Checked;
            if (useDx && !dx.Ok)
            {
                Messaggio(this, Lang.T("Il locator della stazione DX non è valido.\nCorreggilo oppure togli la spunta \"Confronta con la seconda stazione\"."),
                    "YAEC", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                dx.Loc.Focus();
                return;
            }
            if (me.El1.Value > me.El2.Value || (useDx && dx.El1.Value > dx.El2.Value))
            {
                Messaggio(this, Lang.T("L'elevazione minima è maggiore della massima."), "YAEC",
                    MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }
            double freq;
            if (!ReadFreq(out freq))
            {
                Messaggio(this, Lang.T("Frequenza non valida: inserisci i MHz (es. 144) e i kHz (da 0 a 999, es. 180)."), "YAEC",
                    MessageBoxButtons.OK, MessageBoxIcon.Warning);
                cmbFreq.Focus();
                return;
            }
            DateTime start = DateTime.SpecifyKind(dtp.Value, DateTimeKind.Utc);
            start = new DateTime(start.Year, start.Month, start.Day, start.Hour, start.Minute, 0, DateTimeKind.Utc);
            double durMin = (double)nudDur.Value * 1440.0;
            int step = (int)nudStep.Value;
            int n = (int)Math.Floor(durMin / step) + 1;
            if (n > 200000)
            {
                Messaggio(this, Lang.T("Troppe righe (") + n.ToString("N0", ci) + Lang.T("). Aumenta l'intervallo o riduci la durata."),
                    "YAEC", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            Cursor = Cursors.WaitCursor;
            try
            {
                bool refr = chkRefr.Checked;
                tutte = new List<Riga>(n);
                for (int i = 0; i < n; i++)
                    tutte.Add(Calcola1(start.AddMinutes((double)i * step), useDx, freq, refr));
                calcDx = useDx;
                calcFreq = freq;
                calcTzDx = dx.Tz;
                SetupColumns(useDx);
                ApplyFilter();
                txtWin.Text = Finestre(step);
                SaveSettings();
            }
            finally
            {
                Cursor = Cursors.Default;
            }
        }

        void ApplyFilter()
        {
            if (chkOnly.Checked)
            {
                mostrate = new List<Riga>();
                foreach (Riga r in tutte) if (r.Ok) mostrate.Add(r);
            }
            else mostrate = tutte;
            lv.SelectedIndices.Clear();
            lv.VirtualListSize = mostrate.Count;
            lv.Invalidate();
            int nOk = 0;
            foreach (Riga r in tutte) if (r.Ok) nOk++;
            if (tutte.Count > 0)
                lblStatus.Text = string.Format(ci, Lang.T("{0:N0} righe calcolate, {1:N0} {2} ({3:F0}%).   Frequenza {4} MHz"),
                    tutte.Count, nOk, calcDx ? Lang.T("con la Luna puntabile da entrambe le stazioni") : Lang.T("con la Luna puntabile"),
                    100.0 * nOk / tutte.Count, calcFreq.ToString("0.###", ci));
        }

        // Tutti i valori della riga, nell'ordine di ColTitle
        string[] Valori(Riga r, string fmtAng)
        {
            DateTime loc = TimeZoneInfo.ConvertTimeFromUtc(r.Utc, TimeZoneInfo.Local);
            string[] v = new string[ColTitle.Length];
            for (int i = 0; i < v.Length; i++) v[i] = "";
            v[0] = FmtWD(r.Utc);
            v[1] = FmtT(r.Utc);
            v[2] = FmtT(loc);
            v[3] = r.P.Az.ToString(fmtAng, ci);
            v[4] = r.P.El.ToString(fmtAng, ci);
            if (calcDx)
            {
                v[5] = r.Q.Az.ToString(fmtAng, ci);
                v[6] = r.Q.El.ToString(fmtAng, ci);
                v[7] = FmtT(TimeZoneInfo.ConvertTimeFromUtc(r.Utc, calcTzDx));
                v[8] = r.Dpol.ToString("F0", ci);
                v[9] = r.PolLoss.ToString("F1", ci);
                v[10] = r.Mnr.ToString("F1", ci);
                v[13] = r.DgrdDx.ToString("F1", ci);
                v[16] = Hz(r.DopDx, ci);
                v[17] = Hz(r.DopMe + r.DopDx, ci);
            }
            v[11] = r.Tsky.ToString("F0", ci);
            v[12] = r.DgrdMe.ToString("F1", ci);
            v[14] = Hz(r.DopMe, ci);
            v[15] = Hz(2 * r.DopMe, ci);
            v[18] = (calcFreq - r.DopMe / 1e6).ToString("F6", ci);
            v[19] = (calcFreq + r.DopMe / 1e6).ToString("F6", ci);
            v[20] = r.P.Dec.ToString("F2", ci);
            v[21] = r.P.Ha.ToString("F1", ci);
            v[22] = r.P.DistTopo.ToString("N0", ci);
            if (calcDx) v[23] = r.Q.DistTopo.ToString("N0", ci);
            double saz, sel, sra, sdec;
            Moon.SunPos(r.Utc, me.Lat, me.Lon, out saz, out sel, out sra, out sdec);
            double el = Moon.Separation(sra, sdec, r.P.Ra, r.P.Dec);
            v[24] = el.ToString("F1", ci);
            v[25] = ((1 - Math.Cos(el * Math.PI / 180.0)) / 2.0 * 100.0).ToString("F0", ci);
            return v;
        }

        void Lv_RetrieveVirtualItem(object sender, RetrieveVirtualItemEventArgs e)
        {
            int nc = Math.Max(1, visCols.Count);
            if (e.ItemIndex < 0 || e.ItemIndex >= mostrate.Count)
            {
                ListViewItem empty = new ListViewItem("");
                for (int i = 1; i < nc; i++) empty.SubItems.Add("");
                e.Item = empty;
                return;
            }
            Riga r = mostrate[e.ItemIndex];
            string[] v = Valori(r, "F1");
            ListViewItem it = new ListViewItem(v[visCols[0]]);
            for (int i = 1; i < visCols.Count; i++) it.SubItems.Add(v[visCols[i]]);
            if (r.Ok) it.BackColor = colOk;
            else if (calcDx && (r.OkMe || r.OkDx)) it.BackColor = colSolo;
            else if (r.P.El < 0) it.ForeColor = colSotto;
            e.Item = it;
        }

        string Finestre(int step)
        {
            StringBuilder sb = new StringBuilder();
            if (calcDx)
                sb.AppendLine(Lang.T("Finestre COMUNI: Luna dentro i limiti di puntamento di entrambe le stazioni."));
            else
                sb.AppendLine(Lang.T("Finestre con la Luna dentro i limiti di puntamento della tua antenna."));
            sb.AppendLine();
            int count = 0;
            int i = 0;
            while (i < tutte.Count)
            {
                if (!tutte[i].Ok) { i++; continue; }
                int a = i;
                int best = i;
                while (i < tutte.Count && tutte[i].Ok)
                {
                    double vb = calcDx ? Math.Min(tutte[best].P.El, tutte[best].Q.El) : tutte[best].P.El;
                    double vi = calcDx ? Math.Min(tutte[i].P.El, tutte[i].Q.El) : tutte[i].P.El;
                    if (vi > vb) best = i;
                    i++;
                }
                int b = i - 1;
                count++;
                Riga ra = tutte[a], rb = tutte[b], rm = tutte[best];
                TimeSpan dur = rb.Utc - ra.Utc;
                string note = "";
                if (a == 0) note += Lang.T("  [già in corso all'inizio]");
                if (b == tutte.Count - 1) note += Lang.T("  [continua oltre la fine]");
                sb.AppendFormat(ci, Lang.T("{0,2}) {1} → {2} UTC   durata {3,2} h {4:00} min{5}"),
                    count, FmtDT(ra.Utc), FmtDT(rb.Utc), (int)dur.TotalHours, dur.Minutes, note);
                sb.AppendLine();
                sb.AppendFormat(ci, Lang.T("    Io: Az {0,5:F1}° → {1,5:F1}°   El max {2,4:F1}°   Dgrd {3,5:F1} dB"),
                    ra.P.Az, rb.P.Az, MaxEl(a, b, false), rm.DgrdMe);
                sb.AppendLine();
                if (calcDx)
                {
                    sb.AppendFormat(ci, Lang.T("    DX: Az {0,5:F1}° → {1,5:F1}°   El max {2,4:F1}°   Dgrd {3,5:F1} dB"),
                        ra.Q.Az, rb.Q.Az, MaxEl(a, b, true), rm.DgrdDx);
                    sb.AppendLine();
                    sb.AppendFormat(ci, Lang.T("    Dpol: {0:F0}° → {1:F0}°   Momento migliore (elevazione minima più alta): {2} UTC, Dpol {3:F0}°, perdita pol. {4:F1} dB"),
                        ra.Dpol, rb.Dpol, FmtT(rm.Utc), rm.Dpol, rm.PolLoss);
                    sb.AppendLine();
                }
                else
                {
                    sb.AppendFormat(ci, Lang.T("    Culminazione alle {0} UTC"), FmtT(rm.Utc));
                    sb.AppendLine();
                }
                sb.AppendLine();
            }
            if (count == 0)
                return calcDx
                    ? Lang.T("Nessuna finestra comune nel periodo scelto con questi limiti di puntamento.")
                    : Lang.T("Nessuna finestra utile nel periodo scelto con questi limiti di puntamento.");
            sb.AppendFormat(ci, Lang.T("Inizio e fine delle finestre hanno la risoluzione dell'intervallo scelto ({0} min)."), step);
            return sb.ToString();
        }

        double MaxEl(int a, int b, bool dxSide)
        {
            double m = -90;
            for (int i = a; i <= b; i++)
            {
                double e = dxSide ? tutte[i].Q.El : tutte[i].P.El;
                if (e > m) m = e;
            }
            return m;
        }

        Pillola btnColonne;

        void DisegnaTestataPos(object sender, DrawListViewColumnHeaderEventArgs e)
        {
            Graphics g = e.Graphics;
            int id = e.ColumnIndex >= 0 && e.ColumnIndex < visCols.Count ? visCols[e.ColumnIndex] : -1;
            bool fissa = id >= 0 && id < ColFisse;
            Color fondo = Tema.Scuro ? (fissa ? Tema.Section : Tema.Field) : (fissa ? Color.FromArgb(226, 234, 247) : Color.FromArgb(241, 245, 251));
            using (Brush b = new SolidBrush(fondo)) g.FillRectangle(b, e.Bounds);
            using (Pen p = new Pen(Tema.Scuro ? Tema.Linea : Color.FromArgb(200, 210, 226)))
            {
                g.DrawLine(p, e.Bounds.Left, e.Bounds.Bottom - 1, e.Bounds.Right, e.Bounds.Bottom - 1);
                g.DrawLine(p, e.Bounds.Right - 1, e.Bounds.Top + 3, e.Bounds.Right - 1, e.Bounds.Bottom - 4);
            }
            Rectangle r = new Rectangle(e.Bounds.X + S(5), e.Bounds.Y, e.Bounds.Width - S(10), e.Bounds.Height);
            int wl = fissa ? S(12) : 0;
            Color ct = Tema.Scuro ? Tema.Fore : Color.FromArgb(25, 45, 80);
            using (Font f = new Font(lv.Font, FontStyle.Bold))
            {
                TextFormatFlags tf = TextFormatFlags.VerticalCenter | TextFormatFlags.EndEllipsis | TextFormatFlags.SingleLine
                    | (id >= 0 && ColRight[id] ? TextFormatFlags.Right : TextFormatFlags.Left);
                Rectangle rt = new Rectangle(r.X, r.Y, r.Width - wl, r.Height);
                TextRenderer.DrawText(g, e.Header.Text, f, rt, ct, tf);
                if (fissa)
                {
                    // lucchetto disegnato: corpo e arco
                    SmoothingMode sm = g.SmoothingMode;
                    g.SmoothingMode = SmoothingMode.AntiAlias;
                    float lx = r.Right - S(9), ly = e.Bounds.Top + e.Bounds.Height / 2f;
                    Color cl = Color.FromArgb(160, 140, 90);
                    using (Pen pa = new Pen(cl, Math.Max(1f, S(1.3f)))) g.DrawArc(pa, lx + S(1.5f), ly - S(5), S(6), S(7), 180, 180);
                    using (Brush bl = new SolidBrush(cl)) g.FillRectangle(bl, lx, ly - S(1), S(9), S(6));
                    g.SmoothingMode = sm;
                }
            }
        }

        void TestoPulsanteColonne()
        {
            if (btnColonne == null) return;
            int n = 0;
            for (int i = ColFisse; i < colScelte.Length; i++) if (colScelte[i]) n++;
            btnColonne.Text = "▦ " + string.Format(ci, Lang.T("Colonne · {0} aggiuntive"), n) + " ▾";
        }

        // Finestra di scelta delle colonne aggiuntive (bozzetto): scheda bianca con interruttori, colonne fisse come pastiglie grigie,
        // etichette "DX" (arancioni) e "nuova" (verdi); Tutte, Nessuna e Predefinite a sinistra, Chiudi blu a destra
        static readonly int[] ColNuove = { 23, 24, 25 };

        void ScegliColonne()
        {
            bool[] scelte = (bool[])colScelte.Clone();
            using (Form f = new Form())
            {
                f.Text = Lang.T("Colonne della tabella");
                f.FormBorderStyle = FormBorderStyle.FixedDialog;
                f.MaximizeBox = false; f.MinimizeBox = false; f.ShowInTaskbar = false;
                f.StartPosition = FormStartPosition.CenterParent;
                f.AutoScaleMode = AutoScaleMode.None;
                f.Font = new Font(Lang.FontUi, 10F);
                f.RightToLeft = Lang.Rtl ? RightToLeft.Yes : RightToLeft.No;
                try { f.Icon = this.Icon; } catch { }
                Color carta = Tema.Scuro ? Tema.Back : Color.White;
                f.BackColor = carta;
                List<KeyValuePair<RectangleF, int>> zone = new List<KeyValuePair<RectangleF, int>>();
                PannelloDisegno pc = new PannelloDisegno();
                int W = S(560);
                int totAgg = colScelte.Length - ColFisse;
                string[] gruppi = { Lang.T("Rumore e degradazione"), Lang.T("Doppler e frequenze"), Lang.T("Geometria della Luna") };
                Func<Graphics, bool, float> disegna = null;
                disegna = (g, vero) =>
                {
                    zone.Clear();
                    Color blu = Color.FromArgb(25, 65, 127), viola = Color.FromArgb(91, 63, 168), grigio = Tema.Muted;
                    float x = S(18), w = W - S(36), y = S(16);
                    using (Font ft = FontPx(Lang.FontUi, S(16), true))
                    using (Font fk = FontPx(Lang.FontUi, S(11), true))
                    using (Font fc = FontPx(Lang.FontUi, S(12), false))
                    using (Font fg = FontPx(Lang.FontUi, S(12.5f), true))
                    using (Font fl = FontPx(Lang.FontUi, S(13), false))
                    using (Font ftag = FontPx(Lang.FontUi, S(9.5f), false))
                    using (Font fn = FontPx(Lang.FontUi, S(11.5f), false))
                    {
                        int nAgg = 0;
                        for (int i = ColFisse; i < scelte.Length; i++) if (scelte[i]) nAgg++;
                        string conta = string.Format(ci, Lang.T("{0} aggiuntive su {1}"), nAgg, totAgg);
                        if (vero)
                        {
                            Testo(g, Lang.T("Colonne della tabella"), ft, Tema.Scuro ? Tema.Fore : blu, new RectangleF(x, y, w * 0.7f, S(26)), StringAlignment.Near, StringAlignment.Center);
                            Testo(g, conta, fc, grigio, new RectangleF(x, y, w, S(26)), StringAlignment.Far, StringAlignment.Center);
                        }
                        y += S(38);
                        // colonne sempre visibili
                        if (vero)
                        {
                            Color cl = Color.FromArgb(180, 140, 60);
                            using (Pen pa = new Pen(cl, S(1.3f))) g.DrawArc(pa, x + S(1.5f), y + S(2), S(6), S(7), 180, 180);
                            using (Brush bl = new SolidBrush(cl)) g.FillRectangle(bl, x, y + S(6), S(9), S(6));
                            Testo(g, Lang.T("SEMPRE VISIBILI (FINO A MNR)"), fk, grigio, new RectangleF(x + S(14), y, w, S(18)), StringAlignment.Near, StringAlignment.Center);
                        }
                        y += S(22);
                        float xc = x;
                        for (int i = 0; i < ColFisse; i++)
                        {
                            string t = ColTitle[i];
                            int pp = t.LastIndexOf(" (");
                            if (pp > 0) t = t.Substring(0, pp);
                            float wc = g.MeasureString(t, fc).Width + S(16);
                            if (xc + wc > x + w) { xc = x; y += S(26); }
                            RectangleF rc = new RectangleF(xc, y, wc, S(22));
                            if (vero)
                                using (GraphicsPath p = Arrotondato(rc, S(11)))
                                using (Brush b = new SolidBrush(Tema.Scuro ? Tema.Section : Color.FromArgb(238, 240, 244)))
                                {
                                    g.FillPath(b, p);
                                    Testo(g, t, fc, Tema.Scuro ? Tema.Fore : Color.FromArgb(75, 85, 99), rc, StringAlignment.Center, StringAlignment.Center);
                                }
                            xc += wc + S(6);
                        }
                        y += S(36);
                        if (vero) Testo(g, Lang.T("COLONNE AGGIUNTIVE"), fk, grigio, new RectangleF(x, y, w, S(18)), StringAlignment.Near, StringAlignment.Center);
                        y += S(22);
                        float rh = S(29), cw = w / 2f;
                        for (int k = 0; k < ColGruppi.Length; k++)
                        {
                            if (vero)
                            {
                                Testo(g, gruppi[k], fg, viola, new RectangleF(x, y, w, S(20)), StringAlignment.Near, StringAlignment.Center);
                                using (Pen pl = new Pen(Tema.Scuro ? Tema.Linea : Color.FromArgb(226, 230, 238))) g.DrawLine(pl, x, y + S(21), x + w, y + S(21));
                            }
                            y += S(26);
                            for (int j = 0; j < ColGruppi[k].Length; j++)
                            {
                                int id = ColGruppi[k][j];
                                float cx = x + (j % 2) * cw, cy = y + (j / 2) * rh;
                                RectangleF sw = new RectangleF(cx, cy + S(4), S(34), S(19));
                                bool on = scelte[id];
                                float wt = g.MeasureString(ColTitle[id], fl).Width;
                                zone.Add(new KeyValuePair<RectangleF, int>(new RectangleF(cx, cy, Math.Min(cw - S(4), S(46) + wt + S(60)), rh), id));
                                if (!vero) continue;
                                using (GraphicsPath p = Arrotondato(sw, S(9.5f)))
                                using (Brush b = new SolidBrush(on ? Color.FromArgb(31, 111, 209) : (Tema.Scuro ? Tema.Linea : Color.FromArgb(214, 218, 225))))
                                    g.FillPath(b, p);
                                float d = S(15);
                                RectangleF pomo = new RectangleF(on ? sw.Right - d - S(2) : sw.Left + S(2), sw.Top + S(2), d, d);
                                g.FillEllipse(Brushes.White, pomo);
                                Testo(g, ColTitle[id], fl, Tema.Fore, new RectangleF(cx + S(44), cy, cw - S(48), rh), StringAlignment.Near, StringAlignment.Center);
                                float xt = cx + S(44) + wt + S(8);
                                if (ColDx[id]) xt += Etichetta2(g, "DX", ftag, Color.FromArgb(217, 119, 6), Color.FromArgb(255, 243, 214), xt, cy + rh / 2f) + S(4);
                                if (Array.IndexOf(ColNuove, id) >= 0) Etichetta2(g, Lang.T("nuova"), ftag, Color.FromArgb(23, 128, 61), Color.FromArgb(222, 244, 229), xt, cy + rh / 2f);
                            }
                            y += ((ColGruppi[k].Length + 1) / 2) * rh + S(6);
                        }
                        // nota in fondo, con l'etichetta DX
                        string nota = Lang.T("[DX] = compare solo con la seconda stazione attiva · la scelta viene salvata e vale anche per Esporta CSV");
                        if (nota.StartsWith("[DX]")) nota = nota.Substring(4).TrimStart();
                        float we = 0;
                        if (vero) we = Etichetta2(g, "DX", ftag, Color.FromArgb(217, 119, 6), Color.FromArgb(255, 243, 214), x, y + S(9));
                        else we = g.MeasureString("DX", ftag).Width + S(10);
                        float hn = g.MeasureString(nota, fn, (int)(w - we - S(6))).Height;
                        if (vero) using (Brush bn = new SolidBrush(grigio)) g.DrawString(nota, fn, bn, new RectangleF(x + we + S(6), y, w - we - S(6), hn + S(2)));
                        y += hn + S(14);
                    }
                    return y;
                };
                using (Graphics gm = f.CreateGraphics()) pc.Size = new Size(W, (int)disegna(gm, false));
                pc.Location = new Point(0, 0);
                pc.Paint += (s, e) => { PreparaGrafica(e.Graphics); e.Graphics.Clear(carta); disegna(e.Graphics, true); };
                pc.MouseMove += (s, e) =>
                {
                    bool su = false;
                    foreach (KeyValuePair<RectangleF, int> kv in zone) if (kv.Key.Contains(e.Location)) su = true;
                    pc.Cursor = su ? Cursors.Hand : Cursors.Default;
                };
                pc.MouseClick += (s, e) =>
                {
                    foreach (KeyValuePair<RectangleF, int> kv in zone)
                        if (kv.Key.Contains(e.Location)) { scelte[kv.Value] = !scelte[kv.Value]; pc.Invalidate(); break; }
                };
                // pulsanti: tre bianchi a sinistra, Chiudi blu a destra
                Font fb = new Font(Lang.FontUi, 10F);
                Pillola bTutte = new Pillola(Lang.T("Tutte"), StilePillola.Pieno, Color.FromArgb(75, 85, 99), fb);
                Pillola bNessuna = new Pillola(Lang.T("Nessuna"), StilePillola.Pieno, Color.FromArgb(75, 85, 99), fb);
                Pillola bPred = new Pillola(Lang.T("Predefinite"), StilePillola.Pieno, Color.FromArgb(75, 85, 99), fb);
                Pillola bOk = new Pillola(Lang.T("Chiudi"), StilePillola.Pieno, Color.FromArgb(31, 111, 209), new Font(Lang.FontUi, 10F, FontStyle.Bold));
                bOk.DialogResult = DialogResult.OK;
                bTutte.Click += (s, e) => { for (int i = ColFisse; i < scelte.Length; i++) scelte[i] = true; pc.Invalidate(); };
                bNessuna.Click += (s, e) => { for (int i = ColFisse; i < scelte.Length; i++) scelte[i] = false; pc.Invalidate(); };
                bPred.Click += (s, e) => { for (int i = ColFisse; i < scelte.Length; i++) scelte[i] = Array.IndexOf(ColPredefinite, i) >= 0; pc.Invalidate(); };
                Panel linea = new Panel(); linea.BackColor = Tema.Scuro ? Tema.Linea : Color.FromArgb(226, 230, 238);
                Panel barra = new Panel(); barra.BackColor = carta;
                int hb = Math.Max(bOk.Height, bTutte.Height) + S(26);
                linea.SetBounds(0, pc.Height, W, 1);
                barra.SetBounds(0, pc.Height + 1, W, hb);
                int xb = S(18);
                foreach (Pillola pb in new Pillola[] { bTutte, bNessuna, bPred })
                {
                    pb.Location = new Point(xb, (hb - pb.Height) / 2);
                    barra.Controls.Add(pb);
                    xb += pb.Width + S(8);
                }
                bOk.Width = Math.Max(bOk.Width, S(80));
                bOk.AutoSize = false;
                bOk.Location = new Point(W - S(18) - bOk.Width, (hb - bOk.Height) / 2);
                barra.Controls.Add(bOk);
                f.Controls.Add(pc); f.Controls.Add(linea); f.Controls.Add(barra);
                f.ClientSize = new Size(W, pc.Height + 1 + hb);
                f.AcceptButton = bOk;
                f.CancelButton = bOk;
                f.ShowDialog(this);
                fb.Dispose();
            }
            for (int i = ColFisse; i < colScelte.Length; i++) colScelte[i] = scelte[i];
            TestoPulsanteColonne();
            SetupColumns(tutte.Count > 0 ? calcDx : chkDx.Checked);
            ApplyFilter();
            SaveSettings();
        }

        // etichetta piccola arrotondata (DX, nuova) centrata in verticale su yc; restituisce la larghezza
        float Etichetta2(Graphics g, string t, Font f, Color testo, Color fondo, float x, float yc)
        {
            SizeF sz = g.MeasureString(t, f);
            RectangleF r = new RectangleF(x, yc - sz.Height / 2f - S(1), sz.Width + S(8), sz.Height + S(2));
            using (GraphicsPath p = Arrotondato(r, S(4)))
            using (Brush b = new SolidBrush(fondo)) g.FillPath(b, p);
            Testo(g, t, f, testo, r, StringAlignment.Center, StringAlignment.Center);
            return r.Width;
        }

        void EsportaCsv()
        {
            if (tutte.Count == 0)
            {
                Messaggio(this, Lang.T("Calcola prima la tabella."), "YAEC", MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }
            SaveFileDialog dlg = new SaveFileDialog();
            dlg.Filter = Lang.T("File CSV (*.csv)|*.csv|Tutti i file (*.*)|*.*");
            string nome = "YAEC_" + me.Loc.Text.Trim();
            if (calcDx) nome += "_" + dx.Loc.Text.Trim();
            dlg.FileName = nome + "_" + tutte[0].Utc.ToString("yyyyMMdd_HHmm", inv) + ".csv";
            if (dlg.ShowDialog(this) != DialogResult.OK) return;
            string sep = ci.TextInfo.ListSeparator;
            if (string.IsNullOrEmpty(sep) || sep == ci.NumberFormat.NumberDecimalSeparator) sep = ";";
            try
            {
                using (StreamWriter w = new StreamWriter(dlg.FileName, false, new UTF8Encoding(true)))
                {
                    List<string> h = new List<string>();
                    foreach (int c in visCols) h.Add(ColTitle[c]);
                    w.WriteLine(string.Join(sep, h.ToArray()));
                    foreach (Riga r in mostrate)
                    {
                        string[] v = Valori(r, "F2");
                        List<string> row = new List<string>();
                        foreach (int c in visCols) row.Add(v[c]);
                        w.WriteLine(string.Join(sep, row.ToArray()));
                    }
                }
                lblStatus.Text = Lang.T("Esportato: ") + dlg.FileName;
            }
            catch (Exception ex)
            {
                Messaggio(this, Lang.T("Impossibile salvare il file:\n") + ex.Message, "YAEC",
                    MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

