        static string Lingua(string l) { return testi.ContainsKey(l) ? l : "en"; }
        public static string T(string lingua, string chiave) { return testi[Lingua(lingua)][chiave]; }
        public static string[] E(string lingua, string chiave) { return elenchi[Lingua(lingua)][chiave]; }
    }

    // Cartella "data" accanto all'eseguibile: contiene TUTTI i dati del programma
    //   impostazioni.txt        impostazioni (la password LoTW è cifrata con DPAPI di Windows)
    //   solar-radio-flux.json   flussi solari RSTN scaricati da NOAA SWPC
    //   lotw.adi                log scaricato da LoTW
    //   tiles\                  tessere della mappa già scaricate
    // Alla prima esecuzione vi si spostano i dati delle versioni precedenti
    // (AppData\Roaming\LunaCalc e la cartella dell'eseguibile).
    // Windows, Linux o macOS: su Linux e macOS il programma gira con Mono (stesso YAEC.exe)
    static class Piattaforma
    {
        public static readonly bool Windows = Environment.OSVersion.Platform == PlatformID.Win32NT
            || Environment.OSVersion.Platform == PlatformID.Win32Windows;
        public static readonly bool Mac = !Windows && Directory.Exists("/System/Library/CoreServices") && Directory.Exists("/Applications");
        public static readonly bool Linux = !Windows && !Mac;
        public static readonly bool Mono = Type.GetType("Mono.Runtime") != null;
        public static string Nome { get { return Windows ? "Windows" : (Mac ? "macOS" : "Linux"); } }
    }

    static class Dati
    {
        public static readonly string[] FileNoti = { "impostazioni.txt", "solar-radio-flux.json", "lotw.adi" };

        // Windows: sottocartella data accanto a YAEC.exe (come sempre).
        // Linux e macOS: il programma è installato in una cartella di sola lettura, quindi la cartella data
        // sta in quella dell'utente: ~/.local/share/YAEC/data (Linux) o ~/Library/Application Support/YAEC/data (macOS).
        static string cartella;
        public static string Cartella
        {
            get
            {
                if (cartella != null) return cartella;
                if (Piattaforma.Windows) cartella = Path.Combine(Application.StartupPath, "data");
                else
                {
                    string casa = Environment.GetEnvironmentVariable("HOME") ?? Environment.GetFolderPath(Environment.SpecialFolder.Personal);
                    string baseDir;
                    if (Piattaforma.Mac) baseDir = Path.Combine(Path.Combine(Path.Combine(casa, "Library"), "Application Support"), "YAEC");
                    else
                    {
                        string xdg = Environment.GetEnvironmentVariable("XDG_DATA_HOME");
                        baseDir = Path.Combine(string.IsNullOrEmpty(xdg) ? Path.Combine(Path.Combine(casa, ".local"), "share") : xdg, "YAEC");
                    }
                    cartella = Path.Combine(baseDir, "data");
                }
                try { Directory.CreateDirectory(cartella); } catch { }
                return cartella;
            }
        }

        public static string Percorso(string nome) { return Path.Combine(Cartella, nome); }

        static string VecchiaAppData()
        {
            try { return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), "LunaCalc"); }
            catch { return ""; }
        }

        // Sposta un file; se in data esiste già, la copia vecchia viene eliminata (vince quella in data)
        static void SpostaFile(string da, string a)
        {
            try
            {
                if (!File.Exists(da)) return;
                Directory.CreateDirectory(Path.GetDirectoryName(a));
                if (File.Exists(a)) File.Delete(da);
                else File.Move(da, a);
            }
            catch { }
        }

        // Sposta una cartella file per file (File.Move funziona anche tra dischi diversi), poi elimina quelle vuote
        static void SpostaCartella(string da, string a)
        {
            try
            {
                if (!Directory.Exists(da)) return;
                foreach (string f in Directory.GetFiles(da, "*", SearchOption.AllDirectories))
                    SpostaFile(f, Path.Combine(a, f.Substring(da.Length).TrimStart('\\', '/')));
                EliminaVuote(da);
            }
            catch { }
        }

        static void EliminaVuote(string d)
        {
            try
            {
                foreach (string s in Directory.GetDirectories(d)) EliminaVuote(s);
                if (Directory.GetFileSystemEntries(d).Length == 0) Directory.Delete(d);
            }
            catch { }
        }

        // Da chiamare all'avvio, prima di leggere le impostazioni
        public static void Prepara()
        {
            try { Directory.CreateDirectory(Cartella); } catch { }
            try { Directory.CreateDirectory(Percorso("tiles")); } catch { }
            if (!Piattaforma.Windows) return;   // Linux e macOS: nessun dato delle versioni beta per Windows da spostare
            // v19-v21: file accanto all'eseguibile (più recenti, quindi spostati per primi)
            foreach (string n in FileNoti) SpostaFile(Path.Combine(Application.StartupPath, n), Percorso(n));
            SpostaCartella(Path.Combine(Application.StartupPath, "tiles"), Percorso("tiles"));
            // fino alla v18: AppData\Roaming\LunaCalc
            string vecchia = VecchiaAppData();
            if (vecchia.Length > 0 && Directory.Exists(vecchia))
            {
                foreach (string n in FileNoti) SpostaFile(Path.Combine(vecchia, n), Percorso(n));
                SpostaCartella(vecchia, Cartella);
                EliminaVuote(vecchia);
            }
            CorreggiPercorsoAdif(vecchia);
        }

        // Il log ADIF scaricato da LoTW si trovava nelle vecchie cartelle: il percorso salvato va aggiornato
        static void CorreggiPercorsoAdif(string vecchia)
        {
            try
            {
                string p = Percorso("impostazioni.txt");
                if (!File.Exists(p)) return;
                string[] righe = File.ReadAllLines(p);
                bool cambiato = false;
                for (int i = 0; i < righe.Length; i++)
                {
                    if (!righe[i].StartsWith("adif=")) continue;
                    string v = righe[i].Substring(5).Trim();
                    if (v.Length == 0 || File.Exists(v)) continue;
                    string dir = "";
                    try { dir = Path.GetDirectoryName(v); } catch { }
                    if (string.Equals(dir, Application.StartupPath, StringComparison.OrdinalIgnoreCase)
                        || (vecchia.Length > 0 && dir.StartsWith(vecchia, StringComparison.OrdinalIgnoreCase)))
                    {
                        string nuovo = Path.Combine(Cartella, v.Substring(dir.Length).TrimStart('\\', '/'));
                        if (File.Exists(nuovo)) { righe[i] = "adif=" + nuovo; cambiato = true; }
                    }
                }
                if (cambiato) File.WriteAllLines(p, righe, Encoding.UTF8);
            }
            catch { }
        }

        static string Impostazione(string chiave)
        {
            try
            {
                string p = Percorso("impostazioni.txt");
                if (!File.Exists(p)) return "";
                foreach (string line in File.ReadAllLines(p))
                    if (line.StartsWith(chiave + "=")) return line.Substring(chiave.Length + 1).Trim();
            }
            catch { }
            return "";
        }

        // Linux e macOS con Mono: spesso Mono non ha il suo archivio dei certificati radice (pacchetto
        // ca-certificates-mono assente) e ogni HTTPS fallisce con TrustFailure. In quel caso la catena del server
        // si verifica con le autorità radice del sistema operativo (il file PEM di /etc/ssl): la verifica resta
        // completa (nome del server, date, catena fino a una radice del sistema), cambia solo l'elenco delle radici.
        static List<System.Security.Cryptography.X509Certificates.X509Certificate2> radiciSistema;
        static HashSet<string> impronteRadici;
        static bool verificaPronta;

        internal static void PreparaVerificaCertificati()
        {
            if (Piattaforma.Windows || verificaPronta) return;
            verificaPronta = true;
            try { ServicePointManager.ServerCertificateValidationCallback = VerificaCertificato; } catch { }
        }

        static void CaricaRadici()
        {
            if (radiciSistema != null) return;
            List<System.Security.Cryptography.X509Certificates.X509Certificate2> l = new List<System.Security.Cryptography.X509Certificates.X509Certificate2>();
            HashSet<string> imp = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            string[] file = { "/etc/ssl/certs/ca-certificates.crt", "/etc/pki/tls/certs/ca-bundle.crt", "/etc/ssl/ca-bundle.pem",
                "/etc/pki/ca-trust/extracted/pem/tls-ca-bundle.pem", "/etc/ssl/cert.pem", "/usr/local/etc/openssl/cert.pem", "/opt/homebrew/etc/ca-certificates/cert.pem" };
            foreach (string f in file)
            {
                try
                {
                    if (!File.Exists(f)) continue;
                    string t = File.ReadAllText(f);
                    const string A = "-----BEGIN CERTIFICATE-----", B = "-----END CERTIFICATE-----";
                    int i = 0;
                    while ((i = t.IndexOf(A, i, StringComparison.Ordinal)) >= 0)
                    {
                        int j = t.IndexOf(B, i, StringComparison.Ordinal);
                        if (j < 0) break;
                        try
                        {
                            byte[] der = Convert.FromBase64String(t.Substring(i + A.Length, j - i - A.Length).Replace("\r", "").Replace("\n", "").Trim());
                            System.Security.Cryptography.X509Certificates.X509Certificate2 c = new System.Security.Cryptography.X509Certificates.X509Certificate2(der);
                            if (imp.Add(c.Thumbprint)) l.Add(c);
                        }
                        catch { }
                        i = j + B.Length;
                    }
                    if (l.Count > 0) break;
                }
                catch { }
            }
            impronteRadici = imp;
            radiciSistema = l;
        }

        static bool VerificaCertificato(object mittente, System.Security.Cryptography.X509Certificates.X509Certificate cert,
            System.Security.Cryptography.X509Certificates.X509Chain catena, System.Net.Security.SslPolicyErrors errori)
        {
            if (errori == System.Net.Security.SslPolicyErrors.None) return true;
            // nome del server sbagliato o certificato assente: sempre rifiutato
            if ((errori & ~System.Net.Security.SslPolicyErrors.RemoteCertificateChainErrors) != 0 || cert == null) return false;
            try
            {
                CaricaRadici();
                if (radiciSistema.Count == 0) return false;
                using (System.Security.Cryptography.X509Certificates.X509Chain c = new System.Security.Cryptography.X509Certificates.X509Chain())
                {
                    c.ChainPolicy.RevocationMode = System.Security.Cryptography.X509Certificates.X509RevocationMode.NoCheck;
                    c.ChainPolicy.VerificationFlags = System.Security.Cryptography.X509Certificates.X509VerificationFlags.AllowUnknownCertificateAuthority;
                    foreach (System.Security.Cryptography.X509Certificates.X509Certificate2 r in radiciSistema) c.ChainPolicy.ExtraStore.Add(r);
                    if (catena != null)
                        foreach (System.Security.Cryptography.X509Certificates.X509ChainElement el in catena.ChainElements) c.ChainPolicy.ExtraStore.Add(el.Certificate);
                    c.Build(new System.Security.Cryptography.X509Certificates.X509Certificate2(cert));
                    if (c.ChainElements.Count < 2) return false;
                    foreach (System.Security.Cryptography.X509Certificates.X509ChainElement el in c.ChainElements)
                        foreach (System.Security.Cryptography.X509Certificates.X509ChainStatus st in el.ChainElementStatus)
                            if (st.Status != System.Security.Cryptography.X509Certificates.X509ChainStatusFlags.NoError
                                && st.Status != System.Security.Cryptography.X509Certificates.X509ChainStatusFlags.UntrustedRoot)
                                return false;
                    // la radice della catena deve essere una delle autorità del sistema
                    return impronteRadici.Contains(c.ChainElements[c.ChainElements.Count - 1].Certificate.Thumbprint);
                }
            }
            catch { return false; }
        }

        internal static byte[] Scarica(string url, int timeoutMs)
        {
            PreparaVerificaCertificati();
            try
            {
                ServicePointManager.SecurityProtocol = (SecurityProtocolType)3072 | (SecurityProtocolType)768 | SecurityProtocolType.Tls;
            }
            catch { }
            HttpWebRequest rq = (HttpWebRequest)WebRequest.Create(url);
            rq.Timeout = timeoutMs;
            rq.ReadWriteTimeout = timeoutMs;
            rq.UserAgent = "YAEC/" + MainForm.Versione.TrimStart('v') + " (EME calculator for radio amateurs)";
            rq.CachePolicy = new System.Net.Cache.RequestCachePolicy(System.Net.Cache.RequestCacheLevel.NoCacheNoStore);
            using (WebResponse rs = rq.GetResponse())
            using (Stream st = rs.GetResponseStream())
            using (MemoryStream ms = new MemoryStream())
            {
                st.CopyTo(ms);
                return ms.ToArray();
            }
        }

        internal static void ScriviAtomico(string p, byte[] dati)
        {
            string tmp = p + ".tmp";
            File.WriteAllBytes(tmp, dati);
            if (File.Exists(p)) File.Delete(p);
            File.Move(tmp, p);
        }

        // Controllo eseguito durante la barra verde dell'avvio: ogni file mancante o non valido
        // viene preso di nuovo dalla sua fonte. stato() riceve i messaggi da mostrare.
        public static void Controlla(Action<string> stato)
        {
            stato(Lang.T("Controllo dei file nella cartella data…"));
            try
            {
                Directory.CreateDirectory(Cartella);
                Directory.CreateDirectory(Percorso("tiles"));
                string prova = Percorso("scrittura.tmp");
                File.WriteAllText(prova, "ok");
                File.Delete(prova);
            }
            catch (Exception ex)
            {
                stato(Lang.T("Impossibile scrivere nella cartella data: ") + ex.Message);
                return;
            }

            // flussi solari: mancanti, non validi o più vecchi di 12 ore
            string sfu = Percorso("solar-radio-flux.json");
            bool valido = false;
            try
            {
                if (File.Exists(sfu) && (DateTime.UtcNow - File.GetLastWriteTimeUtc(sfu)).TotalHours < 12)
                {
                    string t = File.ReadAllText(sfu, Encoding.UTF8).TrimStart();
                    valido = t.StartsWith("[") || t.StartsWith("{");
                }
            }
            catch { valido = false; }
            if (!valido)
            {
                string url = Impostazione("sfu_url");
                if (url.Length == 0) url = MainForm.SfuUrlDefault;
                stato(Lang.T("Flusso solare: scaricamento da NOAA…"));
                try
                {
                    byte[] b = Scarica(url, 15000);
                    string t = Encoding.UTF8.GetString(b).TrimStart();
                    if (!(t.StartsWith("[") || t.StartsWith("{"))) throw new Exception("?");
                    ScriviAtomico(sfu, b);
                    stato(Lang.T("Flusso solare scaricato di nuovo da NOAA"));
                }
                catch { stato(Lang.T("Flusso solare non raggiungibile: si usano i dati salvati")); }
            }

            // log LoTW: solo se mancante e con nome utente e password memorizzati
            string lotw = Percorso("lotw.adi");
            string u = Impostazione("lotw_utente"), pw = MainForm.DecifraPassword(Impostazione("lotw_password"));
            if (!File.Exists(lotw) && u.Length > 0 && pw.Length > 0)
            {
                stato(Lang.T("Registro LoTW mancante: scaricamento in corso…"));
                try
                {
                    string url = "https://lotw.arrl.org/lotwuser/lotwreport.adi?login=" + Uri.EscapeDataString(u)
                        + "&password=" + Uri.EscapeDataString(pw)
                        + "&qso_query=1&qso_qsl=no&qso_qsldetail=yes&qso_mydetail=yes&qso_withown=yes";
                    byte[] b = Scarica(url, 180000);
                    string t = Encoding.GetEncoding(28591).GetString(b);
                    if (t.IndexOf("<eoh>", StringComparison.OrdinalIgnoreCase) < 0) throw new Exception("login");
                    ScriviAtomico(lotw, b);
                    stato(Lang.T("Registro LoTW scaricato di nuovo"));
                }
                catch { stato(Lang.T("Registro LoTW non raggiungibile")); }
            }

            // CALL3.TXT (nominativi e locator delle stazioni EME): mancante o più vecchio di 7 giorni
            if (!File.Exists(Call3.Percorso)) stato(Lang.T("CALL3.TXT mancante: scaricamento da W7GJ e WSJT-X Improved…"));
            else if ((DateTime.UtcNow - File.GetLastWriteTimeUtc(Call3.Percorso)).TotalDays >= Call3.GiorniValidita)
                stato(Lang.T("CALL3.TXT più vecchio di 7 giorni: scaricamento da W7GJ e WSJT-X Improved…"));
            stato(Call3.Aggiorna(false));
            Attivi.Aggiorna();   // stazioni attive (chat N0UK): in silenzio
            stato(Lang.T("Cartella data pronta"));
        }
    }

    // Stazioni EME attive: nominativi che hanno scritto (o sono stati decodificati) nella chat EME di N0UK
    // negli ultimi 90 giorni. L'elenco è preparato una volta al giorno su GitHub (tools/n0uk_attivi.py,
    // ramo "attivi") e contiene solo nominativo e data dell'ultimo messaggio; il programma lo scarica
    // in data/attivi.gz e lo usa solo per bordare in arancione la casella del nominativo del DX.
    static class Attivi
    {
        public const string Url = "https://raw.githubusercontent.com/ic8tem/YAEC/attivi/attivi.gz";
        public const int Giorni = 90;
        static readonly object blocco = new object();
        static Dictionary<string, DateTime> elenco;
        static DateTime letto = DateTime.MinValue;
        static volatile bool inCorso;

        public static string Percorso { get { return Dati.Percorso("attivi.gz"); } }

        static Dictionary<string, DateTime> Leggi(byte[] gz)
        {
            Dictionary<string, DateTime> d = new Dictionary<string, DateTime>(StringComparer.OrdinalIgnoreCase);
            string t;
            using (MemoryStream ms = new MemoryStream(gz))
            using (System.IO.Compression.GZipStream z = new System.IO.Compression.GZipStream(ms, System.IO.Compression.CompressionMode.Decompress))
            using (StreamReader sr = new StreamReader(z, Encoding.ASCII))
                t = sr.ReadToEnd();
            DateTime limite = DateTime.UtcNow.Date.AddDays(-Giorni);
            foreach (string r0 in t.Split('\n'))
            {
                string[] p = r0.Trim().Split(' ');
                DateTime dt;
                if (p.Length != 2 || p[0].Length < 3 || p[0].Length > 13) continue;
                if (!DateTime.TryParseExact(p[1], "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out dt)) continue;
                if (dt < limite) continue;
                DateTime pr;
                if (!d.TryGetValue(p[0], out pr) || dt > pr) d[p[0]] = dt;
            }
            return d;
        }

        // Scarica l'elenco se manca o ha più di 20 ore (in silenzio: in caso di errore resta quello salvato)
        public static bool Aggiorna()
        {
            if (inCorso) return false;
            inCorso = true;
            try
            {
                string p = Percorso;
                if (File.Exists(p) && (DateTime.UtcNow - File.GetLastWriteTimeUtc(p)).TotalHours < 20) return false;
                byte[] b = Dati.Scarica(Url, 20000);
                Leggi(b);   // controllo: deve essere un elenco leggibile
                Dati.ScriviAtomico(p, b);
                lock (blocco) letto = DateTime.MinValue;
                return true;
            }
            catch { return false; }
            finally { inCorso = false; }
        }

        public static bool DaAggiornare
        {
            get { try { return !File.Exists(Percorso) || (DateTime.UtcNow - File.GetLastWriteTimeUtc(Percorso)).TotalHours >= 20; } catch { return false; } }
        }

        static void Carica()
        {
            try
            {
                string p = Percorso;
                if (!File.Exists(p)) { elenco = null; return; }
                DateTime m = File.GetLastWriteTimeUtc(p);
                if (elenco != null && m == letto) return;
                elenco = Leggi(File.ReadAllBytes(p));
                letto = m;
            }
            catch { elenco = null; }
        }

        // Data dell'ultimo messaggio del nominativo (anche scritto con prefisso o suffisso: IS0/DL1ABC, DL1ABC/P)
        public static bool Cerca(string call, out DateTime ultimo)
        {
            ultimo = DateTime.MinValue;
            if (string.IsNullOrEmpty(call)) return false;
            call = call.Trim().ToUpperInvariant();
            if (call.Length < 3) return false;
            lock (blocco)
            {
                Carica();
                if (elenco == null) return false;
                DateTime limite = DateTime.UtcNow.Date.AddDays(-Giorni);
                List<string> prove = new List<string> { call };
                string lungo = "";
                foreach (string parte in call.Split('/')) if (parte.Length > lungo.Length) lungo = parte;
                if (lungo != call) prove.Add(lungo);
                foreach (string c in prove)
                {
                    DateTime d;
                    if (elenco.TryGetValue(c, out d) && d >= limite && d > ultimo) ultimo = d;
                }
                return ultimo != DateTime.MinValue;
            }
        }
    }

    // CALL3.TXT: elenco nominativo → locator delle stazioni EME (quello usato da WSJT-X).
    // Due fonti: la lista curata da W7GJ e quella distribuita con WSJT-X Improved (SourceForge).
    // Si scaricano entrambe; se una non risponde si usa l'altra; se rispondono tutte e due si fondono
    // per nominativo (in caso di locator diversi vale W7GJ). Il file finale sta in data/CALL3.TXT.
    static class Call3
    {
        public const string Nome = "CALL3.TXT";
        public static readonly string[][] Fonti = {
            new string[] { "W7GJ", "http://www.bigskyspaces.com/w7gj/CALL3.TXT", "https://www.bigskyspaces.com/w7gj/call3.txt", "http://www.bigskyspaces.com/w7gj/call3.txt" },
            new string[] { "WSJT-X Improved (SourceForge)", "https://downloads.sourceforge.net/project/wsjt-x-improved/Additional%20Files/CALL3.TXT",
                "https://sourceforge.net/projects/wsjt-x-improved/files/Additional%20Files/CALL3.TXT/download",
                // ultima possibilità senza HTTPS (alcune installazioni di Mono non accettano i certificati dei mirror):
                // il contenuto viene comunque controllato riga per riga prima di usarlo
                "http://downloads.sourceforge.net/project/wsjt-x-improved/Additional%20Files/CALL3.TXT" } };
        public const int GiorniValidita = 7;

        static readonly object blocco = new object();
        static Dictionary<string, string> griglie;      // nominativo → locator
        static DateTime caricato = DateTime.MinValue;  // data del file letto
        public static volatile bool InCorso;
        public static string[] Esito = { "", "" };      // esito dell'ultimo tentativo per ciascuna fonte

        public static string Percorso { get { return Dati.Percorso(Nome); } }

        // Righe valide: "NOMINATIVO,LOCATOR,..." (le righe che iniziano con // sono commenti)
        static bool RigaValida(string riga, out string call, out string grid)
        {
            call = grid = null;
            if (riga.Length < 6 || riga.StartsWith("//")) return false;
            string[] p = riga.Split(',');
            if (p.Length < 2) return false;
            call = p[0].Trim().ToUpperInvariant();
            grid = p[1].Trim().ToUpperInvariant();
            if (call.Length < 3 || call.Length > 13 || call.IndexOf(' ') >= 0) return false;
            double la, lo;
            if (grid.Length < 4 || !Locator.TryParse(grid, out la, out lo)) return false;
            return true;
        }

        // Testo scaricato → righe valide (null se non sembra un CALL3)
        static List<string> Analizza(byte[] b)
        {
            if (b == null || b.Length < 200) return null;
            string t = Encoding.GetEncoding(28591).GetString(b);
            if (t.IndexOf("<html", StringComparison.OrdinalIgnoreCase) >= 0) return null;
            List<string> ok = new List<string>();
            string c, g;
            foreach (string r0 in t.Split('\n'))
            {
                string r = r0.Trim('\r', ' ', '\t');
                if (RigaValida(r, out c, out g)) ok.Add(r);
            }
            return ok.Count >= 50 ? ok : null;
        }

        // Scaricamento che segue a mano i rinvii (SourceForge rimanda a un mirror, anche da https a http,
        // e Mono non segue da solo quel passaggio)
        static string ultimoUrl = "";
        static byte[] ScaricaConRinvii(string url, int timeoutMs)
        {
            Dati.PreparaVerificaCertificati();
            try { ServicePointManager.SecurityProtocol = (SecurityProtocolType)3072 | (SecurityProtocolType)768 | SecurityProtocolType.Tls; } catch { }
            for (int salto = 0; salto < 8; salto++)
            {
                ultimoUrl = url;
                HttpWebRequest rq = (HttpWebRequest)WebRequest.Create(url);
                rq.Timeout = timeoutMs;
                rq.ReadWriteTimeout = timeoutMs;
                rq.AllowAutoRedirect = false;
                rq.UserAgent = "YAEC/" + MainForm.Versione.TrimStart('v') + " (EME calculator for radio amateurs)";
                HttpWebResponse rs;
                try { rs = (HttpWebResponse)rq.GetResponse(); }
                catch (WebException wex)
                {
                    rs = wex.Response as HttpWebResponse;
                    if (rs == null) throw;
                }
                using (rs)
                {
                    int code = (int)rs.StatusCode;
                    if (code >= 300 && code < 400)
                    {
                        string dove = rs.Headers["Location"];
                        if (string.IsNullOrEmpty(dove)) throw new WebException("HTTP " + code);
                        url = new Uri(new Uri(url), dove).AbsoluteUri;
                        continue;
                    }
                    if (code != 200) throw new WebException("HTTP " + code);
                    using (Stream st = rs.GetResponseStream())
                    using (MemoryStream ms = new MemoryStream())
                    {
                        st.CopyTo(ms);
                        return ms.ToArray();
                    }
                }
            }
            throw new WebException("too many redirects");
        }

        static List<string> ScaricaFonte(int i)
        {
            string errore = "";
            for (int k = 1; k < Fonti[i].Length; k++)
            {
                try
                {
                    List<string> r = Analizza(ScaricaConRinvii(Fonti[i][k], i == 0 ? 30000 : 120000));   // SourceForge: 2 MB, a volte lento
                    if (r != null) { Esito[i] = string.Format(Lang.Cultura, Lang.T("{0:N0} nominativi"), r.Count); return r; }
                    errore = "?";
                }
                catch (Exception ex)
                {
                    errore = ex.Message;
                    for (Exception x = ex.InnerException; x != null; x = x.InnerException) errore += " / " + x.Message;
                    if (ultimoUrl.Length > 0) errore += " @ " + ultimoUrl;
                }
            }
            Esito[i] = Lang.T("non raggiungibile") + (errore.Length > 0 ? " (" + errore + ")" : "");
            return null;
        }

        // Scarica e fonde; forza = ignora l'età del file. Restituisce un messaggio per l'utente.
        public static string Aggiorna(bool forza)
        {
            string p = Percorso;
            try
            {
                if (!forza && File.Exists(p) && (DateTime.UtcNow - File.GetLastWriteTimeUtc(p)).TotalDays < GiorniValidita)
                    return Lang.T("CALL3.TXT aggiornato");
            }
            catch { }
            if (InCorso) return Lang.T("CALL3.TXT: aggiornamento già in corso…");
            InCorso = true;
            try
            {
                List<string> a = ScaricaFonte(0), b = ScaricaFonte(1);
                if (a == null && b == null) return Lang.T("CALL3.TXT non raggiungibile: si usa il file salvato");
                // fusione per nominativo: prima W7GJ, poi le stazioni che mancano prese dall'altra fonte
                List<string> righe = new List<string>();
                HashSet<string> visti = new HashSet<string>();
                int diversi = 0, aggiunti = 0;
                Dictionary<string, string> ga = new Dictionary<string, string>();
                string c, g;
                if (a != null)
                    foreach (string r in a)
                        if (RigaValida(r, out c, out g) && visti.Add(c)) { righe.Add(r); ga[c] = g; }
                if (b != null)
                    foreach (string r in b)
                    {
                        if (!RigaValida(r, out c, out g)) continue;
                        string g0;
                        if (ga.TryGetValue(c, out g0)) { if (!LocatorCompatibili(g0, g)) diversi++; continue; }
                        if (visti.Add(c)) { righe.Add(r); if (a != null) aggiunti++; }
                    }
                righe.Sort((x, y) => string.CompareOrdinal(x, y));
                StringBuilder sb = new StringBuilder();
                string fonti = a != null && b != null ? Fonti[0][0] + " + " + Fonti[1][0] : (a != null ? Fonti[0][0] : Fonti[1][0]);
                sb.Append("// CALL3.TXT - " + righe.Count.ToString(CultureInfo.InvariantCulture) + " stations - "
                    + DateTime.UtcNow.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture) + " UTC\r\n");
                sb.Append("// Sources: " + fonti + (a != null && b != null ? " (merged by callsign, W7GJ preferred)" : "") + "\r\n");
                sb.Append("// Downloaded and merged by YAEC - Yet Another EME Calc\r\n");
                sb.Append("// " + Fonti[0][0] + ": " + Esito[0] + " - " + Fonti[1][0] + ": " + Esito[1] + "\r\n");
                foreach (string r in righe) sb.Append(r).Append("\r\n");
                Dati.ScriviAtomico(p, Encoding.GetEncoding(28591).GetBytes(sb.ToString()));
                lock (blocco) { griglie = null; }
                if (a != null && b != null)
                    return string.Format(Lang.Cultura, Lang.T("CALL3.TXT aggiornato: {0:N0} nominativi da W7GJ e WSJT-X Improved ({1:N0} solo nella seconda, {2:N0} con locator diverso: vale W7GJ)"),
                        righe.Count, aggiunti, diversi);
                return string.Format(Lang.Cultura, Lang.T("CALL3.TXT aggiornato: {0:N0} nominativi (solo {1}, l'altra fonte non risponde)"), righe.Count, fonti);
            }
            catch (Exception ex) { return Lang.T("CALL3.TXT non aggiornato: ") + ex.Message; }
            finally { InCorso = false; }
        }

        // Due locator della stessa stazione sono "uguali" se il più corto è l'inizio del più lungo
        static bool LocatorCompatibili(string x, string y)
        {
            return x.StartsWith(y, StringComparison.Ordinal) || y.StartsWith(x, StringComparison.Ordinal);
        }

        static Dictionary<string, string> Tabella()
        {
            lock (blocco)
            {
                string p = Percorso;
                DateTime d = DateTime.MinValue;
                try { if (File.Exists(p)) d = File.GetLastWriteTimeUtc(p); } catch { }
                if (griglie != null && d == caricato) return griglie;
                Dictionary<string, string> t = new Dictionary<string, string>();
                try
                {
                    if (d != DateTime.MinValue)
                    {
                        string c, g;
                        foreach (string r in File.ReadAllLines(p, Encoding.GetEncoding(28591)))
                            if (RigaValida(r.Trim(), out c, out g) && !t.ContainsKey(c)) t[c] = g;
                    }
                }
                catch { }
                griglie = t; caricato = d;
                return t;
            }
        }

        public static int Conteggio { get { return Tabella().Count; } }
        public static DateTime DataFile
        {
            get { try { return File.Exists(Percorso) ? File.GetLastWriteTime(Percorso) : DateTime.MinValue; } catch { return DateTime.MinValue; } }
        }

        // Locator di un nominativo (anche con prefisso o suffisso: EA8/IK1ABC, IK1ABC/P); null se assente
        public static string Cerca(string testo, out string call)
        {
            call = null;
            if (string.IsNullOrEmpty(testo)) return null;
            string t = testo.Trim().ToUpperInvariant();
            if (t.Length < 3) return null;
            Dictionary<string, string> tab = Tabella();
            if (tab.Count == 0) return null;
            string g;
            if (tab.TryGetValue(t, out g)) { call = t; return g; }
            string piu = null;
            foreach (string pz in t.Split('/'))
                if (pz.Length >= 3 && (piu == null || pz.Length > piu.Length)) piu = pz;
            if (piu != null && piu != t && tab.TryGetValue(piu, out g)) { call = piu; return g; }
            return null;
        }

        // Cartella dei dati di WSJT-X sul sistema in uso
        public static string CartellaWsjtx()
        {
            if (Piattaforma.Windows)
                return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "WSJT-X");
            string home = Environment.GetEnvironmentVariable("HOME") ?? Environment.GetFolderPath(Environment.SpecialFolder.Personal);
            if (Piattaforma.Mac) return Path.Combine(home, "Library", "Application Support", "WSJT-X");
            string xdg = Environment.GetEnvironmentVariable("XDG_DATA_HOME");
            return Path.Combine(string.IsNullOrEmpty(xdg) ? Path.Combine(home, ".local", "share") : xdg, "WSJT-X");
        }
    }

